window.DEEP_STORIES["smartphone"] = {"slug":"smartphone","title":"The Smartphone","emoji":"📱","tagline":"From brick-sized car phones to a supercomputer in every pocket","intro":"Look around: there is probably a smartphone within arm's reach right now. It is a telephone, a camera, a map, a music player, a game console, a library and a flashlight, all squeezed into a slab of glass thinner than a pencil. But fifty years ago, a 'mobile phone' meant a heavy radio bolted into the trunk of a car! In these 20 parts we will travel from Alexander Graham Bell's wires and the first car phones to Martin Cooper's famous street-corner call in 1973, through chunky 'brick' phones, the first text message, pocket organizers, the forgotten IBM Simon, BlackBerry's keyboards, the iPhone and Android. Then we will open the phone up and see how touchscreens, chips, radio networks, batteries, cameras and sensors really work. Finally we will explore apps, how phones changed the whole world, the problems they cause, and where they might go next. Ready? Let's dial in.","outline":[{"n":1,"title":"Talking Without Wires: The World Before Mobile Phones","when":"1876 – 1970s"},{"n":2,"title":"The First Handheld Call","when":"1947 – 1984"},{"n":3,"title":"Phones Shrink and Learn to Text","when":"1985 – 2000"},{"n":4,"title":"Pocket Computers: The PDA","when":"1984 – 2005"},{"n":5,"title":"IBM Simon: The Forgotten First Smartphone","when":"1992 – 2000"},{"n":6,"title":"Japan's Mobile Internet Leap","when":"1997 – 2006"},{"n":7,"title":"BlackBerry and the Keyboard Years","when":"1984 – 2010"},{"n":8,"title":"One More Thing: The iPhone","when":"2004 – 2008"},{"n":9,"title":"Android and the Phone Wars","when":"2003 – 2015"},{"n":10,"title":"How It Works: Touchscreens and Displays","when":"1965 – today"},{"n":11,"title":"How It Works: The Chip — A Brain Made of Sand","when":"1947 – today"},{"n":12,"title":"How It Works: Radio Waves, Cells and Networks","when":"1947 – today"},{"n":13,"title":"How It Works: Batteries and Power","when":"1970s – today"},{"n":14,"title":"How It Works: The Camera in Your Pocket","when":"1969 – today"},{"n":15,"title":"How It Works: Sensors and GPS","when":"1970s – today"},{"n":16,"title":"There's an App for That","when":"2008 – today"},{"n":17,"title":"A World in Your Pocket: How Smartphones Changed Society","when":"2007 – today"},{"n":18,"title":"The Dark Side: Problems and Controversies","when":"2007 – today"},{"n":19,"title":"Phones of Today and Tomorrow","when":"2018 – future"},{"n":20,"title":"From Brick to Brain: Putting It All Together","when":"1876 – future"}],"people":[["Alexander Graham Bell (1847–1922)","Scottish-born inventor who received the first US telephone patent in 1876 (others, like Elisha Gray and Antonio Meucci, also worked on telephones)."],["Guglielmo Marconi (1874–1937)","Italian inventor who developed practical long-distance radio; shared the 1909 Nobel Prize in Physics."],["Hedy Lamarr (1914–2000)","Austrian-American film star and inventor who, with composer George Antheil, patented a frequency-hopping idea in 1942."],["Douglas H. Ring and W. Rae Young","Bell Labs engineers who described the cellular network idea in a 1947 memo."],["Amos Joel Jr. (1918–2008)","Bell Labs engineer whose patent covered handing calls from one cell to another."],["Martin Cooper (born 1928)","Motorola engineer who led the team behind the first handheld cellular phone and made the famous first public call in 1973."],["Joel Engel","Bell Labs engineer who led work on AT&T's cellular system and received Cooper's 1973 call; he later shared engineering awards for cellular work."],["Neil Papworth","British engineer who sent the first SMS text message, 'Merry Christmas', in 1992."],["Taneli Armanto","Nokia engineer who programmed the famous Snake game for Nokia phones (1997)."],["David Potter","South African-born British businessman, founder of Psion, maker of the 1984 Psion Organiser."],["John Sculley (born 1939)","Apple CEO who championed the Newton and popularized the term 'personal digital assistant'."],["Jeff Hawkins (born 1957)","inventor of the Palm Pilot and Graffiti handwriting system; co-founded Palm and Handspring."],["Donna Dubinsky (born 1955)","business leader who ran Palm and co-founded Handspring with Jeff Hawkins."],["Frank Canova","IBM engineer who led the design of the IBM Simon."],["Mike Lazaridis (born 1961)","co-founder of Research In Motion and a creator of the BlackBerry."],["Douglas Fregin","co-founder of Research In Motion with Mike Lazaridis in 1984."],["Jim Balsillie (born 1961)","co-CEO of Research In Motion who grew BlackBerry into a global business."],["Mari Matsunaga (born 1954) and Takeshi Natsuno (born 1965)","key creators of NTT Docomo's i-mode service."],["Shigetaka Kurita (born 1972)","designer of the influential 176-emoji set for i-mode in 1999."],["Steve Jobs (1955–2011)","Apple co-founder and CEO who led the creation of the iPhone and presented it in 2007."],["Jony Ive (born 1967)","Apple's chief designer, who shaped the look of the iPhone."],["Tony Fadell (born 1969)","led Apple's iPod division and the iPhone's hardware engineering."],["Scott Forstall (born 1969)","led the team that created the iPhone's software (iOS)."],["Wendell Weeks (born 1959)","Corning CEO whose company produced Gorilla Glass for the first iPhone."],["Wayne Westerman and John Elias","founders of FingerWorks, a multi-touch company bought by Apple in 2005."],["Andy Rubin (born 1962)","co-founder of Android Inc. who led Android at Google."],["Rich Miner, Nick Sears and Chris White","co-founders of Android Inc. in 2003."],["E. A. Johnson","British engineer at the Royal Radar Establishment who described the capacitive touchscreen in 1965."],["G. Samuel Hurst (1927–2010)","American physicist who invented resistive touch sensing and founded Elographics."],["Bill Buxton (born 1949)","Canadian computer scientist and researcher of multi-touch interfaces."],["Jeff Han","researcher whose 2006 multi-touch demonstration amazed audiences."],["Gordon Moore (1929–2023)","Intel co-founder who made the 1965 prediction known as Moore's Law."],["Sophie Wilson (born 1957) and Steve Furber (born 1953)","British computer scientists who designed the first ARM processor at Acorn."],["M. Stanley Whittingham (born 1941)","chemist who created an early rechargeable lithium battery in the 1970s; 2019 Nobel laureate."],["John B. Goodenough (1922–2023)","American physicist whose cobalt-oxide cathode (1980) made lithium-ion batteries powerful; 2019 Nobel laureate."],["Akira Yoshino (born 1948)","Japanese chemist who built the first practical lithium-ion battery in 1985; 2019 Nobel laureate."],["Willard Boyle (1924–2011) and George E. Smith (born 1930)","Bell Labs scientists who invented the CCD image sensor in 1969; 2009 Nobel laureates."],["Eric Fossum (born 1957)","engineer who led the NASA JPL team that developed the CMOS active-pixel image sensor used in phone cameras."],["Philippe Kahn (born 1952)","entrepreneur who in 1997 shared a photo of his newborn daughter using a phone linked to a digital camera, an early example of instant photo sharing."],["Bradford Parkinson (born 1935)","US Air Force officer and engineer who led the development of GPS."],["Gladys West (1930–2026)","American mathematician whose modeling of Earth's shape helped make GPS accurate."],["Jaap Haartsen (born 1963)","Dutch engineer at Ericsson who developed the core ideas of Bluetooth in the 1990s."]],"glossary":[["cellular network","a phone network that divides land into small areas called cells, each with its own tower, so radio channels can be reused"],["cell tower (base station)","an antenna and radio equipment that connects phones in one cell to the rest of the network"],["handoff","passing a call or data connection from one cell tower to the next as you move"],["analog vs digital","analog sends a smooth wave copying the sound; digital turns it into numbers (1s and 0s)"],["1G / 2G / 3G / 4G / 5G","generations of mobile networks; each newer one is faster and can carry more data"],["SMS","short message service: text messages of up to 160 characters"],["SIM card","a small chip card that identifies your phone account to the network"],["PDA","personal digital assistant: a handheld electronic organizer, usually without a phone"],["smartphone","a mobile phone that is also a general-purpose computer able to run apps and use the internet"],["operating system (OS)","the main software that runs a phone and its apps, such as Android or iOS"],["app","an application: a program you install on a phone to do a particular job"],["capacitive touchscreen","a screen that senses your finger by the tiny change it makes in an electric field"],["resistive touchscreen","a screen that senses where two flexible layers are pressed together"],["multi-touch","a touchscreen's ability to sense two or more touches at once, allowing gestures like pinch-to-zoom"],["transistor","a tiny electronic switch; billions of them make up a phone's chip"],["system-on-a-chip (SoC)","one chip that holds the processor, graphics, AI engine, modem and more"],["lithium-ion battery","a rechargeable battery in which lithium ions move between two electrodes"],["image sensor (CMOS)","the chip in a camera that turns light into electrical signals, pixel by pixel"],["GPS","Global Positioning System: US satellites whose signals let a receiver work out its location"],["accelerometer","a sensor that measures movement and tilt, for example to rotate the screen"]],"parts":[{"n":1,"title":"Talking Without Wires: The World Before Mobile Phones","when":"1876 – 1970s","summary":"Long ago, every telephone was tied to a wall by a wire. Then inventors learned to send messages through the air with radio, and soldiers, police and ships began to talk without wires. In 1946 the first car phones arrived, but they were as heavy as a big dog, and so few people could use them at once that many had to wait in line!","sections":[{"heading":"A Voice on a Wire","paragraphs":["Picture a workshop in Boston in March 1876. A 29-year-old teacher of deaf students named Alexander Graham Bell leans toward a strange gadget made of a membrane, a magnet and a coil of wire. In another room his assistant, Thomas Watson, holds a matching gadget to his ear. On March 10, Bell speaks into his device, and Watson hears the words clearly through the wire: 'Mr. Watson, come here, I want to see you.' Watson hurries into the room. For the first time, a human voice had traveled along a wire and come out the other end as understandable speech.","Just three days before that famous moment, on March 7, 1876, the United States Patent Office had granted Bell patent number 174,465. A patent is an official document that says, in effect, 'This idea belongs to this inventor, and nobody else may copy it for a number of years.' Bell's patent became one of the most valuable ever issued, because it covered a way of sending speech by electricity.","Bell was not the only person chasing this dream, though. On February 14, 1876, the very same day Bell's lawyer filed his application, a lawyer for an inventor named Elisha Gray filed a notice describing Gray's own design for a telephone. People argued for years about who really got there first. Long before both of them, an Italian immigrant in New York named Antonio Meucci had built voice-carrying devices too, and in 2002 the US House of Representatives passed a resolution honoring his work. Big inventions are often like that: several clever people are racing toward the same finish line at once, and history usually remembers only one name.","So how did Bell's telephone work? When you speak, your voice makes the air vibrate. In Bell's design, those vibrations shook a thin membrane attached to a small piece of iron sitting near an electromagnet. As the iron wobbled, it caused a tiny electric current in a coil of wire to rise and fall in exactly the same pattern as the sound. That changing current zipped along the wire to the receiver, where it pushed and pulled on another membrane, making it vibrate just like the speaker's voice. In other words, the telephone turned sound into electricity, sent the electricity down a wire, and then turned it back into sound.","The wires soon stretched farther. On August 10, 1876, Bell made a call in Ontario, Canada, between the towns of Brantford and Paris, about 13 kilometers apart, which is often described as the first true long-distance call. On October 9, 1876, Bell and Watson held a two-way conversation over a line between Cambridge and Boston, each talking and listening in turn. Every one of these calls, however, depended on a continuous metal path from one telephone to the other.","Inventors quickly made it better. Thomas Edison and others developed carbon microphones that made voices louder and clearer. The Bell Telephone Company was founded in 1877, and within about a year the first telephone exchange, a building where operators connected one caller to another, was running in Connecticut. Over the following decades, telephone poles and wires marched across cities and countryside.","But notice the catch. A telephone needed a wire. The wire ran from your house to the exchange, and the phone sat on a wall or desk at the end of it. If you wanted to make a call, you had to go to where the phone was. You could not take it on a walk, into a car, or onto a ship in the middle of the ocean. To set the telephone free, people needed a completely different way to send signals: through the empty air."]},{"heading":"Messages Through Thin Air","paragraphs":["In the 1860s the Scottish scientist James Clerk Maxwell worked out mathematically that electricity and magnetism could travel together as waves, moving at the speed of light. These waves were invisible, and for years nobody had proved they really existed. Then, in 1888, the German physicist Heinrich Hertz built a machine in his laboratory that made sparks jump across a gap and showed that the sparks sent out invisible waves that could be detected across the room. Today we call them radio waves. Hertz himself did not think they would be very useful. He was wrong!","A young Italian named Guglielmo Marconi, born in Bologna on April 25, 1874, read about Hertz's experiments and became fascinated. At his family's country home, the Villa Griffone near Bologna, he built his own transmitters and receivers in the attic and garden. His big breakthroughs were simple but clever: he raised his antenna high into the air and connected his equipment to the ground. By 1895 he could send signals about 2 kilometers, over a hill and out of sight.","Marconi could not find enough support in Italy, so in 1896 he moved to Britain. On June 2, 1896, he filed British patent number 12,039, often described as the first patent for a radio communication system. In 1897 he sent a radio message across the Bristol Channel, a stretch of sea between England and Wales, and he started a company to sell his wireless equipment. In 1899 his signals crossed the English Channel to France.","Then came his boldest attempt. On December 12, 1901, Marconi sat in a building at St. John's, Newfoundland, on the eastern edge of North America, listening through an earphone. Across the Atlantic Ocean, about 3,500 kilometers away at Poldhu in Cornwall, England, his team was tapping out the letter 'S' in Morse code: three short dots. Marconi reported that he heard the faint clicks. Some historians have questioned whether he truly did, because there was no machine recording, only his ears, and static can play tricks. But within a few years radio messages were regularly crossing oceans, so the dream was real either way.","In 1909 Marconi shared the Nobel Prize in Physics with the German scientist Ferdinand Braun for their work on wireless telegraphy. Notice that word: telegraphy. Early radio did not carry voices at all. It carried Morse code, a system of short and long signals (dots and dashes) that stood for letters. Sending actual speech by radio, called radiotelephony, needed better equipment such as vacuum tubes, which could make smooth, strong radio waves and amplify weak ones. That technology grew up in the 1910s and 1920s and led to the radio broadcasting that filled family living rooms with music and news.","Radio quickly proved it could save lives. Ships carried radio operators, many of them employed by Marconi's company. When the Titanic struck an iceberg in April 1912, its Marconi operators sent distress calls that brought the ship Carpathia to rescue the survivors. After that disaster, governments made radio watches on passenger ships much more important. For the first time, people far out of reach of any wire could call for help."]},{"heading":"Police Cars, Trains and Talking Radios","paragraphs":["Once radio could carry voices, people wanted to use it on the move. Some of the earliest experiments happened on trains. From 1918, German railways tested wireless telephone calls on military trains running between Berlin and Zossen, and in 1926 first-class passengers on trains between Hamburg and Berlin could make telephone calls while rolling through the countryside. It was a luxury for wealthy travelers, but it showed that a phone call did not have to stay still.","Police departments were another early customer. In the late 1920s, police in Detroit began sending radio messages to patrol cars, so officers could be told about a crime while they were already out driving. At first many of these systems worked in only one direction: the station could talk, but the officers in the car could only listen. Later systems let both sides talk, and two-way police radio spread across many cities during the 1930s.","There was a big difference between these radios and the telephone you know. A telephone call is a conversation where both people can talk at the same time. Most early two-way radios worked by 'push-to-talk.' You pressed a button to speak, and while you were talking you could not hear the other person. When you finished, you let go of the button and listened. That is why people on radios say 'over' at the end of a sentence: it means 'I'm done, your turn.' Engineers call this half-duplex, meaning signals go both ways, but only one way at a time."]},{"heading":"Walkie-Talkies Go to War","paragraphs":["During the 1930s and 1940s, radios shrank enough for a person to carry one. Who made the first 'walkie-talkie'? That question has several possible answers, and it is fair to tell you about all of them.","In Canada, an English-born inventor named Donald Hings built a portable radio in 1937 while working for a mining and smelting company. He called it a 'packset,' and it let people out in the wilderness stay in touch. During World War II he worked on improved versions for the Canadian military, and about 18,000 of his C-58 sets were made for soldiers. In 2001 he was appointed to the Order of Canada, one of the country's highest honors.","In the United States, a young radio enthusiast named Al Gross, who had earned an amateur radio license at just 16, built and patented his own small two-way radios between 1938 and 1941. Gross went on to make some of the first Citizens Band (CB) radios and, in 1949, adapted his ideas into one of the first telephone pager systems. Both Hings and Gross are sometimes called 'the inventor of the walkie-talkie,' and many historians simply say both deserve credit.","Meanwhile, a company in Chicago was building radios for the US Army. It was called the Galvin Manufacturing Company, and it sold its car radios under the brand name 'Motorola,' which later became the company's name. Around 1940, a Galvin team that included Dan Noble and Henryk Magnuski developed the SCR-300, a radio carried on a soldier's back. It used a technique called frequency modulation (FM), which reduced crackling noise, and it was the first radio widely nicknamed a 'walkie-talkie.'","Galvin also made a smaller set, the SCR-536, which could be held in one hand like a very large telephone handset. It was called the 'Handie-Talkie.' It weighed about 2.3 kilograms (5 pounds) with its batteries, held five vacuum tubes inside a waterproof case, and had a telescoping antenna about a meter long. Its range was only about 1.6 kilometers (a mile) over land, or about 5 kilometers over water, but for a soldier that could make all the difference. About 130,000 were built during the war, and they went ashore with American troops in North Africa, Sicily, Italy and on the beaches of Normandy in June 1944.","After the war, the same company would use what it had learned about small, tough, handheld radios to build something even more amazing. Keep the name Motorola in mind. It comes back in a big way in Part 2."]},{"heading":"June 17, 1946: The First Car Phone","paragraphs":["Now imagine you are a businessman in St. Louis, Missouri, in the summer of 1946. World War II ended less than a year ago. You have just paid for the newest gadget in America: a telephone in your car. On June 17, 1946, the Bell System, the giant telephone company led by AT&T, switched on its Mobile Telephone Service in St. Louis. For the first time, ordinary customers could make a telephone call from a moving car and talk to someone on a regular home or office phone.","But do not imagine a slim phone in your pocket. The radio equipment weighed about 36 kilograms (80 pounds), as much as a big dog or a fourth-grader. Most of it sat in the trunk of the car, with a cable running to a handset under the dashboard. The car's battery powered it, and a tall antenna stuck up from the car.","Making a call was nothing like tapping a name on a screen. You picked up the handset and, if the channel was free, pressed a button to signal the operator, a real person sitting at a switchboard. You told the operator the number you wanted, and the operator connected you. Calls coming to you went through an operator too. Like the walkie-talkies, the system used push-to-talk: you pressed the button to speak and released it to listen, so you could not both talk at once. And since anyone with a suitable radio receiver could tune in, your conversation was not very private.","It was also expensive. Customers paid about 15 dollars a month plus about 30 to 40 cents for each local call, at a time when a new car might cost around 1,000 dollars. Even so, the service spread. Chicago got car phones in October 1946, with the first calls on Illinois Bell's service on October 2 carried by equipment made by Motorola, the same company that had built the wartime Handie-Talkie, and car phone service soon spread to other cities. Within a few years the Bell System had roughly 5,000 car phone customers making about 30,000 calls a week across the United States.","Other countries tried their own systems. Sweden launched an automatic car phone system in 1956, where callers did not need an operator, though its equipment weighed about 40 kilograms. In West Germany a network called the A-Netz started in 1958. In the Soviet Union, an engineer named Leonid Kupriyanovich showed off experimental pocket radiotelephones between 1957 and 1961, and one 1961 model weighed only about 70 grams, but it remained an experiment rather than a public service. Around the world, the car phone became a symbol of being important and very busy."]},{"heading":"Too Many Callers, Too Few Channels","paragraphs":["There was one enormous problem, and no amount of money could easily fix it. To understand it, think about radio stations. Each station broadcasts on its own frequency, its own spot on the dial. If two stations used the same frequency in the same city, they would drown each other out, and you would hear a jumble. Car phone calls worked the same way. Each conversation needed its own radio channel, a narrow slice of frequencies, and only a small number of channels had been set aside for car phones.","When the St. Louis service started, it had only three channels for the whole metropolitan area. That meant at most three customers could be on a call at the same moment. If you picked up your car phone and all three channels were busy, you simply had to wait, hoping someone would hang up soon.","Why not just add more channels? Because of the way the system was designed. Each city had one big, powerful transmitter on a tall tower or building, shouting out over the whole city and beyond. Later systems used base stations with 100 to 250 watts of power, covering an area roughly 65 to 100 kilometers (40 to 60 miles) across. A single channel used by one caller was therefore blocked for everyone else across that entire huge area. And the government, which divides up radio frequencies among television, radio stations, police, the military, ships and planes, had only allowed a few channels for car phones.","In 1964 AT&T introduced an upgrade called the Improved Mobile Telephone Service (IMTS). It was a real improvement: customers could dial numbers themselves without an operator, and both people could talk at the same time, just like a normal phone. But it still used one big transmitter per area and still had only a handful of channels. In New York City in the 1970s, about 2,000 customers shared just 12 channels, and callers could wait around half an hour to get a free line. AT&T limited the service to about 40,000 customers in the whole country.","Other countries ran into the very same wall. West Germany's A-Netz had only about 11,000 users by 1971, so a new system, the B-Netz, followed in 1972. Britain's first car phone service, opened around Manchester in 1959, still needed operators, and it stayed small for many years. Finland launched a network called ARP in 1971 that eventually reached about 35,000 subscribers, a lot for a small country but still a tiny fraction of the population. Everywhere, the story was similar: a few lucky users, long lines, and networks that filled up almost as soon as they opened.","Many more people wanted car phones than could get them. In some cities hundreds of people sat on waiting lists, and some had to wait for years before a spot opened up. The equipment itself cost a fortune: an IMTS car phone could cost 2,000 to 4,000 dollars, and calls could cost more than a dollar a minute. A telephone engineer of the time might have summed up the problem like this: the more popular car phones became, the worse they worked."]},{"heading":"Comic Strips and Starships","paragraphs":["While engineers wrestled with channels and transmitters, storytellers were dreaming much bigger. On January 13, 1946, just months before the first car phone call in St. Louis, readers of the Dick Tracy comic strip saw the square-jawed police detective use a brand-new gadget: a '2-Way Wrist Radio.' Tracy could talk to headquarters through a radio strapped to his wrist like a watch. The comic strip, created by cartoonist Chester Gould, had begun in 1931, and the wrist radio became one of its most famous features. According to some accounts, Gould was inspired by the small two-way radios of Al Gross. In 1964 the comic upgraded Tracy's gadget to a '2-Way Wrist TV' with a picture screen.","To readers in 1946, a phone on your wrist was pure fantasy. Real car phones needed a trunk full of equipment. Today, of course, millions of people wear smartwatches that can make calls, which makes Dick Tracy look less like science fiction and more like a prediction.","Twenty years later, another piece of fiction captured imaginations. When the television series Star Trek first aired in 1966, its crew members carried small 'communicators' when they beamed down to planets. A communicator flipped open, with an antenna grille in the top half and the controls in the bottom half, and with a quick 'Kirk to Enterprise' the captain could talk to his starship orbiting far above. The prop was designed and built by the artist Wah Ming Chang. For a whole generation of viewers, the communicator showed what a personal, pocket-sized phone might look like.","Some engineers who later built real mobile phones grew up reading Dick Tracy or watching Star Trek. Did these stories directly cause the inventions? That is hard to prove, and people's memories of what inspired them can change over time. But science fiction did something important: it made a handheld phone seem like a normal, exciting thing to want. It gave people a picture to aim for."]},{"heading":"The Problem Waiting for a Clever Idea","paragraphs":["Let's pause and see how far the world had come by the early 1970s. A century earlier, a voice could not travel anywhere without a wire. Now radio linked ships across oceans, police cars across cities, and soldiers across battlefields. Rich businesspeople and doctors could make calls from their cars. Comic strips and TV shows were full of pocket communicators.","Yet the real mobile phone was stuck. Car phones were heavy, costly and nearly impossible to get. The problem was not that phones were too big, although they were. The deeper problem was the network: one giant transmitter per city, a handful of channels, and thousands of people stuck in line.","Engineers needed a way to let many more people use the same small number of channels at the same time. What if, instead of one giant tower shouting across the whole city, you used many small, quiet towers, each covering only a little patch of ground? What if the same channel could be used again and again in different patches, as long as they were far enough apart not to interfere? Surprisingly, a pair of engineers had already written down exactly this idea, back in 1947. They imagined chopping a city into small areas called 'cells.' It would take more than 25 years, and a race between two rival companies, before anyone could carry that idea in their hand. That story is next."]}],"deepDive":"Why could the 1940s car phone serve only a few thousand people in a whole country? The answer is spectrum, the limited range of radio frequencies that governments share out among users. Mobile Telephone Service used VHF frequencies, around 150 megahertz in its later high-band form, and each conversation occupied a channel tens of kilohertz wide. Because every city had a single high-power base station, often 100 to 250 watts, covering an area 65 to 100 kilometers across, each channel could carry only one conversation over that entire area. A useful way to think about capacity is simple division. If 2,000 New York customers shared 12 IMTS channels, that is about 167 customers per channel. Telephone engineers use a branch of mathematics called traffic theory (developed by the Danish engineer A. K. Erlang in the early 1900s) to estimate how long callers will wait for a free line. With so many users per channel, waits of tens of minutes at busy times were exactly what the math predicted. Half-duplex push-to-talk made things worse in the early MTS days, because a channel stayed busy even while each person was silently listening. Historians also debate several 'firsts' in this part. Bell, Elisha Gray and Antonio Meucci all worked on telephones, and the timing of Bell's and Gray's filings on February 14, 1876, is still argued about. Marconi's reception of the letter 'S' across the Atlantic in 1901 relied only on his own hearing, so some researchers doubt it, although regular transatlantic radio followed soon after. The walkie-talkie has at least three strong claimants: Donald Hings in Canada, Al Gross in the United States, and Motorola's wartime engineering team. Most careful historians conclude that portable two-way radio was developed by several people at once, because vacuum tubes, batteries and wartime demand had made it possible. The lesson for later parts is that progress needed not only smaller gadgets but a smarter way to reuse the same scarce frequencies.","funFact":"The Dick Tracy comic strip introduced its famous 2-Way Wrist Radio on January 13, 1946, about five months before the first public car phone service began in St. Louis on June 17, 1946.","check":{"q":"Why could only a few people use car phones at the same time in the 1940s and 1950s?","a":"Each city had one big transmitter and only a few radio channels, so each channel could carry just one call across the whole area.","wrong":["Because the phones had to be charged for a whole day between calls","Because the law allowed car phones only on Sundays","Because the telephone wires were too short to reach cars"]},"sources":[{"title":"Invention of the telephone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Invention_of_the_telephone"},{"title":"Guglielmo Marconi","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Guglielmo_Marconi"},{"title":"Walkie-talkie","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Walkie-talkie"},{"title":"SCR-536","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/SCR-536"},{"title":"Mobile Telephone Service","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mobile_Telephone_Service"},{"title":"Improved Mobile Telephone Service","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Improved_Mobile_Telephone_Service"},{"title":"History of mobile phones","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/History_of_mobile_phones"},{"title":"Dick Tracy","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Dick_Tracy"}],"photos":[{"src":"img/deep/smartphone/01-1.jpg","alt":"Alexander Graham Bell speaks into a telephone at the opening of the New York to Chicago line in 1892.","file":"Alexander Graham Bell at the opening of the long-distance line from New York to Chicago LCCN00650383.jpg","url":"https://commons.wikimedia.org/wiki/File:Alexander_Graham_Bell_at_the_opening_of_the_long-distance_line_from_New_York_to_Chicago_LCCN00650383.jpg","author":"Miscellaneous Items in High Demand, PPOC, Library of Congress","license":"Public domain"},{"src":"img/deep/smartphone/01-2.jpg","alt":"A US soldier in Aachen, Germany, talks to headquarters on a handheld Handie-Talkie radio in 1944.","file":"SC 195637 - In Aachen, Germany, Pfc. Ragnel Lundgren, Jamestown, New York, maintains continuous communications with his headquarters with a handie-talkie radio. 15 October, 1944. (52598916203).jpg","url":"https://commons.wikimedia.org/wiki/File:SC_195637_-_In_Aachen,_Germany,_Pfc._Ragnel_Lundgren,_Jamestown,_New_York,_maintains_continuous_communications_with_his_headquarters_with_a_handie-talkie_radio._15_October,_1944._(52598916203).jpg","author":"Signal Corps Archive from United States","license":"Public domain"},{"src":"img/deep/smartphone/01-3.jpg","alt":"Young Guglielmo Marconi with his early wireless telegraph transmitter and receiver, around 1897.","file":"Marconi and his wireless apparatus 1897.jpg","url":"https://commons.wikimedia.org/wiki/File:Marconi_and_his_wireless_apparatus_1897.jpg","author":"Unknown author","license":"Public domain"}],"words":3671},{"n":2,"title":"The First Handheld Call","when":"1947 – 1984","summary":"In 1973 an engineer named Martin Cooper stood on a busy New York street and made a phone call from a phone he held in his hand, with no wires and no car. His phone was as big as a brick and its battery lasted only about half an hour. Ten years later people could finally buy one, but it cost about as much as a small car!","sections":[{"heading":"A Memo Full of Hexagons","paragraphs":["Our story begins not with a gadget but with a piece of paper. On December 11, 1947, at Bell Telephone Laboratories in New Jersey, the research center of the giant AT&T telephone company, an engineer named Douglas H. Ring wrote an internal memo. A memo is a note sent around inside a company. Ring, working with his colleague W. Rae Young, described a new way to build a mobile phone network.","Remember the big problem from Part 1: each city had one huge, powerful transmitter, and every call used up a channel across the whole city. Ring and Young suggested the opposite. Divide the city into many small areas, each served by its own low-power antenna. They drew these areas as hexagons, six-sided shapes that fit together like the cells of a honeycomb, which is why we still say 'cell phone' today.","Here is the clever part. Because each small antenna is quiet, its signal fades out after a few kilometers. That means a channel used in one cell can be used again in another cell some distance away without the two calls bumping into each other. Instead of a city getting, say, 12 conversations at once, it might get 12 conversations in each of dozens of cells. When a driver moved from one cell to the next, the call would have to be passed from one antenna to the next, a trick called a handoff. (Part 12 explores how cells and handoffs work in much more detail.)","So why didn't anyone build it in 1947? Because the tools did not exist yet. Handing a call between towers in a split second needed fast electronic switching and computer control, and the transistor had only just been invented at Bell Labs that same year. Small, cheap computer chips were still decades away. The government had also not set aside enough radio frequencies. The idea had to wait, like a seed in dry ground, for the right conditions.","Over the next 25 years, Bell Labs engineers kept working on the problem. In the late 1960s and early 1970s, a team including Richard Frenkiel, Philip Porter and Joel Engel worked out how a real cellular system could be laid out: how big the cells should be, how to track moving cars, and how to split cells into smaller ones as more customers joined. In 1971 they sent a detailed plan for a 'High Capacity Mobile Telephone System' to the Federal Communications Commission (FCC), the US government agency that controls radio frequencies. Another Bell Labs engineer, Amos Joel Jr., received a patent in 1972 for a switching system that helped pass calls from one cell to the next as a caller moved. Many minds, over many years, built the cellular idea piece by piece.","Several of these engineers were later honored for their work. Amos Joel received some of the biggest prizes in engineering, including the Kyoto Prize in 1989 and the IEEE Medal of Honor in 1992, and he joined the National Inventors Hall of Fame in 2008. Joel Engel and Richard Frenkiel shared the US National Medal of Technology in 1994. Their names are much less famous than Martin Cooper's, but without them there would have been no cellular network for any handheld phone to connect to."]},{"heading":"Two Giants, Two Different Dreams","paragraphs":["By the early 1970s two companies were racing to make mobile phones real, and they had very different pictures in their heads.","AT&T, through Bell Labs, was the biggest telephone company in the world. In the United States it ran almost all telephone service. Its engineers imagined cellular service mainly for cars. That made sense: a car has a big battery to power a radio, plenty of space for equipment, and a roof to hold an antenna. In AT&T's vision, the mobile phone would be a better car phone.","Motorola saw things differently. Motorola, based near Chicago, did not run phone networks. It built radios: car radios, police radios, and the handheld Handie-Talkies used in World War II. Its engineers knew a lot about making tough, portable radios that people carried around all day. To Motorola, a phone should belong to a person, not a car. Why should you only be able to call when you were sitting in the driver's seat?","The two companies were not strangers. When the Bell System opened car phone service in Chicago in October 1946, the very first calls were carried on equipment made by Motorola. For decades Motorola had sold radios to the phone company, to police departments and to taxi firms. Now the supplier wanted to become a rival, and the competition between them would push both sides to move faster.","There was also a business worry. If the FCC handed all the new cellular frequencies to AT&T, AT&T might control the whole mobile phone world, the way it already controlled ordinary phones. Motorola wanted the government to allow competing companies into cellular service and to make room for portable phones. To win that argument in Washington, Motorola needed to show everyone that a handheld cellular phone was not a fantasy. It needed a phone people could see and touch. The man who took charge of that job was Martin Cooper."]},{"heading":"Marty Cooper and the 90-Day Phone","paragraphs":["Martin Cooper was born on December 26, 1928, in Chicago, the son of Jewish immigrants from Ukraine. He studied electrical engineering at the Illinois Institute of Technology, graduating in 1950, then served as an officer on submarines in the US Navy during the Korean War. In 1954 he joined Motorola, where he would spend 29 years. Along the way he also earned a master's degree in electrical engineering in 1957.","By the early 1970s Cooper was a senior manager in Motorola's communications business. His boss and mentor, John F. Mitchell, led Motorola's portable products and strongly backed the idea of a personal phone. Together they decided to build a working handheld cellular phone to prove their point, and to do it fast. According to Cooper, his team designed and built the first one in less than 90 days. Industrial designer Rudy Krolopp and his team shaped the case, and engineers crammed in the radio circuits, a microphone, a speaker, a keypad and a battery.","The result was called the DynaTAC, short for 'Dynamic Adaptive Total Area Coverage.' The prototype weighed about 1.1 kilograms (2.5 pounds), roughly as much as a big bag of sugar, and was about 25 centimeters (10 inches) tall, not counting its stubby antenna. It looked like a beige brick with buttons. Some people called it 'the shoe' phone. Inside were circuit boards packed with many separate electronic parts, because the tiny, powerful chips we have now did not exist yet. The battery alone made up a big part of the weight.","That battery was the weakest point. It gave only about 20 to 30 minutes of talking, and recharging it took about 10 hours. Cooper has joked that the short battery life did not really matter, because nobody could hold up such a heavy phone to their ear for longer than that anyway!","Cooper's story did not end with the DynaTAC. After leaving Motorola in the 1980s he co-founded several companies, including ArrayComm in 1992, which worked on smart antennas that help cell towers serve more people, and a company behind GreatCall, which made simple phones for older adults. He has also advised the FCC on technology. Well into his nineties, he was still giving interviews about the future of wireless communication."]},{"heading":"April 3, 1973: 'Joel, This Is Marty'","paragraphs":["Imagine Sixth Avenue in Manhattan on the morning of April 3, 1973. Yellow taxis honk, people in long coats hurry past, and the tall buildings of Midtown rise all around. Near the New York Hilton hotel, where Motorola is about to hold a press conference, a man in a suit stands on the sidewalk holding a beige plastic block to his ear. Passers-by stare. Some of them have never seen anyone talk on a telephone outdoors without a phone booth.","Motorola had placed a special base station, an antenna and radio receiver, on the roof of a nearby skyscraper called Burlington House. That base station was connected to the ordinary landline telephone network. So when Cooper dialed, the radio signal from his handset flew up to the rooftop antenna, then traveled along regular telephone wires to whoever he was calling.","And whom did he call first? Not his family, and not his boss. With a sense of humor and a bit of showmanship, Cooper called his biggest rival: Joel Engel, the head of the cellular research effort at Bell Labs. According to Cooper, he said something like: 'Joel, this is Marty. I'm calling you from a cell phone, a real handheld portable cell phone.' Imagine being the leader of the team at the world's largest phone company and hearing that your competitor had just beaten you to a working handheld phone!","This was the first public call made on a handheld cellular phone. It is important to be fair about what it meant. Cooper did not invent the telephone, radio, or the idea of cells, which came from Bell Labs in 1947. Many engineers at both Motorola and Bell Labs made cellular phones possible. What Cooper and his team proved was that a real person could carry a cellular phone in one hand, walk down a street and make a call. Motorola then showed the phone to reporters at its press conference.","In October 1973, Cooper and his colleagues applied for a patent on their 'Radio telephone system.' It was granted as US patent 3,906,166 on September 1, 1975, with Cooper as the lead inventor and John F. Mitchell among the names on it.","People love a good origin story, and one is often told about Cooper's phone: that he was inspired by the flip-open communicators on Star Trek. Cooper himself has told this story in different ways over the years. In some interviews and in at least one documentary, he linked the idea to Star Trek's communicator. At other times he has pointed instead to Dick Tracy's 2-Way Wrist Radio, the comic strip gadget he remembered from his youth.","So what is the truth? We can only say that these are Cooper's own later memories, told decades after the events. Memories change as we retell them, and a fun story sometimes grows in the telling. What we can say for certain is that Motorola had very practical reasons to build a handheld phone, including its long experience with portable radios and its battle with AT&T over who would run cellular service. Science fiction may have helped people imagine the future, but engineering, business and government decisions did the heavy lifting."]},{"heading":"Ten Long Years of Waiting","paragraphs":["You might think that after such a dramatic demonstration, everyone could buy a cell phone the next year. Not at all! It took about another ten years, and Motorola spent more than 100 million dollars on development, before a handheld cellular phone went on sale in the United States.","There were three big hurdles. First, the government. The FCC had to decide which radio frequencies to give to cellular service and who could use them. Cooper spent roughly a decade traveling to Washington, meeting officials and arguing that competing companies, not just AT&T, should be allowed to run cellular networks. In the end, the FCC decided that each city would have two cellular companies: one connected to the local telephone company and one independent competitor.","Second, the networks. A handheld phone is useless without towers to talk to, and building a cellular network meant putting up many base stations, linking them to computers that could hand calls from cell to cell, and testing everything. Bell Labs began a trial of its cellular system, called AMPS (Advanced Mobile Phone System), in Chicago in 1978, first with about 100 test units and then with a service test of about 2,000 paying customers. Bell Labs had been developing AMPS since 1968.","Third, the phone itself. The 1973 prototype was a demonstration, not a product. Motorola's engineers spent years making the phone lighter, more reliable, and able to work on the real AMPS network. They went through several versions. By 1983 the handset weighed about half as much as the original prototype."]},{"heading":"Tokyo, Scandinavia and Chicago Switch On","paragraphs":["While the Americans argued about rules, other countries moved ahead. In 1979 the Japanese telephone company NTT (Nippon Telegraph and Telephone) launched the world's first commercial cellular network in Tokyo. It was designed for car phones, and within about five years it had spread across Japan, making it one of the first cellular systems to cover a whole country. Japan, as you will see in Part 6, would keep surprising the world with its phones.","Next came the Nordic countries: Sweden, Norway, Denmark and Finland. Their phone companies worked together on a shared system called NMT (Nordic Mobile Telephone). The Swedish company Ericsson ran an early NMT pilot in Saudi Arabia from September 1, 1981, with about 1,200 users. Then NMT opened in Sweden in October 1981 and Norway in November 1981, followed by Denmark and Finland in 1982. NMT used radio frequencies around 450 megahertz.","NMT had a feature that was amazing for its time: roaming. A customer could drive from Sweden into Norway or Finland and keep using the same phone, because all the countries used the same standard. NMT also dialed calls automatically and handed calls from cell to cell from the start. By 1985 it had about 110,000 subscribers across Scandinavia and Finland, about 63,300 of them in Norway alone, making it the largest mobile phone network in the world at that time.","NMT kept growing. In 1986 a new version called NMT-900, using higher frequencies with room for more channels, was added, and over the following years NMT networks opened in many other countries, from Switzerland and Poland to Russia, Thailand and China. Nokia, then a Finnish company better known for many other products, built NMT phones such as the Mobira Cityman 150 of 1989. You will hear much more about Nokia in later parts.","In the United States, the big day was October 13, 1983. Ameritech, the regional telephone company serving the Chicago area, officially launched commercial AMPS cellular service. Celebratory first calls were made that day near Soldier Field, Chicago's football stadium, and according to accounts of the launch, one of them went all the way to Germany, to a grandson of Alexander Graham Bell. It was a neat way of linking the first telephone to the first American cellular service.","These first-generation, or 1G, networks were analog. That means your voice traveled as a smooth radio wave that copied the shape of the sound wave, rather than being turned into digital numbers. AMPS used frequencies around 800 to 900 megahertz, and each conversation used a pair of channels, one for each direction. Each city's two carriers started with 333 channel pairs each, hundreds more than the dozen or so channels of the old car phone systems, and because the channels could be reused in cell after cell, the network could carry far more calls than ever before."]},{"heading":"How the Brick Made a Call","paragraphs":["Let's follow a single call on the new American network in 1984, step by step, to see how different it was from the old car phones.","When you switched on your DynaTAC, it did not just wait silently. It listened to special control channels, which are like a radio noticeboard that each cell tower uses to send instructions. On AMPS, each carrier set aside 21 control channels for this job. Your phone picked the strongest control signal nearby, which told it which cell it was in.","To call someone, you typed the number on the keypad, checked it on the red display, and pressed 'Snd.' The phone sent the number and its own identity to the tower over the control channel. A computer at the network's switching center checked that you were a paying customer, picked a free voice channel in your cell, and told your phone to tune to it. Then it connected you through the ordinary telephone network to the person you were calling. No operator was involved at all.","Now imagine you were walking or being driven across town while talking. As you moved away from one tower, your signal grew weaker there and stronger at the next tower. The switching computer noticed, chose a free channel in the new cell, and told your phone to jump to it. This handoff took only a moment, so you usually heard nothing more than a tiny click. Meanwhile, the channel you had just left became free for someone else in the old cell.","Your voice traveled as an analog signal, using a method called frequency modulation (FM), the same basic method used by FM music radio. The radio wave's frequency wiggled up and down in step with your voice. That kept the sound fairly clear, but it had a downside: anyone with the right scanner radio could listen in, so calls were not private. Making calls secret and squeezing more calls into the same frequencies were two big reasons engineers later switched to digital phones, as Part 3 explains.","Around the world, other first-generation networks followed in the mid-1980s, such as West Germany's C-Netz in 1985. Even so, mobile phones stayed rare for years. In Japan, home of the very first cellular network, only about 0.15 percent of people had a mobile phone subscription in 1989. The technology worked; it was simply far too expensive for most families."]},{"heading":"The Brick Goes on Sale","paragraphs":["Motorola unveiled its finished phone, the DynaTAC 8000X, on March 6, 1983. The FCC approved it on September 21, 1983, making it the first handheld cellular phone approved for sale in the United States. Large-scale production began in early 1984, and many eager buyers put their names on waiting lists.","What did you get? A phone about 25 centimeters (10 inches) tall that weighed about 790 grams (1.75 pounds), roughly as much as three cans of soda. It had a keypad with 12 number keys plus extra buttons with labels such as 'Rcl' (recall), 'Snd' (send) and 'Pwr' (power). A glowing red LED display showed the digits you dialed, and the phone could remember 30 phone numbers. A full charge took about 10 hours and gave about 30 minutes of talk time. There were no apps, no camera, no texting and no games. It made phone calls, and that was all.","And the price? 3,995 dollars. That is roughly 12,000 dollars in today's money, about as much as a small used car. On top of that, customers paid monthly fees and high charges for every minute they talked. Not surprisingly, early buyers were mostly wealthy businesspeople, stockbrokers, doctors and celebrities.","Because of its size, shape and weight, people quickly gave the DynaTAC a nickname that stuck: 'the brick.' Carrying one said something about you. It told everyone you were important, rich, and so busy that you needed to make calls from the sidewalk. In films and television of the 1980s, the brick phone became a symbol of power and money.","Owning a brick also took planning. Because the battery lasted only about half an hour of talking, many owners carried a spare battery, and Motorola offered a separate fast charger that could refill a battery in about an hour instead of ten. Phone calls dropped when you wandered outside the few cities that had cellular service, because towers had only been built in and around big urban areas. Still, for the first time, a person could stand on a street corner, at a beach, or in a stadium and talk to anyone with a telephone. Motorola kept making DynaTAC models for about ten years, and in 1989 it introduced a smaller, folding successor called the MicroTAC.","From the memo of 1947 to the brick of 1984, about 37 years had passed. A dream drawn as hexagons on paper had become a real phone in a real person's hand. But it was still huge, expensive, and could only carry voices. Over the next 15 years, engineers would shrink phones until they fit in a shirt pocket, slash their prices so that teenagers could own them, and teach them a brand-new trick: sending words, not just voices. That is where Part 3 picks up the story."]}],"deepDive":"The cellular idea works because of frequency reuse, and a little geometry shows why it is so powerful. Engineers group neighboring cells into clusters, often seven cells in a classic hexagonal layout, and give each cell in the cluster a different set of channels. The same pattern then repeats across the city. The minimum distance between two cells using the same channels is D = R times the square root of 3N, where R is the cell radius and N is the number of cells in a cluster. With N = 7, D is about 4.6 times the cell radius, far enough that the weak signals barely interfere. In early AMPS, each carrier received 333 channel pairs (each voice channel 30 kilohertz wide in each direction). Divided across a 7-cell cluster, that is about 47 channels per cell. A city of 50 cells could therefore carry over 2,000 simultaneous calls on the same frequencies that once allowed a handful, and when a busy cell filled up, engineers could split it into smaller cells, multiplying capacity again. That was the key advantage over IMTS. The price was complexity: computers had to track which cell each phone was in and hand calls over within a fraction of a second, which is why the concept of 1947 could not be built until the 1970s and 1980s. Historians and engineers also discuss credit. Bell Labs engineers conceived cells and handoffs; Motorola built the first handheld cellular phone. In 2013 the National Academy of Engineering awarded the Charles Stark Draper Prize jointly to Martin Cooper, Joel Engel, Richard Frenkiel, Thomas Haug (a key figure behind NMT) and Yoshihisa Okumura (who worked on NTT's system), recognizing that many people built mobile phones. Sources also disagree on details: the 1973 prototype's weight is given as about 1.1 kg in some accounts, while Motorola's 1973 announcement spoke of about 1.4 kg (3 pounds), and DynaTAC talk time is quoted as 30 to 60 minutes. That is a good reminder to compare sources.","funFact":"On the day American cellular service launched in Chicago, October 13, 1983, one of the celebratory calls is said to have gone to Germany, to a grandson of Alexander Graham Bell.","check":{"q":"Whom did Martin Cooper call during the first public handheld cellular phone call on April 3, 1973?","a":"Joel Engel, his rival at Bell Labs","wrong":["His mother in Chicago","The President of the United States","Alexander Graham Bell"]},"sources":[{"title":"Martin Cooper (inventor)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Martin_Cooper_(inventor)"},{"title":"Motorola DynaTAC","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Motorola_DynaTAC"},{"title":"Cell Phone Development (Motorola heritage)","publisher":"Motorola Solutions","url":"https://www.motorolasolutions.com/en_us/about/company-overview/history/explore-motorola-heritage/cell-phone-development.html"},{"title":"Advanced Mobile Phone System","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Advanced_Mobile_Phone_System"},{"title":"Nordic Mobile Telephone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nordic_Mobile_Telephone"},{"title":"Cellular network","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Cellular_network"},{"title":"Richard H. Frenkiel","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Richard_H._Frenkiel"},{"title":"1G","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/1G"}],"photos":[{"src":"img/deep/smartphone/02-1.jpg","alt":"Martin Cooper, inventor of the handheld cell phone, holds his 1973 DynaTAC prototype in 2007.","file":"2007Computex e21Forum-MartinCooper.jpg","url":"https://commons.wikimedia.org/wiki/File:2007Computex_e21Forum-MartinCooper.jpg","author":"Rico Shen","license":"CC BY-SA 3.0"},{"src":"img/deep/smartphone/02-2.jpg","alt":"The Motorola DynaTAC 8000X, the first handheld cell phone sold to the public, nicknamed \"the brick\".","file":"Motorola DynaTAC 8000X.png","url":"https://commons.wikimedia.org/wiki/File:Motorola_DynaTAC_8000X.png","author":"Avicente05","license":"CC BY-SA 4.0"},{"src":"img/deep/smartphone/02-3.jpg","alt":"Hexagon cells in clusters of 3, 4 and 7: cells with the same number reuse the same radio frequencies.","file":"Frequency reuse factors.png","url":"https://commons.wikimedia.org/wiki/File:Frequency_reuse_factors.png","author":"Johannes M","license":"CC BY-SA 4.0"}],"words":3701},{"n":3,"title":"Phones Shrink and Learn to Text","when":"1985 – 2000","summary":"In just fifteen years, phones went from heavy bricks to little gadgets that fit in your pocket. They started turning voices into numbers, learned to send short text messages, and even came with a game about a hungry snake. Soon teenagers were picking phones the way they picked sneakers.","sections":[{"heading":"From Smooth Waves to Strings of Numbers","paragraphs":["At the end of Part 2, the brick phone was a toy for the rich. It worked, but it had a secret weakness hidden inside the way it talked. Phones like the DynaTAC belonged to what we now call the first generation, or 1G. A 1G phone sent your voice as an analog radio wave. Analog means the wave copies the shape of the sound itself: when your voice went up and down, the radio wave wiggled up and down in the same pattern, like a copy traced on tracing paper.","Analog radio is simple, and it was a brilliant first step. But it had problems. A smooth wave picks up every bit of noise along the way, so calls could be full of hiss and crackle, especially at the edge of a cell. Worse, anybody with the right kind of radio scanner could tune in and listen to your conversation, because the wave was not scrambled at all. Criminals also learned to 'clone' phones by copying the identity numbers that analog phones broadcast, so that someone else's calls were charged to your bill.","There was a bigger problem in Europe. Different countries had built different analog systems. The Nordic countries used NMT, Britain used a system called TACS, West Germany had its own network, and France had another. A phone that worked in Stockholm might be useless in Paris.","The answer was the second generation, 2G. A 2G phone does something clever before it sends your voice: it measures the sound thousands of times every second and turns each measurement into a number, written in binary as 1s and 0s. Those numbers are squeezed down (compressed) so that fewer of them are needed, and then they are sent by radio. At the other end, a chip turns the numbers back into sound. This is what engineers mean by digital.","Turning a voice into numbers brought three big gifts. First, numbers can be scrambled with a secret code, called encryption, so a stranger with a scanner hears only nonsense. Second, digital signals use the radio spectrum much more efficiently. In the GSM system, for example, each radio channel is chopped into eight tiny time slots that take turns many times a second. Eight people can share one channel, each speaking in their own slice of time, and none of them notices the sharing. This trick is called TDMA, which stands for time-division multiple access. Third, once a phone is sending numbers anyway, it can send other kinds of numbers too: not just voices, but letters. That last gift would change the world, as we will see.","2G did not come in only one flavor. Europe built GSM. In North America, many networks used a digital version of the old American system, called D-AMPS, while others chose a rival technology called cdmaOne (also known as IS-95), first switched on in 1995, which let many calls share the same frequencies at the same time by giving each call its own special code. Japan built its own standard, called PDC. All of them were digital, and all of them were a big jump from 1G. But GSM was the one that spread across the planet."]},{"heading":"Europe Agrees: GSM and the Prime Minister's Call","paragraphs":["In the early 1980s, European telephone officials looked at their messy patchwork of analog networks and decided to do something unusual: they would design one shared digital system for the whole continent. In 1982 and 1983 a committee was set up under a European telecommunications group called CEPT. It was named the Groupe Spécial Mobile, which is French for 'Special Mobile Group'. Its initials, GSM, became the name of the standard. Later, as the system spread far beyond Europe, people decided GSM should stand for Global System for Mobile Communications instead.","Designing a phone system that dozens of companies and countries could all build was slow, careful work. Engineers from many nations argued about radio frequencies, how voices should be compressed and how phones should prove who they were. In 1987, representatives from 13 European countries met in Copenhagen, Denmark, and signed an agreement promising to build GSM networks. In 1989 the work moved to a new European standards body called ETSI.","Then came the big moment. On July 1, 1991, in Finland, Prime Minister Harri Holkeri picked up a GSM phone and called Kaarina Suonio, the deputy mayor of the city of Tampere. The call travelled over the network of a brand-new Finnish operator called Radiolinja, using equipment from the Finnish company Nokia and the German company Siemens, on radio waves around 900 megahertz. It is celebrated as the world's first GSM call. To be fair to history, engineers had already made test calls on the network before that day, and at least one former Nokia engineer later said he had made a test call a few hours before the prime minister. But Holkeri's call was the official one, the moment the world noticed.","Nokia is worth a quick detour, because it will be a star of this part. The company began back in 1865 as a wood-pulp mill on the rapids of the Tammerkoski river near Tampere, founded by an engineer named Fredrik Idestam. Over the next century it made rubber boots, cables, tires, televisions and computers. In January 1992, a new boss, Jorma Ollila, decided Nokia should focus on telecommunications and sell off most of its other businesses. That same year, in November 1992, Nokia launched the Nokia 1011, the first GSM phone sold to the public. It was a bold bet, and it paid off spectacularly.","GSM spread fast. Because it was one shared standard, a traveler could carry a GSM phone from Finland to Germany to Italy and keep using it, a trick called roaming. Countries in Asia, Africa, the Middle East and eventually the Americas joined in. By 2004 there were more than 1 billion GSM subscribers, by 2008 more than 3 billion, and GSM eventually ran in well over 200 countries and territories. Few technologies in history have spread to so many people so quickly."]},{"heading":"The Tiny Card That Knows Who You Are","paragraphs":["With 1G phones, your phone number and account were usually built into the phone itself. If you wanted a new phone, the phone company had to set it up for you. GSM's designers had a smarter plan: put your identity on a removable smart card. They called it the SIM, which stands for subscriber identity module. A subscriber is simply a customer who pays for the phone service.","The first SIM cards were made in 1991 by Giesecke+Devrient, a company in Munich, Germany, that was famous for printing banknotes and making smart cards. It sold 300 of them to Radiolinja in Finland, the network that carried the first GSM call. Those first SIMs were as big as a credit card, about 85.6 by 54 millimeters, because they were based on the same smart-card design used for bank cards.","As phones shrank, so did the SIM. The 'mini-SIM' arrived in 1996, about 25 by 15 millimeters, roughly the size of a postage stamp. That is the one many of your parents remember snapping out of a credit-card-sized holder. The 'micro-SIM' (15 by 12 millimeters) followed in 2003, and the 'nano-SIM' in 2012, at about 12.3 by 8.8 millimeters and only 0.67 millimeters thick, which is thinner than a fingernail. Many modern phones now use an eSIM, a chip soldered inside that can be programmed over the air, but the idea is still the same.","So what does the SIM actually hold? Two especially important things. One is a long number called the IMSI (international mobile subscriber identity), which tells the network which customer you are. The other is a secret key, a 128-bit number. 128 bits means a string of 128 ones and zeros, so there are more possible keys than there are grains of sand on all the beaches on Earth. The phone company keeps a copy of your key in a guarded computer called the authentication center.","Here is the clever part. The key is never sent over the radio, and the SIM is built so that even the phone cannot read it out. When your phone joins the network, the network sends a random number as a challenge. The SIM mixes that number with its secret key using a special formula and sends back the answer. The network does the same calculation with its own copy of the key. If the answers match, you are who you say you are. It is like a secret handshake where the handshake changes every time, so an eavesdropper who hears one answer cannot reuse it.","SIMs also brought a feature that felt like magic in the 1990s: you could pull your SIM out of one phone, push it into another, and the new phone instantly became 'yours', with your number and your saved contacts. To stop thieves, a SIM can be locked with a four-digit PIN code. If someone guesses wrong three times, the SIM locks itself and needs a longer code called a PUK to unlock. Now our digital, secure, swappable phone was ready for its most famous trick."]},{"heading":"Merry Christmas: The First Text Message","paragraphs":["The idea of sending short written messages through the phone network began years before anyone did it. In 1984, two engineers working on the French-German side of the GSM planning, Friedhelm Hillebrand of Germany and Bernard Ghillebaert of France, worked out a way to slip little notes into the network almost for free. A mobile network is always sending small control signals back and forth between phones and towers: 'Are you there?', 'Here I am', 'Ring this phone'. Those signals travel in special signalling channels that are not full most of the time. Hillebrand and Ghillebaert realized that short messages could ride along in the spare space, like letters tucked into the gaps of a delivery van that was making the trip anyway.","But how short is short? The story goes that Hillebrand sat at his typewriter writing out typical sentences and questions, and he looked at postcards and Telex messages (an old system for sending typed messages along telegraph lines). Most of them fitted easily into about 160 characters. That became the famous limit. It was not a random number. The messages had to fit the size of the existing signalling packets, which held 140 bytes, or 1,120 bits. If each character uses 7 bits instead of the usual 8, then 1,120 divided by 7 gives exactly 160 characters. So the 160-character text message is really a piece of clever arithmetic.","The service was named SMS, for short message service. GSM documents approved it in 1985, and a draft of its technical rules was ready by 1987. Then, for years, nobody really used it. Phone companies thought it might be handy for sending customers little alerts, like 'You have a voicemail', rather than for people chatting with each other.","Now picture an office in Newbury, a town in the south of England, in early December 1992. Neil Papworth, a 22-year-old developer and test engineer at a company called Sema Group, was building a message center for the British phone company Vodafone. The message center was the computer that would receive texts and pass them on. To prove that it worked, someone had to actually send a message to a real phone.","On December 3, 1992, Papworth typed two words on a computer keyboard: 'Merry Christmas'. Phones of the time had no proper way to type letters, so the first text in history was sent from a computer, not from a phone. It travelled across Vodafone's GSM network and appeared on an Orbitel 901 handset belonging to Richard Jarvis, a Vodafone director, who was at the company's Christmas party. The handset could receive the message but had no way to type a reply. To Papworth it was simply a successful test on a busy workday. Nobody in the room could have guessed that trillions of messages would follow.","Sending texts between ordinary customers took a little longer. In 1993, the Finnish operator Radiolinja (the same network that carried the first GSM call) offered one of the first texting services that customers could pay for, and the first message sent by one person to another over a phone network is usually dated to that year in Finland. In January 1994 Nokia released a phone, the Nokia 2010, that made typing a message much easier.","At first, texting grew slowly. In 1995, the average GSM customer sent fewer than one text every two months, about 0.4 messages a month. Then young people discovered it. A text was cheap, quiet, private and could be read later, so you could send one from the back of a bus or under the table. By the end of 2000, the average user was sending around 35 texts a month. In the Philippines, where texts were much cheaper than calls, people sent so many messages that by 2001 the country was nicknamed the 'texting capital of the world'. Worldwide, the number of texts climbed from about 366 billion in 2002 to about 6.1 trillion in 2010. A service designed for voicemail alerts had become one of the most popular ways humans have ever talked to each other."]},{"heading":"Typing With Your Thumbs: Multi-Tap and T9","paragraphs":["There was just one catch: a 1990s phone had 12 buttons, and the alphabet has 26 letters. The answer was to share. Look at the number keys on any phone keypad, even the one on a smartphone screen today, and you will still see letters printed under the numbers: ABC on 2, DEF on 3, GHI on 4, JKL on 5, MNO on 6, PQRS on 7, TUV on 8 and WXYZ on 9.","The first way of texting is called multi-tap. You press a key once for its first letter, twice for its second letter, and so on. To type S, you press 7 four times: P, Q, R, S. To type the word 'hello', you press 4 twice for H, 3 twice for E, 5 three times for L, then wait for a moment so the phone knows you have finished that letter, 5 three times again for the second L, and finally 6 three times for O. That is 13 presses and a pause, just for one friendly word. The pause matters: if you want two letters from the same key in a row, you have to wait for the cursor to move on, or the phone thinks you are still cycling through the first letter.","Texters became astonishingly fast anyway, and they invented a new kind of spelling to save presses: 'c u l8r' for 'see you later', 'gr8' for 'great', and 'txt' for 'text'. Teachers and grandparents sometimes worried that this shorthand would ruin people's spelling. Many language experts have since argued that it was mostly a playful code that people switched on and off, rather like slang, and that you have to know how to spell a word before you can cleverly shorten it.","A smarter method grew out of an unexpected place. In 1987, a team that included Martin King, Dale Grover and Cliff Kushler began working on a way for people with disabilities to type using eye movements, choosing from a small number of groups of letters. They noticed that their letter groups worked a lot like a phone keypad, which also has only eight keys with letters on them. If a computer had a good dictionary, it could guess which word you meant from just one press per letter.","They called it T9, short for 'Text on 9 keys'. With T9, you press each key just once and the phone looks up every word that matches that pattern of keys, showing the most common one first. Typing 4-3-5-5-6 gives 'hello' in five presses instead of thirteen. Sometimes several words share the same keys. For example, the keys 3-6-7-3 can spell 'ford', 'dose' and 'fore', so the phone shows one and you press a 'Next' key to see the others. T9 even learned from you, putting the words you chose most often at the top of the list.","The team founded a company called Tegic Communications in Seattle in 1996, and T9 first appeared in September 1997 on a small organizer, the Texas Instruments Avigo. The first phone with T9 was a Samsung model sold in South Korea in April 1998, and the Finnish Benefon iO, announced in 1999, was the first GSM phone with it. Soon phone makers everywhere licensed T9 or built their own versions, and predictive text became normal on almost every phone. In a way, it is the great-grandparent of the word suggestions that pop up above your keyboard today."]},{"heading":"Pocket Stars: StarTAC, Snake and the Nokia 3310","paragraphs":["While networks went digital, the phones themselves were shrinking at amazing speed. Remember that the DynaTAC brick weighed about 790 grams. On January 3, 1996, Motorola unveiled the StarTAC, which weighed as little as 88 grams in its lightest version, less than a chocolate bar and about one-ninth of the brick. It was the smallest and lightest phone of its time.","The StarTAC was a clamshell, or flip phone. Closed, it was a neat little shell you could clip to a belt or drop into a shirt pocket. Flicking it open with one hand made a satisfying snap. It was not the first clamshell phone (NEC, a Japanese company, had made one earlier in the 1990s), but it was the one that made folding phones fashionable. It could also vibrate instead of ringing, which seems ordinary now but was a big deal then: you could feel a call arrive in a quiet meeting without disturbing anyone. It launched at about 1,000 dollars, and many people got it by signing a long phone contract instead of paying all at once. In South Korea it became so popular that it pushed Samsung to design clamshell phones of its own.","Meanwhile, Nokia was racing ahead. In October 1998, Nokia overtook Motorola as the best-selling mobile phone brand in the world, a position it held for about a decade. One reason was a phone announced in December 1997 and sold from 1998: the Nokia 6110. It was a business phone, with a calculator, calendar and currency converter, and it was the first GSM phone powered by an ARM processor, a power-saving chip design you will meet properly in Part 11. It was also Nokia's first phone with an infrared port, a little dark window that could send data on invisible light, like a TV remote.","But people remember the 6110 for something much more fun: Snake. The idea of a game where you steer a line that keeps moving and must never crash into a wall or itself goes back to an arcade game called Blockade from 1976. At Nokia, an engineer named Taneli Armanto, who worked in a group designing how phones' menus and screens should behave, programmed a version for the 6110's tiny black-and-white screen. Your snake slithers around eating dots, and every dot makes it longer, so the game gets harder the better you do. Two players could even battle each other by pointing their phones' infrared windows at each other.","Snake was simple, but it was always in your pocket and it was free. Millions of people who had never owned a games console played it on buses, in waiting rooms and during boring car journeys. Nokia put Snake on phone after phone, and later versions added mazes and color. According to Nokia, hundreds of millions of copies of Snake exist in one form or another, which may make it one of the most played video games ever.","Then, announced on September 1, 2000, came the phone that many people still call a legend: the Nokia 3310. It weighed about 133 grams and fit comfortably in one hand. It had a removable battery that lasted for days, more than 35 built-in ringtones, a calculator, a stopwatch, and four games, including Snake II and a space shooter called Space Impact. Its 'Chat' feature showed a conversation of texts in order, a little like a modern messaging app, and it could join several texts together to send messages up to 459 characters long.","The 3310 was cheap enough for ordinary families and tough enough to survive being dropped. People joke that it was 'indestructible' and that it could crack the floor instead of its own screen. That is a joke, of course; a 3310 could certainly break, but it was famously sturdy. Nokia sold about 126 million of them, which makes it one of the best-selling phones in history. In 2015 Finland even chose it as one of its official 'national emojis', and in 2017 a new company that now made Nokia phones released a modern version as a nostalgic treat."]},{"heading":"Ringtones, Covers and a Phone That Says Who You Are","paragraphs":["Something else was changing in the late 1990s: who owned phones. In 1985 a mobile phone was a tool for business people and the wealthy. By 2000, in countries like Finland, Britain, Italy and Japan, teenagers were carrying them in their school bags. And teenagers did not just want a phone. They wanted a phone that looked like them.","Nokia noticed. Phones like the Nokia 5110 and 3210 had covers that you could pop off and replace in seconds. Nokia called its version Xpress-On covers. Shops and market stalls sold them in every color and pattern imaginable: see-through plastic, flames, flowers, football teams, glow-in-the-dark. The 3310 alone had thousands of cover designs made by different companies. A phone became something like a sticker-covered pencil case, a little piece of personal style.","Then there was sound. The most famous ringtone of all, the 'Nokia tune', is a short phrase from a piece of classical guitar music called Gran Vals, written in 1902 by the Spanish guitarist Francisco Tárrega. Nokia had used the melody in an advert for the Nokia 1011 in 1992, and it first appeared as a ringtone on the Nokia 2110 in 1994. At first it was just called 'Type 5'. On the 6110 it was named 'Grande valse', and in 1998 it was renamed 'Nokia tune'. A 2009 estimate suggested it was being heard around 1.8 billion times a day across the world, about 20,000 times every second.","Hearing the same tune from everybody's pocket gave people an idea: why not choose your own? In Japan in 1996, a phone made by the company Denso let owners type in their own melodies, note by note. A Japanese book of instructions for programming pop songs into phones reportedly sold more than 3.5 million copies.","In 1998, Radiolinja in Finland launched a service called Harmonium, invented by Vesa-Matti Paananen, that let people get new ringtones sent straight to their phone by text message. It is often described as the first downloadable ringtone service, one of the very first times people got something digital delivered to a phone through the air, years before app stores. Ringtones quickly became big business. By the early-to-mid 2000s, people around the world were spending a few billion dollars a year on them.","By the year 2000, the mobile phone had been transformed. It weighed a sixth of the brick or less, it fit in a pocket, its calls were digital and private, its battery lasted days instead of minutes, and hundreds of millions of people owned one. It could send words as well as voices, play a game and show off your taste in music and color.","But something was still missing. A phone could hold a list of names and send 160 characters, yet it could not keep your full diary, hold your notes or work like a real computer. Many people who wanted those things carried a second gadget in their other pocket. While phones were learning to talk and text, a different family of little machines had been growing up alongside them: pocket computers. That is where we go next."]}],"deepDive":"Why exactly 160 characters? The GSM signalling packets that carry SMS have room for 140 bytes of user data, which is 1,120 bits. GSM uses a special 7-bit alphabet for ordinary Latin letters, digits and common punctuation, so 1,120 / 7 = 160 characters. If you type characters outside that alphabet, such as Chinese characters, Arabic letters or most emoji, phones switch to a 16-bit encoding called UCS-2 (a forerunner of UTF-16), and the limit falls to 140 / 2 = 70 characters per message. Longer texts are split into pieces, each carrying a small header that tells the receiving phone how to stitch them back together, which is how the Nokia 3310 could send 459-character messages. Engineers also argue about what made 2G so much better than 1G. Encryption and the SIM ended easy eavesdropping and cloning, although GSM's original A5/1 cipher was later shown by researchers to be breakable, and only the radio link between phone and tower was protected. Capacity was the other prize: GSM's TDMA divides each 200-kilohertz channel into eight time slots, while the rival cdmaOne system spreads all calls across a wide band and separates them by code, and supporters of each claimed theirs carried more calls. The CDMA approach went on to shape 3G, while GSM won the 2G popularity contest by sheer scale, with more than 3 billion subscribers by 2008. Historians also debate 'firsts'. Harri Holkeri's call of 1 July 1991 is the celebrated first GSM call, but test calls were made earlier on the same network, and a former Nokia engineer later said he made one a few hours before the prime minister. Likewise, Neil Papworth's 1992 'Merry Christmas' was the first SMS, but it came from a computer; the first person-to-person text between phones followed in Finland in 1993. Being careful about these details is part of telling the story fairly.","funFact":"The very first text message, 'Merry Christmas', was typed on a computer, not a phone, because the phones of 1992 had no way to write letters.","check":{"q":"Why is a standard text message limited to 160 characters?","a":"Because the signalling space holds 140 bytes (1,120 bits), and 1,120 bits divided by 7 bits per character makes 160 characters.","wrong":["Because Neil Papworth's first message happened to be 160 letters long","Because phone screens in 1992 could only show 160 letters","Because the GSM committee had 160 members, one for each letter"]},"sources":[{"title":"SMS","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/SMS"},{"title":"GSM","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/GSM"},{"title":"SIM card","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/SIM_card"},{"title":"T9 (predictive text)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/T9_(predictive_text)"},{"title":"Motorola StarTAC","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Motorola_StarTAC"},{"title":"Nokia 6110","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nokia_6110"},{"title":"Nokia 3310","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nokia_3310"},{"title":"Nokia tune","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nokia_tune"}],"photos":[{"src":"img/deep/smartphone/03-1.jpg","alt":"A blue Nokia 3310 with its simple black-and-white screen (set to German) and number keypad.","file":"Nokia 3310 blue.jpg","url":"https://commons.wikimedia.org/wiki/File:Nokia_3310_blue.jpg","author":"Michael Brandtner","license":"Public domain"},{"src":"img/deep/smartphone/03-2.jpg","alt":"A Motorola StarTAC flip phone from 1997, flipped open to show its keypad and small screen.","file":"MotorolaStarTAC.jpg","url":"https://commons.wikimedia.org/wiki/File:MotorolaStarTAC.jpg","author":"ProhibitOnions at English Wikipedia","license":"CC BY-SA 3.0"},{"src":"img/deep/smartphone/03-3.jpg","alt":"SIM cards keep shrinking: Mini, Micro and Nano SIM, plus a tiny eSIM chip soldered inside phones.","file":"SIM card sizes.png","url":"https://commons.wikimedia.org/wiki/File:SIM_card_sizes.png","author":"Jbond2018","license":"CC0"}],"words":4274},{"n":4,"title":"Pocket Computers: The PDA","when":"1984 – 2005","summary":"Long before smartphones, people carried little computers that could keep a diary, an address book and notes, but could not make a single phone call. One inventor tested his design by carrying a block of wood in his pocket! Soon busy people had a phone in one pocket and a pocket computer in the other.","sections":[{"heading":"A Diary That Thinks","paragraphs":["Picture a busy office worker in the early 1980s. In one pocket there is a fat paper diary stuffed with appointments. In a briefcase there is a card index, or a ring binder full of names, addresses and phone numbers, with crossings-out where people have moved house. On the desk there are sticky notes, a calculator and a to-do list written on the back of an envelope. If the diary falls in a puddle, months of plans are smudged away. If the address book is lost, so is every contact.","Computers could already store all of this information neatly. The trouble was that computers lived on desks. A personal computer of 1984 had a heavy box, a separate keyboard and a screen as deep as a small television. Even 'portable' computers of the time were the size of a sewing machine and weighed around 10 kilograms. Nobody was going to carry one to a meeting just to check a date.","So inventors began asking a simple question: what if a tiny computer did just a few jobs, but did them anywhere? It would not need to run big programs or print letters. It would only need to remember your calendar, your contacts, your notes and your to-do list, and it would need batteries that lasted a long time. This kind of gadget came to be called a PDA, short for personal digital assistant. 'Personal' because it was yours alone, 'digital' because it was a computer, and 'assistant' because it was meant to help you, like a very organized secretary who lived in your pocket.","One thing is important to understand from the start: a PDA was not a phone. Most PDAs could not make calls or send text messages at all. They were organizers. To share information with other people or with your main computer, you usually had to plug them in. That separation between the phone in one pocket and the organizer in the other is the whole story of this part, and it explains why someone would eventually try to squash the two together.","The tools that made PDAs possible were the same ones shrinking mobile phones. Microchips were getting smaller and cheaper. Liquid-crystal displays (LCDs), the gray screens on calculators and digital watches, used very little power. Memory chips that could hold thousands of letters were becoming affordable. Put them together in a plastic case with a few batteries, and you had a computer you could hold in one hand."]},{"heading":"The Psion Organiser: A London Pioneer","paragraphs":["The first gadget usually called a PDA came not from California but from London. A company named Psion had been founded there in 1980 by David Potter, a South African-born British businessman. Psion started out writing software and games for early home computers such as the Sinclair ZX81 and ZX Spectrum. Then, in 1984, it launched a machine of its own: the Psion Organiser.","The original Organiser looked a bit like a chunky calculator with a sliding cover. It cost 99 pounds and was advertised as the world's first practical pocket computer. Its brain was an 8-bit chip from the Japanese company Hitachi that ran at about 0.9 megahertz, meaning it could tick through just under a million simple steps every second. It had only 2 kilobytes of working memory (RAM), enough to hold about one page of text, and 4 kilobytes of permanent memory (ROM) for its built-in programs. Its screen showed a single line of 16 characters. That is fewer letters than you will find in this sentence.","So how did it store anything useful? Psion invented little plug-in memory cartridges called Datapaks, which slotted into the back of the machine. The first Datapaks used a type of chip called EPROM. You could write information onto it, but you could not simply delete it. To wipe a Datapak clean, you had to shine strong ultraviolet light onto the chip through a little window, a bit like how bright sunlight bleaches a poster. It sounds clumsy today, but it meant your data stayed safe even when the batteries ran out.","The first Organiser could work as a calculator and a clock, and it had a simple database, a kind of electronic card index where you could store and search for records. A simple programming language was also available for it on a plug-in Datapak, so owners could write small programs of their own. It was a clever start, but it was really a gadget for enthusiasts.","The big success came in 1986 with the Organiser II. It had a two-line screen (later models had four lines), more memory, a diary, an address book, an alarm clock and a better programming language called OPL, which was similar to the BASIC language that many children learned on home computers. The Organiser II sold more than 500,000 units.","What is fascinating is how people used it. The British department store Marks and Spencer gave Organiser IIs to staff on shop floors, specially branded and with most keys hidden so that workers only saw the buttons they needed. More than 3,000 were used by the UK government to calculate people's benefit payments. Surveyors connected them to measuring instruments, banks used them to work out currency exchange rates, and factories used them for checking the quality of products. The Organiser showed that a pocket computer could do real work.","Psion did not stop there. In 1991 it launched the Psion Series 3, a clamshell that opened like a tiny laptop, with a full keyboard and a wider screen. It looked very much like what people later imagined a PDA should be. Psion's software ideas would later help create Symbian, an operating system for phones that you will meet in Part 5. The little London company had set the pattern for a whole new kind of machine. Now one of the biggest names in computing wanted to go further."]},{"heading":"Apple's Newton: A Big Dream With Messy Handwriting","paragraphs":["In 1987, inside Apple Computer in California, an engineer named Steve Sakoman started a secret project. His dream was a tablet-shaped computer with no keyboard at all. You would write on its screen with a pen, just like writing on paper, and the computer would read your handwriting. The project was named Newton, a fitting name at Apple, whose very first company logo had shown Isaac Newton sitting under an apple tree.","Apple's chief executive at the time, John Sculley, became the project's biggest champion. On January 7, 1992, at the Consumer Electronics Show in Las Vegas, he used a phrase that would stick: he called this new kind of device a 'personal digital assistant'. Psion had made organizers before, but it was Sculley who gave the whole category its famous name. He predicted that PDAs would become an enormous business.","The Newton needed a special brain: powerful enough to recognize handwriting but frugal enough to run on batteries. Apple found its answer in Britain. It invested in a new company formed with Acorn Computers to develop the ARM processor, a chip designed to do a lot of work using very little power. (You will learn much more about ARM in Part 11, because today its descendants run almost every smartphone on Earth.) The Newton's choice of chip may be one of its most important legacies.","The first Newton, called the MessagePad, went on sale on August 2, 1993, at the Macworld Expo in Boston. It cost about 699 dollars. Inside was an ARM 610 chip running at 20 megahertz. It had a black-and-white touchscreen of 336 by 240 pixels, ran on four AAA batteries and weighed about 0.4 kilograms, roughly as much as a can of beans. It could store notes, names and appointments, send faxes with an accessory, and beam information to another Newton using infrared light. It even tried to be smart: if you wrote 'lunch with Anna Friday', it could try to work out that you meant an appointment and put it in the calendar.","Early sales were respectable, reportedly around 50,000 in the first three months. But then the handwriting recognition let it down. The software was not truly ready when the MessagePad launched. It often turned perfectly neat words into strange nonsense, and the world noticed. The cartoonist Garry Trudeau drew Doonesbury comic strips in which a character's Newton turned his writing into gibberish; in one, the words 'Catching on?' came out as 'Egg Freckles'. The TV show The Simpsons joined in with a scene where a bully's note reading 'Beat up Martin' was turned into 'Eat up Martha'. Once a gadget becomes a joke on television, it is very hard to make people take it seriously.","Apple kept improving the Newton. Later models such as the MessagePad 2000 and 2100 had a much faster 162-megahertz StrongARM chip, a backlit screen and handwriting recognition that many owners said worked surprisingly well. There was even the eMate 300, a tough, clamshell Newton with a keyboard, sold to schools. But it was too late. The Newton was expensive, and its early reputation stuck. When Steve Jobs returned to lead Apple in 1997, he wanted to focus on a small number of products. He disliked the stylus, and in 1998 the Newton was discontinued.","The Newton is often remembered as a flop, but that is not the whole story. It introduced the name PDA, it helped launch the ARM chip, and it showed what a pen-based pocket computer might be. It also taught a valuable lesson to everyone watching: if the computer cannot understand people, perhaps people could meet the computer halfway. One engineer took that lesson very seriously."]},{"heading":"The Palm Pilot and the Block of Wood","paragraphs":["Jeff Hawkins was born in 1957 in Huntington, New York, and studied electrical engineering at Cornell University. He was fascinated by two things: computers and how the human brain works. In the late 1980s he worked at a company called GRiD Systems, where he led the creation of the GridPad (1989), one of the first tablet computers you could write on with a pen. The GridPad was clever, but it was heavy and expensive, and it sold mostly to businesses. Hawkins wanted to make something ordinary people would love.","In 1992 he founded his own company, Palm Computing. He was soon joined by Donna Dubinsky, a sharp business leader who had worked at Apple, and Ed Colligan, an expert in marketing. At first Palm wrote software for other companies' hardware. Its programs ran on the Zoomer, a handheld made by Casio and sold by Tandy in 1993. The Zoomer was slow and bulky and did not sell well. The Palm team concluded that if they wanted a handheld done right, they would have to design the whole machine themselves.","This is where the most famous part of the story happens. Before building anything electronic, Hawkins made a model out of wood: a small, flat block, about the size he imagined the finished device would be, small enough to slip into a shirt pocket. He used a chopstick as a pretend pen. Then he carried the block around and acted as if it were real. In meetings, when someone suggested a date for lunch, he would pull out the block and 'tap' on it as though he were checking his calendar or writing a note. He counted how many taps each job needed and asked himself whether it felt quick enough.","It might sound silly, but it was brilliant design thinking. Hawkins was testing the experience before the technology. He learned that people would not use a gadget that was too big for a pocket, that it must turn on instantly, and that checking an appointment should take a couple of seconds, not a minute. Many earlier PDAs had tried to do everything a desktop computer could. Hawkins decided his would do a few things extremely well and very fast.","Building a new computer costs a lot of money, so in 1995 Palm was bought by US Robotics, a large company that made modems (the boxes that connected computers to the internet through phone lines). In 1996 the first Palm devices went on sale: the Pilot 1000 and Pilot 5000. They cost about 299 dollars, less than half the price of the first Newton. The Pilot 1000 had 128 kilobytes of memory and the Pilot 5000 had 512 kilobytes. Inside was a Motorola chip running at 16 megahertz. The black-and-white touchscreen was 160 by 160 pixels, and the whole thing ran on two ordinary AAA batteries.","Those numbers sound tiny, but the Pilot was a hit. It switched on the moment you pressed a button. It slipped into a pocket. Its batteries lasted a long time. It did not pretend to be a desktop computer; it was simply the best calendar and address book anyone had ever carried. The Computer History Museum describes it as the first wildly popular handheld computer. In 1997 came the PalmPilot Personal and PalmPilot Professional, and by 1998 more than a million of these organizers had been sold.","The name changed, too. The Pilot Pen Corporation, which made writing pens, sued over the name 'Pilot', and the case was settled in 1998. After that, Palm dropped 'Pilot' and its machines were simply called Palms. The Palm III (1998) added an infrared port, so two owners could 'beam' business cards to each other by pointing their Palms together, which became a popular party trick at conferences. The slim, metal Palm V of 1999 had a rechargeable battery, and the Palm VII could connect wirelessly to some internet services, though only in the United States. By 2000, Palm had roughly three-quarters of the PDA market."]},{"heading":"Graffiti: Teaching People to Write for Machines","paragraphs":["Remember the Newton's handwriting troubles? Jeff Hawkins had thought hard about the same problem, and he came up with a surprising answer. Everybody's handwriting is different. Some people write in joined-up letters, some in capitals, some in a scrawl only they can read. Teaching a small, slow computer to understand all of those styles was extremely hard in the 1990s. So Hawkins flipped the problem around: instead of making the computer learn your handwriting, why not have people learn a slightly simpler alphabet that the computer could read almost perfectly?","He called it Graffiti. Each letter was drawn in a single stroke, without lifting the pen. Most Graffiti letters looked very much like normal capital letters, so they were easy to remember, but the tricky ones were simplified. An ordinary capital A needs a crossbar, which means lifting the pen; in Graffiti, A was drawn as an upside-down V with no crossbar. T, F and K were also changed so that they could be drawn without lifting the pen. Because every letter was one stroke, the computer always knew exactly when a letter started and finished, which made recognition much easier.","There was another clever trick. Instead of writing across the screen, you wrote each letter on top of the last one in a small box at the bottom of the Palm, called the Graffiti area. Letters went on one side of the box and numbers on the other. You did not need to see what you had drawn; you just made the stroke, and the letter appeared on the screen above. Hawkins compared learning Graffiti to learning to touch-type: a skill that takes a little practice at first and then becomes automatic.","Two Palm engineers, Joe Sipher and Ron Marianetti, extended the alphabet with more characters and punctuation marks. Graffiti first appeared in 1994 as software for the Zoomer, and the Pilot 1000 and 5000 were the first machines to come with it built in. Many users found that after a short period of practice they could write quickly and accurately, which is something the first Newton owners could only dream of.","Graffiti also became the center of a long legal fight. The research lab Xerox PARC in California had a patent on a similar idea called Unistrokes, invented by the researcher David Goldberg. Xerox sued Palm, saying Graffiti copied it. The case went back and forth through the courts for years. In 2003 Palm switched to a new version called Graffiti 2, based on a different handwriting system called Jot, in which some letters were closer to normal handwriting. Later, the two companies made a deal, and Palm paid Xerox 22.5 million dollars. Even a simple alphabet, it turns out, can be worth a lot of money."]},{"heading":"Cradles, Syncing and the Windows Rivals","paragraphs":["A PDA on its own was useful, but it had a big weakness: most people also had information on a computer at home or at work. If you added a new phone number to your Palm, how would your desk computer know? And if you dropped your Palm in a lake, would all your appointments be lost forever?","Palm's answer was the cradle. Each Pilot came with a little plastic stand that plugged into a desktop computer with a cable. You dropped your Palm into the cradle and pressed one button, called HotSync. The two machines then compared their information. New contacts on the Palm were copied to the computer, new appointments on the computer were copied to the Palm, and if you had changed the same entry in both places, the software tried to sort out which was newer. This is called synchronizing, or syncing. It also meant the computer kept a backup of everything, so a lost PDA no longer meant lost plans.","Historians at the Computer History Museum point out that this was one of Palm's smartest decisions. Earlier pocket computers had tried to replace the desktop computer. The Palm was designed as a companion to it, a little window into information that really lived on your main computer. That made it simpler, cheaper and more useful. Today your phone syncs your photos, contacts and messages through the internet without any cradle at all, but the idea started with that button.","Of course, a successful product attracts rivals. The software giant Microsoft created a smaller version of its Windows operating system for handheld devices, called Windows CE, and first used it in 1996 on small clamshell computers with keyboards, known as Handheld PCs. In January 1998 Microsoft announced keyboard-free 'Palm-size PCs' to compete directly with Palm. The name was announced as 'Palm PC' at first but was changed before the devices went on sale.","On April 19, 2000, Microsoft launched the Pocket PC, built on a new version, Windows CE 3.0. Pocket PCs were made by several companies, including Hewlett-Packard, Casio and Compaq, whose iPAQ became one of the best-known models. They tended to be more powerful than Palms, with faster chips and, on many models, color screens. They came with mobile versions of Microsoft programs such as Word and Excel, could play music and video with Windows Media Player, and could browse the web. Later versions were renamed Windows Mobile, starting with Windows Mobile 2003.","So by the early 2000s there were two big PDA families. Palm devices were simple, quick and had long battery lives. Pocket PCs were more powerful and felt more like a tiny Windows computer, but they used more power and could be more complicated. Fans of each argued fiercely about which was better, much as Android and iPhone fans argue today. In 2000, Palm still had about three-quarters of the market, but it was gradually losing ground to Microsoft's Pocket PC devices."]},{"heading":"Too Many Gadgets: The Dream of Convergence","paragraphs":["Now imagine a gadget-loving business traveler in about the year 2001. In one pocket there is a mobile phone, maybe a Nokia, for calls and text messages. In another pocket there is a Palm or a Pocket PC for the calendar and contacts. Clipped to the belt might be a pager, a small device that beeps to show a short message. In the bag there might be a digital camera, and perhaps an MP3 music player too; Apple's first iPod arrived in October 2001. That is four or five separate devices, each with its own battery, charger and cable. Airport security trays must have looked like electronics shops.","Each gadget also contained many of the same parts: a battery, a screen, buttons, a processor, memory and a little speaker. Engineers and business people began to talk about convergence, a word meaning things coming together into one. Why carry five screens and five batteries when one clever device could do it all?","It was not easy, though. In the 1990s, the parts that made a good phone and the parts that made a good PDA pulled in different directions. A phone needed to be small and to have a battery that lasted for days on standby. A PDA needed a bigger screen and a stronger processor, both of which used more power. Mobile networks were also slow. 2G networks were designed for voices and short texts, not for loading web pages or downloading email attachments. Combining everything risked making a device that was too big, too expensive and too quickly drained.","People tried anyway, in all sorts of ways. Some business users connected their PDA to their phone with a cable, or with infrared light, so the PDA could use the phone's connection to send a short email. The Palm VII had its own radio for some wireless services in the United States. Handspring, a company started in 1998 by Hawkins, Dubinsky and Colligan after they left Palm, made a PDA called the Visor with a slot in the back where you could plug in extra modules. One of those modules turned the Visor into a phone. Handspring went on to build the Treo, a phone and organizer in one, which you will meet again in Part 7.","Meanwhile, phones were creeping toward PDAs from the other direction. Phone makers added calendars, address books and games, and the GSM phones of Part 3 could send text messages. Every year phones got a little more like computers, and PDAs got a little more like phones. By the mid-2000s, the PDA as a separate device was fading, swallowed up by phones that could do the same jobs. In the early 2010s, smartphones and tablets had almost completely replaced it.","The PDA era left behind lasting ideas: the stylus and touchscreen, syncing with a computer, beaming information, tiny on-screen keyboards, calendar alerts, and the principle that a pocket device must be instant and simple. It also left behind important companies and chips, including the ARM processor and the Palm and Windows Mobile software that later powered early smartphones.","So here is the big question. Who would be the very first to put a real PDA and a real mobile phone together in one handheld device, with a touchscreen, a calendar, an address book and email? You might guess Apple, or Palm, or Nokia. The surprising answer is the giant computer company IBM, and it happened much earlier than most people think: in 1994, more than a dozen years before the iPhone. That forgotten machine is the star of Part 5."]}],"deepDive":"The PDA story is a lesson in the gap between what engineers can build and what users will accept. The hardest technical problem was handwriting recognition. Natural handwriting varies hugely between people, letters run together, and a pen-based computer must guess where one letter ends and the next begins (the 'segmentation' problem) before it can even guess which letter it is. The Newton tried to solve this with statistical recognition that compared strokes against dictionaries of likely words. That is powerful when it works, but it failed visibly on unusual words and names, and the early MessagePad, with only about 640 kilobytes of memory and a 20-megahertz processor, had little room for big dictionaries. Graffiti took the opposite approach: by forcing every character to be one stroke, it solved segmentation for free, and by choosing distinct shapes it made classification almost trivial. It moved part of the work from the machine to the human, a trade-off that designers still weigh today whenever they ask users to learn a gesture, a shortcut or a new keyboard layout in exchange for speed and reliability. Historians of design often hold up Hawkins's wooden block as an early, famous example of 'experience prototyping': testing how a product feels in daily life before a single circuit exists. Debates continue about 'firsts'. Psion's 1984 Organiser is usually credited as the first PDA, but there were earlier electronic organizers and handheld computers, and the term PDA was only popularized by John Sculley in 1992. Some argue that the Newton, despite poor sales, mattered more than its success suggests: Apple's investment helped found ARM, whose energy-efficient designs dominate mobile chips today. Market figures tell the rest of the story: Palm held around three-quarters of the PDA market in 2000, yet within a decade the stand-alone PDA had nearly disappeared, absorbed by smartphones. Convergence did not just combine devices; it erased an entire product category.","funFact":"Before building the first Palm Pilot, Jeff Hawkins carried a wooden model around and 'used' it in meetings with a chopstick as a pretend pen, to test whether the size and design felt right.","check":{"q":"Why did Palm's Graffiti alphabet make every letter a single stroke?","a":"So the computer always knew where each letter started and ended, making the letters much easier to recognize correctly.","wrong":["So the batteries would last longer by using less ink","Because the Palm screen could only show capital letters","Because Apple's patent banned letters with two strokes"]},"sources":[{"title":"Psion Organiser","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Psion_Organiser"},{"title":"Apple Newton","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Apple_Newton"},{"title":"MessagePad","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/MessagePad"},{"title":"Revolution: Mobile Computing (the PalmPilot)","publisher":"Computer History Museum","url":"https://www.computerhistory.org/revolution/mobile-computing/18/321"},{"title":"Palm (PDA)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Palm_(PDA)"},{"title":"Graffiti (Palm OS)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Graffiti_(Palm_OS)"},{"title":"Pocket PC","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pocket_PC"},{"title":"Personal digital assistant","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Personal_digital_assistant"}],"photos":[{"src":"img/deep/smartphone/04-1.jpg","alt":"The Psion Organiser from 1984, with its one-line display, keyboard and slide-on protective case.","file":"Psion Organiser 1.jpg","url":"https://commons.wikimedia.org/wiki/File:Psion_Organiser_1.jpg","author":"The Science Museum UK","license":"CC BY 4.0"},{"src":"img/deep/smartphone/04-2.jpg","alt":"An Apple Newton MessagePad 100 with its stylus; the screen shows a sketch drawn by hand.","file":"Apple Newton MessagePad 100 with stylus.jpg","url":"https://commons.wikimedia.org/wiki/File:Apple_Newton_MessagePad_100_with_stylus.jpg","author":"Felix Winkelnkemper","license":"CC BY-SA 4.0"},{"src":"img/deep/smartphone/04-3.jpg","alt":"A PalmPilot Professional beside its HotSync cradle, which connected it to a computer by cable.","file":"Palm Pilot Professional 02.JPG","url":"https://commons.wikimedia.org/wiki/File:Palm_Pilot_Professional_02.JPG","author":"Museo8bits","license":"CC BY-SA 3.0"}],"words":4118},{"n":5,"title":"IBM Simon: The Forgotten First Smartphone","when":"1992 – 2000","summary":"In 1994, long before the iPhone, IBM sold a phone with a touchscreen, a calendar and email. It was called Simon! It was heavy, its battery died fast and it cost a lot, so few people bought it, but it showed the world what a phone could become.","sections":[{"heading":"An Engineer, an Idea and a Trip to Las Vegas","paragraphs":["Imagine it is 1992. If you are a busy businessperson, your coat pockets are heavy. In one there is a mobile phone, which by now has shrunk from the 'brick' to something closer to a large TV remote. In another there is a pager, a little beeping box that shows a phone number when someone wants you to call them back. In your briefcase there is a paper diary stuffed with appointments, a thick address book, maybe a pocket organizer, and a stack of business cards. Back at the office sit the fax machine and the desktop computer, where your email waits. Nothing talks to anything else.","At IBM, the giant American computer company, an engineer named Frank Canova was thinking about that pile of gadgets. Canova had grown up in Florida and studied electrical engineering at the Florida Institute of Technology, graduating in 1978. By the early 1990s he was working on small, battery-powered devices, and he noticed something important: computer chips and radio parts had become small enough and cheap enough that a whole computer and a whole phone might fit into one hand-sized box.","According to some accounts, his boss, Jerry Merckel, was working on PCMCIA cards. These were thin, credit-card-sized plug-in cards that could add memory or a modem to a laptop. Merckel saw that the same kind of card slot could make a handheld device expandable, so new abilities could simply be slotted in. Together the idea grew: why not build a phone that was also a personal organizer, and that could send faxes and email too?","A team at IBM set to work. IBM first asked Motorola, the company that had built the first handheld cellular phones, to help build the device, but Motorola said no. So IBM partnered with the Japanese electronics company Mitsubishi Electric, which would manufacture it. Inside IBM the project went by code names; reports mention 'Sweetspot' for the early prototype and 'Angler' for the product. Canova and his teammates later received a patent for the design, with a 1992 starting date. Because the idea began with him, Frank Canova is often described today as the inventor of the smartphone, although, as with almost every invention in this story, it took a whole team to make it real.","Every November, the computer world gathered in Las Vegas for COMDEX, the biggest computer trade show of its day. Picture enormous convention halls, carpeted aisles, glowing monitors, and tens of thousands of visitors collecting brochures and free pens. Companies used COMDEX to show off their newest machines and to whisper about the future.","IBM's team rushed to get their prototype ready in time. On November 16, 1992, they showed it off: a handheld device that was a cellular phone and an electronic organizer at the same time. You could tap its screen instead of pressing lots of buttons. The demonstration included little sample programs showing things like stock prices, news, sports scores and the weather, a hint of the kind of information people might one day get on a phone.","Visitors were impressed. It is worth remembering what else existed at the time. Part 4 described the PDAs, or personal digital assistants: handheld organizers with no phone inside. Apple's Newton had not even gone on sale yet; it arrived in 1993. Most mobile phones still had small one- or two-line displays that could show only a phone number. A phone with a touchscreen, an address book and a calendar was like a glimpse of the future arriving early.","But a trade-show prototype is not the same as a product you can buy in a shop. It would take almost two more years of work, partnerships and software fixes before ordinary people could get their hands on one."]},{"heading":"Meet Simon: The Personal Communicator","paragraphs":["To sell a phone in the United States, you needed a phone company to connect it to its network. IBM teamed up with BellSouth Cellular, the mobile arm of one of the large American phone companies. BellSouth gave the device its friendly name: the Simon Personal Communicator, usually just called the IBM Simon. It was shown at the Wireless World Conference in November 1993, and the plan was to start selling it in May 1994. Software problems pushed the launch back, and the Simon finally went on sale on August 16, 1994.","What did you get? The Simon was about 8 inches (20 cm) long, 2.5 inches (6.4 cm) wide and 1.5 inches (3.8 cm) thick, and weighed about 510 grams (18 ounces). That is roughly the weight of two and a half modern smartphones, or a full can of soup. Most of its front was taken up by a screen about 4.5 inches long and 1.4 inches wide, a tall, narrow strip of liquid crystal display (LCD) with 160 by 293 pixels. The screen was monochrome, meaning it showed only dark dots on a light background, and it had a backlight so you could see it in the dark.","The screen was a resistive touchscreen. As Part 10 will explain, this kind of screen is made of layers that register a touch when they are pressed together. That meant you could press it with a fingertip or with the plastic stylus (a pen-shaped pointer) that came with it. There was no keyboard with real keys at all. To dial, you tapped numbers on a keypad drawn on the screen. To type a note, you tapped letters on an on-screen keyboard, or you could write by hand.","Its programs, built in from the factory, read like the home screen of a much later phone: an address book, a calendar, an appointment scheduler, a calculator, a world clock that told you the time in other cities, a notepad, and a sketch pad for quick drawings. Most exciting of all, Simon could send and receive email and faxes. A fax is a copy of a paper page sent over phone lines; in 1994 faxes were still one of the main ways businesses sent documents. With Simon, a salesperson standing in a parking lot could receive a fax right on the screen.","In the box came a charging stand, a rechargeable battery and a leather cover. Extra equipment included a cable to connect Simon to a desktop computer, an adapter to plug it into an ordinary wall phone socket, and even a pager card made by Motorola that slotted into its card slot. Simon was not just a phone with extras. It was a little computer that happened to make phone calls.","Open a Simon up and you would find parts that seem tiny by today's standards. Its brain was a processor called the NEC V30HL, running at 16 megahertz. Megahertz means millions of ticks per second; a modern phone chip runs at a few thousand megahertz, with several processor cores working at once. The processor was built into a chip from a company called Vadem that combined several jobs in one package, an early cousin of the 'system-on-a-chip' you will meet in Part 11.","For memory, Simon had about 1 megabyte of working memory and 1 megabyte of flash memory to store programs and data. Engineers used a compression trick, squeezing data the way you might roll clothes tightly in a suitcase, so the flash memory could hold about 2 megabytes. To compare, a single photo from a modern phone camera is often 2 to 5 megabytes. Simon's entire memory could not hold one of today's selfies.","Underneath the friendly screen, Simon ran a version of DOS, the text-based operating system used by many personal computers of the time. The company Datalight supplied it, under the name ROM-DOS. But owners never saw a blinking DOS prompt. IBM built a touch-friendly layer on top, called Navigator, with big buttons you could tap. This idea, a friendly touch interface sitting on top of a hidden operating system, is exactly how smartphones work today.","To connect to the outside world, Simon had a built-in modem, the part that turns computer data into sounds that can travel over a phone line or a cellular voice channel. It could send data at 2,400 bits per second and faxes at 9,600 bits per second. A short email of a few hundred words would arrive in a few seconds, which felt fine in 1994. But a typical 3-megabyte photo from a modern phone would have taken almost three hours to send at 2,400 bits per second.","Power came from a rechargeable nickel-cadmium (NiCad) battery pack. Lithium-ion batteries, the lighter and more powerful kind used in phones today, had only gone on sale in 1991 and were still rare and expensive. That choice of battery would turn out to be one of Simon's biggest problems."]},{"heading":"Why Simon Did Not Take Over the World","paragraphs":["Simon was clever, but clever is not enough to make people open their wallets. The first problem was the price. With a two-year BellSouth contract, Simon cost about $899. Without a contract it cost about $1,099. Because prices have risen over the years, $899 in 1994 is worth roughly $1,900 in today's money. On top of that, you paid for calls by the minute, and mobile calls in 1994 were expensive. BellSouth later cut the price to $599 with a contract, but by then interest was fading.","The second problem was the battery. With all its computing parts and its backlit screen, Simon drained its NiCad battery fast. Reports from the time describe about an hour of talking, or less, before the battery ran flat. Imagine buying the most advanced gadget in the world and then having to search for a power socket by lunchtime.","Third, Simon was big and heavy. At about half a kilogram, it was heavier than many of the regular mobile phones of 1994. You could not easily slip it into a shirt pocket.","Fourth, the world around Simon was not ready. Mobile networks in the United States in 1994 were still mostly first-generation, or 1G, analog networks, designed for voice calls rather than data. Simon had no web browser, and that made sense: the World Wide Web was only a few years old, the first popular graphical web browser, Mosaic, had appeared in 1993, and most websites were simple pages built for big desktop screens. Even if Simon had had a browser, loading web pages at 2,400 bits per second over an analog phone channel would have been painfully slow. There was also no app store, no easy way for outside programmers to write programs for it, and very few people outside offices even had an email address.","The results showed it. About 50,000 Simons were sold in roughly six months. For comparison, popular phones of the late 1990s would sell in the tens of millions. In February 1995, only about six months after launch, Simon was withdrawn from sale. IBM had worked on a smaller, lighter follow-up, code-named 'Neon', but it was cancelled before it ever reached shops.","Frank Canova did not give up on handheld computers, though. In 1997 he joined Palm, the company behind the hugely successful Palm Pilot you met in Part 4, and became head of engineering for several of its PDAs. The ideas he had worked on at IBM lived on in the next generation of pocket computers."]},{"heading":"Was Simon Really the First Smartphone?","paragraphs":["Today, newspapers, museums and history books often call the IBM Simon 'the first smartphone'. It deserves a lot of credit. It combined a mobile phone with a touchscreen, built-in programs for organizing your life, email and fax, and a slot for adding new abilities. By the definition in our glossary, a mobile phone that is also a general-purpose computer, Simon fits remarkably well.","But there is an important detail. Nobody called Simon a 'smartphone' when it was on sale. IBM and BellSouth called it a 'personal communicator'. The word 'smartphone', written as one word, was first used by the Swedish company Ericsson in 1997 for a concept device called the GS88, and the first phone actually sold with the 'smartphone' label came from Ericsson in 2000. Historians later looked back and applied the modern label to Simon because it did so many of the things smartphones would become famous for.","There is also a debate about the word 'first'. Earlier inventors had filed patents in the 1970s and 1980s describing telephones with screens and computer features, and some people point to those ideas as the true beginning. Others argue that a device only counts if real customers could buy it. Some historians prefer to call Simon 'an important forerunner' of the modern smartphone rather than simply the first. All of these views can be fair at the same time. Simon was, as far as historians can tell, the first handheld device sold to the public that combined a cellular phone, a touchscreen and a full set of computer organizer programs. That is a big achievement, even if it was not called a smartphone at the time.","Simon was not alone, either. In 1994 a company called General Magic, founded by former Apple engineers, released software called Magic Cap that ran on 'personal communicators' made by Sony (the Magic Link) and Motorola (the Envoy). These were handheld organizers designed to send messages, though they were not cellular phones in the same way as Simon. In March 1996, the computer company HP sold the OmniGo 700LX, a tiny palmtop computer that clipped onto a Nokia 2110 mobile phone. Many engineers in many companies could see where things were heading. The race was on."]},{"heading":"Nokia's Phone That Opened Like a Book","paragraphs":["The next big step came from Finland. Nokia, which you met in Part 3 as the maker of the 6110 and the 3310, unveiled a remarkable device at the CeBIT technology fair in Hanover, Germany, in 1996. On August 15, 1996, the Nokia 9000 Communicator went on sale.","Closed, the Communicator looked like a large, thick mobile phone, about 17 cm (6.8 inches) tall and nearly 4 cm thick, weighing about 397 grams. You could make calls using the keypad on the front, like any phone. But then came the magic trick: you could open it sideways like a book. Inside was a wide black-and-white screen of 640 by 200 pixels and a full QWERTY keyboard, the same layout of letters you find on a computer. It was like carrying a miniature laptop that was also a phone.","Inside was an Intel 386 processor running at 24 megahertz, the same family of chip that powered many desktop computers a few years earlier, plus 8 megabytes of memory. The organizer side ran software based on GEOS, an operating system originally made for small, inexpensive computers. The Communicator could send email and faxes, print documents through an infrared beam, browse simple web pages and run business programs like a calendar, contacts list and notes.","Because it worked on GSM, the digital second-generation network you met in Part 3, the Communicator could send data more reliably than an analog phone, at up to 9.6 kilobits per second. That is four times faster than Simon's modem, though still thousands of times slower than mobile internet today.","The Communicator was expensive too: about 1,000 pounds in the UK at launch. But it became a status symbol for executives, and it even became a movie star. In the 1997 film The Saint, actor Val Kilmer's character uses a Nokia 9000 Communicator. Nokia kept improving the design, and in 2001 the Nokia 9210 Communicator arrived with a color screen and a new operating system, Symbian, that let owners install extra programs. The line continued for more than a decade, ending with the Nokia E90 in 2007."]},{"heading":"Ericsson Says the Word, and Symbian Is Born","paragraphs":["Remember Psion, the British company that made the Psion Organiser back in 1984 (Part 4)? By the late 1990s, Psion had built a powerful operating system for its handheld computers called EPOC. Phone makers noticed that EPOC was small, efficient and good at saving battery power, which is exactly what a phone needs.","In June 1998, Psion's software team became a new company called Symbian Ltd. It was a joint venture, meaning it was owned together by several companies: Psion and three of the biggest phone makers in the world, Nokia, Ericsson and Motorola. The idea was that instead of every company building its own complicated phone software from scratch, they could share one strong operating system. Rival companies working together like this was unusual, and it shows how hard building smartphone software was.","The first phone to use this software was the Ericsson R380. It was shown at CeBIT in February 1999 and began shipping in 2000. It was the first device marketed with the word 'smartphone'. Closed, the R380 looked like a fairly normal phone of the time, weighing about 160 grams, far lighter than Simon or the Communicator. But the number keypad was on a flap. When you flipped the keypad open, it revealed a long black-and-white touchscreen underneath, which you could use with a stylus to manage your contacts, calendar and messages.","The R380 could also reach the mobile internet using WAP, the Wireless Application Protocol. WAP was a system for showing very simple, text-heavy web pages on small phone screens. It was slow and clunky, and many people were disappointed by it, but it was a start. One big limitation: R380 owners could not install their own extra programs. That changed with the Nokia 9210 in 2001.","Over the next decade, Symbian became the most common smartphone operating system in the world. Nokia's 7650, released in 2002, was the first phone to use the Symbian-based S60 interface, which went on to appear on many Nokia phones. Around 2006, roughly two-thirds of all smartphones sold worldwide ran Symbian. As you will see in Part 9, its reign would not last forever: Android overtook it at the end of 2010, and Nokia announced in February 2011 that it would move to Microsoft's Windows Phone instead. But for many years, if you owned a smartphone, it probably ran software whose story began with Psion's little organizers."]},{"heading":"The Big Lesson: First Is Not the Same as Winning","paragraphs":["Look back at the story of the IBM Simon and you might feel a little sad. Here was a device with a touchscreen, a calendar, email and add-on cards in 1994, thirteen years before the iPhone. Why didn't IBM become the king of smartphones?","The answer teaches one of the most important lessons in the history of invention: being first is not the same as being successful. An invention needs the right timing. In 1994, batteries were heavy and weak, screens were monochrome, chips were slow and power-hungry, and mobile networks were built for voices, not data. An invention also needs the right price. A device that costs as much as a used car will only ever be bought by a few people. And it needs a whole system around it: fast networks, websites designed for small screens, outside programmers writing software, and enough customers to make it all worthwhile.","Think of it like planting a seed in winter. The seed might be perfectly healthy, but if the ground is frozen it cannot grow. Simon was a good seed planted in frozen ground. Over the next decade, the ground slowly thawed: lithium-ion batteries got better, color screens got cheaper, digital networks spread, and chips became faster while using less power.","There is a second lesson too. Simon's ideas did not disappear. They traveled with people like Frank Canova to other companies, and they inspired other engineers who saw what was possible. The Nokia Communicator showed that business users would pay for a pocket office. The Ericsson R380 and Symbian showed that phone companies could share software. Each step, even the ones that failed in the shops, taught the industry something.","Simon itself has become a treasured collector's item. Surviving units are shown in exhibitions about the history of computing, and in 2014, when Simon turned 20, news stories around the world looked back at it as a forgotten pioneer of the smartphone."]},{"heading":"Meanwhile, on the Other Side of the World","paragraphs":["By the end of the 1990s, phones could make calls, send text messages, and, if you paid a lot, organize your calendar and send email. But for most people, the real internet still lived on big desktop computers connected by wires. Mobile web systems like WAP were slow, confusing and expensive. In the United States and Europe, very few ordinary people used the internet on their phones at all.","So where did the mobile internet really take off first? Not in Silicon Valley, the home of so many computer companies. Not in Finland or Sweden, home of Nokia and Ericsson. The answer was Japan. In February 1999, a Japanese phone company launched a service that let millions of ordinary people, from teenagers to grandparents, read the news, check the weather, play games and send emails with little pictures in them, all from their phones. Those little pictures would one day travel all around the world under a Japanese name: emoji. That is where our story goes next."]}],"deepDive":"Why do historians argue about the 'first smartphone'? Partly because the word itself is fuzzy. If a smartphone means a cellular phone that is also a general-purpose computer, the IBM Simon (1994) qualifies: it ran a DOS-based operating system (Datalight ROM-DOS) beneath a touch interface, held about 1 MB of RAM and 1 MB of flash, and could take new abilities through a PCMCIA card slot. Yet almost no third-party software was ever made for it, and its owners could not download programs over the air, which many people now see as a defining smartphone feature. By that stricter test, later devices such as the Nokia 9210 Communicator (2001), the first Symbian Communicator that let users install applications, have a strong claim. Others go further back to 1970s and 1980s patents for phones with screens and data features, which shows how ideas often appear on paper long before they can be built. The numbers also explain Simon's failure. Its 2,400 bit-per-second modem worked over analog (1G) cellular channels designed for voice; sending a 3-megabyte file would have taken close to three hours. Its NiCad battery stored much less energy for its weight than the lithium-ion cells that Sony had only begun selling in 1991, and powering a backlit screen, a 16 MHz processor and a radio transmitter at once drained it in roughly an hour of talk. At $899 with a two-year contract (about $1,900 in today's money), plus per-minute call charges, it was a luxury tool. Economists talk about 'complementary goods': products whose value depends on other products existing. Smartphones need fast data networks, mobile-friendly websites, developers and app stores. In 1994 almost none of these existed. The roughly 50,000 Simons sold in six months were not a failure of imagination but an example of an invention arriving before its ecosystem. Historians of technology see the same pattern with Apple's Newton and General Magic's Magic Cap, and it is a useful warning for anyone predicting which of today's experimental gadgets will win.","funFact":"IBM first asked Motorola, the company behind the first handheld cellular phone, to build the Simon, but Motorola said no, so the Japanese company Mitsubishi Electric manufactured it instead.","check":{"q":"Which phone company sold the IBM Simon Personal Communicator when it went on sale in August 1994?","a":"BellSouth (BellSouth Cellular)","wrong":["Nokia","NTT Docomo","Apple"]},"sources":[{"title":"IBM Simon","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/IBM_Simon"},{"title":"Frank Canova","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Frank_Canova"},{"title":"History of smartphones","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/History_of_smartphones"},{"title":"Nokia 9000 Communicator","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nokia_9000_Communicator"},{"title":"Nokia Communicator","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nokia_Communicator"},{"title":"Ericsson R380","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ericsson_R380"},{"title":"Symbian","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Symbian"}],"photos":[{"src":"img/deep/smartphone/05-1.jpg","alt":"The IBM Simon Personal Communicator in its charging base, showing the phone keypad on its touchscreen.","file":"IBM Simon Personal Communicator (2).png","url":"https://commons.wikimedia.org/wiki/File:IBM_Simon_Personal_Communicator_(2).png","author":"Bcos47","license":"Public domain"},{"src":"img/deep/smartphone/05-2.jpg","alt":"A Nokia 9000 Communicator opened up, showing its wide screen and full QWERTY keyboard.","file":"Nokia Communicator 9000 Opened 01.jpg","url":"https://commons.wikimedia.org/wiki/File:Nokia_Communicator_9000_Opened_01.jpg","author":"textlad","license":"CC BY 2.0"},{"src":"img/deep/smartphone/05-3.jpg","alt":"An Ericsson R380s from 2000, shown with its flip keypad closed over the long touchscreen.","file":"Ericsson R380s 004.jpg","url":"https://commons.wikimedia.org/wiki/File:Ericsson_R380s_004.jpg","author":"The Norwegian Telecom Museum","license":"CC BY-SA 4.0"}],"words":3809},{"n":6,"title":"Japan's Mobile Internet Leap","when":"1997 – 2006","summary":"In 1999, people in Japan started reading news, playing games and sending emails on their phones, years before most of the world. Japan also gave us emoji, the first popular camera phones, the first 3G network and phones you could pay with. Their phones were so special they were nicknamed after the Galápagos Islands!","sections":[{"heading":"A Crowded Train in Tokyo, and the Team Behind i-mode","paragraphs":["Imagine squeezing onto a commuter train in Tokyo at eight in the morning in 1999. The carriage is packed so tightly that you can barely lift your arms. Talking on the phone is considered rude on Japanese trains, so the carriage is strangely quiet. But look around: dozens of people are staring down at the small glowing screens of their mobile phones, thumbs tapping away. One person is reading the news headlines. Another is checking the weather. A teenager is sending an email to a friend, finished off with a tiny heart symbol. Someone is checking their bank balance, and someone else is playing a simple game.","In America and Europe at that time, almost nobody used the internet on a phone. In Japan, it was becoming normal. How did that happen?","Japan had several things going for it. Its cities were huge and crowded, and millions of people spent an hour or more each day on trains, with time to fill but no room to open a laptop. Fewer Japanese homes had personal computers than in the United States, so for many people a phone was the easiest way to go online. Japan had also built its own digital phone network, a second-generation (2G) standard called PDC (Personal Digital Cellular), which the biggest phone company, NTT Docomo, launched as its 'mova' service in March 1993. And Japan's mobile phone companies had a lot of power: they told phone makers like NEC, Panasonic, Fujitsu and Sharp exactly what features to build, so a new service could appear on many new phones at once.","The biggest of those companies was NTT Docomo, the mobile part of Japan's national telephone company. The company says its name comes from the first letters of the phrase 'Do Communications over the Mobile network', though many people also notice that 'doko mo' sounds like the Japanese for 'everywhere'. In the late 1990s, Docomo faced a problem that might sound surprising: so many people already had mobile phones that the number of brand-new customers would soon stop growing quickly. To keep growing, Docomo wanted people to do more with the phones they already had, not just make calls.","In 1997 Docomo set up a small new team to invent mobile services, led by an executive named Keiichi Enoki. He brought in people from outside the phone business, which was unusual for a big, traditional Japanese company.","The most famous was Mari Matsunaga. Born in 1954 in Sasebo, in southern Japan, she had studied French literature and spent twenty years at Recruit, a company that published magazines, including job-hunting magazines for young people and women. She was an expert at one thing engineers often forget: what ordinary people actually want. Matsunaga joined Docomo in July 1997, and she pushed the team to think like magazine editors rather than computer engineers. People did not want to 'access the internet', she argued; they wanted handy services, like checking a train time, a bank balance or a horoscope, as easily as flipping through a magazine. She is credited with coming up with the name 'i-mode'. The 'i' can stand for information, the internet, interactive, or simply 'I', as in me.","Another key person was Takeshi Natsuno, born in 1965, a young businessman with experience of the early internet business. He handled the business side, working out how Docomo and the companies providing content could all make money. Enoki oversaw the technical development and steered the project inside Docomo.","The team made some smart choices. Rather than inventing a new language for phone web pages, they used a simplified version of HTML, the language that ordinary web pages are written in. It was called Compact HTML, or cHTML. Because it was so close to normal HTML, any web designer could quickly learn to make i-mode pages. That was important: the more interesting sites there were, the more people would want i-mode.","In 2000, Fortune magazine ranked Mari Matsunaga as the most powerful businesswoman in Asia, largely because of i-mode. Not bad for someone who had never worked at a phone company before!"]},{"heading":"February 1999: The Internet Arrives on the Phone","paragraphs":["NTT Docomo launched i-mode on February 22, 1999. Docomo calls it the world's first mobile internet services platform. To use it, you bought a new i-mode phone, which had a bigger screen than older models and a special 'i' button. Press it, and up popped a menu of services.","What could you do? You could send and receive short emails to other phones and to ordinary computer email addresses. You could read news and sports results, check the weather forecast, look up train timetables and restaurant guides, do your banking, buy concert tickets, download ringtones and wallpaper pictures for your screen, and play games. Toy and game companies like Bandai and Namco were among the early content providers. Over time, i-mode's official menu grew to more than 12,000 sites, and there were roughly 100,000 unofficial sites made by other companies and individuals.","Two ideas made i-mode very different from the dial-up internet of the time. First, it was 'always on'. With a home computer in 1999, you often had to dial up, wait for a screeching modem to connect, and pay for every minute you were online. i-mode used a packet system, which sends data in small bundles only when there is something to send. That meant your phone could stay connected without tying up a phone line.","Second, you paid for how much data you sent and received, not for how long you were connected. Reading a short weather report cost only a tiny amount. The basic monthly charge for i-mode was only a few hundred yen, a few US dollars. Many extra services, like a horoscope or a game, cost a small monthly fee on top, which Docomo added to your phone bill and passed on to the company that made the service, keeping a small share for itself. This made it easy for content companies to earn money, and easy for customers to pay. It was a little like the app stores that would appear almost a decade later.","The result was explosive. Within a few years, tens of millions of Japanese people were using i-mode. Rival companies quickly launched their own versions: KDDI's EZweb and J-Phone's J-Sky. By June 2006 these three mobile internet services together had more than 80 million subscribers in Japan. In a country of about 127 million people, that was a huge share of the whole population."]},{"heading":"Tiny Pictures, Big Feelings: The Story of Emoji","paragraphs":["Text messages are short, and it is easy to sound grumpy by accident. 'OK.' might mean 'Great!' or 'Fine, whatever'. Japanese phone makers and phone companies found a clever solution: little pictures that could be typed like letters.","The word emoji is Japanese. 'E' means picture and 'moji' means character, so emoji means 'picture character'. Its similarity to the English word 'emotion' is a complete coincidence!","Emoji did not appear out of nowhere. Typed faces made from punctuation, like :-) , had been used on computers since 1982. Some Japanese electronic organizers in the late 1980s, such as the 1988 Sharp PA-8500, included small picture symbols. In 1997 the phone company J-Phone (later part of SoftBank) put a set of about 90 black-and-white picture characters on one of its phones, the DP-211SW. That was an early emoji set for phones, a couple of years before Docomo's.","The set that became world-famous was designed for i-mode in 1999 by a young Docomo employee named Shigetaka Kurita, born in 1972 in Gifu Prefecture. Kurita had already worked on a Docomo pager aimed at teenagers that could show a heart symbol, and he noticed how much young people loved it. For i-mode he designed a set of 176 colored pictograms.","Each one had to fit in a grid only 12 pixels wide and 12 pixels tall, just 144 tiny squares, each either colored in or blank. Try drawing a smiling face, an umbrella or a bicycle on a 12-by-12 piece of graph paper and you will see how hard that is. Kurita took ideas from manga comics, where symbols like a sweat drop or a light bulb show feelings, from weather forecast symbols, from Chinese characters, and from street signs. His set included weather symbols like sun, cloud, rain and snow; hearts; musical notes; vehicles; and signs for places like a restaurant or a hospital.","Interestingly, the round yellow smiley faces that most people picture when they hear the word emoji were not part of Kurita's original set. His pictograms were mostly practical symbols for weather, sports, activities, places and feelings like love. Many of the general-purpose emoji we still use, such as the sun, the umbrella or the musical note, can trace their family tree back to those little 12-by-12 drawings, while the huge range of faces came later as different companies added their own designs.","Emoji spread fast across Japan, and each phone company had its own set, which caused problems when sending messages between companies. The breakthrough for the rest of the world came when Apple and Google pushed to add emoji to Unicode, the international system that gives every letter and symbol in the world's languages its own code number so that all computers display them the same way. In October 2010, Unicode version 6.0 included 722 emoji. Apple's iPhone had first offered an emoji keyboard only in Japan in 2008, and made it available worldwide in 2011. From then on, emoji became a global language.","In 2016, the Museum of Modern Art in New York added Kurita's original 176 emoji to its collection, alongside famous paintings and design objects. Kurita is often called the creator of emoji. That gives him well-deserved credit for the most influential early set, but, as you have seen, picture symbols on Japanese devices and phones existed before his work."]},{"heading":"Say Cheese! The First Camera Phones","paragraphs":["Today it seems obvious that a phone has a camera. In 1999 it was a brand-new idea, and once again Japan got there first.","There had been clever experiments before. On June 11, 1997, in a California hospital, a technology businessman named Philippe Kahn wanted to share the news of his newborn daughter Sophie. Sitting in the waiting room, he rigged up a way to connect his digital camera to his laptop and his mobile phone, and sent her first pictures to more than 2,000 family members, friends and colleagues. It worked, but it was a tangle of separate gadgets and cables. The next step was to build the camera right into the phone.","In May 1999, the Japanese company Kyocera released the Visual Phone VP-210. It worked on Japan's PHS network (Personal Handy-phone System), a cheaper, lower-power kind of mobile phone service popular in Japanese cities. The VP-210 had a small camera of about 110,000 pixels on the front, facing the user. It was sold as a 'mobile videophone': the idea was that two people with VP-210s could see each other while they talked, although the picture updated only about two times per second, more like a flip-book than a smooth video. It could also store up to 20 still photos as JPEG files, a common format for digital pictures, and send them by email.","A year later, in June 2000, Samsung in South Korea released the SCH-V200, which could take photos of about 350,000 pixels. But it could not send them over the phone network; you had to connect it to a computer to get the pictures out.","The camera phone that really started the craze was the Sharp J-SH04, sold by the phone company J-Phone in Japan in November 2000. Sharp describes it as the industry's first camera-equipped mobile phone, with an image sensor of about 110,000 pixels, or about 0.11 megapixels. For comparison, many phones today have main cameras of 12 to 200 megapixels, meaning more than 100 times as many pixels. J-SH04 photos were tiny and grainy by today's standards, just big enough to look good on the phone's own small color screen.","What made the J-SH04 special was not the picture quality but the sharing. J-Phone launched a service called Sha-mail, which comes from 'shashin', the Japanese word for photograph, plus 'mail'. You could snap a picture and send it straight to a friend's phone within seconds. Suddenly a phone was not just for telling people what you were doing; you could show them.","The idea caught on fast. Within about two years, more than half of J-Phone's customers were using camera phones. Rival phone companies rushed out their own. By 2003, more camera phones were being sold worldwide each year than standalone digital cameras, largely because of demand in Japan and South Korea. You will learn in Part 14 exactly how phone cameras capture light, but it all started with these grainy 0.11-megapixel snapshots."]},{"heading":"FOMA: The World's First 3G Network","paragraphs":["i-mode worked on Japan's 2G network, which could carry only a small amount of data at a time. That was fine for short emails and text-heavy pages, but not for video, music or big pictures. Engineers around the world had been designing a third generation of mobile networks, called 3G, built from the start to carry data as well as voices.","Docomo wanted to be first. Its 3G service was called FOMA, short for Freedom of Mobile Multimedia Access, and it used a technology called W-CDMA (wideband code division multiple access). Without getting too technical, W-CDMA lets many phones share a wide band of radio frequencies at the same time, with each phone's signal marked by its own code so the network can tell them apart. Part 12 explains networks in more detail.","The launch did not go smoothly. Docomo had planned to start in May 2001 but postponed it. Instead, about 4,000 people tried out the service in a trial, and there were complaints about problems with the early phones; Docomo even recalled about 1,500 handsets. Finally, in October 2001, FOMA opened as a full commercial service, at first covering Tokyo and nearby Yokohama. It was the world's first commercial 3G mobile service.","FOMA could carry data much faster than Japan's 2G phones, with download speeds of up to a few hundred kilobits per second. That was fast enough for some FOMA phones to make video calls, where you could see the person you were talking to on your phone's screen, and to download music clips and short videos. Imagine making a video call from a Tokyo street corner in 2001, years before most people in the rest of the world had even heard of 3G.","Some numbers show the difference. Japan's PDC network could send ordinary data at 9.6 kilobits per second, and its packet data service at up to 28.8 kilobits per second. At 9.6 kilobits per second, a 100-kilobyte photo would take well over a minute to send. At a few hundred kilobits per second, the same photo could arrive in a few seconds. That jump is what made it practical to send pictures, music and video clips, not just words.","At first, though, FOMA was mostly for enthusiasts. The early handsets were bigger than 2G phones, their batteries ran down quickly, and the network covered only a few areas. It took until about 2004 for FOMA to become popular with ordinary customers. By September 2007 it had over 40 million subscribers. Today, every phone you can buy has data speeds that make early FOMA look slow, but FOMA showed that a phone network could be built mainly for data."]},{"heading":"A Wallet in Your Phone","paragraphs":["In Japan in the early 2000s, many people were already used to tapping a card to pay. In November 2001, the East Japan Railway Company introduced Suica, a contactless card you could tap on ticket gates in the Tokyo area. Inside the card was a FeliCa chip, a contactless technology made by Sony. The card does not need a battery; the reader in the ticket gate sends out a radio signal that powers the chip for a split second and swaps information with it.","Docomo had a bright idea: why not put a FeliCa chip inside a phone? In July 2004 it launched Osaifu-Keitai, which means 'wallet phone' ('osaifu' is a wallet or purse, and 'keitai' is the everyday Japanese word for a mobile phone). On July 10, 2004, the Edy electronic money service started working on Docomo wallet phones. You loaded money onto your phone and then simply held it near a reader at a shop or a vending machine to pay.","The idea grew quickly. The other big Japanese phone companies added their own wallet phones in 2005. On January 28, 2006, Mobile Suica launched, so commuters could walk through Tokyo's ticket gates by tapping their phones. Wallet phones were soon also used for credit card payments, shop loyalty cards, airline check-in and even as membership cards.","Think about how far ahead this was. Apple Pay, which let iPhone owners tap to pay, arrived in 2014, a full ten years after Osaifu-Keitai. Phone payments are now common in many countries, but Japanese commuters were tapping their phones at train gates and convenience stores in the mid-2000s."]},{"heading":"The Galápagos Phones","paragraphs":["By the mid-2000s, Japanese phones were arguably the most advanced in the world. A typical Japanese phone might have a high-resolution color screen, a camera with millions of pixels, a wallet chip, 3G internet, email with emoji, and, from 2006, a tuner that could show live digital TV through a service called One Seg. Some were waterproof so you could use them in the bath. Many people in Europe and America, holding phones with tiny screens and basic cameras, would have been amazed.","Yet hardly anyone outside Japan owned a Japanese-style phone. Why not? There were several reasons. Japan's 2G network, PDC, was used essentially only in Japan, while most of the world used GSM. Japanese phones were designed for the wishes of Japanese phone companies, which decided which features each phone had, and many services, like i-mode and Osaifu-Keitai, depended on the Japanese networks and companies behind them. Docomo did try to export i-mode. It licensed the service to phone companies in about 17 markets, including parts of Europe, but i-mode never became popular outside Japan, partly because the world's biggest phone makers made few phones for it.","People began calling this the 'Galápagos' effect. The Galápagos Islands, in the Pacific Ocean, are famous because Charles Darwin found animals there, like giant tortoises and unusual finches, that had evolved in their own special way because they were cut off from the mainland. Japan's phones, too, had evolved into amazing creatures that were perfectly suited to their home but did not spread elsewhere. Takeshi Natsuno, one of the creators of i-mode, later compared Japanese phones to the unique species Darwin found. In Japan, old-style flip phones are still jokingly called 'garakei', short for 'Galápagos keitai' (Galápagos mobile phone).","The Galápagos story has a bittersweet ending. When touchscreen smartphones with app stores arrived, starting in 2008, many Japanese customers switched to them, and Japanese phone makers lost ground. Usage of i-mode peaked around 2008. In 2019 Docomo announced that the i-mode service would finally close on March 31, 2026, more than 27 years after it began. Yet much of what Japan pioneered lives on in your pocket: mobile email and web, emoji, camera phones with instant photo sharing, 3G networks, and tap-to-pay wallets.","There is a lesson here that echoes the story of the IBM Simon in Part 5. Simon was ahead of its time but arrived before the world was ready. Japan's phones arrived at the right time for Japan, and millions of people loved them, but they were built for one country's networks and companies. To change the whole world, an invention needs both good timing and the ability to travel."]},{"heading":"Meanwhile, in North America","paragraphs":["While Japanese commuters were sending emoji, snapping Sha-mail photos and tapping their phones on ticket gates, life looked rather different across the Pacific Ocean. In the United States and Canada, most people used their phones for calls and, increasingly, text messages. Mobile web browsing was rare.","But in offices, airports and boardrooms, a new habit was spreading. Lawyers, bankers, politicians and business travelers were becoming hooked on a small device made by a company in a quiet Canadian university town. It had a tiny keyboard where every letter had its own little key, perfect for typing with two thumbs, and it delivered email the instant it arrived. Some users checked it so often that people gave it a nickname suggesting it was almost addictive. As the story is often told, its name came from the way its keys looked like the little bumps on a piece of fruit. That device, and the company that made it, are where our journey goes next."]}],"deepDive":"Why did Japan leap ahead? Business historians usually point to the way Japan's mobile market was organized. In most of Europe, phone makers like Nokia and Ericsson designed handsets and sold them to many operators. In Japan, operators such as NTT Docomo wrote detailed specifications, subsidized handsets heavily and had makers like NEC, Panasonic, Sharp and Fujitsu build to order. That 'operator-led' model let Docomo launch i-mode, emoji, FeliCa wallets and 3G on many phones at once, and it controlled billing, so it could collect small monthly fees for content companies. This created a working mobile content economy around a decade before Apple's App Store. The technology choices were pragmatic. i-mode used Compact HTML, a subset of ordinary HTML, while Europe's rival WAP used a new markup language (WML) and a gateway approach that many developers and users found awkward. i-mode was also packet-based and billed by data volume, so users could stay connected without paying for airtime by the minute. The same model had a downside. Because handsets were tailored to Japanese networks and services, built on the Japan-only PDC 2G standard, they had little export market; i-mode licensing reached about 17 markets but never caught on abroad. Economists describe this as path dependence: early, locally successful choices can lock an industry into a path that fails to transfer. When open platforms (iOS from 2007 and Android from 2008) separated the phone's software from the operator, the advantage of operator control disappeared, and Japanese makers lost share. Numbers also show how quickly technology moved. The Sharp J-SH04's camera, at about 0.11 megapixels, captured around 110,000 pixels per photo; a 12-megapixel phone camera captures over 100 times as many pixels. FOMA's early W-CDMA speeds of a few hundred kilobits per second were a big jump over 2G but are thousands of times slower than good 5G connections today. Historians still debate how much credit Japan deserves for the modern smartphone, but there is wide agreement that mobile email, emoji, camera-phone sharing and contactless phone payments were popularized in Japan first.","funFact":"Shigetaka Kurita's original 176 emoji for i-mode were each drawn on a grid of just 12 by 12 pixels, and in 2016 New York's Museum of Modern Art added them to its collection.","check":{"q":"What was the name of NTT Docomo's mobile internet service launched in February 1999?","a":"i-mode","wrong":["FOMA","Sha-mail","Symbian"]},"sources":[{"title":"i-mode","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/I-mode"},{"title":"Company history","publisher":"NTT Docomo","url":"https://www.docomo.ne.jp/english/corporate/about/outline/history/"},{"title":"A Sharp Journey: Sharp's 'Only One' products (Industry's first camera-equipped mobile phone J-SH04)","publisher":"Sharp Corporation","url":"https://global.sharp/corporate/info/history/only_one/"},{"title":"Shigetaka Kurita","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Shigetaka_Kurita"},{"title":"Emoji","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Emoji"},{"title":"Camera phone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Camera_phone"},{"title":"FOMA","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/FOMA"},{"title":"Osaifu-Keitai","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Osaifu-Keitai"}],"photos":[{"src":"img/deep/smartphone/06-1.jpg","alt":"An advert for NTT Docomo's i-mode mobile internet on a London Underground platform: \"i am faster than wap\".","file":"I am faster than wap.jpg","url":"https://commons.wikimedia.org/wiki/File:I_am_faster_than_wap.jpg","author":"No machine-readable author provided. Edward assumed (based on copyright claims).","license":"Public domain"},{"src":"img/deep/smartphone/06-2.jpg","alt":"The Sharp J-SH04 (2000) for J-Phone, one of the first camera phones. Its tiny camera lens is on the back.","file":"Sharp J-SH04 CP+ 2011.jpg","url":"https://commons.wikimedia.org/wiki/File:Sharp_J-SH04_CP%2B_2011.jpg","author":"Morio","license":"CC BY-SA 3.0"},{"src":"img/deep/smartphone/06-3.jpg","alt":"Ticket gates at a Japanese train station for IC cards only. Riders tap a card or phone on the reader.","file":"SUGOCA Automatic Ticket Gate.jpg","url":"https://commons.wikimedia.org/wiki/File:SUGOCA_Automatic_Ticket_Gate.jpg","author":"わたらせみずほ","license":"CC BY-SA 3.0"}],"words":3778},{"n":7,"title":"BlackBerry and the Keyboard Years","when":"1984 – 2010","summary":"In a small Canadian city, two friends started a company that built a little gadget with a tiny keyboard. It got email to busy people the second it was sent, and soon presidents, bankers and movie stars could not put it down. People even joked it was so addictive they called it the 'CrackBerry'!","sections":[{"heading":"Two Friends from Windsor","paragraphs":["Our story starts not in California, but in a chilly university town in Canada called Waterloo, in the province of Ontario. Waterloo is about an hour and a half's drive west of Toronto. In the early 1980s it was known for farms, insurance companies and a fast-growing university that was famous for training engineers. That university is where a young man named Mike Lazaridis was studying electrical engineering.","Lazaridis was born in 1961 in Istanbul, Turkey, to a Greek family, and moved to Canada with his parents when he was about five years old. They settled in Windsor, Ontario, a car-making city just across the river from Detroit. Young Mike was the kind of kid who took things apart to see how they worked. According to stories about his childhood, when he was 12 he won a prize from the Windsor Public Library for reading every science book on its shelves. In high school he spent his spare time in the electronics shop, and there he became close friends with another tinkerer, Douglas Fregin.","In 1979 Lazaridis went to the University of Waterloo. He was a strong student, but in 1984, only about two months before he would have graduated, he did something bold: he dropped out. He had just won a contract from General Motors to build a computer-controlled display system, the kind of electronic sign that could show messages on a factory floor. With that contract, a small government grant and a loan from his parents, he started a company with Doug Fregin and a third partner, Mike Barnstijn. The date was March 7, 1984. They called the company Research In Motion, usually shortened to RIM.","The name sounds a bit mysterious, and for years the company did not have one famous product. It did all sorts of clever engineering jobs. One of its early successes was a high-speed barcode reader for the film industry. Movie film has tiny codes printed along its edge, and RIM's reader helped editors keep track of exactly which frame was which. The invention earned technical awards from the world of film and television.","In 1992 a businessman named Jim Balsillie joined the company. Lazaridis was the engineer who dreamed up gadgets; Balsillie was a fast-talking, competitive deal-maker who loved selling them. The two became co-chief executives, which means they shared the job of running the company. It was an unusual arrangement, but for many years it worked brilliantly: one man built the machines and the other found the customers."]},{"heading":"A Pager That Learned to Type","paragraphs":["To understand what RIM built, you need to know about pagers. In the 1980s and 1990s, doctors, plumbers, reporters and drug-store delivery drivers often wore a small box on their belt called a pager, or 'beeper'. When someone wanted to reach you, they phoned a paging company, and a radio signal made your pager beep and show a phone number on its little screen. Then you had to go and find a telephone to call back. A pager could receive, but it could not answer.","Lazaridis had become fascinated by wireless data, meaning computer information sent by radio rather than voices. He believed that one day people would want to send real messages through the air, not just phone numbers. In the mid-1990s RIM built a two-way pager: a device that could both receive and send short messages. In 1998 it began shipping the Inter@ctive Pager 950, a chunky little gadget about the size of a bar of soap, with a tiny keyboard and a screen that showed a few lines of text. It ran on a single AA battery. That same year RIM announced a deal worth about 10 million dollars to supply two-way pagers to IBM.","Then came the device that gave the company its future. On January 19, 1999, RIM launched the BlackBerry 850. It still looked like a pager, and it was still called one, but it did something special: it brought your office email to your belt. You could read a message from your boss while sitting in a taxi, and you could type a reply with your thumbs on a keyboard with about 30 tiny keys.","Typing with two thumbs sounds normal today, but in 1999 it was a new idea. Most people typed on phones by pressing number keys several times for each letter, as you read about in Part 3. Lazaridis was convinced that a small keyboard held in both hands, with keys shaped so your thumbs could find them, would be faster. He was right. Practised users could type surprisingly quickly without even looking.","And the name? RIM hired a naming company called Lexicon Branding, which came up with about 40 possibilities. Someone noticed that the rows of little round keys looked like the bumpy seeds, called drupelets, on a blackberry fruit. The word also felt friendly and easy to say, which was a nice change from the stiff, technical names of most business machines. The name stuck, and it eventually became so famous that the company itself was renamed BlackBerry in 2013."]},{"heading":"The Magic of Push Email","paragraphs":["The real secret of the BlackBerry was not the keyboard. It was an idea called push email. To see why it mattered, imagine how email usually worked on early devices. Your gadget had to keep asking the server, 'Any new mail? Any new mail?' This is called pulling. It wastes battery and radio time, and if your device only checked every half an hour, an important message might sit waiting for 29 minutes.","The BlackBerry turned this around. A piece of software sat on a computer in the company's office, watching each worker's mailbox. The instant a new email arrived, the software squeezed it down to a smaller size, scrambled it into a secret code, and pushed it out through RIM's own network centre to the BlackBerry. A few seconds later, the little device buzzed. You did not have to do anything. The mail simply came to you.","This system needed very little radio data, which was important because wireless networks of the late 1990s were painfully slow. The early BlackBerry pagers used special data-only radio networks that had been built for things like delivery trucks and pagers, not for phone calls. Because RIM compressed every message so carefully, a BlackBerry could keep a busy person connected without running out of battery or costing a fortune.","For companies, the most important part was security. Messages were encrypted, meaning they were turned into scrambled code that only the right device could unscramble. The company version of the system, called BlackBerry Enterprise Server, used strong encryption methods such as Triple DES and, later, AES. That meant a bank, a law firm or a government department could let workers carry their email around without worrying that a spy with a radio receiver could read it. Over time, governments became some of BlackBerry's biggest customers. Germany's government even described its BlackBerry communications as 'spy-proof', although later reports showed that some consumer BlackBerry services were less protected than the company versions.","Push email changed what it meant to work in an office. Before, you left work and your email stayed on your desk computer. Now it followed you to the train station, the airport, the restaurant and the kitchen table. Some people loved the freedom. Others discovered that their boss now expected an answer at 10 o'clock at night. Both of those feelings are still with us today."]},{"heading":"From Pager to Phone: Trackwheels, Trackballs and BBM","paragraphs":["At first, a BlackBerry was not a phone at all. You carried it alongside your mobile phone. But RIM quickly saw that people did not want two gadgets on their belts. In 2002 it released the BlackBerry 5810, the first BlackBerry that could make phone calls. It used the GSM network, which you met in Part 3, and a newer data system called GPRS that let it fetch email and simple web pages. There was one awkward detail: to talk on the 5810 you had to plug in a headset, because it had no built-in speaker for your ear. Later models fixed that.","The early BlackBerry devices had no touchscreen. To move around the menus, you used a trackwheel, a little ridged wheel on the right side that you rolled with your thumb and pressed to select. It was simple and worked well with one hand, but it could only move up and down.","In September 2006 RIM launched the BlackBerry Pearl. It was smaller and prettier than earlier models, aimed at ordinary people as well as business workers, and it had a camera and a music player. In place of the trackwheel, it had a shiny trackball in the middle, about the size of a pea, that glowed and could roll in every direction. Later came popular models such as the Curve (2007) and the Bold (2008), which added faster 3G data. Eventually the trackball was replaced by an optical trackpad, a tiny sensor that followed your thumb like a miniature computer mouse.","Then there was BBM. BlackBerry Messenger launched on August 1, 2005. Every BlackBerry had its own eight-character code called a PIN, made of numbers and letters. If a friend gave you their PIN, you could send them instant messages over the internet instead of paying for ordinary text messages. BBM showed whether your message had been delivered and whether it had been read, and conversations popped back and forth almost instantly. For many teenagers and students, especially from about 2008 onward, 'What's your BBM PIN?' became a normal question. In May 2011 RIM said BBM had about 43 million active users. In some countries, such as Indonesia, BBM stayed hugely popular for years.","Notice something here: instant chat apps such as WhatsApp, which you will meet in Part 16, work in a very similar way. BBM was one of the first to show how much people wanted free, fast messaging on their phones."]},{"heading":"CrackBerry Nation and the President's Phone","paragraphs":["By the mid-2000s, BlackBerrys were everywhere in the worlds of business, politics and news. Walk into a meeting in Washington, London or Toronto and you might see a row of people looking down at their laps, thumbs tapping. Bankers checked them in elevators. Lawyers checked them at the dinner table. Some people slept with one next to the pillow, and the first thing they did each morning was check it.","This habit earned the device a cheeky nickname: the 'CrackBerry'. The joke compared it to an addictive drug, because people found it so hard to stop checking. The word became so common that in 2006 it was officially recognized by Webster's New World College Dictionary. Doctors even started talking about 'BlackBerry thumb', a sore thumb from too much tiny typing. It was a joke, but it pointed at something real: a device that brings you messages instantly can be very hard to ignore. Part 18 looks at that problem honestly.","Owning a BlackBerry was also a signal. It told people you were important enough that the world needed to reach you right now. Celebrities, sports stars and business leaders carried them, and photographers caught film stars tapping away on them. For a while, a BlackBerry on the table at lunch was a bit like the brick phone of the 1980s: a status symbol.","The numbers show how big it became. In the United States, about 18 million of the roughly 43 million smartphones in use in January 2010 were BlackBerrys, around 43 percent, more than four out of every ten. Around the world, the number of BlackBerry users kept climbing even after the iPhone arrived, reaching roughly 80 million in about 2011 to 2012. Different reports give slightly different peak numbers, from about 80 to 85 million, but either way it was a giant. RIM, the little company from Waterloo, had become one of the most valuable technology firms in Canada.","Perhaps the most famous BlackBerry user of all was Barack Obama. During his 2008 campaign to become President of the United States, he relied on his BlackBerry to keep in touch with advisers, friends and family. Photographers often caught him reading it between speeches.","When he won the election, a problem appeared. The President of the United States is one of the most watched people on Earth, and foreign spies would love to read his messages. On top of that, US law says that a president's official communications are public records that must be saved for history. For years, presidents had simply not used email at all. Security experts and lawyers warned that Obama might have to give up his beloved device.","Obama argued hard to keep it, and in January 2009, soon after he took office, it was reported that he had won. The New York Times described it as a 'hard-fought e-victory'. According to news reports at the time, his BlackBerry was given extra security protection, and only a small circle of senior staff and close friends had his address. His messages were also kept as official records, as the law required. He became the first sitting American president known to carry a smartphone-style device for email.","Marketing experts estimated that this kind of free, world-famous advertising was worth tens of millions of dollars to RIM. Imagine a company that started by building barcode readers for film editors, and now the most powerful leader in the world refused to let go of its product. It looked as if BlackBerry could not lose. Years later, in 2016, it was reported that Obama had finally moved on to a different phone, and by then the whole phone world had changed."]},{"heading":"The Rivals: Treo, Windows Mobile and the Giant from Finland","paragraphs":["BlackBerry was not alone. The 2000s were a crowded, noisy time for smart phones, with many companies trying different ideas. Remember Jeff Hawkins and Donna Dubinsky, who created the Palm Pilot in Part 4? They had left Palm and started a new company called Handspring. In 2002 Handspring released the Treo 180, which combined a Palm organizer with a mobile phone and a little keyboard. The Treo 600 followed in 2003, a neat 'candy bar' shape with a colour touchscreen you could tap with a stylus and a thumb keyboard underneath. That same year Palm bought Handspring, bringing the inventors back home. Treo fans loved how you could look at your calendar while on a call, or dial someone straight from your contacts list. Nineteen different Treo models were released before the line ended around 2009.","Microsoft had its own plan. Its software for handheld computers began as Pocket PC in 2000, and in 2003 it was renamed Windows Mobile. Microsoft did not usually make the phones itself. Instead, many manufacturers built phones that ran its software, a bit like many companies building personal computers that run Windows. A Taiwanese company called HTC built about 80 percent of the roughly 50 million Windows Mobile devices made up to early 2009. These phones had a Start menu and tiny scroll bars that looked like a shrunken desktop computer, which made them powerful but fiddly. You usually needed a stylus to hit the small buttons. Even so, Windows Mobile was a serious competitor: one estimate gave it about 42 percent of the American smartphone market in 2007, even more than BlackBerry that year by that particular count.","But the true giant of the phone world lived far from America, in Finland. You met Nokia in Part 3, maker of the Nokia 3310. In October 1998 Nokia overtook Motorola to become the world's biggest seller of mobile phones, and it stayed on top for well over a decade, until about 2012. At the end of 2007, around four out of every ten mobile phones sold on Earth were Nokias, and about half of all smartphones sold were Nokias too.","Most Nokia smartphones ran an operating system called Symbian, which Nokia had helped set up in 1998 together with other phone makers, as Part 5 explained. Nokia's flagship smartphones, called the N-series, were packed with features. The Nokia N95, announced in September 2006 and sold from March 2007, had a 5-megapixel camera with Carl Zeiss lenses and a flash, built-in GPS for maps, Wi-Fi, fast 3G internet and a clever screen that slid in two directions: one way to reveal number keys, the other way to show music buttons. Nokia proudly called it a 'multimedia computer'. It cost about 730 US dollars in America without a contract, and about 7 million were sold in 2007 alone.","If you had asked experts in 2006 who would rule the future of smartphones, most would have named BlackBerry for business, Nokia for everyone else, and perhaps Microsoft or Palm as challengers. Hardly anyone would have mentioned a computer company famous for music players."]},{"heading":"Life on a Tiny Screen","paragraphs":["What was it actually like to use a phone in about 2005? Let's take an imaginary walk through a day.","In the morning you pick up your phone. Its colour screen is about 2 inches across, with roughly 176 by 220 pixels. That is so few dots that a single icon on a modern phone has almost as much detail. If you have a smartphone, it probably has a physical keyboard, either below the screen or sliding out from the side, and maybe a plastic stylus tucked into a slot. You select menus with a joystick, a trackwheel, a direction pad or the stylus.","On the bus you try to check the news. Phone networks are slow, and many websites are far too big and complicated for your phone. So you visit special mobile pages written in a stripped-down format called WAP, which shows mostly text and a few tiny pictures. A page might take many seconds to load, and you might pay for every kilobyte of data. Some phones could show full websites, but you had to scroll around them like looking at a giant poster through a keyhole.","In the afternoon you want to listen to music. Your phone might play a few songs, but most people carried a separate MP3 player, often an Apple iPod, as well. If you wanted a good photo, you probably brought a separate digital camera too. The great dream of convergence from Part 4, one device that did everything well, still had not quite come true.","In the evening you might want a new game. Many phones of this time could run small programs written in a version of the Java programming language, so you could download games such as puzzle, racing or football games. But you usually had to buy them through your phone company's own menu, the choice was small, and a game written for one phone often looked wrong or would not work on another model with a different screen size. There was no single, simple shop where any programmer in the world could sell software to every owner of a particular phone. That missing piece would turn out to matter enormously, as Part 16 will show.","Not everyone wanted a smartphone anyway. The coolest phone of the mid-2000s was not smart at all. In late 2004 Motorola released the Razr V3, a flip phone made of thin aluminium, only about 13 millimetres thick when closed and weighing about 95 grams. Its keypad was cut from a single sheet of metal and glowed blue. Motorola designer Chris Arnholt helped give it its sleek, razor-like shape. At first it was an expensive luxury item, but as the price dropped, everyone seemed to have one in pink, black or silver. Many reports say about 130 million Razrs were sold, making it the best-selling flip phone of all time. The Razr proved something important: people cared a lot about how a phone looked and felt, not just what it could do."]},{"heading":"Kings of the Keyboard","paragraphs":["By 2006 and early 2007, the phone world seemed settled. Business people had BlackBerrys and would not give them up. Ordinary customers around the world bought Nokias by the hundreds of millions. Fashion fans flipped open their Razrs. Gadget lovers carried Treos or Windows Mobile phones with styluses.","Almost everyone agreed on one thing: a serious smartphone needed a physical keyboard. How else could you type an email quickly? Touchscreens existed, but they were mostly the resistive kind you will learn about in Part 10, which needed a firm press or a stylus and could feel slow and clumsy. Typing on a flat piece of glass, with no keys to feel, sounded like a terrible idea to many experts.","In Waterloo, RIM was busy and confident. In Finland, Nokia was the most powerful phone company in history. Neither of them knew exactly what was happening in a guarded building in Cupertino, California. There, behind locked doors, a secret team at Apple had been working for more than two years on a phone with almost no buttons at all, and no keyboard. Its makers were betting that your fingers, sliding and tapping across glass, could do everything a keyboard and stylus could do, and more. In January 2007 the world was about to find out whether they were right."]}],"deepDive":"Why did BlackBerry win so big, and then fall so fast? Historians and business writers usually point to the same strengths. RIM's system was built for a world of slow, expensive wireless data. Every message passed through RIM's own network operations centres, where it was compressed and encrypted, so a BlackBerry used far less data than rival devices and its battery lasted longer. For company IT departments, the BlackBerry Enterprise Server was the killer feature: they could control thousands of devices centrally, wipe a lost one remotely and trust the encryption. That is why governments, banks and law firms bought BlackBerrys by the thousands, and why the US government became one of its most important customers. The same strengths turned into weaknesses after 2007. As 3G and then 4G networks made data cheap and fast, RIM's careful data-saving mattered less, while big touchscreens, full web browsers and app stores mattered more. Customers increasingly chose their own phones and brought them to work, so IT departments lost some of their power to pick BlackBerry for everyone. RIM's first all-touchscreen answer, the BlackBerry Storm (2008), had a screen that physically clicked when pressed and received many poor reviews. The numbers tell the story. In the US, BlackBerrys made up about 43 percent of smartphones in use in January 2010; by February 2016 the figure was less than 1 percent. The company's stock fell by about 87 percent between 2010 and 2013. In October 2011 a network switch failure knocked out email and messaging for tens of millions of users for about three days, and under pressure from unhappy shareholders, co-CEOs Lazaridis and Balsillie stepped down in early 2012. Notice also that the user count kept rising until about 2012 even while market share collapsed: the whole smartphone market was growing so fast that BlackBerry could gain customers and still fall far behind. Sources even disagree about the exact peak, quoting figures from about 80 to 85 million subscribers, a reminder that company statistics depend on how you count. In September 2016 BlackBerry announced it would stop designing its own phones and license its brand to other manufacturers. The company survives today as a software and cybersecurity business. Business schools still teach its story as a warning that being the best at yesterday's problem is not enough.","funFact":"The name BlackBerry was chosen partly because the device's rows of small round keys reminded people of the tiny bumps, called drupelets, on a blackberry fruit.","check":{"q":"What was special about BlackBerry's 'push email'?","a":"New emails were sent to the device automatically the moment they arrived, without the user having to check","wrong":["You had to push a button every hour to download new emails","Emails were printed out and pushed under your office door","It could only send emails, never receive them"]},"sources":[{"title":"BlackBerry Limited","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/BlackBerry_Limited"},{"title":"BlackBerry","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/BlackBerry"},{"title":"Mike Lazaridis","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mike_Lazaridis"},{"title":"BlackBerry Messenger","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/BlackBerry_Messenger"},{"title":"Palm Treo","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Palm_Treo"},{"title":"Windows Mobile","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Windows_Mobile"},{"title":"Nokia N95","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nokia_N95"},{"title":"Motorola Razr V3","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Motorola_Razr_V3"}],"photos":[{"src":"img/deep/smartphone/07-1.jpg","alt":"An early RIM BlackBerry 957 (2000), with a big grey screen and a tiny thumb keyboard.","file":"Blackberry RIM 957 - 01.jpg","url":"https://commons.wikimedia.org/wiki/File:Blackberry_RIM_957_-_01.jpg","author":"Jarek Tuszyński","license":"CC BY 4.0"},{"src":"img/deep/smartphone/07-2.jpg","alt":"President Barack Obama checks his BlackBerry as he walks to the Oval Office, March 2010.","file":"P031810PS-0013 (4456732652).jpg","url":"https://commons.wikimedia.org/wiki/File:P031810PS-0013_(4456732652).jpg","author":"The White House from Washington, DC","license":"Public domain"},{"src":"img/deep/smartphone/07-3.jpg","alt":"The super-thin Motorola Razr V3 flip phone, closed (left) and open to show its flat metal keypad (right).","file":"Motorola Razr V3 montage closed open.png","url":"https://commons.wikimedia.org/wiki/File:Motorola_Razr_V3_montage_closed_open.png","author":"Raimond Spekking","license":"CC BY-SA 4.0"}],"words":3867},{"n":8,"title":"One More Thing: The iPhone","when":"2004 – 2008","summary":"Inside Apple, a secret team built a phone with almost no buttons, where you used your fingers to tap, swipe and pinch a big glass screen. When Steve Jobs showed it on stage in 2007, people gasped. It was not the first smartphone, but it changed what everyone thought a phone should be.","sections":[{"heading":"A Music Company Worries About Phones","paragraphs":["In the mid-2000s, Apple was riding high on a little white music player. The iPod, first sold in 2001, had become one of the most popular gadgets in the world. Its white earbuds were everywhere, on buses, in schools and on running tracks. Apple's boss, Steve Jobs, had co-founded the company in 1976 and returned to lead it in 1997, and the iPod had helped turn Apple from a struggling computer maker into one of the most talked-about companies on the planet.","But Jobs and his team could see a danger coming. Mobile phones were getting better at playing music. If everyone's phone could hold their songs, why would anyone carry a separate iPod? The very thing that made Apple successful could be swallowed up by phones made by other companies.","Apple's first answer was a partnership. In 2005 it worked with Motorola, maker of the famous Razr you met in Part 7, on a phone called the ROKR E1 that could play songs from Apple's iTunes software. It was a disappointment. It was slow to load music, it was limited to about 100 songs, and it looked like an ordinary phone because Motorola and the phone company had a big say in its design. Many people at Apple felt that letting other companies design the product had been a mistake. If Apple was going to make a phone, it wanted to design everything itself: the outside, the software and how it felt in your hand.","There was another problem. In those days, phone networks such as Cingular, Verizon and Vodafone had huge power over the phones they sold. They often decided which features a phone had, what software was on it and what logos appeared on the screen. Jobs disliked most of the phones of the time and reportedly complained that they were confusing and ugly. So Apple made an unusual deal with Cingular Wireless, a big American network that later became part of AT&T. Cingular agreed to let Apple design the phone completely by itself, in secret, without even seeing it until it was nearly finished. In return Cingular got the right to be the only American network to sell it for several years, and Apple received a share of the monthly money customers paid. The collaboration reportedly cost about 150 million dollars over about 30 months."]},{"heading":"Project Purple","paragraphs":["Inside Apple, the phone was known by a code name: Project Purple. Apple is famous for secrecy, and Project Purple was secret even by Apple standards. The team eventually grew to about a thousand people. Engineers were sometimes recruited onto the project without being told what it was, only that they would work very hard, give up nights and weekends, and could not tell even their families. Parts of the building where they worked were locked off with badge readers, and team members reportedly nicknamed one area 'the Purple Dorm' because they spent so much time there.","Three leaders under Steve Jobs shaped the phone. Jony Ive, a British designer who had also shaped the iMac and the iPod, led the design: how it looked and felt. Tony Fadell, who had led the iPod team, was in charge of the hardware: the electronics, the antennas and the battery. Scott Forstall, a software engineer who had worked with Jobs for years, led the team writing the phone's software, which was based on the Mac computer's operating system but squeezed down to fit in a pocket.","Interestingly, the iPhone grew partly out of a different idea. Apple had been experimenting with a tablet computer, a flat screen you could control by touching it. Jobs later said that when he saw how well the touch technology worked, he decided to use it for a phone first, and save the tablet for later. That tablet idea eventually became the iPad in 2010.","Apple's touch skills got a big boost from a small company in Delaware called FingerWorks. It had been founded in 1998 by Wayne Westerman, a university student researching multi-touch surfaces, meaning surfaces that can sense several fingers at once, and his professor John Elias. Westerman had painful wrist and hand problems from too much typing, called repetitive strain injury, and he wanted to invent gentler ways to control computers. FingerWorks made touch pads and keyboards that understood finger gestures, such as sliding two fingers to scroll. In 2005 Apple quietly bought FingerWorks' patents and technology, and Westerman and Elias went to work at Apple. Their ideas became part of the iPhone's multi-touch screen.","The team tried more than one approach. According to later interviews with team members, one early prototype used an iPod-style click wheel for dialing numbers, a bit like an old rotary phone. It did not work well, and the multi-touch design won. Building a big touchscreen phone was extremely hard. The team had to make the glass sense fingers reliably, stop your cheek from pressing buttons during calls, and make everything respond so smoothly that touching the screen felt natural, not laggy. Many of these problems were still not fully solved only weeks before the phone was shown to the world.","The hardware team had its own puzzles. Radio waves do not pass easily through metal, yet the designers wanted a sleek aluminium back. Their solution was a strip of black plastic across the bottom of the phone's back, which hid the antennas and let radio signals in and out. The battery was sealed inside to save space, which is one reason the phone could be so thin. Every millimetre mattered, because the large screen, the battery, the circuit board and the speakers all had to fit into a case not much thicker than a pencil."]},{"heading":"The Glass That Came Back from the 1960s","paragraphs":["Early iPhone prototypes had screens covered in hard plastic. Glass seemed too risky, because it might shatter if you dropped the phone. But a famous story says that Steve Jobs carried a prototype in his pocket and found that his keys had scratched the plastic. He decided the phone must have a glass screen after all, one that would resist both scratches and breaking. The problem was that the phone was due to go on sale only months later, and nobody was making such glass in the right size and thickness.","Apple turned to Corning, an American glass company based in the town of Corning, New York, with a history going back to the 1800s. Corning had made the glass for Thomas Edison's light bulbs and for countless television tubes. Its chief executive, Wendell Weeks, told Jobs about an old experiment hidden in the company's files.","Back in the early 1960s, Corning had run a research effort called Project Muscle to make glass much stronger. By the early 1960s its scientists were working on a chemical treatment that worked by swapping atoms. Ordinary glass contains small sodium ions. When the glass is dipped into a bath of hot, melted potassium salt at about 400 degrees Celsius, some of those sodium ions near the surface swap places with bigger potassium ions. Picture a row of tightly packed tennis balls where you squeeze bigger footballs into the same spaces. The surface ends up crammed tight and squeezed together, which scientists call compressive stress. A crack has a much harder time starting in glass whose surface is already being squeezed. Part 10 explains this ion exchange in more detail.","Corning sold the strengthened glass as Chemcor. It was so tough that it was tested in the windows of a small number of racing cars, about 100 Dodge Darts and Plymouth Barracudas in 1968, where light weight mattered. But it was expensive, and few customers needed it, so the idea mostly sat on the shelf. Corning had started looking again at whether the glass could be made thin enough for gadgets in about 2005.","According to Walter Isaacson's biography of Steve Jobs, when Jobs asked for the glass, Weeks explained that Corning had no factory making it. Jobs insisted that Corning could do it. Corning converted a factory in Harrodsburg, Kentucky, that had been making glass for screens, and managed to produce the new glass in a matter of months. It was later given a brand name: Gorilla Glass. So remember, Gorilla Glass was not invented for the iPhone. It was a 1960s invention that found its perfect use about 45 years later. By October 2012, Corning said more than a billion mobile devices used it."]},{"heading":"Three Things in One: January 9, 2007","paragraphs":["Imagine a huge, dark hall at the Moscone Center in San Francisco on the morning of January 9, 2007. Thousands of people have packed in for Macworld, a yearly show for fans of Apple computers. Reporters sit with laptops open. Rumours have swirled for months that Apple might make a phone, but nobody outside the company knows what it looks like.","Steve Jobs walks on stage in his usual outfit: black turtleneck, blue jeans and grey trainers. After talking about computers and the iPod, he tells the crowd that every once in a while a revolutionary product comes along that changes everything. Then he says Apple is going to introduce three revolutionary products. The first, he says, is a widescreen iPod with touch controls. The second is a revolutionary mobile phone. The third is a breakthrough internet communications device.","He repeats the list: 'An iPod, a phone, and an internet communicator.' He says it again, faster. The audience starts to laugh and cheer as they realize what is happening. 'These are not three separate devices,' Jobs explains. 'This is one device, and we are calling it iPhone.' Then he announces: 'Today, Apple is going to reinvent the phone.'","Over the next hour, Jobs showed the phone working on a giant screen. He scrolled through a music library by flicking his finger. He tapped a contact to make a call. He stretched a photo bigger by spreading two fingers apart. He opened a full web page of The New York Times and zoomed in with a double-tap. To show off Google Maps, he searched for a nearby coffee shop and, as a joke, called it on stage and ordered 4,000 lattes to go before hanging up. In Apple's press release that day, Jobs said, 'We are all born with the ultimate pointing device, our fingers.'","What the audience did not know was how fragile the demonstration was. According to later reporting, the prototype phones were still full of software bugs and could crash if used in the wrong order. Engineers had planned a careful 'golden path', a sequence of actions known to work, and Jobs had rehearsed it again and again. Some team members reportedly watched with their hearts in their mouths, and quietly celebrated when each part of the demo succeeded.","The same keynote included two smaller surprises. Apple announced that it was changing its name from Apple Computer to simply Apple Inc., a sign that it now saw itself as much more than a computer company. And there was a problem with the name 'iPhone': another company, Cisco, already held a trademark for it and sued Apple the very next day. The two companies soon reached an agreement that let both use the name."]},{"heading":"What Was New: Pinch, Swipe and the Whole Web","paragraphs":["The first iPhone was a slim slab of glass and aluminium, about 11.6 millimetres thick and weighing about 135 grams. Most of its front was a 3.5-inch screen with 320 by 480 pixels, which works out to about 163 pixels per inch. That seems tiny compared with today's phones, but in 2007 it was a huge, sharp screen for a phone. It had only four physical buttons, a volume control and a ringer switch. The most famous button sat just below the screen: the round Home button that always took you back to the main screen.","The biggest change was multi-touch. Earlier touchscreen phones mostly used resistive screens that sensed one point at a time and worked best with a stylus. The iPhone's capacitive screen could sense more than one finger at once. This allowed new gestures that soon felt completely natural: swiping to scroll, flicking through photos, and pinch-to-zoom, where you spread or squeeze two fingers to make something bigger or smaller. Scrolling lists even seemed to have weight and bounce gently at the end. Part 10 explains how capacitive screens sense your fingers.","Because there was no keyboard, the phone showed a keyboard on the screen only when you needed one. The rest of the time the whole front could be used for pictures, video, maps or web pages. To help with mistyped letters on flat glass, the software quietly guessed which key you meant and corrected common mistakes.","When you switched the phone on, you saw a home screen with a neat grid of colourful rounded-square icons, one for each app, and a row of four favourites along the bottom: Phone, Mail, Safari and iPod. There were no complicated menus inside menus, as on many older phones. You simply touched the thing you wanted. Even a small child could work out how to look at photos within a minute or two, something that was rarely true of the button-filled phones of the time.","The iPhone also came with Safari, a real web browser that showed full websites, the same pages you would see on a computer, instead of the cut-down WAP pages most phones used. You could double-tap a column of text to zoom into it. For many people, this was the first time the 'real' internet felt usable on a phone.","There were clever smaller ideas too. Visual voicemail showed a list of your voice messages, so you could play any message in any order instead of listening to them one after another. Three sensors worked quietly in the background. An accelerometer noticed when you turned the phone sideways and rotated the picture. A proximity sensor turned off the screen when you held the phone to your ear, so your cheek did not press buttons. An ambient light sensor adjusted the brightness to match the room. Inside was a processor based on the ARM designs you will meet in Part 11, running at 412 megahertz, and 128 megabytes of working memory."]},{"heading":"What Was Missing","paragraphs":["For all its magic, the first iPhone had some surprising gaps, and critics pointed them out loudly. The most important was speed. It did not support 3G, the faster mobile data networks that were spreading in 2007. Instead it used an older, slower system called EDGE, so web pages could take a long time to load when you were away from Wi-Fi.","There was also no App Store. You could not install new programs made by other companies. You got the apps Apple included, such as Mail, Safari, Maps, Weather, Stocks, Photos, Calculator and Notes, and that was it. Apple suggested that programmers build web apps that ran inside Safari instead. Other missing features now seem amazing: there was no copy-and-paste for text, no way to send picture messages (called MMS), no GPS chip, and the 2-megapixel camera could take photos but not record video. You could not change the battery yourself either.","Some clever owners did not wait for Apple. Within weeks, hobbyists found ways to 'jailbreak' the iPhone, unlocking its software so they could install unofficial apps and games. This showed how badly people wanted to add their own programs, a lesson Apple would act on the following year.","Hackers also attacked another limit. The iPhone was locked to AT&T in the United States, meaning it would only work with an AT&T SIM card. In August 2007 a 17-year-old American student named George Hotz became famous for being one of the first people to unlock an iPhone so it could be used on another network. Unlocking soon spread around the world, and people in countries where the iPhone was not yet sold began importing and unlocking them.","Rivals noticed the gaps too. In a 2007 interview, Microsoft's boss Steve Ballmer laughed at the iPhone, calling it 'the most expensive phone in the world' and pointing out that 'it doesn't have a keyboard.' He predicted it would not win much of the market. Many people at BlackBerry and Nokia also doubted that business users would ever give up real keys or that a phone without a keyboard could work well for email. They were not foolish: on paper, the iPhone was missing features their phones already had. What they underestimated was how much people would love how it felt to use."]},{"heading":"Lines Around the Block: June 29, 2007","paragraphs":["The iPhone went on sale in the United States on Friday, June 29, 2007, at 6 p.m. in each time zone. Days before, people started lining up outside Apple and AT&T stores, some with folding chairs, sleeping bags and snacks. Reporters interviewed the people at the front of the lines as if they were waiting for a royal wedding. When the doors opened, store workers clapped and cheered for each customer.","The prices were high. The 4-gigabyte model cost 499 dollars, and the 8-gigabyte model cost 599 dollars, and both required a two-year contract with AT&T, the company Cingular had become. About 270,000 iPhones were sold in the United States in the first week. The phone reached its one-millionth sale 74 days after launch.","Then Apple surprised everyone. On September 5, 2007, only about two months after the launch, it dropped the 8-gigabyte iPhone's price from 599 to 399 dollars and stopped selling the 4-gigabyte model. Early buyers who had waited in line felt cheated. Jobs apologised in a public letter, and Apple gave those early customers a 100-dollar store credit. The iPhone went on sale in Germany, Britain and France in November 2007, and later in other countries.","Reviewers were impressed but careful. They praised the screen, the web browser and the touch controls, and complained about the slow EDGE network and the on-screen keyboard, which took some getting used to. At the end of 2007, Time magazine named the iPhone its Invention of the Year. In all, Apple sold about 6.1 million first-generation iPhones. That was a small number compared with the hundreds of millions of phones Nokia sold each year, but the iPhone's influence was far bigger than its sales. Almost overnight, phone makers everywhere began working on big touchscreens.","It is important to be fair here. The iPhone did not invent the smartphone. IBM's Simon had a touchscreen in 1994, Nokia's Communicators and Symbian phones ran apps, and BlackBerry and Palm Treo users had carried email in their pockets for years. Even the iPhone's key technologies came from many places: Corning's glass, multi-touch research going back decades, FingerWorks' gestures and ARM-based chips made by Samsung. What Apple did was combine these ideas into one polished, easy-to-use package, and in doing so it changed what people expected a phone to be."]},{"heading":"The iPhone 3G and an Open Door","paragraphs":["Apple did not stand still. On July 11, 2008, about a year after the first iPhone, it released the iPhone 3G. As the name says, it finally supported fast 3G networks. It also added a GPS chip, so maps could show exactly where you were, and its price dropped to 199 dollars with a two-year contract. It launched in 22 countries on its first day and eventually in about 70, far more than the original. By the end of 2008, it had overtaken the Motorola Razr as the best-selling phone in the United States.","The iPhone 3G arrived with new software that unlocked the biggest change of all: the App Store, which opened on July 10, 2008, a day before the phone went on sale. For the first time, programmers outside Apple could build apps and sell them to iPhone owners all over the world through a single shop. That story, and how it created a whole new industry, gets its own chapter in Part 16.","The first iPhone was also changing the plans of its rivals. One of them was a company that, back in 2005, had quietly bought a small startup with an interesting project: software for mobile phones. When the iPhone appeared, that team was building a phone that looked rather like a BlackBerry, with a keyboard and a small screen. After watching Jobs on stage, they realized the future had changed. The company was Google, the startup was called Android, and its software was about to change direction and race into battle with the iPhone."]}],"deepDive":"Historians of technology often use the iPhone as an example of 'combination innovation': almost nothing inside it was brand new, but the way the parts were combined was. Capacitive touch sensing dates to E. A. Johnson's work in 1965; multi-touch research ran through university labs from the early 1980s; FingerWorks had sold gesture pads since about 1999; ARM processor designs began in 1985; and Corning's strengthened glass was a 1960s invention. The first iPhone's Samsung-made chip used a 32-bit ARM core that could run at 620 MHz but was slowed to 412 MHz to save battery, and the phone had 128 MB of memory and a 1,400 mAh battery. So why did this combination succeed when earlier touchscreen phones did not? Several reasons are usually given. First, a capacitive multi-touch screen made finger control precise enough to drop the stylus. Second, Apple controlled both the hardware and the software, so it could tune the animations and touch response closely. Third, the deal with Cingular gave Apple unusual power over a product that phone networks normally controlled. Fourth, a full web browser made the phone useful from day one even without third-party apps. There are also debates. Some writers argue that the iPhone's true revolution was not the 2007 phone but the 2008 App Store, which turned the phone into a platform for other people's inventions. Jobs had at first resisted third-party apps, encouraging web apps instead, then announced in October 2007 that a software kit for developers would come in early 2008. Others point out that the first iPhone was weaker than rivals on paper: no 3G, no GPS, no video, no apps and a relatively low-resolution camera. Business analysts still argue over how much the iPhone's success came from engineering and how much from design, marketing and timing. Finally, it is worth comparing the numbers. The first iPhone had about 163 pixels per inch and sold about 6.1 million units over roughly a year. Modern phones often exceed 450 pixels per inch, and Apple now sells well over 200 million iPhones in a typical year, a scale that would have been hard to imagine in 2007.","funFact":"On the same day in January 2007 that Steve Jobs unveiled the iPhone, Apple also announced it was changing its name from Apple Computer, Inc. to Apple Inc.","check":{"q":"The iPhone's tough Gorilla Glass came from an old Corning experiment. What was it called?","a":"Chemcor, from Corning's 'Project Muscle' in the 1960s","wrong":["Project Purple, invented by Apple in 2006","Graffiti, from the Palm Pilot in 1996","FOMA, from NTT Docomo in 2001"]},"sources":[{"title":"Apple Reinvents the Phone with iPhone (press release, January 9, 2007)","publisher":"Apple Newsroom","url":"https://www.apple.com/newsroom/2007/01/09Apple-Reinvents-the-Phone-with-iPhone/"},{"title":"iPhone (1st generation)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/IPhone_(1st_generation)"},{"title":"iPhone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/IPhone"},{"title":"Gorilla Glass","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gorilla_Glass"},{"title":"FingerWorks","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/FingerWorks"},{"title":"iPhone 3G","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/IPhone_3G"},{"title":"Apple Inc.","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Apple_Inc."},{"title":"George Hotz","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/George_Hotz"}],"photos":[{"src":"img/deep/smartphone/08-1.jpg","alt":"Steve Jobs introduces the iPhone at Macworld in San Francisco, January 2007: \"Apple reinvents the phone\".","file":"Steve Jobs presents iPhone (cropped 3-2).jpg","url":"https://commons.wikimedia.org/wiki/File:Steve_Jobs_presents_iPhone_(cropped_3-2).jpg","author":"Blake Patterson","license":"CC BY 2.0"},{"src":"img/deep/smartphone/08-2.jpg","alt":"The back of a first-generation iPhone (2007): aluminium with a black plastic strip at the bottom.","file":"IPhone First Generation 8GB (3680480234).jpg","url":"https://commons.wikimedia.org/wiki/File:IPhone_First_Generation_8GB_(3680480234).jpg","author":"Carl Berkeley from Riverside California","license":"CC BY-SA 2.0"},{"src":"img/deep/smartphone/08-3.jpg","alt":"A FingerWorks TouchStream: a flat, gesture-reading touch keyboard. Apple bought FingerWorks in 2005.","file":"Fingerworks Touchstream keyboard.jpg","url":"https://commons.wikimedia.org/wiki/File:Fingerworks_Touchstream_keyboard.jpg","author":"Aslak Raanes","license":"CC BY 2.0"}],"words":3730},{"n":9,"title":"Android and the Phone Wars","when":"2003 – 2015","summary":"A tiny startup named after a robot made phone software that any company could use for free. Google bought it, and soon Android phones came in every size and price. Big companies went to court, and some old phone giants lost their crowns.","sections":[{"heading":"A Startup Named After a Robot","paragraphs":["Picture a small office in Palo Alto, California, in October 2003. There is no giant logo on the door and no crowd of reporters outside. Inside, a handful of engineers are starting a company called Android Inc. Its founders were Andy Rubin and Chris White, and they were soon joined by Rich Miner and Nick Sears. Nobody outside the technology world had heard of them. Within ten years, the software they started would be running on more pocket computers than any other system on Earth.","The company's name came from Andy Rubin himself. Back in 1989, when Rubin was a young engineer at Apple, his coworkers gave him the nickname 'Android' because he loved robots so much. He had already worked as a robotics engineer at the German optics company Carl Zeiss. The nickname stuck with him for years, and when he helped start a new company, he used it. That is why the Android software still has a little green robot as its mascot.","Rubin was not new to pocket gadgets. After Apple he worked at General Magic, a famous early-1990s company that tried to build a handheld 'personal communicator' long before the world was ready for one. Later he co-founded a company called Danger, which made the Hiptop, sold in the United States as the T-Mobile Sidekick. The Sidekick had a screen that flipped around to reveal a keyboard, and it was popular with teenagers and celebrities for sending messages and browsing a simple version of the web. Rubin left Danger in early 2004 to work full time on Android.","Here is a surprise: Android was not first meant for phones at all. The team's earliest plan was software for digital cameras, under a working name of FotoFrame. The idea was that a camera could run smart software and send photos to a computer or the internet. But digital cameras were a smaller business than the founders hoped, and phones were selling by the hundreds of millions. In April 2004 the team changed direction. They would make an operating system for mobile phones instead.","Remember from the glossary that an operating system, or OS, is the main software that runs a device and lets apps work on it. In 2004, almost every phone company built its own operating system, or used one that belonged to somebody else, like Symbian (shared by Nokia, Ericsson and others), Windows Mobile from Microsoft, or BlackBerry's own system. Writing an app that worked on all of them was a nightmare, because each one was different. Android's founders dreamed of one open system that many companies could share. It was a big idea for a tiny team that was running short of money."]},{"heading":"Google Comes Knocking","paragraphs":["In July 2005, the internet search company Google quietly bought Android Inc. The price was not announced, but it is usually reported as at least 50 million US dollars. That sounds like a lot, but for Google it was a small purchase, and hardly anyone noticed at the time. Rubin, Miner, Sears and White all moved to Google, and Rubin went on to lead the Android project there.","Why would a search company want phone software? Google made most of its money from advertisements shown next to search results. Its leaders could see that people would soon be going online with phones instead of only with desktop computers. If phones were controlled by companies that preferred their own search engines and their own stores, Google might be shut out. Having its own phone software meant Google's search, maps and email would always have a home in people's pockets.","It is important to be fair about who made Android. Google did not invent it from nothing. It began as the startup Android Inc., and Google bought it and then spent years building on it with a much bigger team. Many of the most important later parts came from Google engineers, but the seed was planted by Rubin and his co-founders.","For the next two years the Android team worked in secret. According to later accounts by journalists and people who were there, their main test phone, nicknamed 'Sooner', looked a lot like a BlackBerry: a small screen with a full keyboard of tiny buttons below it, and no touchscreen. In early 2007 that seemed perfectly sensible, because keyboards were what serious smartphones had.","Then, on January 9, 2007, Steve Jobs walked onto a stage and showed the iPhone, as we saw in Part 8. It had a big multi-touch screen and no keyboard at all. Reports say the Android team realized at once that their plans had to change. They pushed harder on a second, touchscreen design that HTC was building. Android would still support keyboards, but from then on it was built for fingers on glass as well. The iPhone did not create Android, but it changed the direction Android took."]},{"heading":"Free for Everyone: The Open Handset Alliance","paragraphs":["On November 5, 2007, Google finally told the world what it had been doing. It did not announce a 'Google phone'. Instead, it announced a group called the Open Handset Alliance, with 34 founding members. The list included phone makers such as HTC, Motorola, Samsung and Sony Ericsson; chip companies such as Qualcomm, Intel, Texas Instruments and NVIDIA; and mobile networks such as T-Mobile, Sprint, China Mobile and Japan's NTT Docomo. Together they promised to support Android as a shared platform.","What made Android so different was the word 'open'. Android was released as open-source software, which means its source code (the human-readable instructions that programmers write) was published for anyone to read, copy and change. Most of it was shared under a license called the Apache License 2.0, which lets companies use the code for free, even in products they sell. That is very different from Apple's iOS, which only Apple can put on a phone, or BlackBerry's system, which only BlackBerry used.","Android was built on top of Linux, a free operating system started in 1991 by a Finnish student named Linus Torvalds. The deepest part of Linux, called the kernel, is like the engine room of a ship. It controls the memory, decides which program gets to use the processor next, and talks to hardware such as the screen, the radio and the battery. By borrowing the Linux kernel, the Android team did not have to write all that difficult low-level code from scratch, and they got software that had already been tested on millions of computers.","A week later, on November 12, 2007, Google released a software development kit, or SDK: a free set of tools that let programmers start writing Android apps before any Android phone even existed. Google also ran a contest with prize money to encourage developers to build the first apps.","But wait: if Android was free, how did Google make money? The answer was its services. Phone makers that wanted the official Google apps, such as Gmail, Google Maps, YouTube and the app store, made agreements with Google, and Google earned money from the searches and advertisements people saw on their phones. The free software was a bit like giving away the road so that more people would drive to your shops.","For phone makers, this was a gift. Building an operating system costs huge amounts of time and money. Now a company in Taiwan, South Korea or China could take Android, add its own design touches, and sell a modern smartphone without writing a whole system itself. That one decision would shape the next decade of the phone industry."]},{"heading":"Meet the G1: The First Android Phone","paragraphs":["On September 23, 2008, T-Mobile and the Taiwanese company HTC showed off the first phone to run Android. In the United States it was called the T-Mobile G1; HTC called it the HTC Dream. It went on sale in the US on October 20, 2008, for 179 dollars with a two-year T-Mobile contract, and in the UK in November 2008.","If you held a G1 today, it would feel like a strange cousin of a modern phone. It had a 3.2-inch capacitive touchscreen with 320 by 480 pixels, the same number of pixels as the first iPhone. But the whole screen slid sideways to reveal a full keyboard with five rows of keys, a reminder of the BlackBerry era. On the 'chin' below the screen sat a little clickable trackball for scrolling and selecting. It weighed about 158 grams and ran on a 528-megahertz Qualcomm processor with 192 megabytes of working memory and a 3.15-megapixel camera with autofocus.","Some things the G1 did better than the first iPhone. It worked on fast 3G networks, it had GPS, and its battery could be swapped out. It also came with Google's own apps built in: Gmail, Google Maps with Street View, and YouTube. Most important of all, it had the Android Market, an app store where people could download new programs. The Android Market opened in the autumn of 2008, just a few months after Apple's App Store (Part 16 tells the story of apps).","Other things were clumsy. The G1 had no normal headphone socket, so you needed an adapter to plug in ordinary headphones. At first you could only type on the slide-out keyboard, because there was no on-screen keyboard yet. Reviewers liked the ideas inside it but found the design a bit awkward. Even so, T-Mobile said in April 2009 that it had sold more than one million G1s in the US.","Android improved quickly. Version 1.5, released in April 2009, added an on-screen keyboard and the ability to record video. It was nicknamed 'Cupcake', starting a famous tradition: Android versions were named after sweet treats in alphabetical order. After Cupcake came Donut, Eclair, Froyo (frozen yogurt), Gingerbread, Honeycomb, Ice Cream Sandwich, Jelly Bean, KitKat, Lollipop, Marshmallow, Nougat, Oreo and Pie. In 2019 Google dropped the dessert names and simply called the next version Android 10, saying numbers were clearer for people around the world.","At the end of 2009, another phone showed how far Android had come. The Motorola Droid, sold by the US network Verizon, ran Android 2.0 and was backed by a huge advertising campaign with the slogan 'Droid Does', a cheeky way of pointing out things the iPhone could not do at the time. For the first time, Android looked like a real challenger."]},{"heading":"Galaxies, Phablets and Phones for Everyone","paragraphs":["The company that gained the most from Android was Samsung, the South Korean electronics giant. On March 23, 2010, Samsung announced the Galaxy S. It went on sale in June 2010 with a 4-inch Super AMOLED screen (a kind of OLED display, which you will meet in Part 10), and it sold more than 24 million units. Each year a new Galaxy S followed, and within a few years Samsung was selling more smartphones than any other company in the world.","In 2011 Samsung tried something many experts thought was silly. At the IFA electronics show in Berlin, it revealed the Galaxy Note, a phone with a 5.3-inch screen. Today that sounds normal, maybe even small, but at the time it looked enormous next to a 3.5-inch iPhone. One review website called it 'positively gargantuan'. The Note also came with a stylus called the S Pen that could sense 128 different levels of pressure, so you could draw thin or thick lines like a real pen.","Reporters invented a word for this in-between gadget, half phone and half tablet: the 'phablet'. Many people laughed, but buyers did not. Samsung had sold about 10 million Galaxy Notes by August 2012. People liked bigger screens for watching videos, reading and looking at maps. Over the next few years almost every phone maker, including Apple with the iPhone 6 Plus in 2014, made bigger phones too. The phablet won so completely that the word has almost disappeared, because nearly every phone is now that size.","Android also made smartphones much cheaper. Because the software was free, companies could concentrate on building affordable hardware. In China, companies such as Huawei, Lenovo, ZTE, Oppo, Vivo and Xiaomi (founded in 2010) built phones for millions of first-time buyers. In India, companies such as Micromax sold Android phones for a small fraction of an iPhone's price. In 2014 Google launched a program called Android One, starting in India, to help local companies make decent low-cost phones.","This is one of Android's biggest effects on history. For many people in Asia, Africa and South America, their first computer of any kind was a cheap Android phone. Part 17 explores how that changed lives around the world.","Openness had a downside, though. With hundreds of companies making thousands of different Android models, each with its own screen sizes, chips and customized software, it was hard for apps to work perfectly everywhere. Programmers called this 'fragmentation'. Many phones also stopped receiving software updates after a year or two, because the phone maker and the mobile network both had to prepare each update. Google spent years trying to fix this, for example with a 2017 project called Treble that separated the phone maker's code from the main Android system so updates could arrive faster."]},{"heading":"The Patent Wars","paragraphs":["As Android phones grew more popular, Apple grew angry. Steve Jobs believed Android had copied the iPhone. In his authorized biography, written by Walter Isaacson and published in 2011, Jobs is quoted as saying, 'I'm going to destroy Android, because it's a stolen product.' Instead of attacking Google directly, Apple went after the companies that made Android phones, especially Samsung.","To understand the fight, you need to know what a patent is. A patent is a legal right given by a government to an inventor. For a limited time, usually about 20 years for an invention, nobody else can use that invention without permission. There are utility patents, which protect how something works, and design patents, which protect how something looks. A company that thinks its patent has been copied can sue and ask a court for money or even a ban on selling the copying product.","In April 2011, Apple sued Samsung in a federal court in California. Apple said Samsung had copied iPhone features protected by its patents, such as the way a page 'bounces back' when you scroll past the end, tapping to zoom in, and the look of the phone itself: a flat rectangle with rounded corners, a grid of colorful icons and a single button at the bottom. Samsung fought back and sued Apple over some of its own patents, especially ones about mobile radio technology.","In August 2012 a jury in San Jose decided that Samsung had copied Apple's patents and awarded Apple about 1.05 billion dollars, one of the largest patent awards ever at that time. But that was far from the end. The judge, Lucy Koh, found mistakes in how the damages had been calculated and ordered parts of the case to be tried again, which cut the amount. The case climbed all the way to the US Supreme Court, which ruled 8 to 0 in December 2016 that design-patent damages might be based only on the copied part of a phone, such as its case and screen, rather than the whole phone. In a new trial in May 2018, a jury set the damages at about 539 million dollars. Then, in June 2018, after seven years of fighting, Apple and Samsung quietly settled. The details were kept secret.","The fight spread around the world, to courts in Germany, the Netherlands, South Korea, Japan, Australia and Britain. Results were mixed. In the UK, a judge decided that Samsung's Galaxy tablets did not copy the iPad, and Apple was ordered to post a notice on its own website saying so. Meanwhile, other companies sued each other too, which is why newspapers started calling this period the 'smartphone patent wars'.","Here is the strange part: during all these years in court, Samsung was also one of Apple's biggest suppliers, making chips and screens for iPhones. The two companies were enemies and business partners at the same time. In the end, the patent wars did not stop Android. They mostly made lawyers busy and showed how valuable a good design had become."]},{"heading":"Giants Fall: Nokia and BlackBerry","paragraphs":["While Android and the iPhone rose, the old kings of the phone world struggled. In Part 7 we saw that Nokia was the world's biggest phone maker and BlackBerry ruled the business world. Their fall is one of the fastest in the history of any industry.","Nokia's smartphones ran Symbian, an operating system designed in an age of keyboards and small screens. It was hard to make it feel as smooth as an iPhone. In February 2011, Nokia's new boss, Stephen Elop, sent his staff a memo comparing the company to a man standing on a burning oil platform who must jump into the icy sea to survive. A few days later Nokia announced it would abandon Symbian for its best phones and use Microsoft's Windows Phone instead. Nokia's Lumia phones that followed had colorful designs and good cameras, but few app makers wrote apps for Windows Phone, and buyers mostly stayed with Android and the iPhone.","In September 2013, Microsoft agreed to buy Nokia's phone business. The deal was completed on April 25, 2014, for about 5.4 billion euros, including a license to use Nokia's patents. It did not work out. In 2015 Microsoft wrote off most of the value of the purchase, about 7.6 billion dollars, and announced thousands of job cuts. By 2017 it had stopped making new phones. Since 2016, phones carrying the Nokia name have been made by a different Finnish company, HMD Global, and many of them run Android.","BlackBerry's story was similar. Its company, Research In Motion, tried to answer the iPhone with the BlackBerry Storm (2008), a touchscreen BlackBerry that reviewers did not like much, and a tablet called the PlayBook (2011) that sold poorly. In January 2012 its co-leaders Mike Lazaridis and Jim Balsillie stepped down. A completely new system, BlackBerry 10, finally arrived in January 2013, and around that time the company renamed itself BlackBerry. By then it was too late. One estimate suggests BlackBerry's share of smartphone sales fell from about 20 percent in 2009 to around 1 percent by 2014.","BlackBerry even released Android phones, such as the Priv in 2015. In September 2016 it announced that it would stop designing its own phones and would let partner companies such as TCL make BlackBerry-branded phones instead. The company turned to security software for businesses and cars. In January 2022 it switched off the services that older BlackBerry phones needed, and those classic keyboard phones stopped working for data, calls and texts."]},{"heading":"Two Giants Left Standing","paragraphs":["Android became the world's most used smartphone operating system around 2011, only three years after the G1. Today about 70 percent of the world's smartphones run Android, and almost all of the rest run Apple's iOS. Symbian, Windows Phone and BlackBerry's systems have all disappeared. Android is also used in tablets, televisions, cars and watches, and it has billions of users.","The two winners took opposite paths. Apple controls everything about the iPhone: the hardware, the software and the App Store, so its phones work smoothly together but come from just one company. Android is shared by many companies, so it comes in every size, color and price, from cheap phones to expensive folding ones, but it is less tidy. Neither approach is simply 'better'; they suit different people. Competition between them has pushed both to improve every year.","Google itself eventually started selling phones too, to show other companies what a 'pure' Android phone could be. The Nexus One, built for Google by HTC, appeared in January 2010, and later Nexus phones were made with partners such as Samsung, LG and Motorola. In 2016 Google launched its own Pixel phones, designed in-house. Even so, the vast majority of Android phones are still made by other companies, which was the whole point of an open platform from the start.","The lesson of this part is that being big today does not protect you tomorrow. In 2007 Nokia and BlackBerry looked unbeatable. A few years later, a small startup named after a robot, together with a computer company that had never made a phone before 2007, had taken their place. Being ready to change, as Android itself did when it switched from cameras to phones and from keyboards to touchscreens, mattered more than being first.","So far we have followed companies, inventors and business battles. Now it is time to open up the phone itself. We will start with the part you touch hundreds of times a day without thinking about it: the screen. How does a sheet of glass know exactly where your finger is?"]}],"deepDive":"Android's success is often explained with a simple business idea: platform economics. A platform becomes more valuable as more people use it, because more users attract more app developers, and more apps attract more users. Apple built this loop by controlling one premium product. Google built it by giving the software away. Phone makers paid nothing for the open-source code, but to ship Google's popular apps and the Play Store they signed agreements with Google, which earned money from search advertising and app sales. This model let Android spread from the most expensive phones down to devices costing well under 100 dollars, and it is the main reason Android holds roughly 70 percent of the global market today, while iOS earns a large share of the industry's profits by selling fewer, pricier phones. The openness also raised legal questions. Besides Apple v. Samsung, Oracle sued Google in 2010, claiming that Android copied parts of the Java programming language's structure. The case reached the US Supreme Court, which ruled 6 to 2 in Google's favor in 2021, finding that Google's use was 'fair use'. In Europe, regulators fined Google about 4.3 billion euros in 2018, saying it had used Android to unfairly push its own search and browser apps; Google appealed, and the fine was largely upheld in 2022. Historians of technology also debate why Nokia lost. Some point to Elop's 2011 switch to Windows Phone, which left Nokia dependent on a weak third platform. Others argue the damage started earlier, because Symbian was difficult for developers and Nokia's internal teams competed with one another. Most agree that the iPhone and Android changed what customers valued: from hardware features and battery life to software, apps and touchscreens, areas where the old leaders were weaker. The patent wars, meanwhile, revealed how much of a smartphone is covered by patents: estimates suggest a single smartphone may touch on tens of thousands of them, many licensed through industry standards for radio networks.","funFact":"Android got its name from co-founder Andy Rubin's old nickname: coworkers at Apple called him 'Android' in 1989 because he loved robots.","check":{"q":"What was the name of the first phone to run Android, released in the US in October 2008?","a":"The T-Mobile G1 (HTC Dream)","wrong":["The Samsung Galaxy S","The Motorola Razr","The IBM Simon"]},"sources":[{"title":"Android (operating system)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Android_(operating_system)"},{"title":"HTC Dream","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/HTC_Dream"},{"title":"Open Handset Alliance","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Open_Handset_Alliance"},{"title":"Apple Inc. v. Samsung Electronics Co.","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Apple_Inc._v._Samsung_Electronics_Co."},{"title":"Samsung Galaxy Note (original)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Samsung_Galaxy_Note_(original)"},{"title":"Microsoft Mobile","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Microsoft_Mobile"},{"title":"BlackBerry Limited","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/BlackBerry_Limited"},{"title":"Andy Rubin","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Andy_Rubin"}],"photos":[{"src":"img/deep/smartphone/09-1.jpg","alt":"The HTC Dream (T-Mobile G1), the first Android phone, with its keyboard slid open.","file":"HTC Dream opened.jpg","url":"https://commons.wikimedia.org/wiki/File:HTC_Dream_opened.jpg","author":"Marcus Sümnick","license":"CC BY 3.0"},{"src":"img/deep/smartphone/09-2.jpg","alt":"A statue of the green Android robot mascot, wearing glasses, at a Google event in Berlin.","file":"Google IO connect Berlin android.jpg","url":"https://commons.wikimedia.org/wiki/File:Google_IO_connect_Berlin_android.jpg","author":"Martinimarcello00","license":"CC BY 4.0"},{"src":"img/deep/smartphone/09-3.jpg","alt":"A Samsung Galaxy Note II (2012), the second big-screen \"phablet\" Note, with its S Pen stylus.","file":"Samsung Galaxy Note II (with S-Pen) - Front.jpg","url":"https://commons.wikimedia.org/wiki/File:Samsung_Galaxy_Note_II_(with_S-Pen)_-_Front.jpg","author":"Beamish4","license":"CC BY 4.0"}],"words":3764},{"n":10,"title":"How It Works: Touchscreens and Displays","when":"1965 – today","summary":"Your phone's screen can feel exactly where your finger is, even though it is just smooth glass. Underneath, millions of tiny red, green and blue lights work together to make every picture. In this part we find out how the magic glass was invented and how it really works.","sections":[{"heading":"A Touch of Radar","paragraphs":["Our story starts not in a phone shop but in a room full of radar screens. In the 1960s, the Royal Radar Establishment in Malvern, England, was one of Britain's top laboratories for radar and electronics. Air traffic controllers there and elsewhere had a hard job: they watched glowing dots of aircraft on screens and had to give instructions quickly and without mistakes. Typing commands on a keyboard was slow. What if a controller could simply touch the screen?","An engineer named E. A. Johnson worked on exactly that question. In 1965 he published a short article describing a 'touch display', a screen that could sense a finger, and in 1967 he wrote a longer description of how it worked. His design used capacitive sensing, the same basic idea inside your phone today. Thin conductors were fixed to the face of the screen, and when a finger touched near one of them, an electronic circuit noticed a tiny change and knew which spot had been chosen.","Johnson's screen was very simple compared with a modern phone. It could sense only one touch at a time, and it was built to recognize a limited set of touch spots rather than any point on the glass. But it proved something important: a person could talk to a computer by pointing at it directly. Touch technology for air traffic control was described in further articles in the late 1960s.","A few years later, engineers at CERN, the giant European physics laboratory near Geneva, built touchscreens too. In 1972 a Danish engineer named Bent Stumpe designed a capacitive touchscreen so that scientists could control CERN's huge particle accelerator, the Super Proton Synchrotron, by touching buttons drawn on a screen instead of using thousands of physical switches. Later, with his colleague Frank Beck, he built a more advanced version that sensed touch where two sets of lines crossed.","Remember the word capacitive from the glossary: a capacitive touchscreen senses your finger by the tiny change it makes in an electric field. We will see exactly how that works in a moment. But first, the touchscreen story took a turn into a quite different technology, invented by a physicist who was trying to solve a boring problem with graph paper."]},{"heading":"Pressing Two Layers Together","paragraphs":["George Samuel Hurst, usually called Sam Hurst, was born in 1927 in a small community in Bell County, Kentucky. He became a physicist at Oak Ridge National Laboratory in Tennessee, where he studied radiation detectors, and in 1966 he became a physics professor at the University of Kentucky.","According to the story Hurst and his colleagues later told, the idea came from a dull task: his research team had to read huge amounts of experimental data from paper charts, point by point. Hurst wondered whether a sheet of electrically conducting material could do the job automatically, so that pressing on a spot would tell a computer its exact position. He and his partners set up a company called Elographics in 1971 to develop the idea. The first versions were opaque, which means you could not see through them, so they worked like a drawing tablet rather than a screen.","The big step came when the technology was made transparent and placed over a display. Starting in 1977, Elographics worked with the German company Siemens to build a see-through version, and a transparent resistive touchscreen was shown to the public at the 1982 World's Fair in Knoxville, Tennessee.","So how does a resistive touchscreen work? Imagine a sandwich made of two thin, clear, flexible sheets. Each sheet is coated on the inside with a material that conducts electricity, but not perfectly; it resists the flow a little, which is where the word 'resistive' comes from. The two sheets are held apart by a tiny gap, often using microscopic dots like the bumps on bubble wrap. When you press the top sheet with a finger or a pen, it bends and touches the bottom sheet at one spot.","Now the clever part. The controller chip sends a small voltage across the first sheet from left to right, so the voltage slowly changes along the way, like a slope. Where the sheets touch, the second sheet picks up the voltage at that exact spot, and that number reveals how far from the left edge you pressed. A few thousandths of a second later, the controller swaps roles and puts the voltage slope across the second sheet from top to bottom, which reveals how far down you pressed. Put the two numbers together and you have the position of your touch, a bit like coordinates on a map.","Because a resistive screen only cares about pressure, it works with almost anything: a bare finger, a gloved finger, a fingernail or a plastic stylus. That is why many stylus gadgets, from PDAs like the Palm Pilot (Part 4) and early keyboard-and-stylus smartphones such as the Palm Centro to handheld game consoles such as the Nintendo DS, used resistive screens. They were also cheap to make.","But they had drawbacks. You had to press, not just brush the glass, so swiping felt sluggish. The extra flexible layers made the picture a little dimmer and more reflective, and the soft top sheet could be scratched or damaged. Most resistive screens could also sense only one point at a time; if you pressed in two places, they would get confused. Capacitive screens overtook resistive ones in sales around 2010 to 2011, and today nearly every phone uses them."]},{"heading":"How Your Finger Talks to Glass","paragraphs":["Your body conducts electricity. Not much, and it is completely safe, but enough to matter. Your skin is damp and salty, and salty water carries electric charge well. A capacitive touchscreen uses this fact.","Underneath the outer glass of a phone is a grid of electrodes so thin that you cannot see them. They are usually made of indium tin oxide, or ITO, a rare material that has two useful properties at once: it conducts electricity and it is almost perfectly transparent. One set of these invisible lines runs across the screen in rows, and another set runs up and down in columns, separated by a thin insulating layer. Every place where a row crosses a column becomes a tiny sensing point. A phone screen has hundreds of these crossing points.","Each crossing works like a small capacitor, which is a device that stores a little electric charge between two conductors that are close together but not touching. The phone's touch controller sends quick electrical pulses along one set of lines and measures how much reaches the other set at each crossing. This is called mutual capacitance.","When your finger comes close, it disturbs the electric field around the nearby crossings. Some of the field that normally links the row and column is drawn toward your finger instead, so the signal measured at those crossings drops a little. The controller scans the whole grid again and again, often more than a hundred times every second, building a map of where the signals have changed. The center of the changed area is where your finger is. Software then works out whether that was a tap, a swipe or a long press.","This explains some everyday mysteries. Thick winter gloves usually do not work, because the fabric is an insulator; it keeps your conductive finger too far from the glass to change the field enough. Special touchscreen gloves have conductive threads sewn into the fingertips to carry the effect through. A plastic pen does nothing, but a touchscreen stylus has a soft tip made of conductive material. And water drops on the screen can cause 'ghost' touches, because water conducts electricity a bit like a finger does.","Because a capacitive screen measures the whole grid at once, it can see several fingers at the same time, which is the secret behind pinch-to-zoom. You do not even need to press; a light brush is enough. That is why swiping on a modern phone feels effortless, and why the iPhone in 2007 could throw away the stylus. But the idea of sensing many fingers at once has its own long history."]},{"heading":"More Than One Finger","paragraphs":["Multi-touch means a screen or touchpad can sense two or more touches at once. It feels like an invention of the iPhone age, but researchers were experimenting with it more than 20 years before the iPhone.","In 1982, a student at the University of Toronto in Canada named Nimish Mehta described a system in his master's thesis that could sense several fingers pressing on a sheet of frosted glass, using a camera underneath to watch the dark spots where fingers touched. The computer scientist Bill Buxton, who worked in the same research group and later collected the history of multi-touch, calls it the earliest multi-touch system for computer input that he knows of.","Other pioneers followed. In 1983 the American artist and computer scientist Myron Krueger built systems called Videoplace and Video Desk that used cameras to follow people's hands and bodies, letting them stretch and move shapes with gestures; some of these gestures look a lot like pinch-to-zoom. In 1984 Bob Boie at Bell Labs built a transparent capacitive screen that could sense many touches. Around the same time Buxton's Toronto team, with colleagues S. K. Lee and K. C. Smith, made a capacitive multi-touch tablet that could report the position and pressure of any number of fingers.","The idea finally reached ordinary people through a company in Delaware. Wayne Westerman, a graduate student at the University of Delaware, developed painful repetitive strain injuries in his hands while working on his doctorate. Together with his professor John Elias, he studied how to type and control a computer with light finger gestures on a flat surface instead of hard key presses. Westerman's 1999 thesis described ways to track every finger of both hands and work out which finger was which. In 1998 the two men founded a company called FingerWorks, which sold gesture keyboards and touchpads like the TouchStream and iGesture Pad. Many of its customers were people with hand injuries.","In early 2005, FingerWorks suddenly stopped selling products. Apple had bought its technology, its patents and its founders. Westerman and Elias joined Apple, where their ideas helped shape the multi-touch screen of the iPhone.","Meanwhile, in 2005 and 2006, a researcher at New York University named Jeff Han showed off a large multi-touch screen that used a clever optical trick: light bouncing inside a sheet of acrylic escaped wherever a finger pressed, and a camera saw the bright spots. His demonstration at the TED conference in February 2006, where he spun, stretched and zoomed photos and maps with his hands, amazed the audience. It was almost a year before the iPhone was announced.","Who invented multi-touch, then? Bill Buxton's answer is that no single person or company did. He describes a 'long nose of innovation': new ideas usually spend 20 to 30 years being tested, improved and slowly passed from lab to lab before they suddenly seem to appear everywhere. Multi-touch is a perfect example. The iPhone did not invent it, but it packed it into a product that millions of people used every day."]},{"heading":"Under the Glass: Millions of Tiny Lights","paragraphs":["The touch sensor tells the phone where your finger is. But the picture you see comes from a different layer underneath: the display. Look at a phone screen through a strong magnifying glass, or a drop of water on the glass, and you might see something surprising. The smooth image is really made of tiny dots arranged in a grid. Each dot is called a pixel, short for 'picture element'.","Each pixel is made of even smaller parts called sub-pixels: usually one red, one green and one blue. By making each sub-pixel brighter or dimmer, the phone can mix almost any color. Red and green light at full brightness together look yellow to your eyes. All three at full brightness look white. All three off look black. This is called additive color mixing, and it works because the human eye has three kinds of color-sensing cells, most sensitive to red, green and blue light. Your brain does the mixing.","A modern phone has a lot of pixels. A typical phone screen today has about 1,080 by 2,400 pixels, which is more than 2.5 million pixels and over 7 million sub-pixels, each controlled separately. Many phone screens pack in more than 400 pixels per inch (ppi), so close together that at normal reading distance you cannot see the individual dots. Compare that with the first iPhone in 2007, which had 320 by 480 pixels, about 163 ppi. In 2010 Apple's iPhone 4 had a 326 ppi screen that Apple called a 'Retina display', and in 2017 Sony made a phone with about 807 ppi.","The screen also redraws the whole picture many times every second. Most phones refresh 60 times per second, and many newer phones can refresh 90 or 120 times per second, which makes scrolling look smoother. Each pixel is switched by its own tiny transistor, part of a thin layer of electronics behind the screen called the thin-film transistor (TFT) backplane. That arrangement, where every pixel has its own switch, is called an active matrix.","For many years, most phone screens were LCDs, which stands for liquid crystal displays. An LCD does not make its own light. At the back is a backlight, a panel lit by small LEDs, that shines white light forward all the time. In front of it are two polarizing filters, which only let light waves vibrating in one direction pass through, and between them is a thin layer of liquid crystals: strange substances that flow like a liquid but whose rod-shaped molecules line up like soldiers. When a voltage is applied to a pixel, the crystals twist or untwist, changing how much light can pass through the second filter. Colored filters turn the white light into red, green and blue sub-pixels. So an LCD pixel is really a tiny electronic shutter in front of a lamp."]},{"heading":"OLED: Pixels That Glow by Themselves","paragraphs":["Many phones today use a different technology: OLED, which stands for organic light-emitting diode. Here 'organic' does not mean grown on a farm; it means the light comes from carbon-based chemical compounds. In an OLED, each sub-pixel is a tiny sandwich of extremely thin organic layers between two electrodes. When electricity flows through it, negative charges (electrons) meet positive 'holes' in the organic material, and as they combine they release energy as light. Different chemicals give off different colors.","The first practical OLED device was built in 1987 by two chemists at the Eastman Kodak company in Rochester, New York: Ching Wan Tang and Steven Van Slyke. Their clever two-layer design made OLEDs bright enough and efficient enough to be useful. It took many more years of work before OLED screens could be made cheaply and reliably, but by the 2010s they were common in phones. Samsung, for example, used its own 'Super AMOLED' screens in the Galaxy S in 2010. AMOLED simply means active-matrix OLED.","Because each OLED pixel makes its own light, there is no backlight. To show black, a pixel just switches off, so blacks on an OLED screen are truly black and use almost no power. On an LCD, the backlight is always on, so black areas still glow a little. That is why OLED pictures look so vivid, and why a dark theme on an OLED phone can save some battery (Part 13 explains more about power). OLED screens can also be made very thin and even built on flexible plastic, which is what makes folding phones possible (Part 19).","OLEDs have weaknesses too. The organic materials slowly wear out, and the blue ones fade fastest, so screen makers often make the blue sub-pixels bigger to balance things out. If the same bright image stays on screen for a very long time, such as a navigation bar, it can leave a faint permanent shadow called burn-in. And the organic layers are damaged by water and oxygen, so they must be sealed very carefully. Engineers keep improving these problems, and both LCD and OLED are still made today."]},{"heading":"Building the Sandwich","paragraphs":["A phone screen is not one thing but a stack of layers glued together, each thinner than a sheet of paper and many of them completely transparent. From the back to the front, a typical stack has the backplane of tiny transistors, the light-making layer (an OLED layer, or an LCD with its backlight and filters), a polarizing film that cuts down reflections, the touch sensor grid, and finally the cover glass. In many modern phones the touch electrodes are not a separate sheet at all but are built directly onto or into the display layer, which makes the screen thinner, lighter and brighter.","The layers are joined with optically clear adhesive, a special glue as see-through as the glass itself. If even a thin film of air were left between the layers, light would bounce off each surface, making the picture look washed out in sunshine. Filling the gaps with clear glue removes most of those reflections. That is one reason a modern phone is easier to read outdoors than an old one, along with brighter screens.","Making all this has to be done in extremely clean factories. A single speck of dust trapped between layers can ruin a screen, and a single broken transistor can leave a pixel that is stuck on or stuck off. Displays are made on large sheets of glass that are later cut into many phone-sized pieces, a bit like baking a big tray of brownies and slicing it up.","The software has work to do too. The touch controller and the phone's operating system must decide which signals are real. If the side of your palm brushes the edge of the screen while you hold the phone, clever 'palm rejection' software tries to ignore it. If you rest a finger and then slide it, the software must tell a scroll from a tap. When you type, the keyboard app quietly guesses which key you meant, even if your finger landed between two letters. Much of what feels like a perfect touchscreen is really a perfect partnership between hardware and software."]},{"heading":"The Armor on Top: Strong Glass","paragraphs":["All of this delicate technology sits under a sheet of cover glass, the part your finger actually touches. It has to be clear, smooth, scratch-resistant and tough enough to survive being dropped, sat on and carried in a pocket with keys. Ordinary window glass would crack far too easily.","Part 8 told how Apple asked the glass company Corning for tough glass for the first iPhone, and how Corning revived its 1960s research. Here is the science behind it. Corning began a research program in the early 1960s, nicknamed Project Muscle, to make stronger glass. Its researchers used a chemical trick called ion exchange, and their strengthened glass, sold as Chemcor, was used for things like racing car windows in the late 1960s. Decades later that research became Gorilla Glass, which appeared on the first iPhone in 2007.","Ion exchange works like this. The glass contains sodium atoms that have an electric charge; charged atoms are called ions. The finished glass is dipped into a bath of molten potassium salt (potassium nitrate) heated to about 400 degrees Celsius, far hotter than a kitchen oven. At that temperature, sodium ions near the surface slip out of the glass, and potassium ions from the bath move in to take their places.","Potassium ions are bigger than sodium ions. Imagine a row of seats in a cinema where every small child is swapped for a large adult: everyone is suddenly squeezed together. In the same way, the bigger potassium ions crowd the surface of the glass and put it under strong compression, a constant squeezing force that can reach about 690 megapascals, roughly 100,000 pounds on every square inch. Glass usually breaks when a tiny scratch is pulled open by tension. A surface already squeezed tightly resists that pulling, so cracks have a much harder time starting and spreading. Chemically strengthened glass is typically six to eight times as strong as ordinary glass.","It is not unbreakable. A deep scratch or a hard drop on a corner can still go through the squeezed layer and shatter the screen. Corning and its rivals keep releasing new versions, and by October 2017 Gorilla Glass had reportedly been used in about five billion devices. Some newer phones even mix tiny ceramic crystals into the glass to make it tougher still.","So the next time you tap your phone, think of the layers: strengthened glass on top, an invisible grid of electrodes sensing your finger, and millions of tiny red, green and blue lights underneath. But that raises a bigger question. When you tap an icon, the touchscreen only reports a position. What actually decides what happens next? For that, we need to meet the phone's brain: the chip."]}],"deepDive":"A capacitive touchscreen never 'sees' your finger directly; it measures tiny changes in capacitance, often a fraction of a picofarad (a trillionth of a farad), against a background of electrical noise from the display, the charger and the radio. The touch controller therefore relies heavily on signal processing. It scans each row-and-column crossing, subtracts a slowly updated 'baseline' for the empty screen, filters out noise, and then calculates the center of each touched area by interpolating between neighboring crossings. This is why a phone can locate a finger much more precisely than the spacing of its electrodes, which is typically a few millimeters. There are two main approaches. Self-capacitance measures each electrode against ground; it is very sensitive, so it is good for detecting a finger hovering near the glass, but with two fingers it can produce 'ghost' points, because it only knows which rows and which columns are active, not which combinations. Mutual capacitance measures each crossing separately, which removes the ghosts and allows true multi-touch, so most phones rely on it, sometimes combined with self-capacitance. To make phones thinner and brighter, makers moved the sensor inside the display stack: 'on-cell' designs put the electrodes on top of the display layer, and 'in-cell' designs build them into the display itself. Displays raise their own debates. Many OLED phones use a PenTile-style layout in which pixels share sub-pixels, so a quoted resolution does not always mean three full sub-pixels per pixel. Some OLED phones dim the screen by flickering it on and off very quickly (pulse-width modulation), which a small number of people say causes eye strain; researchers are still studying how common that is. Meanwhile the transparent conductor ITO depends on indium, a fairly scarce metal produced mainly as a by-product of zinc mining, so scientists are researching alternatives such as silver nanowires, metal meshes and graphene, especially for flexible and folding screens.","funFact":"The first finger-operated capacitive touchscreen was described in 1965 by E. A. Johnson at Britain's Royal Radar Establishment, for air traffic control, more than 40 years before the iPhone.","check":{"q":"Why does a capacitive touchscreen usually not work when you wear thick winter gloves?","a":"The glove fabric is an insulator, so your conductive finger cannot change the screen's electric field","wrong":["The screen needs to feel the heat of your skin","Gloves are too light to press the two layers together","The screen reads your fingerprint pattern"]},"sources":[{"title":"Touchscreen","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Touchscreen"},{"title":"Resistive touchscreen","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Resistive_touchscreen"},{"title":"Multi-Touch Systems that I Have Known and Loved","publisher":"Bill Buxton, billbuxton.com","url":"https://www.billbuxton.com/multitouchOverview.html"},{"title":"FingerWorks","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/FingerWorks"},{"title":"George Samuel Hurst","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/George_Samuel_Hurst"},{"title":"OLED","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/OLED"},{"title":"Chemically strengthened glass","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Chemically_strengthened_glass"},{"title":"Gorilla Glass","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gorilla_Glass"}],"photos":[{"src":"img/deep/smartphone/10-1.jpg","alt":"A close-up of a laptop screen showing a rainbow. The zoomed box shows its tiny red, green and blue sub-pixels.","file":"LCD subpixels.jpg","url":"https://commons.wikimedia.org/wiki/File:LCD_subpixels.jpg","author":"Politelyinsulting","license":"CC BY-SA 3.0"},{"src":"img/deep/smartphone/10-2.jpg","alt":"A phone's capacitive touchscreen in slanted light, showing the faint grid of see-through electrode lines that sense your finger.","file":"Capacitive touchscreen.jpg","url":"https://commons.wikimedia.org/wiki/File:Capacitive_touchscreen.jpg","author":"Medvedev","license":"CC BY 3.0"},{"src":"img/deep/smartphone/10-3.jpg","alt":"CERN touchscreens by Bent Stumpe: a 1977 x-y multi-touch prototype (left) and a 1972 capacitive screen (right).","file":"CERN-Stumpe Capacitance Touchscreen.jpg","url":"https://commons.wikimedia.org/wiki/File:CERN-Stumpe_Capacitance_Touchscreen.jpg","author":"Maximilien Brice","license":"CC BY 2.0"}],"words":3795},{"n":11,"title":"How It Works: The Chip — A Brain Made of Sand","when":"1947 – today","summary":"Inside every phone is a chip smaller than a postage stamp, made from silicon, the same stuff found in sand. It holds billions of tiny switches that flick on and off billions of times every second. That is how your phone thinks!","sections":[{"heading":"What Happens When You Tap?","paragraphs":["Tap the camera icon on a phone. In less time than it takes to blink, the screen wakes up the camera, the lens focuses, a picture of the world appears and little buttons slide into place around it. It feels like magic. But somewhere under the glass, a thin, flat square of silicon about the size of a fingernail has just done billions of tiny jobs, one after another and side by side, to make all of that happen.","That square is the phone's main chip. People often call it the phone's brain, and that is a fair nickname, although it works very differently from the soft, wet brain inside your head. Your brain uses about 86 billion nerve cells that send chemical and electrical signals to each other. A phone chip uses billions of transistors: microscopic switches that can only do one thing, which is turn on or turn off.","That sounds far too simple to run a video game or recognize a face. The trick is that an on-or-off switch can stand for a number. Engineers call 'on' a 1 and 'off' a 0. A single 1 or 0 is called a bit. Put eight bits in a row and you get a byte, which can stand for any whole number from 0 to 255. Line up enough bytes and you can describe a letter, the color of one pixel on the screen, a note in a song, or the position of your finger. Everything your phone stores or shows, from a text message to a movie, is really a gigantic pattern of 1s and 0s.","Switches can also make decisions. Wire two switches one after the other, and current gets through only if the first AND the second are on. Wire them side by side, and current gets through if the first OR the second is on. These little arrangements are called logic gates. Clever combinations of logic gates can add two numbers, compare them, remember them, or choose what to do next. Stack up millions of these combinations and you have a processor: a machine that follows a list of instructions, called a program, one step at a time and astonishingly fast.","So when you tap the camera icon, the touchscreen (from Part 10) reports a pair of numbers, the place where your finger landed. The processor compares those numbers with the positions of the icons, works out that you meant the camera, loads the camera program from storage and starts following its instructions. Every one of those steps is just transistors switching on and off in the right order. The rest of this part explains how humans learned to build such tiny switches, why they keep getting smaller, and why a phone chip has to be not only clever but also careful with energy."]},{"heading":"From Sand to Switches","paragraphs":["Pick up a handful of beach sand and you are holding a lot of silicon. Most sand is made of quartz, which is silicon dioxide: silicon atoms joined to oxygen atoms. Silicon is the second most common element in Earth's crust, after oxygen. It is also a semiconductor, which means it is not a great conductor of electricity like copper, and not a good insulator like glass or rubber, but something in between. Even better, engineers can change how well it conducts by adding tiny traces of other elements such as boron or phosphorus. That process is called doping, and it is what lets silicon be turned into switches.","The story of the transistor begins at Bell Telephone Laboratories in Murray Hill, New Jersey. In December 1947, John Bardeen and Walter Brattain, working in a group led by William Shockley, built the first working transistor. It was a clumsy-looking thing made from a slab of germanium, a strip of gold foil and a spring (some accounts say it was a bent paper clip), and it was about as big as your thumb. But it could do what the glowing vacuum tubes in old radios did, switching and boosting electrical signals, while being much smaller, cooler and tougher. The three men shared the 1956 Nobel Prize in Physics.","The next big leap was to stop building transistors one at a time. In September 1958, Jack Kilby at Texas Instruments demonstrated the first integrated circuit: several components made together on a single piece of germanium, joined with fine gold wires. A few months later, in early 1959, Robert Noyce at Fairchild Semiconductor worked out a far more practical way to make a whole circuit on one flat piece of silicon, with the connections printed on top. Kilby later received the 2000 Nobel Prize in Physics, and Noyce, who had died in 1990, is usually given equal credit as a co-inventor of the chip. Today's chips also depend on a type of transistor called the MOSFET, demonstrated by Mohamed Atalla and Dawon Kahng at Bell Labs in 1960. The MOSFET is now the most manufactured object in human history: by one estimate, more than 13 sextillion (13 followed by 21 zeros) had been made by 2018.","Here is roughly how a MOSFET works as a switch. It has three connections, called the source, the drain and the gate. The source and drain are like two ends of a road. The gate sits above the road, separated from it by an incredibly thin layer of insulating material. When there is no voltage on the gate, the road is closed and no current flows. Put a small voltage on the gate, and its electric field pulls charges into the silicon underneath, opening a narrow channel. Current flows. Off, on, off, on: that is a bit flipping from 0 to 1 and back.","Turning sand into a chip is one of the most precise jobs humans have ever attempted. First, quartz is heated with carbon in furnaces to free the silicon, and the silicon is purified again and again until it is about 99.9999999 percent pure. That is often called nine nines, meaning that only about one atom in a billion is something other than silicon. The pure silicon is melted, and a small seed crystal is dipped in and slowly pulled upward while turning. Silicon atoms freeze onto the seed in perfect rows, growing a single, shiny crystal cylinder called a boule. A diamond saw slices the boule into wafers, which are polished until they are mirror-smooth. A modern wafer is 300 millimeters (about 12 inches) across and less than a millimeter thick, about 0.775 mm.","Then comes the printing. Chip factories, called fabs, coat the wafer with light-sensitive chemicals and shine light through a patterned mask, a bit like a slide projector, so that the pattern is copied onto the wafer. This is called photolithography, which means 'writing on stone with light'. Chemicals then etch away some areas, other materials are added, and the whole process is repeated dozens of times to build up many layers of transistors and the metal wires that connect them. The most advanced fabs use extreme ultraviolet light with a wavelength of just 13.5 nanometers. Only one company, ASML in the Netherlands, makes these machines for chip production. Each one costs around 180 million US dollars, weighs nearly 200 tonnes, more than a hundred family cars put together, and makes its light by blasting tiny droplets of molten tin with a laser, tens of thousands of times a second.","Fabs are among the cleanest places on Earth, because a single speck of dust landing on a wafer can ruin the chips underneath it. Workers wear full-body suits, sometimes nicknamed bunny suits, and the air is filtered constantly. When the printing is finished, each wafer holds hundreds of identical chips. They are tested, cut apart, and sealed into small packages with connections underneath. One of those little packages is what sits inside your phone."]},{"heading":"Moore's Law: Double, Double, Double","paragraphs":["In April 1965, a chemist named Gordon Moore wrote a short magazine article that would become one of the most famous predictions in technology. Moore worked at Fairchild Semiconductor, the company where Robert Noyce had built the silicon chip. Electronics magazine asked him to guess what would happen to chips over the next ten years. His article had a very plain title: 'Cramming more components onto integrated circuits'.","Moore had noticed something remarkable. Each year, engineers were managing to fit roughly twice as many components onto a chip as the year before, while the cost of each component kept falling. He predicted that this doubling would keep going for at least ten years, and he guessed that by 1975 a single chip might hold about 65,000 components. At the time, the best chips held only around 50 or 60. It sounded wild.","He turned out to be close. In 1975 Moore updated his prediction, saying the doubling would now happen about every two years instead of every year. Other people began calling this pattern Moore's Law. It is important to understand that it is not a law of nature, like gravity. Nothing in physics forces chips to double. It is an observation about how quickly engineers, factories and companies could improve, and it worked partly because the whole chip industry used it as a target and planned around it.","Doubling is more powerful than it sounds. Imagine putting one grain of rice on the first square of a chessboard, two on the second, four on the third, and so on. By the last square you would need more rice than the whole world grows. Chips doubled in a similar way for decades. Intel's 4004, sold in 1971 and often called the first commercial microprocessor, had about 2,300 transistors. Apple's A17 Pro chip, released in September 2023 in the iPhone 15 Pro, has about 19 billion. That is roughly eight million times more, packed into a chip you could cover with your thumbnail.","Doubling the number of transistors does not only mean more of them. Because they are smaller, they can switch faster and use less energy each. For a long time, every new generation of chips was faster, cheaper and less power-hungry all at once. That is the main reason a phone in your pocket can now beat the giant supercomputers of the 1980s and 1990s at many tasks.","Today the pace has slowed. Experts have noticed since about 2010 that progress is coming more slowly than Moore's original rhythm, and in 2023 Intel's boss Pat Gelsinger said the doubling is now closer to every three years. Some industry leaders have declared Moore's Law dead, and others insist it is still alive. Either way, the most advanced chips still hold more transistors every few years, but each step is now harder and enormously more expensive."]},{"heading":"ARM: The British Chip Inside Almost Every Phone","paragraphs":["If you could peel open almost any smartphone in the world, whether it is an iPhone, a Samsung Galaxy or a cheap Android phone, you would find a processor built on designs that began in a small company in Cambridge, England, in the 1980s. That company was Acorn Computers, famous in Britain for the BBC Micro, a home computer used in thousands of schools.","In October 1983, Acorn decided to design its own processor for its next computers. Sophie Wilson, a brilliant young programmer who had already written the BBC Micro's built-in programming language, designed the instruction set: the list of basic commands the chip would understand. Steve Furber, a hardware engineer who had earned a PhD studying fluid dynamics, designed how the chip itself would be built. The team was tiny compared with the giant teams at American chip companies, and they had very little money for the project, so they kept the design simple on purpose.","Their idea was called RISC, short for reduced instruction set computer. Many processors of the time understood hundreds of complicated instructions, some of which took many steps to finish. A RISC chip understands a smaller set of simple instructions, each of which can be carried out quickly. Think of a cook who has fewer, simpler recipe steps but does each one very fast. Simplicity meant fewer transistors, and fewer transistors meant a chip that was cheaper, cooler and easier to design.","Acorn's partner, VLSI Technology, manufactured the first chips. On 26 April 1985 the first ARM processor, later called ARM1, was tested, and it worked the very first time, which is extremely rare for a brand-new chip. It ran at 6 megahertz, meaning its internal clock ticked six million times a second. The team later told a famous story: the chip used so little power that it once kept running even though its main power supply had not been properly connected, apparently powered by the small trickle of electricity leaking in from its signal wires. Whether or not every detail is remembered exactly, the point was clear. This chip was extraordinarily frugal with energy.","At first, low power was almost a happy accident; Acorn mainly wanted a cheap chip for desktop computers, and the first Archimedes computers using ARM went on sale in 1987. But a frugal chip is exactly what a battery-powered gadget needs. In 1990, Acorn's chip team became a separate company, Advanced RISC Machines, set up as a joint venture with Apple and VLSI Technology. Apple wanted an efficient processor for its Newton handheld (Part 4), which used an ARM chip.","The new company had an unusual plan. Instead of making and selling chips itself, ARM sells licenses to its designs. Other companies pay to use ARM's designs or its instruction set, then build their own chips around them. This is why Apple, Qualcomm, Samsung, MediaTek and many others can each make their own phone chips while all of them speak the same basic ARM language. By 2005 about 98 percent of mobile phones sold contained at least one ARM processor, and by 2010 ARM-based processors were inside about 95 percent of smartphones. More than 230 billion ARM-based chips have been made in total. Sophie Wilson and Steve Furber have received many honors for their work, including Fellowships of the Royal Society and a shared 2022 Charles Stark Draper Prize, one of engineering's top awards."]},{"heading":"A Whole Computer on One Chip","paragraphs":["An old desktop computer was a box full of separate parts: a processor in one place, a graphics card in a slot, sound chips, a network card and more, all joined by wires and circuit boards. A phone has no room for that. Instead, its main chip is a system-on-a-chip, usually shortened to SoC. It puts most of the important parts of a computer onto one piece of silicon, a bit like squeezing a whole town's worth of workshops into one tall building.","The CPU, or central processing unit, is the general manager. It runs the operating system and the apps, following their instructions step by step. Modern phone CPUs have several cores, which are complete processors working side by side. Many of them mix two kinds of cores: big, fast performance cores for hard work, such as loading a game, and small efficiency cores that handle easy jobs, like checking for new messages, while using much less energy. ARM introduced this mix-and-match idea, called big.LITTLE, in 2011.","The GPU, or graphics processing unit, is the artist. It is built to do thousands of simple calculations at the same time, which is exactly what you need to work out the color of millions of pixels many times every second for games, animations and video.","The NPU, or neural processing unit, is a newer addition, built for artificial intelligence. Apple calls its version the Neural Engine. AI jobs such as recognizing a face, understanding speech, translating words or guessing the next word you will type involve enormous numbers of multiplications. An NPU is designed to do just those calculations quickly and cheaply in energy.","The image signal processor, or ISP, works with the camera. It takes the raw signals from the camera sensor and turns them into a finished photo, fixing colors, reducing graininess and combining several shots into one (you will learn more in Part 14). Other parts of the chip handle video, sound, security keys and fingerprints, and controllers that move data to and from memory. Many phone SoCs also include the modem, the part that talks to the mobile network by radio, which is the subject of Part 12. On some phones the modem is a separate chip right next door.","Let us take a real example. Apple's A17 Pro, which appeared in the iPhone 15 Pro and 15 Pro Max in September 2023, holds about 19 billion transistors. Its CPU has six cores: two performance cores that can tick about 3.78 billion times a second, and four efficiency cores. Its GPU has six cores, and its Neural Engine has 16 cores that Apple says can perform about 35 trillion operations every second. It was described as the first widely available chip built on a so-called 3-nanometer process.","What does 3 nanometers mean? A nanometer is one billionth of a meter. A human hair is roughly 50,000 to 100,000 nanometers thick. The '3 nanometer' name today is really a label for a generation of manufacturing rather than a measurement of one exact part of the transistor, but the smallest features on these chips really are only a few nanometers across, sometimes just a few dozen atoms thick. That means thousands of the tiniest structures could be lined up across the width of a single hair. Squeezing billions of switches into such a tiny space, and making nearly all of them work, is one of the greatest engineering achievements in history."]},{"heading":"Apollo Guidance Computer vs the Phone in Your Pocket","paragraphs":["In July 1969, the Apollo 11 astronauts landed on the Moon with the help of a computer. The Apollo Guidance Computer, or AGC, was designed at the MIT Instrumentation Laboratory and built by the company Raytheon. Its software was written by a team that included Margaret Hamilton, who led the work on the spacecraft's flight software and later received the Presidential Medal of Freedom in 2016. The AGC was one of the first computers built from integrated circuits, and its orders for chips helped the young chip industry grow.","It is tempting to say a phone is 'a million times smarter' than the Apollo computer, but that kind of vague claim does not tell you much. It is far more interesting to compare real numbers.","Size and weight first. The AGC was a box about 61 by 32 by 17 centimeters, roughly the size of a large suitcase lying flat, and it weighed about 32 kilograms (70 pounds). It used about 55 watts of power. An iPhone 15 Pro weighs about 190 grams, roughly a sixth of a kilogram, and its whole chip uses just a few watts even when working hard.","Memory next. The AGC's changeable working memory, called erasable memory, held 2,048 words, which works out to about 4 kilobytes. Its programs were stored in 'core rope memory', where wires were literally woven by hand through or around tiny magnetic rings to store 1s and 0s. It held 36,864 words, roughly 72 kilobytes, and once woven it could not be changed. A modern phone has around 8 gigabytes of working memory: that is about 8 billion bytes, or roughly two million times the AGC's erasable memory. Its storage, often 128 gigabytes or more, could hold the AGC's entire rope memory well over a million times over.","Speed. The AGC's main clock ran at about 2 megahertz, and each basic memory step took about 12 microseconds, so it could carry out tens of thousands of simple operations every second. The A17 Pro's performance cores tick almost 4 billion times a second, and each core can do several things per tick. Its Neural Engine alone is rated at about 35 trillion operations per second.","Chips. The final version of the AGC used about 2,800 integrated circuits, and each one held just two simple logic gates. The A17 Pro has about 19 billion transistors on one chip.","But numbers are not the whole story. The AGC was built for one job, and it did that job brilliantly. During the Apollo 11 landing, it flashed a '1202' alarm because it was being swamped with extra work from a radar. Instead of crashing, it restarted and dropped less important tasks so that the most important ones, the ones steering the landing, kept running. That clever design, by people working with tiny resources, helped Neil Armstrong and Buzz Aldrin land safely. Your phone is vastly more powerful, but it stands on the shoulders of engineers who did amazing things with very little."]},{"heading":"Hot Chips: Why Fast Is Not Enough","paragraphs":["Here is a problem that desktop computers mostly do not have to worry about. Every time a transistor switches, it uses a tiny bit of energy, and nearly all of that energy ends up as heat. One switch makes an almost unmeasurably small amount of heat. But billions of switches flipping billions of times a second add up quickly. A desktop computer deals with this using big metal heat sinks, whirring fans and sometimes even liquid cooling. A phone has no fan at all. It has to get rid of its heat through its own case and screen, and it is held in your hand or pressed against your face, so it cannot get very hot.","Phones also run on a battery that must last all day. A battery stores only a limited amount of energy (Part 13 explains how), so every watt the chip uses is drained from it. If a phone chip were designed just to be as fast as possible, the battery would run flat in an hour or two and the phone would become uncomfortably warm.","That is why phone chip designers care about efficiency, meaning how much useful work the chip does for each bit of energy. Engineers use many tricks. Efficiency cores take over the easy jobs. Parts of the chip that are not needed are switched off completely, so the GPU sleeps while you read a text message and the camera processor sleeps until you open the camera. The chip constantly changes its speed and voltage: it races when you open an app and slows to a crawl when the screen is off. Lower voltage saves a lot of energy, because the power a switching circuit uses rises steeply as the voltage goes up.","Special-purpose blocks also save energy. A general CPU can play a video or recognize a face, but a dedicated video block or NPU can do the same job using far less power, the same way a tool made for one job, like a pencil sharpener, does it better than a pocketknife. This is a big reason modern SoCs have so many specialized parts.","Even so, if you play a demanding game for a long time, you may notice your phone getting warm, and sometimes the game gets slightly less smooth. That is the phone protecting itself: when sensors inside detect too much heat, the chip deliberately slows down to cool off. Engineers call this thermal throttling. It is not a fault. It is a safety feature that keeps the chip and battery in a healthy temperature range.","Smaller transistors helped for decades, because each switch needed less energy. But as transistors shrank to just a few nanometers, new problems appeared. Tiny amounts of current started leaking through switches even when they were supposed to be off, a bit like a tap that never quite stops dripping. Chip designers now spend as much effort fighting leaks and heat as they do chasing raw speed. The champion phone chip is not simply the fastest one. It is the one that gives you the most speed for the least energy.","Still, even the cleverest, coolest brain is useless if it is trapped in a sealed box. To send a message, load a web page or make a call, the chip has to talk to the rest of the world, and it does that with something you cannot see, hear or feel at all: invisible radio waves racing out to towers and networks, which is where we are heading next."]}],"deepDive":"Why did chips keep getting better for so long, and why is it getting harder? For about three decades, chipmakers enjoyed what engineers call Dennard scaling, named after IBM's Robert Dennard, who described it in 1974. As transistors shrank, their voltage and current could shrink too, so the power used per square millimeter stayed roughly the same. Each new generation gave you more transistors, running faster, without a hotter chip. Around the mid-2000s this broke down. Voltages could not be lowered much further without transistors becoming unreliable, and leakage current, electricity sneaking through switches that are supposed to be off, grew as insulating layers became only a few atoms thick. That is why desktop processor clock speeds stopped climbing quickly at a few gigahertz around 2005, and why the industry turned to multiple cores and specialized accelerators like GPUs and NPUs instead. Transistor shapes have also changed. Flat transistors gave way to FinFETs, where the channel rises up like a fin so the gate can grip it from three sides, and the newest chips are moving to gate-all-around designs where the gate wraps the channel completely. The names of manufacturing generations, such as 5 nm or 3 nm, no longer match any single physical dimension; they are marketing labels for steps of improvement in density. Debate continues over whether Moore's Law is over. Nvidia's Jensen Huang declared it dead in 2022, while Intel argued it continues at a slower pace of roughly every three years. Some engineers prefer to talk about improvements in performance per watt or per dollar, which also come from better chip packaging, stacking chips on top of one another, and smarter software. There are also hard physical limits ahead: a silicon atom is about 0.2 nanometers across, so features cannot shrink forever. Meanwhile the cost of a cutting-edge fab has soared into tens of billions of dollars, and only a handful of companies, such as TSMC, Samsung and Intel, can make the most advanced logic chips. That concentration has turned chipmaking into a matter of national strategy for many governments.","funFact":"The Apollo Guidance Computer's programs were stored in core rope memory that was woven by hand, with workers threading wires through or around tiny magnetic rings to record each 1 or 0.","check":{"q":"Which British company designed the first ARM processor, which first worked in April 1985?","a":"Acorn Computers","wrong":["Intel","Texas Instruments","Nokia"]},"sources":[{"title":"Moore's law","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Moore%27s_law"},{"title":"ARM architecture family","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/ARM_architecture_family"},{"title":"Sophie Wilson","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Sophie_Wilson"},{"title":"Apollo Guidance Computer","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Apollo_Guidance_Computer"},{"title":"Apple A17","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Apple_A17"},{"title":"Transistor","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Transistor"},{"title":"Invention of the integrated circuit","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Invention_of_the_integrated_circuit"},{"title":"Unsung heroes of tech: ARM creators Sophie Wilson and Steve Furber","publisher":"The Register","url":"https://www.theregister.com/2012/05/03/unsung_heroes_of_tech_arm_creators_sophie_wilson_and_steve_furber/"}],"photos":[{"src":"img/deep/smartphone/11-1.jpg","alt":"A replica of the first transistor, Bell Labs 1947, beside a later, much smaller GE transistor.","file":"A replica of the first working transistor 02.jpg","url":"https://commons.wikimedia.org/wiki/File:A_replica_of_the_first_working_transistor_02.jpg","author":"Mister rf","license":"CC BY-SA 4.0"},{"src":"img/deep/smartphone/11-2.jpg","alt":"A 12-inch silicon wafer covered in rows of tiny printed circuits, shimmering with rainbow colors.","file":"Semiconductor Wafer of Microelectronics.jpg","url":"https://commons.wikimedia.org/wiki/File:Semiconductor_Wafer_of_Microelectronics.jpg","author":"DrHughManning","license":"CC BY-SA 4.0"},{"src":"img/deep/smartphone/11-3.jpg","alt":"The Apollo Guidance Computer with its DSKY display and keypad on top, at the Computer History Museum.","file":"ApolloGuidanceComputerwithDSKY.agr.jpg","url":"https://commons.wikimedia.org/wiki/File:ApolloGuidanceComputerwithDSKY.agr.jpg","author":"ArnoldReinhold","license":"CC BY-SA 3.0"}],"words":4345},{"n":12,"title":"How It Works: Radio Waves, Cells and Networks","when":"1947 – today","summary":"When you talk on a phone, your voice turns into invisible radio waves that zoom to a nearby tower at the speed of light. Towers are spread out like a honeycomb, and as you move, your call is passed from one tower to the next like a baton in a relay race!","sections":[{"heading":"Your Voice Becomes a Wave","paragraphs":["Imagine calling your grandmother from the back seat of a car on a highway. You say 'Hi, Grandma!' and less than a second later she hears you in her kitchen hundreds of kilometers away. No wire connects your phone to hers. So how does your voice escape from the car?","It starts with the microphone. Sound is a wave of pressure in the air. When you speak, the air pushes on a tiny flexible part inside the microphone, and the microphone turns those pushes into a changing electrical signal. Modern phones then measure that signal thousands of times every second and turn each measurement into a number. This is the digital idea from Part 3: instead of sending a smooth copy of the wave, the phone sends a long stream of 1s and 0s. Clever software squeezes, or compresses, the numbers so they take up less room, and adds extra checking information so mistakes can be spotted and fixed. The same thing happens to a photo, a text message or a video. Everything becomes data.","Next, the phone's modem and radio turn those 1s and 0s into radio waves. Radio waves are a kind of electromagnetic wave, the same family as visible light, microwaves and X-rays. They are invisible, and they are the longest waves in that family. They travel at the speed of light: about 300,000 kilometers every second. That is fast enough to circle the Earth about seven and a half times in one second.","Two words help describe any wave. The frequency is how many waves pass a point each second, measured in hertz. One hertz means one wave per second; a megahertz (MHz) is a million waves a second and a gigahertz (GHz) is a billion. The wavelength is the distance from the top of one wave to the top of the next. Because all radio waves travel at the same speed, higher frequency means shorter wavelength. You can even work it out yourself: divide the speed of light by the frequency. A phone signal at 700 MHz has waves about 43 centimeters long. At 2 GHz the waves are about 15 centimeters long. Some 5G signals at around 28 GHz have waves only about one centimeter long.","How do you hide information in a wave? Think of a flashlight in the dark. You could send a message by switching it on and off, or by making it brighter and dimmer. Radios do something similar but much more cleverly. They make tiny, rapid changes to the wave's strength, to its exact timing, called its phase, or to its frequency. Each kind of change stands for a few bits. A modern phone can change its signal in so many carefully measured ways that each little piece of the wave carries many bits at once.","Different frequencies behave differently, and engineers choose them carefully. Lower frequencies, with longer waves, travel farther and slip through walls and around hills more easily, which is good for covering the countryside. Higher frequencies carry more data but fade quickly and are blocked more easily, even by leaves, windows or your own hand. Governments divide up the radio spectrum like land and decide who can use which frequencies, so that phones, TV, aircraft radios, police and satellites do not drown each other out. Mobile network companies often pay billions of dollars at auctions for the right to use a slice of it."]},{"heading":"The Honeycomb Idea: How Cells Work","paragraphs":["Remember the big problem from Parts 1 and 2? Early car phones used one powerful transmitter for a whole city, and there were only a handful of channels, so only a few people could talk at once. The solution was written down on December 11, 1947, in an internal memo by Douglas H. Ring at Bell Labs, with his colleague W. Rae Young. Their idea: instead of one giant transmitter, cover the land with many small areas, each served by its own low-power station. They called these areas cells, which is why we have cellular networks and cell phones.","On diagrams, engineers draw cells as hexagons fitting together like a honeycomb. Real cells are not neat hexagons, of course. Their edges are bumpy and blurry, shaped by hills, buildings and trees. But the hexagon picture makes the idea easy to see, because hexagons cover a flat surface with no gaps and no overlaps.","Each cell has a cell tower, also called a base station: antennas, usually on a tall mast, a rooftop or even disguised as a fake tree or church tower, connected to radio equipment. The base station talks to all the phones in its cell. Behind it, cables or microwave links connect it to the rest of the network, which routes your call or data across the country or around the world, often through fiber-optic cables that carry information as flashes of light.","Here is the clever part, called frequency reuse. Neighboring cells use different sets of frequencies so they do not interfere with each other. But because each base station only whispers rather than shouts, its signal fades before it gets very far. So a cell a few steps away across the honeycomb can use exactly the same frequencies again. Engineers group cells into clusters. In a classic arrangement, a cluster of seven cells shares out the available frequencies, and the pattern repeats over and over across the map. That way the same handful of frequencies can carry thousands of conversations across one city, instead of just a few.","Even better, when an area gets crowded, engineers can split a busy cell into several smaller cells, each with its own base station. Smaller cells mean more reuse, and more reuse means more people can talk at the same time. That is why a big city has towers every few hundred meters, while a farm region might have one tower covering many kilometers. In empty countryside a cell can reach out as far as about 30 kilometers from its tower, or tiny: microcells cover a few blocks, picocells serve a building or a stadium, and femtocells are small boxes that cover one home.","Your phone, meanwhile, is always quietly listening, even when you are not using it. Every few moments it checks which nearby towers it can hear and how strong each signal is. It tells the network roughly where it is, as a member of a group of cells. When someone calls you, the network sends a 'paging' message out through all the towers in that group, a bit like an announcement over a school's loudspeakers: 'Phone number such-and-such, please answer!' Your phone hears its name, replies, and the call is connected."]},{"heading":"Handoff: Passing the Baton","paragraphs":["Back in the car on the highway: you are talking to Grandma, and you are moving at 100 kilometers an hour. Every few minutes, you drive out of one cell and into the next. So why doesn't the call cut off?","The answer is the handoff, also called handover. While you talk, your phone keeps measuring the signals from the tower it is using and from neighboring towers on a list the network gives it. It reports those measurements back. When the signal from the next tower becomes clearly stronger, the network tells your phone to switch, and your call moves to a new channel on the new tower. It happens in a fraction of a second, and usually you never notice. It is like a relay race, with each tower passing the baton to the next runner without stopping the race.","Building a system that could keep track of moving phones and switch them between towers was a hard problem in the 1960s and 1970s, when computers were still large and slow. Amos Joel, an engineer at Bell Labs, worked on the switching system that made it possible, and his patent, granted in 1972, is often cited as a key part of the cellular handoff story. Many other engineers at Bell Labs, Motorola and elsewhere also solved pieces of the puzzle.","There are two main styles of handoff. In a hard handoff, the phone lets go of the old tower and grabs the new one, an approach engineers call 'break before make'. It is simple, but if something goes wrong at that instant, the call can drop. In a soft handoff, used by some 3G systems, the phone talks to two or more towers at the same time for a moment, 'make before break', so there is always at least one good link. That is more reliable but uses more network resources.","Handoffs do not only happen when you move. If one cell gets too crowded, say at a football game when 50,000 fans are posting videos at half-time, the network may move some phones to a neighboring cell that has spare room. And sometimes a phone right on the edge between two cells keeps flipping back and forth. Engineers call that ping-ponging, and they tune their networks carefully to avoid it."]},{"heading":"1G to 5G: Five Generations in Forty Years","paragraphs":["Mobile networks are grouped into generations, shortened to G. Each new generation is not just a little faster; it usually changes the way signals are sent. Here is the family tree, from grandparent to the newest child.","1G, the analog generation. The first commercial cellular networks opened in Tokyo in 1979, run by NTT, followed by the Nordic NMT system in 1981 and the AMPS network in Chicago in October 1983 (Part 2 tells that story). These phones sent your voice as an analog radio wave, a smooth copy of the sound. That had problems. Calls could crackle and fade, each conversation used up a whole radio channel, and anyone with the right radio scanner could listen in. The early networks also used different systems in different countries, so a phone from one country often would not work in another.","2G, the digital generation. In Finland on July 1, 1991, the first call was made on a GSM network, run by the company Radiolinja. 2G phones turned voices into numbers before sending them. Digital signals can be compressed, so several calls can share one channel by taking turns in tiny time slots, thousands of times a second. They can also be scrambled, or encrypted, which made eavesdropping much harder. And 2G brought text messaging (Part 3). Data was very slow at first, roughly 10 kilobits per second, enough for a few words but painfully slow for pictures.","3G, the mobile internet generation. NTT Docomo in Japan opened the world's first commercial 3G network, called FOMA, in October 2001 (Part 6). 3G was designed from the start to carry data as well as voice. Speeds of a few hundred kilobits per second, and later several megabits, made it practical to browse real web pages, download music and make video calls. The first iPhone in 2007 did not have 3G, but its successor, the iPhone 3G in 2008, did, and 3G helped turn smartphones into internet machines.","4G, the fast data generation. On December 14, 2009, the Nordic company TeliaSonera opened the first commercial LTE networks, in Stockholm, Sweden, and Oslo, Norway. LTE stands for Long Term Evolution, a slightly dull name for a big change. The idea had been proposed as an international standard by NTT Docomo in 2004. Unlike older systems, LTE treats everything, even voice calls, as internet-style data packets. That early Stockholm network was designed to reach about 50 megabits per second downloads, and later LTE versions could reach hundreds of megabits per second in ideal conditions. 4G made streaming video, video chat and live maps feel normal on a phone. (Engineers still argue about whether the first LTE networks truly met the official 4G definition, but the name stuck.)","5G, the newest generation. On April 3, 2019, South Korea switched on a nationwide 5G service, and within hours Verizon began a smaller 5G service in a few US cities. 5G uses a wider range of frequencies than before. Its lower and middle frequencies reach about as far as 4G but carry more data. Its very high 'millimeter wave' frequencies, above about 24 gigahertz, can deliver several gigabits per second but travel only short distances and are blocked by walls, windows and even trees. In real life, average 5G speeds have often been in the low hundreds of megabits per second, such as about 430 megabits per second in South Korea in 2022. 5G also aims for very short delays, called latency, and for connecting huge numbers of devices at once, from phones to sensors in factories.","To get a feel for the progress: downloading a 4-minute song file of about 4 megabytes would take around an hour on early 2G data, a minute or two on early 3G, a second or two on good 4G, and a blink on good 5G. In just a few decades, wireless data became tens of thousands of times faster."]},{"heading":"The SIM Card: How the Network Knows It's You","paragraphs":["Billions of phones are switched on around the world right now. When your phone connects, how does the network know it is you, and not someone pretending to be you to make calls on your account?","The answer lives on the SIM card, short for subscriber identity module. The first SIMs were made in 1991 by Giesecke+Devrient, a company in Munich, Germany, which sold 300 of them to Radiolinja in Finland for the world's first GSM network. Early SIM cards were the size of a credit card. Over the years they shrank: the mini-SIM in 1996, the micro-SIM in 2003 and the tiny nano-SIM in 2012, all with the same gold contact pads in the same arrangement. Since 2016 many phones also use an eSIM, a SIM chip built permanently inside the phone that can be set up by downloading your account details.","A SIM is actually a tiny computer with its own processor and memory. It stores a number called the IMSI, which identifies you as a subscriber; it starts with a code for your country and a code for your mobile network. It also stores a secret: a 128-bit key, a string of 128 ones and zeros, that only your SIM and your network company know. The SIM is designed so that this key is very hard to copy or read out.","When your phone joins the network, it plays a kind of secret-handshake game called challenge and response. The network sends the phone a random number, the challenge. The SIM mixes that random number with its secret key using a special mathematical recipe and sends back the answer. The network does the same calculation on its own computers. If the answers match, the network knows the SIM must hold the right key, so the phone is let in. The secret key itself never travels through the air. The same calculation also produces a fresh temporary key used to scramble your calls and data, so people nearby cannot easily listen in.","Early GSM security had weaknesses that researchers later discovered, and newer generations have made the handshake stronger, for example by letting the phone check that the network is genuine too, not just the other way round. A PIN code can also lock the SIM so that a stranger who finds your phone cannot simply use your account."]},{"heading":"Wi-Fi and Bluetooth: The Short-Range Radios","paragraphs":["A smartphone is not one radio but a whole bundle of them. Besides talking to cell towers, it also has radios for Wi-Fi, Bluetooth, GPS (Part 15) and often NFC, the very-short-range radio used for tap-to-pay.","Wi-Fi connects your phone to a wireless router at home, at school or in a cafe, which is in turn connected to the internet by cable. Its rules were written by a committee of the Institute of Electrical and Electronics Engineers, or IEEE, which published the first version of its 802.11 wireless standard in 1997. That first version managed only 1 or 2 megabits per second. An earlier wireless network product called WaveLAN, developed by NCR and AT&T engineers in the Netherlands around 1991, helped pave the way. Vic Hayes, a Dutch engineer who chaired the 802.11 committee for ten years, is often called the father of Wi-Fi. The 802.11b version, from 1999, reached 11 megabits per second and became the first truly popular one. The same year, a group of companies formed what is now the Wi-Fi Alliance to test equipment and look after the catchy name Wi-Fi. Modern Wi-Fi uses frequency bands at 2.4, 5 and 6 gigahertz, and the newest versions, Wi-Fi 6 and Wi-Fi 7, can in theory reach many gigabits per second, though real speeds are lower.","Bluetooth is for even shorter distances, usually less than 10 meters: connecting earbuds, smartwatches, game controllers, car stereos and wireless speakers. Its story began at the Swedish company Ericsson in Lund, where in the 1990s the Dutch engineer Jaap Haartsen, working with Sven Mattisson, developed the key ideas for a cheap, low-power radio to replace cables. In May 1998, Ericsson, IBM, Intel, Nokia and Toshiba formed the Bluetooth Special Interest Group to turn it into a shared standard.","And the name? In 1997 Jim Kardach of Intel suggested 'Bluetooth' as a temporary code name, after Harald Bluetooth, a Danish king of the 10th century who was remembered for uniting Danish tribes into one kingdom. Just as Harald united Danes, the technology was meant to unite computers, phones and gadgets. The code name was only supposed to be a placeholder, but it stuck. Even the Bluetooth logo comes from the king: it combines the two Viking runes for his initials, H and B.","Bluetooth uses the 2.4 gigahertz band, which is shared with Wi-Fi and even microwave ovens. To avoid getting drowned out, classic Bluetooth uses a trick called frequency hopping. It splits the band into 79 channels and jumps from one channel to another, usually 1,600 times every second, in a pattern that both connected devices know. If one channel is noisy, the next hop is only a split second away. That idea of hopping between frequencies has a surprising history, which leads us to a Hollywood film star."]},{"heading":"Hedy Lamarr's Secret Communication System","paragraphs":["In the 1940s, Hedy Lamarr was one of the most famous film stars in Hollywood. Born in Vienna, Austria, in 1914, she had moved to the United States and starred in many movies. Few of her fans knew that in her spare time she loved inventing things.","During the Second World War, Lamarr worried about a weakness in radio-controlled torpedoes. If a torpedo was steered by a radio signal on one fixed frequency, an enemy could simply blast noise on that frequency, called jamming, and send the torpedo off course. Her idea was to make the signal jump rapidly from frequency to frequency in a secret pattern that only the ship and the torpedo knew. An enemy would not know where to aim the noise.","The hard part was keeping the transmitter and receiver hopping in perfect step. Here her friend George Antheil helped. Antheil was an avant-garde composer whose piece 'Ballet Mecanique' was written for several player pianos, machines that play themselves from punched paper rolls, which had to be kept in sync. Their design used a similar idea of synchronized, punched-paper patterns to keep both ends hopping together. On August 11, 1942, they received US patent 2,292,387 for a 'Secret Communication System', filed under her married name, Hedy Kiesler Markey.","The US Navy did not use it during the war; it was reportedly considered too bulky to fit in a torpedo. Lamarr and Antheil never made money from it, and the patent expired. Frequency hopping was first used in working military systems in 1962, after the patent had expired. Much later, people rediscovered her patent, and in 1997 Lamarr and Antheil received a Pioneer Award from the Electronic Frontier Foundation. In 2014, years after her death, Lamarr was inducted into the National Inventors Hall of Fame.","You may hear people say that Hedy Lamarr invented Wi-Fi or Bluetooth. That is not accurate. Those technologies were developed decades later by large teams of engineers, and they do not use her particular design. What is true is that her patent was an early example of frequency hopping, one member of a wider family of spread-spectrum radio techniques that are used today, for example in Bluetooth and in early versions of Wi-Fi. She was a creative inventor who had a clever idea years ahead of its time, and that is impressive enough.","Think about everything we have seen in this part. Every second, your phone is listening to towers, measuring signals, doing secret handshakes, hopping between frequencies, and firing radio waves into the air through several radios at once, all while its chip crunches numbers and its bright screen glows. All of that takes energy, and lots of it. So where does a phone, cut off from any wall socket, get its power? Turn the page to find out what is inside the battery."]}],"deepDive":"Why do mobile networks keep chasing more spectrum and more towers? The answer lies in a formula from information theory. In 1948, the Bell Labs mathematician Claude Shannon showed that the maximum amount of data a channel can carry depends on two things: its bandwidth (how wide a slice of frequencies it uses) and its signal-to-noise ratio (how loud the signal is compared with background noise). Capacity grows in direct proportion to bandwidth, but only logarithmically with signal strength, so doubling the transmitter power helps far less than doubling the bandwidth. That is why each generation hunts for wider channels: GSM channels were 200 kilohertz wide, LTE channels up to 20 megahertz, and 5G channels up to 100 megahertz in the middle bands and 400 megahertz in millimeter-wave bands. Wide channels are mostly available at higher frequencies, but higher frequencies have short ranges, which forces networks to build many more, smaller cells. Engineers have three main levers to increase capacity: more spectrum, better spectral efficiency (more bits per hertz, through cleverer modulation and coding), and more cells reusing the same frequencies. Engineers often point out that, historically, the third lever, cell splitting, has delivered the biggest gains. A fourth trick is MIMO, multiple-input multiple-output, in which many antennas send separate data streams at the same frequency at once; 5G's 'massive MIMO' base stations can use dozens of antenna elements and steer focused beams toward individual phones, a technique called beamforming. Debates continue. Spectrum is a limited public resource, and governments must balance mobile networks against satellites, weather radar and aviation; in the United States, for example, aviation authorities raised concerns in 2021 and 2022 about some 5G frequencies near aircraft altimeters, leading to temporary limits near airports. Public worries about radio waves and health have also surfaced; the US FDA and other health bodies have found no reliable evidence that 5G exposure at permitted levels harms health, yet false rumors linking 5G to COVID-19 in 2020 led to arson attacks on dozens of phone masts in the UK and elsewhere.","funFact":"Bluetooth is named after Harald Bluetooth, a 10th-century Danish king, and its logo is made by combining the Viking runes for his initials, H and B.","check":{"q":"What is it called when your call is passed from one cell tower to the next as you move?","a":"A handoff (or handover)","wrong":["A text message","A frequency auction","A SIM swap"]},"sources":[{"title":"Cellular network","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Cellular_network"},{"title":"Handover","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Handover"},{"title":"LTE (telecommunication)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/LTE_(telecommunication)"},{"title":"5G","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/5G"},{"title":"SIM card","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/SIM_card"},{"title":"Bluetooth","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bluetooth"},{"title":"IEEE 802.11","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/IEEE_802.11"},{"title":"Hedy Lamarr","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hedy_Lamarr"}],"photos":[{"src":"img/deep/smartphone/12-1.jpg","alt":"The top of a cell tower, bristling with panel antennas that talk to phones nearby.","file":"Cell-Tower.jpg","url":"https://commons.wikimedia.org/wiki/File:Cell-Tower.jpg","author":"The original uploader was J.smith at English Wikipedia.","license":"CC BY-SA 2.5"},{"src":"img/deep/smartphone/12-3.jpg","alt":"Cover of the 1941 patent file for the Secret Communication System by Hedy Kiesler Markey (Hedy Lamarr) and George Antheil.","file":"Patent Case File No. 2,292,387, Secret Communication System, Inventors Hedy Kiesler Markey and George Antheil - DPLA - 128f022cfd9421aa10de72958a7edf90 (page 2).jpg","url":"https://commons.wikimedia.org/wiki/File:Patent_Case_File_No._2,292,387,_Secret_Communication_System,_Inventors_Hedy_Kiesler_Markey_and_George_Antheil_-_DPLA_-_128f022cfd9421aa10de72958a7edf90_(page_2).jpg","author":"Department of Commerce. Patent and Trademark Office. (1975)","license":"Public domain"}],"words":3805},{"n":13,"title":"How It Works: Batteries and Power","when":"1970s – today","summary":"Inside every phone is a flat battery where tiny lithium particles swim back and forth to make electricity. It took three scientists from three countries, and a Nobel Prize, to make it safe and powerful. Let's find out how it works, why it gets tired, and how to look after it!","sections":[{"heading":"A Box of Bottled Chemistry","paragraphs":["Pick up a smartphone and feel its weight. A good chunk of that weight is a flat, silvery rectangle hidden behind the screen: the battery. It is the phone's fuel tank, and every single thing we have explored so far in this Deep Dive, from the glowing pixels of Part 10 to the billions of transistors of Part 11 and the radio chatter of Part 12, drinks from it. When the battery is empty, the most powerful pocket computer ever built becomes a very expensive paperweight.","So what is a battery, really? It is not a little tank of electricity, the way a bottle holds water. Electricity is hard to store directly. Instead, a battery stores chemical energy, the same kind of energy locked inside food, wood or petrol, and it turns that chemical energy into electricity only at the moment you need it.","The idea is more than two hundred years old. In 1800 the Italian scientist Alessandro Volta stacked discs of copper and zinc with pieces of cloth or cardboard soaked in salty water between them. His 'voltaic pile' produced a steady electric current, the first battery in history. The unit we use to measure the push of electricity, the volt, is named after him. Volta did not fully understand why his pile worked, but we now know the secret: a chemical reaction in which tiny charged particles move from one material to another.","Every battery, from Volta's pile to the one in your phone, has the same three main parts. There are two electrodes, which are pieces of material that electricity flows in and out of. One is called the negative electrode (or anode) and the other the positive electrode (or cathode). Between them sits the electrolyte, a substance that lets charged atoms called ions drift across, but does not let electrons through.","Here is the clever trick. The chemicals in a battery 'want' to react with each other, a bit like a ball wants to roll downhill. To react, two things have to travel from the negative side to the positive side: ions and electrons. The ions can take the short route straight through the electrolyte. But the electrons cannot pass through it, so they are forced to take the long way round, through a wire outside the battery. That stream of electrons flowing through the wire is an electric current, and along the way we can make it do work: light a screen, run a chip, or send a radio signal.","In a phone's lithium-ion battery, the travelling ions are lithium ions. A lithium ion is simply a lithium atom that has lost one electron, so it carries a positive charge. When you use your phone, lithium ions leave the negative electrode, swim through the electrolyte and tuck themselves into the positive electrode. At the very same time, their missing electrons rush through the phone's circuits to meet them on the other side.","Charging runs the whole film backwards. When you plug in, the charger pushes electrons back into the negative electrode, and the lithium ions are pulled back across the electrolyte to join them. The energy from the wall socket is stored once more as chemical energy, ready for tomorrow. Because the ions shuttle back and forth again and again, scientists sometimes call lithium-ion batteries 'rocking-chair' batteries.","One more part keeps everything safe: a thin plastic sheet called the separator, full of microscopic holes. It sits between the two electrodes, lets ions slip through, and stops the electrodes from ever touching. If they did touch, the energy could rush out all at once as heat. Remember the separator, because it will become very important later in this story."]},{"heading":"Before Lithium: Heavy Batteries for Heavy Phones","paragraphs":["Batteries that can be recharged are called secondary batteries, and the oldest kind is the lead-acid battery, invented in the 1850s and still used to start most petrol cars today. It is cheap and reliable, but enormously heavy. Nobody wants a lump of lead in their pocket.","For decades, portable gadgets that needed recharging used nickel-cadmium batteries, usually shortened to NiCd. Later came nickel-metal hydride, or NiMH, batteries; the first consumer NiMH cells went on sale in 1989. You may still have NiMH batteries at home, in the shape of rechargeable AA cells for toys and remote controls. Many of the chunky mobile phones of the 1980s and early 1990s ran on nickel-based batteries, and that is one reason they were so bulky and needed charging so often.","Nickel batteries had annoying habits. Each cell gave only about 1.2 volts, so several had to be stacked together to get a useful push. They were heavy for the energy they held. And if you kept recharging them before they were fully empty, they could seem to 'forget' part of their capacity and give out early. People called this the memory effect, and owners of early phones and laptops were often told to run their batteries completely flat before recharging. (Scientists now say that much of what people blamed on 'memory' was a different, reversible problem, but the advice stuck around for years.)","Engineers dreamed of something better, and they knew which element to look at: lithium. Lithium is the lightest metal in the universe; a block of it would float on water. It is number 3 on the periodic table, so each atom is tiny. And lithium is extremely eager to give away its outer electron, which means a battery built around it can produce a much bigger voltage than a nickel cell. Light weight plus high voltage equals lots of energy in a small, light package. That is exactly what a pocket phone needs.","The trouble is that lithium's eagerness is also its danger. Pure lithium metal reacts with water and air, and it can catch fire. Building a battery around it that would be safe to carry in your pocket, recharge thousands of times and sell by the billion took three brilliant scientists, on three continents, about fifteen years. Their story begins with an oil crisis."]},{"heading":"Whittingham's Spark: An Oil Company Builds a Battery","paragraphs":["In the early 1970s the world suddenly worried about running out of oil. In 1973 oil prices shot up, and long queues formed at petrol stations in many countries. Even big oil companies started asking a surprising question: what if the future ran on something other than petrol? Exxon, one of the largest oil companies on Earth, hired young scientists to investigate new kinds of energy, including better batteries.","One of them was M. Stanley Whittingham, a chemist born in 1941 in Nottingham, England, who had studied at the University of Oxford. Whittingham was interested in a strange property of certain materials: they are built from layers, like a stack of paper or the pages of a book, and small atoms can slide into the gaps between the layers and slide out again without wrecking the structure. Chemists call this intercalation, which roughly means 'putting something in between'.","Whittingham found that a material called titanium disulfide was perfect for this. It formed neat layers, and lithium ions could slip in and out of the spaces between them again and again. He used titanium disulfide as the positive electrode of a new battery. For the negative electrode he used lithium metal (in the version Exxon developed, a mixture of lithium and aluminium). The result, announced in the mid-1970s, was the first rechargeable lithium battery. It produced a little over 2 volts per cell, already better than nickel batteries.","Imagine the lab at Exxon in New Jersey: a team of chemists, glove boxes filled with dry gas to protect the reactive lithium from moist air, and test cells being charged and discharged over and over. It was exciting work, but there was a serious problem. When a lithium metal electrode is recharged many times, the lithium does not always settle back smoothly. It can grow into tiny, needle-like spikes called dendrites. If a dendrite grows long enough to pierce the separator and touch the other electrode, the battery short-circuits, heats up, and can catch fire.","Exxon's interest faded in the late 1970s: titanium disulfide was costly to make, and the lithium metal made the cells prone to catching fire. Exxon licensed the technology to other companies, and Whittingham later became a professor at Binghamton University in New York State. But the dendrite danger did not go away. In 1989 a Canadian company called Moli Energy, which made rechargeable batteries with lithium metal electrodes, had to stop sales and recall tens of thousands of phones after one of its batteries caught fire. The company went into receivership, meaning it ran out of money and was taken over to pay its debts. The lesson was clear: to make a truly safe rechargeable lithium battery, scientists would need to get rid of the lithium metal altogether.","Still, Whittingham had proved the key idea: a rechargeable battery could work by tucking lithium ions into the layers of a material and pulling them out again. Every lithium-ion battery since then is built on that idea."]},{"heading":"Goodenough, Yoshino and Sony: Building the Battery That Changed the World","paragraphs":["The next big step happened at the University of Oxford in England, led by an American physicist with a wonderful name: John B. Goodenough. He was born in 1922 in Jena, Germany, to American parents. As a schoolboy he struggled with dyslexia, a difference in how the brain handles reading and spelling, which nobody diagnosed at the time. He taught himself to write well enough to get into a top school, worked as a meteorologist (a weather scientist) for the US Army Air Corps during the Second World War, and became an expert on how atoms are arranged inside solid materials.","Goodenough had a hunch. Whittingham's titanium disulfide worked, but Goodenough reasoned that a metal oxide, a compound of a metal with oxygen, could hold lithium ions with a much stronger 'pull'. A stronger pull would mean a higher voltage, and a higher voltage would mean more energy from the same size of battery. In 1980, working with Koichi Mizushima and other colleagues, he showed that lithium cobalt oxide made an excellent positive electrode. Batteries using it could produce about 4 volts, nearly double Whittingham's cell. Lithium cobalt oxide, and close relatives of it, is still used in phone batteries today.","There is a slightly sad twist. The University of Oxford decided not to patent the discovery. Goodenough and his co-workers signed their rights over to a British government research laboratory, and they received no royalties as their invention went on to earn companies enormous sums. It is a reminder that great inventors do not always become rich from their inventions.","One piece was still missing: a safe negative electrode. Goodenough's cathode came out of the factory already full of lithium, so the battery no longer needed a chunk of dangerous lithium metal on the other side. The negative side just needed a material that could soak up the lithium ions when the battery was charged. That puzzle was solved in Japan.","Akira Yoshino was born in 1948 in Suita, near Osaka. As a schoolboy, a teacher gave him The Chemical History of a Candle, a famous set of lectures by the British scientist Michael Faraday, and it made him fall in love with chemistry. He spent his career at the Japanese chemical company Asahi Kasei. Starting in 1981 he experimented with a plastic that conducts electricity, called polyacetylene, as the negative electrode, but it was too bulky and not stable enough. So he switched to a special kind of carbon, with layers that lithium ions could slip between.","In 1985 Yoshino combined his carbon negative electrode with Goodenough's lithium cobalt oxide positive electrode and built the first practical lithium-ion battery. There was no pure lithium metal anywhere inside it, only lithium ions moving between two layered materials. He also designed it with long electrode sheets rolled up into a coil, like a Swiss roll, so there was a large surface for the ions to cross. To show it was much safer than lithium-metal batteries, his team is said to have tested prototypes harshly, including dropping a heavy lump of iron onto them; the lithium-metal cells burst into flames, while his did not.","Then came the leap from lab to shop. In 1991 Sony, the Japanese electronics company, began selling the first commercial lithium-ion batteries. Over the following years lithium-ion batteries spread into laptops, mobile phones, cameras and music players. Since 1991 the amount of energy packed into a given volume has roughly tripled, while the cost has fallen roughly tenfold. Today the same chemistry also powers electric cars, electric bikes and giant batteries that store solar and wind power.","In October 2019 the three pioneers, Whittingham, Goodenough and Yoshino, were awarded the Nobel Prize in Chemistry 'for the development of lithium-ion batteries'. Goodenough was 97 years old, making him the oldest person ever to win a Nobel Prize. He kept going to work at the University of Texas at Austin into his late 90s and died in 2023, aged 100. Think about that the next time you plug in your phone: the battery inside depends on ideas from a British chemist working for an oil company, an American physicist at Oxford, and a Japanese chemist inspired by a book about candles."]},{"heading":"Why Your Battery Gets Tired","paragraphs":["Look at a phone's specifications and you will usually see a battery number such as 4,000 mAh. The letters stand for milliampere-hours. An ampere (or amp) measures how much electric current flows, and a milliampere is a thousandth of an amp. A 4,000 mAh battery could, in theory, supply a current of 4,000 milliamps for one hour, or 400 milliamps for ten hours. Most smartphone batteries today hold somewhere between about 2,500 and 6,000 mAh.","But mAh does not tell the whole story. It measures electric charge, not energy. To know the energy, you also need the voltage, because energy equals charge multiplied by push. Engineers therefore often use watt-hours (Wh) instead. A typical phone cell works at about 3.7 volts, so a 4,000 mAh battery stores about 15 watt-hours. That is roughly the energy a 15-watt light bulb uses in one hour, and it is enough to run a smartphone through a whole day, which shows how amazingly efficient phones have become.","Every time you drain a battery and fill it back up, you use a charge cycle. Half a drain plus half a recharge on two different days counts as one cycle in total. Lithium-ion batteries can survive hundreds to more than a thousand cycles, but each cycle wears them down a tiny bit. Battery makers usually say a battery has reached the end of its normal life when it can hold only about 80 percent of its original charge.","Why does this happen? Inside the battery, a very thin crust slowly builds up on the surface of the negative electrode. Chemists call it the solid electrolyte interphase. A little of this crust is actually helpful, because it protects the electrode. But as it grows, it traps lithium that can then no longer carry charge, and it makes it harder for ions to move. The electrode materials also swell and shrink slightly every cycle as ions move in and out, and over time tiny cracks appear. Slowly, the battery holds less and delivers its energy less easily.","Heat speeds all of this up. Chemical reactions run faster when it is warm, including the unwanted ones that age a battery. That is why leaving a phone on a car dashboard in summer sunshine, or gaming for hours while it charges under a pillow, is bad for it. Batteries are also stressed when they sit for long periods completely full or completely empty. Cold is a different problem: in freezing weather a battery cannot deliver its energy easily, so a phone may suddenly switch off on a ski slope even though it showed plenty of charge, and then recover once it warms up.","Modern phones are designed to protect their batteries. Their charging chips slow down as the battery gets close to full, and many phones can learn your habits, holding the charge at around 80 percent overnight and finishing the last part just before your usual wake-up time. Some let you cap charging at 80 percent permanently. So you do not need to panic about charging overnight; the phone's electronics are watching. A few sensible habits help a battery last longer: avoid extreme heat, do not let it sit at zero for days, and use a decent charger. And the old advice about draining batteries completely before recharging? That was for nickel batteries. Lithium-ion batteries are happier with frequent top-ups."]},{"heading":"When Batteries Go Wrong: The Galaxy Note 7","paragraphs":["A lithium-ion battery packs a lot of energy into a small space, and its liquid electrolyte can burn. Almost all of the time, that energy comes out slowly and safely through the phone's circuits. Battery fires are rare, considering that billions of these batteries are in use. But when something does go wrong inside a cell, the result can be dramatic, and one famous phone taught the whole industry a hard lesson.","In August 2016 Samsung, by then the world's biggest smartphone maker, launched the Galaxy Note 7. It was a big, powerful, beautifully made phone with a stylus, and the early reviews were excellent. Within days, though, reports began to appear of Note 7 phones becoming dangerously hot and catching fire. On 2 September 2016, only about two weeks after it went on sale, Samsung stopped sales and announced a recall, offering to swap customers' phones for new ones with batteries from a different supplier. About 2.5 million phones were covered by that first recall.","Then something even more worrying happened: some of the replacement phones overheated too. In October 2016 Samsung asked everyone to stop using the Note 7 and, on 11 October, stopped making it altogether. Airlines around the world banned the phone from flights, even switched off. Samsung expected its profits to fall sharply because of the disaster, and analysts estimated that it lost billions of dollars.","In January 2017, after a long investigation, Samsung explained what had happened. There were two different problems in batteries from two different suppliers. In the first batch, the battery was slightly too large for its case, and the electrodes could be bent and pressed together at a corner, causing a short circuit. In the replacement batteries, some cells had rough spots left by the welding process that could poke through the thin separator, along with missing insulating tape. In both cases, the positive and negative sides could touch inside the battery. That is the separator's job, remember: to keep them apart.","When a short circuit happens inside a lithium-ion cell, energy pours out as heat in one spot. The heat can trigger more chemical reactions that release even more heat, a runaway chain called thermal runaway. The electrolyte can boil and vent hot gases, and the cell can catch fire. Engineers learned from the Note 7: Samsung introduced an eight-point battery safety check, and the whole industry paid even closer attention to testing, battery design and the space left around batteries inside thin phones.","There are sensible lessons here for everyone. If a phone battery becomes swollen, so the back of the phone bulges or the screen lifts, stop using it and take it to a repair shop; do not press on it or try to puncture it. Do not use a phone that has been badly crushed or bent. Use chargers and cables from trustworthy makers rather than the cheapest possible unbranded ones. And never throw old phones or batteries in the ordinary rubbish bin, where they can be crushed in a garbage truck and start fires; take them to an electronics recycling point instead. With a little care, a phone battery is a safe and very reliable companion."]},{"heading":"Making Every Drop Count","paragraphs":["Phone batteries have improved, but much more slowly than chips have. So a huge part of the reason phones last all day is not bigger batteries, but smarter ways of spending energy.","The biggest energy users in a phone are usually the screen, the radios and the main chip. The screen is the hungriest when it is bright. Phones with OLED screens have a special trick: as we saw in Part 10, each OLED pixel makes its own light, so a black pixel is simply switched off and uses almost no power. That is why dark mode can save energy on OLED phones. A 2021 study by researchers at Purdue University measured it carefully. At everyday brightness levels of about 30 to 50 percent, switching from light mode to dark mode saved only about 3 to 9 percent of the power on average. At full brightness, though, the savings jumped to roughly 39 to 47 percent. On older LCD screens, where a backlight shines behind every pixel all the time, dark mode saves very little.","Chips save energy too. Modern phone processors contain a mix of big, powerful cores for hard jobs like games and small, thrifty cores for easy jobs like checking messages. When you are not touching the phone, it drops into a deep sleep, waking for a split second now and then to check for new messages or calls. The chip can also lower its speed and voltage when it does not need full power. Radios matter as well: a phone on the edge of coverage has to shout louder to reach a distant tower, which is why your battery drains faster in places with weak signal.","Charging has changed a lot. Lithium-ion batteries are charged in two stages: first with a steady current, which fills them quickly, then with a steady voltage while the current gradually tapers off as the battery nears full. That is why a phone often races from 0 to 50 percent, then slows down for the last part. Fast chargers push more power during the early stage. Many phones now charge at 20 to 45 watts, and some models go much higher, while chips inside the phone and charger 'talk' to each other to agree how much power is safe and watch the battery temperature.","Wireless charging is not really wireless; it just has no plug. Inside the charging pad is a coil of wire carrying an alternating current, which makes a rapidly changing magnetic field. A second coil inside the phone sits in that field, and the changing magnetism creates a current in it, a principle called electromagnetic induction that was discovered by Michael Faraday in the 1830s. Most phones use a standard called Qi (pronounced 'chee'), from a group called the Wireless Power Consortium. The Nokia Lumia 920 of 2012 was one of the first phones to build it in. The basic version delivered 5 watts, and later versions added more, and in 2023 the Qi2 standard added magnets, based on Apple's MagSafe design, to snap the phone into exactly the right spot. Wireless charging is convenient, but some energy is lost as heat, so it is usually a little less efficient than a cable.","Then there is the cable itself. For years every phone brand seemed to use a different plug, and drawers filled up with tangled, useless chargers. In 2022 the European Union passed a law requiring new phones sold in the EU to charge through a common connector, USB-C, by the end of 2024, with laptops following in 2026. The aim was to save money for shoppers and cut electronic waste from abandoned chargers. Apple, the last big holdout, began moving its iPhones to USB-C in 2023, as Part 19 explains.","Look back at how far we have come. The Motorola DynaTAC of 1983 offered about 30 minutes of talking after a long recharge. A modern smartphone, with a battery thinner than a chocolate bar, can stream video, navigate, take photos and chat all day. And some of that power goes to the feature many people use even more than calling. Open the camera app, and the phone's battery, chip and screen all burst into action at once. How does a lens no bigger than a lentil take photos that can rival a big camera? That is where we are heading next."]}],"deepDive":"Why did lithium-ion win? The answer is energy density: how much energy a battery stores per kilogram or per litre. Nickel-metal hydride cells store roughly 46 to 120 watt-hours per kilogram; lithium-ion cells typically store about 160 to 300, and some specialist cells more. Two factors explain the gap. Lithium is the lightest metal, so the charge carriers add very little mass, and lithium-based electrodes give a cell voltage of about 3.6 to 3.7 volts instead of about 1.2 volts for a nickel cell. Since energy is charge multiplied by voltage, tripling the voltage roughly triples the energy from the same amount of charge. The key chemical idea is intercalation: lithium ions slot into the gaps of layered host materials (graphite on the negative side, a metal oxide such as lithium cobalt oxide or a nickel-manganese-cobalt mix on the positive side) without the host's structure collapsing. Because no lithium metal is plated during normal use, the dendrite problem that doomed early lithium-metal cells is largely avoided, though it can return if a cell is charged very fast, overcharged, or charged in freezing cold, when lithium may plate onto the graphite instead of sliding into it. Battery ageing is an active research field. A major cause is the slow thickening of the solid electrolyte interphase on the graphite, which consumes lithium; its growth is often modelled as roughly proportional to the square root of time. Heat accelerates these side reactions, and so does sitting at a high state of charge, which is why phones now pause charging around 80 percent overnight. There are also debates about materials. Cobalt is expensive and much of it is mined in the Democratic Republic of the Congo, raising human-rights concerns discussed in Part 18, so makers are shifting toward cathodes with less cobalt, and toward lithium iron phosphate in many electric cars. The next big hope is the solid-state battery, which replaces the flammable liquid electrolyte with a solid; it promises more energy and better safety, but making it cheaply and reliably at scale is still a challenge (Part 19). Finally, a note on credit: the Nobel committee honoured three people, but many others contributed, including Jürgen Besenhard, who studied lithium intercalation in graphite in the 1970s, and the Sony engineers who turned a prototype into a mass-produced product in 1991.","funFact":"John Goodenough was 97 when he won the 2019 Nobel Prize in Chemistry, making him the oldest Nobel laureate ever, and he kept working on new battery ideas until nearly 100.","check":{"q":"In a lithium-ion battery, what moves through the electrolyte from one electrode to the other?","a":"Lithium ions","wrong":["Drops of water","Tiny pieces of copper wire","Light particles called photons"]},"sources":[{"title":"Lithium-ion battery","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Lithium-ion_battery"},{"title":"John B. Goodenough","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_B._Goodenough"},{"title":"M. Stanley Whittingham","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/M._Stanley_Whittingham"},{"title":"Akira Yoshino","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Akira_Yoshino"},{"title":"Samsung Galaxy Note 7","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Samsung_Galaxy_Note_7"},{"title":"Dark mode may not save your phone's battery life as much as you think","publisher":"Purdue University","url":"https://www.purdue.edu/newsroom/releases/2021/Q3/dark-mode-may-not-save-your-phones-battery-life-as-much-as-you-think,-but-there-are-a-few-silver-linings.html"},{"title":"Qi (standard)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Qi_(standard)"},{"title":"Moli Energy","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Moli_Energy"}],"photos":[{"src":"img/deep/smartphone/13-1.jpg","alt":"John B. Goodenough (right) receives the Enrico Fermi Award from Energy Secretary Steven Chu.","file":"John B. Goodenough (2010).jpg","url":"https://commons.wikimedia.org/wiki/File:John_B._Goodenough_(2010).jpg","author":"U.S. Department of Energy","license":"Public domain"},{"src":"img/deep/smartphone/13-2.jpg","alt":"How a lithium-ion cell works: lithium ions move through the electrolyte between graphite and metal-oxide electrodes.","file":"Lithium ion battery.png","url":"https://commons.wikimedia.org/wiki/File:Lithium_ion_battery.png","author":"Walter Davison","license":"CC BY-SA 4.0"},{"src":"img/deep/smartphone/13-3.jpg","alt":"A flat 3.8-volt lithium-ion battery from an LG smartphone, rated 1700 mAh.","file":"LG Li-Ion battery, Model BL-44JH-1805.jpg","url":"https://commons.wikimedia.org/wiki/File:LG_Li-Ion_battery,_Model_BL-44JH-1805.jpg","author":"Raimond Spekking","license":"CC BY-SA 4.0"}],"words":4404},{"n":14,"title":"How It Works: The Camera in Your Pocket","when":"1969 – today","summary":"The camera on your phone is smaller than a pea, but it can photograph the Moon, your pet and a sunset. Inside, a chip with millions of tiny light-catchers turns light into numbers, and clever software mixes many pictures into one. Let's find out how it all works!","sections":[{"heading":"Catching Light in a Tiny Window","paragraphs":["Turn your phone over and look at the camera. It is a small circle of glass, often no wider than a lentil or a pea. Yet every day people use these little circles to take billions of photos: birthday parties, sunsets, homework, pets doing silly things, the Moon. To understand how such a tiny camera works, we need to start with light itself.","Light travels in straight lines, bouncing off everything around you. When sunlight hits your friend's face, some of it bounces off toward your eyes, carrying the colours and shapes of the face. A camera's job is to collect that bounced light and arrange it into a sharp picture. Our eyes do exactly the same job with a lens at the front and a light-sensitive screen, the retina, at the back.","A lens is a carefully shaped piece of glass or clear plastic. Because light slows down slightly when it enters glass, a curved lens bends the light rays, a bit like a group of marching soldiers turning when one side of the line steps onto mud. A convex lens, one that bulges outward, bends rays from a single point on your friend's nose so that they all meet again at a single point behind the lens. Do that for every point in the scene and you get a complete, upside-down image. When the meeting points land exactly on the light-sensitive surface, the image is sharp: it is in focus. If they meet a little in front of it or behind it, the picture is blurry.","Objects at different distances focus at slightly different places, so a camera needs to adjust. In a big camera you twist the lens. In a phone, the lens is moved by a tiny electromagnetic motor, often called a voice coil motor because it works like the coil in a loudspeaker. It shifts the lens by fractions of a millimetre in a split second. To decide where to move it, the phone measures sharpness and contrast in the image, and many modern sensors also have special focus pixels that compare light arriving from the left and right sides of the lens, rather like your two eyes judging distance.","Why are phone lenses so small? The main reason is the phone's thickness. A typical smartphone is less than a centimetre thick, and the camera has to fit inside, with only a small bump on the back. The distance between a lens and the place where it forms its image is called the focal length, and it depends on the size of the image you want. A big camera with a big sensor needs a focal length of several centimetres. A phone sensor is much smaller, often less than a centimetre across, so its lens can sit just a few millimetres in front of it. Phone lenses are actually stacks of five, six or more tiny moulded plastic lens elements, each shaped with incredible precision to cancel out blurring and colour fringes.","The size of the opening that lets light in is called the aperture. Photographers describe it with an f-number such as f/1.8 or f/2.8; a smaller f-number means a wider opening and more light. Phone cameras usually have wide apertures to catch as much light as possible, because the tiny sensor behind them needs every bit it can get. But a lens only makes an image. To turn that image into a photo you can send to your grandmother, the camera needs something that can feel light and turn it into numbers. That is the image sensor, and its story begins at Bell Labs."]},{"heading":"The Bucket Brigade: Inventing the CCD","paragraphs":["For more than a century, photos were captured on film coated with light-sensitive chemicals, which had to be developed in a darkroom. To make a digital photo, scientists needed a way to turn light directly into electrical signals that a computer could store. The breakthrough came, partly by accident, in 1969.","At Bell Labs in New Jersey, the same research centre that gave the world the transistor and the cellular idea, two physicists named Willard Boyle and George E. Smith were trying to invent a new kind of computer memory. Boyle had grown up in Amherst, Nova Scotia, in Canada, and was taught at home by his mother until he was 14. Smith was an American who had served in the US Navy. Their bosses were keen on a memory technology called magnetic bubble memory, and Boyle and Smith wondered whether tiny packets of electric charge could play the same role as the magnetic bubbles.","Their answer was the charge-coupled device, or CCD. Picture a long row of buckets standing in a field when it starts to rain. Each bucket collects rainwater, and the bucket under the heaviest rain fills the most. Afterwards, to measure the water, you pass the buckets along the row, one after another, to a person at the end who weighs each one. A CCD works like this, except that the rain is light and the buckets are microscopic patches of silicon. When light hits silicon, it knocks electrons loose, and each patch collects electrons in proportion to how much light fell on it. Then carefully timed voltages pass the little packets of charge along, bucket to bucket, to an amplifier at the edge of the chip that measures each one.","Boyle and Smith described the idea in 1970. Engineers quickly saw that it would make a superb light sensor, and by 1971 a Bell Labs team led by Michael Tompsett was making simple images with CCDs. Companies such as Fairchild, RCA and Texas Instruments joined in, and in 1975 Steven Sasson, a young engineer at Kodak, built an experimental digital camera using a Fairchild CCD with just 100 by 100 pixels, ten thousand in total. It was about the size of a toaster and stored its pictures on a cassette tape. Sony later led the way in mass-producing CCDs for video cameras, launching consumer CCD camcorders in the 1980s.","Astronomers loved CCDs most of all. Compared with photographic plates, a CCD captures a much larger share of the light that hits it and measures it very accurately, so faint galaxies and distant planets suddenly became far easier to photograph. CCDs went into telescopes on Earth and in space, as well as into fax machines, scanners and, eventually, the first wave of digital cameras.","In 2009 Boyle and Smith shared half of the Nobel Prize in Physics for inventing the CCD. (The other half went to Charles Kao for his work on sending light through optical fibres, which carries much of the world's internet traffic.) Boyle also had an unusual side career: while working at a company connected to NASA's Apollo programme in the 1960s, he helped choose landing sites on the Moon. But CCDs had a weakness for a phone. Moving charge across the whole chip needs relatively high voltages and a lot of power, and the CCD needs separate support chips. A battery-powered pocket camera needed something leaner."]},{"heading":"A Camera on a Chip: The CMOS Sensor","paragraphs":["The answer came from an unexpected place: NASA's Jet Propulsion Laboratory (JPL) in Pasadena, California, the lab that builds robotic space probes. Spacecraft engineers care about every gram and every milliwatt, because launching weight into space is very expensive and power is precious far from the Sun. In the early 1990s a young engineer at JPL named Eric Fossum led a team working on smaller, more efficient cameras.","Fossum's team built on ideas that other researchers had tried before, going back to the 1960s, and companies such as Olympus and Mitsubishi were exploring similar sensors too. The JPL team's key achievement was to make an excellent active-pixel sensor using CMOS, the same standard manufacturing process used to make ordinary computer chips. CMOS stands for complementary metal-oxide-semiconductor, a mouthful that you can simply think of as 'the normal way chips are made'.","In an active-pixel sensor, every pixel has its own tiny light collector, a photodiode, plus a few transistors right next to it. Instead of passing its charge bucket by bucket across the whole chip like a CCD, each pixel turns its own charge into a voltage on the spot, and the chip reads out the pixels row by row, a bit like reading lines of text in a book. Because the sensor is made with normal chip technology, the same piece of silicon can also hold the circuits that control the camera, convert the signals into digital numbers and even start processing the image. Fossum called it a camera-on-a-chip.","This made a huge difference. CMOS sensors use much less power than CCDs, can be built cheaply in the same factories as other chips, and need fewer extra parts. In 1995 Fossum and his colleague Sabrina Kemeny started a company called Photobit to sell the technology, and its sensors were soon used in webcams. Other companies, especially in Japan and Korea, poured effort into improving CMOS sensors. Early CMOS images were noisier than CCD images, but the gap closed quickly, and by 2007 CMOS sensors were outselling CCDs. Today almost every phone camera, webcam and most digital cameras use CMOS sensors. Fossum later won the Queen Elizabeth Prize for Engineering in 2017.","Engineers kept squeezing more performance out of CMOS. In an ordinary sensor, the light has to pass through a layer of metal wiring before reaching the photodiodes, and some of it is blocked. In 2009 Sony introduced back-illuminated sensors, which flip the chip over so that light arrives from the back, without wires in the way; this made them much more sensitive in dim light. In 2012 Sony introduced stacked sensors, in which the light-catching layer is bonded on top of a separate layer of processing circuits. Some modern phone sensors even have a layer of fast memory sandwiched underneath, so they can grab many frames in a fraction of a second. Those fast grabs are the secret behind the clever photo tricks you will meet shortly."]},{"heading":"Pixels, Colours and the Megapixel Myth","paragraphs":["Zoom far into any digital photo and it breaks up into a grid of tiny coloured squares. Each one is a pixel, short for picture element. A photo that is 4,000 pixels wide and 3,000 pixels tall contains 12 million pixels, or 12 megapixels (mega means million). On the sensor, each pixel corresponds to one microscopic light collector, and on a phone sensor these are astonishingly small, often only about 1 micrometre across, roughly a hundredth of the width of a human hair.","Here is a surprise: an image sensor cannot see colour. Each photodiode only measures how much light hits it, not what colour that light is. To capture colour, a mosaic of tiny coloured filters is laid over the pixels, so each pixel sees only red, only green or only blue light. The most common arrangement is the Bayer filter, patented in 1976 by Bryce Bayer, an engineer at Kodak. In his pattern, half the pixels are green, a quarter are red and a quarter are blue. Why so much green? Because human eyes are most sensitive to green light and judge brightness and detail mostly through it. Afterwards, the phone's processor guesses the two missing colours at every pixel by looking at its neighbours, a step called demosaicing.","For years, phone makers advertised megapixels as if they were the only thing that mattered, and the numbers climbed and climbed. The earliest camera phones, around 1999 and 2000, had about 0.1 megapixels, enough for a small, grainy picture on a tiny screen. In 2012 the Nokia 808 PureView amazed people with a 41-megapixel sensor. Today, many phones have 12 to 50 megapixels on their main camera, and some reach 200.","But more megapixels does not always mean a better photo. Imagine the sensor as a field and the pixels as buckets catching raindrops of light. If you squeeze more buckets into the same field, each bucket gets smaller and catches fewer drops. In dim light, small pixels collect only a little light, and random electrical fluctuations, called noise, become more noticeable, appearing as speckly grain. The quality of a photo also depends on the lens, the size of the whole sensor, how steady the camera is, and especially the software that processes the image.","That is why many high-megapixel phones use a trick called pixel binning. In good light they can use every pixel for fine detail. In dim light, they combine groups of neighbouring pixels, four or even sixteen at a time, into one big 'super-pixel' that gathers more light, producing a photo with fewer megapixels but less noise. The Nokia 808 was an early example of this oversampling idea. So when you compare phones, the megapixel number is only one clue among many, and often not the most important one."]},{"heading":"Many Photos in One: Computational Photography","paragraphs":["Here is a secret about the photos on your phone: many of them are not really one photo at all. When you press the shutter button, a modern phone often grabs a whole burst of frames in a fraction of a second, and its chip combines them into a single picture that is better than any one of them. This is called computational photography: using computing power, not just glass and silicon, to make a picture.","Why is this needed? A tiny phone sensor struggles with two classic problems. The first is contrast. Picture a friend standing in front of a bright window. Expose the photo for the bright sky, and your friend becomes a dark silhouette; expose it for your friend, and the window turns into a blank white blob. The second problem is darkness. In dim light, each tiny pixel catches only a few particles of light, and the picture fills with grainy noise.","The solution to the first problem is HDR, which stands for high dynamic range. The camera captures several frames, some darker and some brighter, and blends them, keeping detail in both the bright sky and the dark face. Photographers had been combining differently exposed pictures for decades, but phones made it automatic. In 2014 Google introduced a system called HDR+ in its camera app. It captures a quick burst of frames, lines them up in software so small hand movements do not cause blurring, and merges them, which also averages away much of the random noise.","The second problem was tackled by night modes. In 2018 Google launched Night Sight on its Pixel phones, described by researchers Marc Levoy and Yael Pritch. Night Sight first measures how much the scene and the phone are moving. If everything is fairly still, it uses longer exposures; held in the hand it might take up to 15 frames, while on a tripod it can take a few frames of up to about one second each. It then aligns and merges them, and uses a machine-learning method to correct the colours, which can look strange under streetlights or candlelight. It was designed to work in light as dim as about 0.3 lux, so dark that ordinary phone cameras of the time produced little more than a black, speckly mess. Apple, Samsung, Huawei and other companies developed their own night modes around the same time.","Portrait mode is another trick. Big cameras with large lenses can take portraits where the person is sharp and the background is softly blurred, a look photographers love. A phone's tiny lens normally keeps almost everything in focus, so it fakes the effect. It works out how far away each part of the scene is, using two cameras that see from slightly different positions, special dual-pixel sensors, or artificial intelligence that recognizes people and hair, and then blurs the background digitally. Sometimes it makes mistakes around glasses or curly hair, which shows that it is a clever simulation, not real optics.","All this needs serious computing power. The image signal processor, or ISP, a dedicated part of the phone's system-on-a-chip that we met in Part 11, handles jobs like demosaicing, noise reduction and colour correction in real time, while the AI engine (NPU) helps recognize faces, skies and food to adjust each part of the picture. A single tap of the shutter may set off billions of calculations. It also raises an interesting question: when software decides how a photo should look, how 'real' is the picture? Photographers and scientists enjoy arguing about that."]},{"heading":"Many Eyes: Lenses, Steady Hands, Video and Selfies","paragraphs":["Turn over a recent phone and you may see two, three or even more camera lenses. Each one has a different job, because a single tiny lens cannot zoom the way a big camera lens can. A big zoom lens moves groups of glass elements back and forth inside a long tube, but there is no room for that inside a thin phone. So phone makers simply include several fixed lenses and switch between them.","The main or wide camera is the everyday one, with the biggest and best sensor. The ultra-wide camera squeezes in a much wider view, great for buildings, landscapes and group photos in small rooms. The telephoto camera gives a closer, zoomed-in view. In 2018 the Huawei P20 Pro became one of the first phones with three rear cameras, and in 2019 the Nokia 9 PureView had five. To fit a longer telephoto lens inside a thin body, some phones use a periscope design: a tiny prism or mirror turns the light sideways by 90 degrees, so the lens can lie along the length of the phone instead of through its thickness, just like a submarine periscope.","Shaky hands are a camera's enemy, especially in dim light when each exposure lasts longer. Optical image stabilization (OIS) fights back. A tiny gyroscope sensor detects the phone's wobbles hundreds of times a second, and electromagnets nudge the lens, or in some phones the whole sensor, in the opposite direction to cancel them out. The Nokia Lumia 920, launched in late 2012, was described as the first phone with an optically stabilized camera, and within a couple of years most high-end phones had it. There is also electronic image stabilization, used especially for video, where software shifts each frame slightly to cancel out shaking; it crops a little of the edge of the picture to have room to move.","Phones also became serious video cameras. The first iPhone of 2007 could not record video at all. The iPhone 4 in 2010 recorded high-definition 720p video, and today many phones film in 4K, a picture about 3,840 by 2,160 pixels, and some even higher, along with slow motion, time-lapse and smooth stabilized footage. Many films, music videos and news reports have now been shot partly or entirely on phones.","Then there is the camera pointing back at you. Kyocera's VP-210, sold in Japan in May 1999 and often called the first camera phone, actually had its camera on the front, with about 110,000 pixels, so that people could send their faces during calls. But front cameras became popular around the world when the iPhone 4 arrived in June 2010 with a front-facing camera and Apple's FaceTime video calling. Its front camera had only about 0.3 megapixels, but it changed how people stayed in touch. Front cameras soon became standard, and the word selfie became so common that Oxford Dictionaries made it Word of the Year in 2013, as Part 17 explores."]},{"heading":"From One Baby Photo to Billions of Snapshots","paragraphs":["Let us step back to one famous day: 11 June 1997, in a hospital in California. The software entrepreneur Philippe Kahn was waiting while his wife was in labour, and he had been working for about a year on a system for sharing pictures online. Using wires, a digital camera, a mobile phone and some quickly written code, he improvised a link between the camera and the phone, and when his daughter Sophie was born, he sent pictures of her through the phone to a picture-sharing system running on a computer at his home, from which friends and family could see them. It was not a camera phone in one device, but it showed what instant photo sharing could feel like. Kahn later co-founded a company called LightSurf, which helped bring picture messaging to phones.","As Part 6 described, real camera phones arrived in Japan soon after. After the Kyocera VP-210 in 1999, the Sharp J-SH04, sold by J-Phone from November 2000, had a camera of about 0.11 megapixels and could send photos over the mobile network. Within a few years camera phones spread across the world, and by the end of the 2000s it was hard to buy a phone without a camera.","The effect on the camera industry was enormous. For about a hundred years, if you wanted to take pictures, you bought a camera. Sales of compact digital cameras peaked around 2010 at well over a hundred million a year, then fell steeply as people realized the camera in their pocket was good enough, always with them, and could share pictures instantly. Today phone cameras are the most common cameras in the world, and most of the photos humans take are taken with phones. Big standalone cameras are still popular with professionals and enthusiasts, especially for sports, wildlife and very low light, but they are now a specialist tool.","Think about everything that has to happen when you snap a photo of your dog. A stack of tiny plastic lenses focuses light, moved into place by a voice coil motor. A CMOS sensor with millions of photodiodes, each under a red, green or blue filter, turns that light into electric charge. A gyroscope steadies the lens. The image processor merges a burst of frames, cleans away noise and fixes the colours, and a few seconds later the picture is on its way to a friend on the other side of the world. It all depends on the work of Boyle and Smith, Fossum and Kemeny, Bayer, Kahn and thousands of other engineers.","But notice something in that list: a gyroscope. The camera is only one of a phone's many senses. Hidden inside the case are tiny sensors that can feel which way is up, count your steps, measure the air pressure, find north, know exactly where you are on the planet using satellites, and even recognize your face in the dark. In the next part, we will meet the senses you never knew your phone had."]}],"deepDive":"Why can a lens the size of a lentil compete with a big camera at all? Physics sets hard limits. The amount of light a camera collects depends on the area of its sensor, and a typical phone main sensor is many times smaller in area than the full-frame sensor of a professional camera. Light arrives as individual photons, and the number caught by each pixel fluctuates randomly; this photon shot noise grows only as the square root of the signal, so the signal-to-noise ratio improves only as the square root of the light collected. Collecting four times more light makes the image only about twice as clean. A small sensor therefore starts at a disadvantage that no lens can fully overcome. Phone makers fight back in three ways. First, they make sensors more efficient: back-illuminated and stacked CMOS designs let a high fraction of incoming photons become electrons, and modern pixels add very little electronic read noise. Second, they gather more light over time instead of space: merging a burst of N aligned frames reduces random noise by roughly the square root of N, which is the core idea behind HDR+ and Night Sight. Alignment is the hard part, because the hand and the subject move between frames; software has to match tiles of each frame and reject pieces that do not fit, or ghosts appear. Third, they use prior knowledge: machine-learning models estimate white balance, separate a person from the background for portrait blur, and sharpen textures they 'expect' to see. This last approach is where debates begin. A photo that has been heavily processed may look better than reality, and critics have argued about phones that enhance the Moon or smooth skin automatically. Historians of technology also debate credit for the image sensor. The CCD is clearly Boyle and Smith's 1969 invention, honoured with the 2009 Nobel Prize, but the active-pixel idea had earlier roots, including Peter Noble's work in the 1960s and Olympus's and Mitsubishi's MOS and CMOS sensors in the 1980s and early 1990s. Eric Fossum's JPL team is widely credited with making the CMOS active-pixel sensor practical and showing it could become a camera-on-a-chip, which is why the phone camera can be so small and use so little battery.","funFact":"Kyocera's VP-210 of 1999, often called the first commercial camera phone, had its camera on the front, pointing at the user, more than a decade before front-facing cameras and FaceTime made video calling popular on the iPhone 4.","check":{"q":"Which kind of image sensor, developed by Eric Fossum's team at NASA's Jet Propulsion Laboratory, is used in almost every phone camera because it uses little power?","a":"The CMOS active-pixel sensor","wrong":["The photographic film plate","The vacuum tube sensor","The magnetic bubble memory"]},"sources":[{"title":"Charge-coupled device","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Charge-coupled_device"},{"title":"Active-pixel sensor","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Active-pixel_sensor"},{"title":"Eric Fossum","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Eric_Fossum"},{"title":"Willard Boyle","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Willard_Boyle"},{"title":"Night Sight: Seeing in the Dark on Pixel Phones","publisher":"Google Research","url":"https://research.google/blog/night-sight-seeing-in-the-dark-on-pixel-phones/"},{"title":"Camera phone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Camera_phone"},{"title":"Bayer filter","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bayer_filter"},{"title":"Philippe Kahn","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Philippe_Kahn"}],"photos":[{"src":"img/deep/smartphone/14-1.jpg","alt":"A square silicon CCD image sensor on a gold-pinned circuit board, from the National Air and Space Museum.","file":"Charge-Coupled Device (NASM-A20000697000cp02-CC).jpg","url":"https://commons.wikimedia.org/wiki/File:Charge-Coupled_Device_(NASM-A20000697000cp02-CC).jpg","author":"Smithsonian National Air and Space Museum","license":"CC BY 4.0"},{"src":"img/deep/smartphone/14-2.jpg","alt":"Bryce Bayer's 1974 Kodak notebook page sketching his red, green and blue filter pattern, with twice as much green.","file":"Bryce Bayer Lab Notebook U203 page 1.jpg","url":"https://commons.wikimedia.org/wiki/File:Bryce_Bayer_Lab_Notebook_U203_page_1.jpg","author":"KAPcooney","license":"CC BY-SA 4.0"},{"src":"img/deep/smartphone/14-3.jpg","alt":"The three rear camera lenses of a Huawei P20 Pro smartphone, made with Leica.","file":"Huawei P20 Pro - Leica triple camera system.jpg","url":"https://commons.wikimedia.org/wiki/File:Huawei_P20_Pro_-_Leica_triple_camera_system.jpg","author":"Mk2010","license":"CC BY-SA 4.0"}],"words":4073},{"n":15,"title":"How It Works: Sensors and GPS","when":"1970s – today","summary":"Your phone has tiny machines inside that feel when you tilt, turn or walk. It has a compass, a light detector, and even a way to recognize your face. And it can find exactly where you are by listening to clocks flying in space!","sections":[{"heading":"Tiny Machines and the Weight on a Spring","paragraphs":["Pick up a phone, turn it sideways, and the picture on the screen spins around to match. Put it in your pocket and go for a walk, and at the end of the day it can tell you that you took 8,412 steps. Tilt it, and a racing car in a game steers left or right. None of this is magic. Hidden inside the phone are some of the smallest machines people have ever built, and they are moving right now, even while the phone lies still on a table.","These machines are called MEMS, short for micro-electromechanical systems. That is a long name for a simple idea: tiny mechanical parts, like springs, beams and weights, made on a chip together with electronics. The parts are measured in micrometres. One micrometre is a thousandth of a millimetre, and a human hair is roughly 70 to 100 micrometres thick. Many of the moving pieces inside a MEMS sensor are only a few micrometres wide, and a whole sensor can be smaller than a grain of rice.","The idea is older than you might think. In 1965, at the Westinghouse research labs in the United States, Harvey C. Nathanson's team built a device called the resonant-gate transistor, in which a tiny metal beam vibrated above a transistor. It is often named as one of the earliest MEMS devices. The word MEMS itself only became popular in the late 1980s. For years the biggest customer for these sensors was not phones but cars: a MEMS accelerometer can notice the sudden jolt of a crash in a few thousandths of a second and tell the airbag to inflate. By the time smartphones arrived, MEMS sensors were cheap, tiny and reliable, and phone makers grabbed them.","The most common motion sensor in a phone is the accelerometer, which measures acceleration, meaning any change in speed or direction. To understand it, imagine a small box with a heavy ball hanging inside on springs. If you suddenly push the box to the right, the ball lags behind for a moment and the springs on one side squash while the springs on the other side stretch. Measure how far the ball moved and you know how hard the box was pushed. That is an accelerometer.","Inside a phone, the ball is a tiny slab of silicon called a proof mass, and the springs are thin silicon beams. Sticking out from the proof mass are rows of little fingers, like the teeth of a comb, that sit between matching fingers fixed to the chip. When the mass shifts, the gaps between the moving fingers and the fixed fingers change. The chip measures this using capacitance, the same kind of electric effect your touchscreen uses (Part 10): as the gaps get smaller or larger, the amount of electric charge the fingers can store changes too. The changes are incredibly small, but the electronics can read them hundreds or even thousands of times a second.","Here is the clever part. Even when the phone is lying still, the accelerometer feels something: gravity. Gravity pulls the proof mass downward, just as it pulls you into your chair. A phone usually has three accelerometers in one package, arranged to measure along three directions at right angles to each other, often called x, y and z. By checking which direction gravity is pulling, the phone knows which way is down. If gravity is pulling toward the bottom edge, you are holding it upright; if gravity is pulling toward the side edge, you have turned it on its side, and the screen rotates.","Accelerometers are also very good at noticing rhythm. Each time you take a step, your body bounces up and down a little, and the phone feels a small bump. A step-counting app looks for that repeating pattern and counts the bumps, ignoring random shakes that do not fit. It can be fooled by a bumpy bus ride, but it is good enough that millions of people track their daily walking without wearing any extra gadget."]},{"heading":"The Gyroscope: Feeling a Twist","paragraphs":["An accelerometer is great at sensing pushes and gravity, but it is not so good at measuring smooth turning. If you spin slowly in an office chair while holding a phone flat, gravity still points straight down the whole time, so the accelerometer barely notices. For turning, phones use a second sensor: the gyroscope.","Old-fashioned gyroscopes were spinning wheels. A spinning wheel resists being tilted, which is why a spinning top stays upright and why ships and aircraft once used big spinning gyroscopes to help them steer. But you cannot fit a whirling wheel inside a thin phone. So MEMS gyroscopes use a trick instead of a spinning wheel: they use a vibrating mass.","Picture a tiny weight that is constantly being shaken back and forth, thousands of times a second, like a pendulum on fast-forward. If the phone turns while the weight is moving, the weight gets nudged sideways. This sideways nudge is caused by the Coriolis effect, the same effect that makes giant storms on Earth swirl, because Earth is turning underneath the moving air. A merry-go-round shows the idea: if you try to roll a ball straight across a spinning merry-go-round, its path seems to curve. In the gyroscope, the sideways nudge is measured with comb-shaped fingers and capacitance, just like the accelerometer. The faster the phone turns, the bigger the nudge.","Gyroscopes made phones far better at games and at augmented reality, which means showing computer pictures mixed into a live camera view of the real world. When you look around a room through your phone's camera and a cartoon creature seems to stay sitting on the real floor, the gyroscope is measuring every tiny turn of your hand so the picture can be shifted to match. Gyroscopes also help keep photos and videos steady (Part 14) by sensing the shake of your hand. Apple added a gyroscope to the iPhone 4 in 2010, and soon gyroscopes became standard in smartphones."]},{"heading":"A Compass, a Barometer and Two Little Eyes","paragraphs":["First comes the magnetometer, the phone's compass. Earth behaves like a giant, weak magnet, and its magnetic field points roughly toward the North and South Poles. A magnetometer measures the strength and direction of that field along three directions. Many phone magnetometers use the Hall effect, discovered by the American physicist Edwin Hall in 1879: when electric current flows through a material sitting in a magnetic field, the field pushes the moving charges slightly to one side, creating a small voltage that can be measured. From that, the phone works out which way north is, so your map can turn to face the same way you are facing. Because metal objects, speakers and magnets nearby can confuse it, a map app sometimes asks you to wave your phone in a figure-eight. That movement helps the software figure out which part of the magnetic reading comes from the phone itself and which comes from Earth.","Next is the barometer, which measures air pressure. Air has weight, and the air above us presses down on everything. The higher you go, the less air is above you, so the pressure drops. Near the ground, climbing about 8 or 9 metres, roughly one floor of a tall building plus a bit, lowers the pressure by about 1 hectopascal, which is about one-thousandth of the pressure at sea level. A MEMS barometer has a tiny, thin membrane sealed over a little chamber; as outside pressure changes, the membrane bends very slightly, and the bending is measured electrically. This lets a fitness app count how many flights of stairs you climbed, and it helps maps and emergency services guess which floor of a building you are on. Weather changes the pressure too, so phones combine the barometer with other information instead of trusting it alone. iPhones gained a barometer with the iPhone 6 in 2014, and many Android phones have one as well.","Then come the two little eyes near the top of the phone. One is the proximity sensor. When you make a phone call and lift the phone to your ear, the screen goes dark. That is not just to save power: without it, your cheek would tap buttons and might hang up the call or turn on the speaker. The proximity sensor sends out a tiny beam of invisible infrared light and watches for it to bounce back. If something is very close, like your ear, plenty of light reflects back, and the phone switches off the touchscreen until you move it away.","The other is the ambient light sensor, which measures how bright the room is. In a dark bedroom, a full-brightness screen would dazzle you; in bright sunshine, a dim screen would be impossible to read. The light sensor lets the phone turn its brightness up and down automatically. Some phones even measure the color of the light around you and shift the screen's colors slightly warmer or cooler so white looks white, like a piece of paper would under the same lamp. Together, these small sensors cost very little and use very little power, yet they make the phone feel as if it understands its surroundings."]},{"heading":"Thirty-Something Clocks in the Sky","paragraphs":["Now for the most amazing sense of all: knowing exactly where on Earth you are. For that, your phone listens to satellites. The best known system is GPS, the Global Positioning System, built and run by the United States military and today operated by the US Space Force. It is free for anyone in the world to use.","By the early 1970s, the US Air Force and Navy each had their own ideas for navigating by satellite, and they were competing. In 1973, an Air Force officer and engineer named Colonel Bradford Parkinson was put in charge of bringing those ideas together. Over the Labor Day weekend that year, he gathered a small group of officers and engineers in nearly empty offices at the Pentagon, a gathering later nicknamed the 'Lonely Halls' meeting. In those few days they sketched the basic plan for the system that became GPS, which was officially called NAVSTAR. Parkinson is often called the father of GPS, though he has always pointed out that many people contributed, including the engineers Ivan Getting and Roger Easton, whose earlier work on satellite timing was important.","The first GPS test satellite was launched on February 22, 1978. GPS was originally built for the military, but a sad event changed its future. In 1983, Korean Air Lines Flight 007, a passenger jet with 269 people on board, drifted off course because of a navigation error and was shot down after it strayed into Soviet airspace. Afterwards, President Ronald Reagan announced that GPS would be made available for civilian use once it was ready, so that ordinary aircraft and ships could know exactly where they were.","By 1993 enough satellites were in orbit for the system to work, and full operation was declared in April 1995. But there was a catch. For civilians, the US military deliberately added small errors to the signals, a feature called Selective Availability, so that enemies could not use GPS for precise targeting. Ordinary receivers could only find their position to within about 100 metres, about the length of a football field. Then, in May 2000, President Bill Clinton ordered Selective Availability turned off. Almost overnight, a basic receiver could find itself to within about 5 to 10 metres. That single decision helped make phone maps, car navigation and later games like Pokémon Go possible.","Today GPS uses a constellation, or group, of about 31 working satellites. They fly about 20,200 kilometres above Earth, more than fifty times higher than the International Space Station, and each one circles the planet about twice a day, taking just under 12 hours per orbit. They are spread across six different orbital paths so that, from almost anywhere on Earth, at least four satellites are above the horizon at any moment, and usually more."]},{"heading":"How Your Phone Finds Itself","paragraphs":["Here is the surprising secret of GPS: the satellites do not know where you are, and they never hear from your phone at all. Your phone does not send anything to them. Each GPS satellite is simply a very accurate clock in space, constantly broadcasting a message that says, in effect, 'I am satellite number such-and-such, I am at this exact spot, and the time right now is this.' Your phone just listens.","Radio signals travel at the speed of light, about 300,000 kilometres per second. So when a message arrives, your phone compares the time stamped on it with the time it was received. Suppose the message took about 0.07 seconds to arrive. Multiply 0.07 seconds by 300,000 kilometres per second and you get about 21,000 kilometres. Now the phone knows it is somewhere on the surface of an imaginary giant ball with a radius of about 21,000 kilometres, centred on that satellite.","One satellite is not enough, because you could be anywhere on that ball. A second satellite gives a second ball, and the two balls cross in a circle. A third ball narrows the circle down to just two points, and usually only one of those is anywhere near Earth's surface. This method of finding a spot from distances is related to trilateration, an idea surveyors and mapmakers have used for a long time.","So why does the phone need at least four satellites? Because of clocks. Each GPS satellite carries atomic clocks, which use the steady vibrations of atoms to keep time so accurately they would drift by only a tiny fraction of a second over many years. Your phone cannot carry an atomic clock; its clock is cheap and wobbly. And timing matters enormously: since light travels about 300 metres in one millionth of a second, a clock error of just one microsecond would put you 300 metres off. The fourth satellite gives the phone one more measurement, which lets it solve for the error in its own clock as well as its three position numbers: east-west, north-south and up-down. In effect, GPS turns your phone's cheap clock into a very precise one.","Then there is Einstein. Albert Einstein's theories of relativity say that time does not tick at the same rate everywhere. His special theory of relativity (1905) says moving clocks tick slightly slower, and GPS satellites race along at nearly 4 kilometres per second, so their clocks lose about 7 microseconds a day. His general theory of relativity (1915) says clocks tick slightly faster where gravity is weaker, and gravity is weaker high above Earth, so the satellite clocks gain about 45 microseconds a day. Put together, the satellite clocks run about 38 microseconds a day fast compared with clocks on the ground. That sounds tiny, but remember: one microsecond is about 300 metres of error. If engineers did not correct for relativity, GPS positions would drift off by roughly 10 to 11 kilometres every single day. So the satellite clocks are deliberately set to tick slightly slow before launch, and the system makes further corrections. Every time your phone shows the blue dot in the right place, it is quietly proving Einstein right.","GPS is no longer alone. Russia runs GLONASS, which became fully working in the 1990s; the European Union runs Galileo, which started offering services in 2016; and China runs BeiDou, which completed its global network in 2020. India (NavIC) and Japan (QZSS) have regional systems too. Together, all of these are called GNSS, global navigation satellite systems. Most modern phones listen to several of them at once, so they can see many more satellites, which makes positions faster and more accurate, especially between tall buildings. Some newer phones also use a second GPS frequency, called L5, which helps them tell the true signal apart from bounced echoes."]},{"heading":"The Mathematician Who Measured the Shape of the Earth","paragraphs":["There is a hidden problem in everything we just described. To turn satellite timing into a position on a map, you need to know exactly what shape Earth is. And Earth is not a perfect ball. It bulges at the equator because it spins, it is slightly flattened at the poles, and its gravity is a little stronger in some places than others because of mountains, ocean trenches and heavy rocks deep underground. If you use the wrong shape, your answers come out wrong.","One of the people who helped solve this problem was Gladys West. She was born in 1930 in Dinwiddie County, Virginia, into a farming family, and she studied hard because she saw education as her way to a different life. She earned a scholarship to Virginia State College (now Virginia State University), where she studied mathematics. In 1956 she was hired at the US Naval Proving Ground in Dahlgren, Virginia, as a mathematician, becoming only the second Black woman ever hired there.","At Dahlgren, West worked on huge computer programs that processed data from satellites. From the mid-1970s into the 1980s, she programmed an IBM computer to calculate an extremely detailed model of Earth's shape, called the geoid: an imaginary surface that shows where the average sea level would be all over the planet if water could flow freely under the continents. The geoid is lumpy, rising and falling by tens of metres. She also worked on Seasat, a satellite launched in 1978 that measured the ocean's surface with radar, and on later satellite projects. Careful models of Earth's shape like the ones she worked on became part of the foundation that lets GPS turn timing measurements into accurate positions.","For decades, almost nobody outside her workplace knew about her contribution. She retired in 1998 after 42 years at Dahlgren, and only around 2018 did her story become widely known, when she was inducted into the US Air Force Space and Missile Pioneers Hall of Fame. In 2021 she became the first woman to receive the Prince Philip Medal from Britain's Royal Academy of Engineering. She lived to the age of 95. Her story is a good reminder that great inventions are rarely the work of one famous name. Behind every blue dot on a map are the quiet calculations of people like her."]},{"heading":"Your Finger and Your Face as a Key","paragraphs":["A phone holds your messages, photos and sometimes even your money, so it needs a good lock. For years, the lock was a four-digit code, a password or a pattern you swiped with your finger. These work, but they can be slow, and someone looking over your shoulder can spot them. So phone makers turned to biometrics: using parts of your body, like your fingerprint or your face, as the key.","Fingerprint readers on phones were not new in 2013. A few phones in the 2000s and early 2010s had them, but they were often fussy and unreliable. Apple had bought a fingerprint-sensor company called AuthenTec in 2012 for about 356 million dollars, and on September 10, 2013, it introduced Touch ID on the iPhone 5s. The sensor sat under the home button, covered by a disc of scratch-resistant sapphire crystal and surrounded by a stainless steel ring that sensed when your finger arrived. Like a touchscreen, it worked with capacitance, but at very high detail: about 500 dots per inch, fine enough to map the ridges and valleys of your skin. The ridges touch the sensor and the valleys sit a little farther away, and the sensor can feel the difference. It could recognize your finger from any angle.","Four years later, on September 12, 2017, Apple introduced the iPhone X with Face ID, which unlocked the phone simply by looking at it. A set of parts at the top of the screen, called the TrueDepth camera, does three jobs. A flood illuminator washes your face in invisible infrared light, so it works even in the dark. A dot projector, using a tiny laser, sprays more than 30,000 invisible infrared dots onto your face. An infrared camera then photographs the pattern. Because the dots land closer together or farther apart depending on the curves of your nose, cheeks and chin, the phone can build a three-dimensional map of your face, which is much harder to fool with a flat photo than an ordinary camera picture would be.","Apple said the chance of a random stranger unlocking your phone with Touch ID was about 1 in 50,000, and with Face ID about 1 in 1,000,000. It also admitted the odds were not as good for identical twins, close siblings and children under 13, whose faces may be still developing. Importantly, the fingerprint or face data is not a photo stored on the internet. It is turned into a mathematical description and kept in a protected part of the phone's chip, called the Secure Enclave, which is designed so that apps, and even Apple, cannot read it.","Android phone makers built their own versions too: fingerprint readers on the back, on the side button, and later hidden under the screen itself, using either a tiny camera that photographs your fingerprint through gaps between the pixels or sound waves (ultrasound) that bounce off the ridges of your skin. Some phones also offer face unlocking. Biometrics are not perfect, and a code is still kept as a backup, but they made locking a phone so easy that far more people actually do it."]},{"heading":"Sensors Working as a Team","paragraphs":["Each sensor on its own has weaknesses. The accelerometer is jittery. The gyroscope slowly drifts if you trust it for too long. The compass gets confused by a nearby metal table. GPS disappears inside tunnels and is slow to notice small movements. But when the phone combines all of them, each one covers for the others. Engineers call this sensor fusion.","Think about walking through a city with a map app open. GPS tells the phone roughly where you are every second or so. The accelerometer counts your steps and notices when you stop. The gyroscope and compass tell it which way you are facing, which is why the blue dot on the map has a little beam showing your direction. If you walk into a tunnel or a big shopping mall and lose the satellites, the phone can keep guessing your path for a while by counting steps and turns, a method sailors would recognize as dead reckoning, then snap back to the right spot when GPS returns.","Sensors can even help save lives. Apple added fall detection to the Apple Watch in 2018: if the watch's sensors feel a hard fall followed by stillness, it asks if you are okay and can call emergency services if you do not answer. Google added car crash detection to some of its Pixel phones starting in 2019, and Apple added Crash Detection to the iPhone 14 in 2022. These features look for the combination of a huge, sudden jolt, a big change in speed, the loud noise of a collision picked up by the microphones, and a sudden change in air pressure as airbags burst open. Google has also used the accelerometers in millions of Android phones as a giant network of tiny earthquake detectors: when many phones in one area feel the first shaking at once, the system can send a warning to phones farther away, sometimes seconds before the strongest shaking arrives.","Step back and think about it. A small slab in your pocket can feel gravity, sense turning, find north, measure the air, see your face, and listen to clocks in space that are corrected using Einstein's theories. It is a laboratory full of instruments. Yet when most people think about why they love their phones, they do not think about MEMS gyroscopes or atomic clocks at all. They think about what the phone lets them do: chat with friends, play games, take photos, order food, find their way home. All of that comes from software, the programs we call apps. The hardware made the smartphone possible, but it was apps that made people fall in love with it, and in Part 16 we will see how one online store opening in July 2008 set off an explosion of millions of them."]}],"deepDive":"GPS is really a timing system that happens to give positions. Each satellite broadcasts its orbit and the time from onboard atomic clocks; a receiver measures 'pseudoranges', distances that include an unknown error from its own cheap clock. With four or more satellites the receiver solves four unknowns at once: three position coordinates and its clock offset. That is why GPS is also the world's most widely used source of precise time, used by mobile networks, power grids and banks to keep their systems in step. Because light covers about 30 centimetres in a nanosecond, timing errors translate directly into distance errors, so everything that delays a signal matters: the charged upper atmosphere (ionosphere) slows signals by an amount that depends on frequency, which is why dual-frequency receivers (L1 plus L5) can cancel much of that error; water vapour in the lower atmosphere adds more delay; and in 'urban canyons' signals bounce off buildings and arrive late, a problem called multipath. Relativity is the famous correction. Special relativity slows the moving satellite clocks by roughly 7 microseconds a day, while general relativity speeds them up by roughly 45 microseconds a day because gravity is weaker at about 20,200 km; the net effect is about +38 microseconds a day. The satellite clock frequency is offset before launch (from 10.23 MHz to about 10.22999999543 MHz) to compensate, and receivers add a small extra correction because the orbits are slightly elliptical. Historians debate who deserves credit for GPS. Bradford Parkinson led the joint program and its 1973 design; Roger Easton's Naval Research Laboratory work on space clocks (the Timation satellites) and Ivan Getting's early advocacy at the Aerospace Corporation were also crucial, and Gladys West's geodesy work belongs to the wider effort to model Earth precisely. In 2019 four GPS pioneers, including Parkinson, shared the Queen Elizabeth Prize for Engineering. On the biometrics side, the quoted false-match rates (1 in 50,000 for Touch ID, 1 in 1,000,000 for Face ID) are the manufacturer's statistical claims for a random person, not guarantees; security researchers have occasionally fooled both systems with elaborate fakes, which is why a passcode remains required after restarts.","funFact":"If engineers did not correct GPS satellite clocks for Einstein's relativity, the positions they give would drift by roughly 10 to 11 kilometres every day.","check":{"q":"Why does a phone need signals from at least four GPS satellites, not just three?","a":"The fourth lets it work out the error in its own clock as well as its position","wrong":["The fourth satellite tells the phone what country it is in","Each satellite only works for six hours a day","The fourth satellite sends the map pictures"]},"sources":[{"title":"Global Positioning System","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Global_Positioning_System"},{"title":"GPS.gov: Official U.S. government information about the Global Positioning System","publisher":"U.S. National Coordination Office for Space-Based PNT","url":"https://www.gps.gov/"},{"title":"Bradford Parkinson","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bradford_Parkinson"},{"title":"Gladys West","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gladys_West"},{"title":"Microelectromechanical systems","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Microelectromechanical_systems"},{"title":"Accelerometer","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Accelerometer"},{"title":"Touch ID","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Touch_ID"},{"title":"Face ID","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Face_ID"}],"photos":[{"src":"img/deep/smartphone/15-1.jpg","alt":"Artist's picture of a GPS Block IIF satellite orbiting high above Earth.","file":"GPS Satellite NASA art-iif.jpg","url":"https://commons.wikimedia.org/wiki/File:GPS_Satellite_NASA_art-iif.jpg","author":"NASA","license":"Public domain"},{"src":"img/deep/smartphone/15-2.jpg","alt":"A tiny MEMS machine carved from silicon, seen through a microscope: a moving plate on thin springy arms.","file":"MEMS (5940479277).jpg","url":"https://commons.wikimedia.org/wiki/File:MEMS_(5940479277).jpg","author":"Christopher/NIST (National Institute of Standards and Technology)","license":"Public domain"},{"src":"img/deep/smartphone/15-3.jpg","alt":"Gladys West and Sam Smith study GPS data at the Naval base in Dahlgren, Virginia, in 1985.","file":"Gladys West and Sam Smith.jpg","url":"https://commons.wikimedia.org/wiki/File:Gladys_West_and_Sam_Smith.jpg","author":"U.S. Navy","license":"Public domain"}],"words":4355},{"n":16,"title":"There's an App for That","when":"2008 – today","summary":"In 2008 a shop opened that you could visit right on your phone, full of games and tools called apps. Soon there were millions of them, made by everyone from giant companies to teenagers. Apps turned one phone into a camera, a map, a game console and even a bank!","sections":[{"heading":"July 10, 2008: The Store Opens","paragraphs":["Imagine owning a phone that can only ever do the jobs it came with. It can call, text, maybe play a couple of built-in games and take a blurry photo, and that is it, forever. For most people before 2008, that was normal. Some phones could download extra games or ringtones, but usually through the phone company's own menu, with a short list chosen by the company, and it was often confusing and expensive. Making software for phones was hard, too: a programmer often had to make deals with phone companies one by one.","When the first iPhone arrived in June 2007 (Part 8), it had no way to add new programs from other companies at all. Steve Jobs at first told outside programmers to build web apps, websites designed to look and work a bit like programs, instead. Programmers were not satisfied, and some people even found ways to 'jailbreak' their iPhones, breaking Apple's software locks so they could install unofficial programs. Apple changed course. In March 2008 it released a software development kit, or SDK: a set of tools and instructions that let outside programmers write real programs for the iPhone.","On July 10, 2008, the App Store opened, just before the iPhone 3G went on sale the next day. It started with about 500 apps, and about 125 of them were free. The word app is short for application, meaning a program that does a particular job. Suddenly, you could tap an icon, browse a shop full of games, tools and toys, and download one in a minute or two, straight over the air, without plugging the phone into a computer. Every new app made the phone you already owned more useful.","People went wild for it. By April 2009, less than a year later, people had downloaded one billion apps. Apple even made a television advertising slogan out of the idea: 'There's an app for that.' Whether you wanted to find a restaurant, check the weather, learn the stars in the night sky, or pop virtual bubble wrap, someone had probably already made an app to do it.","Google was not far behind. Its phone software, Android (Part 9), got its own store, called Android Market. Google announced it in August 2008, and it became available to users on October 22, 2008, when the first Android phone, the T-Mobile G1, went on sale. In March 2012, Google combined Android Market with its online stores for music, books and films and renamed the whole thing Google Play. One difference between the two worlds became important later: on Android, people can also install apps from other places, such as a developer's own website or a different app store, if they change a setting. On the iPhone, for most of its history, Apple's App Store was the only official door.","Today, the main app stores each hold millions of apps. Apple reported close to 2 million apps in its store in 2024, and Google Play has held anywhere from under 2 million to more than 3 million in recent years, with the numbers rising and falling as the stores remove old or broken apps. That is more apps than one person could look at in a lifetime of browsing."]},{"heading":"Anyone Can Make an App","paragraphs":["The App Store did something unusual: it let almost anyone become a software seller to the whole world. In the past, to sell a computer program, you usually needed a company, a box, a disc, a printed manual and a deal with shops. Now a single programmer at a kitchen table could write a game, send it to Apple or Google, and if it was approved, people on the other side of the planet could buy it the very next week.","How does the money work? When someone buys an app or pays for something inside an app, the store keeps a share and passes the rest to the developer, the person or company that made the app. For many years the standard deal was 70/30: the developer kept 70 percent and the store kept 30 percent. That 30 percent pays for running the store, handling payments, checking apps and reaching customers, although many developers argued it was too much. Over time the rules softened. Both Apple and Google started taking only 15 percent on subscriptions after the first year, and from 2021 Apple charged 15 percent to small developers earning under 1 million dollars a year. Google made similar changes. Developers also pay to join: Apple charges a yearly membership fee, and Google charges a one-time registration fee.","Many apps do not cost anything to download. Instead, they make money in other ways: by showing advertisements, by selling extra items or levels inside the app (called in-app purchases), or by asking for a monthly subscription. This 'freemium' idea, free to start but pay for extras, became the most common way to earn money from apps, especially games.","The amounts are enormous. Apple says the App Store helped developers earn hundreds of billions of dollars in sales since 2008. It also created many new kinds of jobs: app designers, programmers, testers, people who write the words in apps, and people who study which apps are popular. Universities and online courses began teaching app-making, and young people around the world, including teenagers, learned to code and publish their own apps. Apple even runs a student challenge as part of its yearly developer conference, and Google, Apple and others offer free coding tools that run right on a laptop.","Of course, publishing an app is not the same as being successful. With millions of apps in the stores, most apps are downloaded only a small number of times, and only a small share of developers earn a living from them. Being noticed is hard. Getting featured on the store's front page, or going viral as friends tell friends, can make the difference between a few downloads and many millions."]},{"heading":"Apps That Changed Our Habits","paragraphs":["Some apps became so popular that they changed how people live, play and talk. Here are a few of the most famous, though there are many more.","It is worth remembering how many everyday jobs quietly moved into apps too. Little tools that once needed their own gadgets, such as a calculator, an alarm clock, a voice recorder, a flashlight, a dictionary or a bus timetable, became free icons on a home screen. Banks put their branches into apps, airlines turned paper boarding passes into codes on a screen, and schools began sending homework and messages to families through apps. None of these were as famous as the hits below, but together they explain why many people now reach for their phones dozens of times a day.","Angry Birds came from Rovio, a small game studio in Finland that had made 51 games for other companies before it created a hit of its own. Designer Jaakko Iisalo sketched some round, grumpy-looking birds with angry eyebrows, and the team built a game around them: you pull back a slingshot with your finger and fling birds at wobbly towers built by green pigs. It came out for the iPhone in December 2009 for 99 cents. It was perfect for a touchscreen, simple to learn but hard to master, with realistic physics as the towers tumbled. Within about a year it had been downloaded over 50 million times, and the Angry Birds series later passed billions of downloads, plus toys, cartoons and movies.","WhatsApp was started in 2009 by Jan Koum and Brian Acton, two former workers at the internet company Yahoo. At first it was meant to be a simple status app, showing friends whether you were busy or on a call. It turned into a messaging app that sent texts over the internet instead of the phone network's SMS system, which saved people a lot of money, especially when messaging friends and family in other countries. In 2014 Facebook bought WhatsApp for about 19 billion dollars, one of the biggest technology deals ever at the time. By 2020 it had more than 2 billion users, and in many countries it became the main way people talk, from family chats to doctors sending appointment reminders.","Instagram began as a different app called Burbn, a check-in app for sharing where you were. Its creators, Kevin Systrom and Mike Krieger, noticed that people mostly liked its photo features, so they stripped it down to just photos. Instagram launched on the App Store on October 6, 2010, with square pictures and filters that made phone photos look like old film snapshots. It gained 1 million users within two months. In 2012 Facebook agreed to buy it for about 1 billion dollars, even though the company had only about a dozen employees.","Maps and navigation changed even more lives. The first iPhone came with a Google Maps app, and in 2009 Google launched free turn-by-turn spoken directions for Android phones. Combined with GPS (Part 15), phone maps replaced folded paper maps and expensive car navigation gadgets for millions of drivers, walkers and cyclists. Maps also made possible another huge change: ride-hailing. Uber, founded in San Francisco in 2009, launched an app that let you tap a button, see a car approaching on a map, and pay automatically. Similar services, such as Lyft in the United States, Didi in China and Grab in Southeast Asia, spread the idea around the world, along with food-delivery apps that work the same way.","Then, in July 2016, came Pokémon Go, made by Niantic with Nintendo and The Pokémon Company. It used GPS to place Pokémon in the real world, so players had to walk to parks, streets and landmarks to catch them, and it used the camera and gyroscope to show the creatures as if they were standing right in front of you. It set records: in its first month it became the most-downloaded mobile game ever in a first month, at about 130 million downloads, and it reached 500 million downloads within a few months. Suddenly crowds of people were walking around cities staring at their phones and cheering. Studies found that many players walked noticeably more than before, at least for the first weeks, which led one journalist to call it an accidental health craze."]},{"heading":"Money in a Text Message: M-Pesa","paragraphs":["Not every world-changing phone service needed a smartphone or an app store. One of the most important ones ran on simple, cheap phones with tiny screens and number keys, and it started in Kenya.","In the early 2000s, millions of Kenyans had mobile phones, but most did not have bank accounts. Banks were far away, especially in the countryside, and opening an account could be costly. Yet people constantly needed to move money: a son working in Nairobi wanted to send part of his wages to his parents in a village hundreds of kilometres away. Often the only way was to hand cash to a bus driver or a friend and hope it arrived. Researchers studying phones in Africa had noticed something clever: people were already sending each other phone airtime, the prepaid credit used to make calls, as a kind of money.","The British phone company Vodafone and its Kenyan partner Safaricom decided to build a proper service. Part of the early money for the project came from a fund run by the UK government's Department for International Development. After a trial starting in 2005, the service launched to the public in March 2007. It was called M-Pesa: M for mobile, and pesa, the Swahili word for money.","Here is how it works. You visit an M-Pesa agent, often a small shop that also sells phone airtime, and hand over cash. The agent adds that amount to the M-Pesa account linked to your phone number. To send money, you use a menu on your phone, type in the person's phone number, the amount and your secret PIN, and the money moves by a secure text message. The person receives a message saying the money has arrived, and they can walk to an agent near them and turn it back into cash, or keep it on their phone and pay for something else. No bank branch, no smartphone and no internet connection needed.","M-Pesa spread incredibly fast. By the end of 2011, Kenya had about 17 million M-Pesa users, and today it operates in several African countries and has tens of millions of customers. People used it to pay school fees, electricity bills and shopkeepers, and to receive wages. A widely cited 2016 study by economists Tavneet Suri and William Jack estimated that access to M-Pesa helped lift about 2 percent of Kenyan households out of extreme poverty, partly by helping women move from farming into business. Other researchers have questioned how big that effect really was, so it is fair to say economists still discuss the exact numbers. But nearly everyone agrees M-Pesa showed the world that a phone could be a bank.","Richer countries came to phone payments later, and in a different way. On October 20, 2014, Apple launched Apple Pay, which lets you pay in shops by holding your phone near a card reader. It uses NFC, near-field communication, a radio link that only works over a few centimetres. Clever security is built in: the phone does not send your real card number to the shop. Instead it sends a stand-in number called a token, plus a one-time code, and you approve the payment with your fingerprint or face (Part 15). Google, Samsung and others offer similar wallets. In many countries, tapping a phone or watch to pay for a bus ride or a sandwich is now ordinary.","China took yet another path. There, many shops skipped card readers almost completely and jumped straight to paying with phones through QR codes, the square black-and-white patterns a camera can read. With apps such as Alipay, from the shopping company Alibaba, and WeChat Pay, built into the hugely popular WeChat messaging app, a customer scans a code printed on a sign at the counter, or the shopkeeper scans a code on the customer's screen, and the money moves instantly. Because a printed QR code costs almost nothing, even street-food sellers and market stalls could accept phone payments. Three very different routes, but the same idea: the phone in your pocket became your wallet."]},{"heading":"Who Decides? Store Rules and the Fortnite Fight","paragraphs":["An app store is a bit like a giant shopping mall where the mall owner decides which shops may open. Before an app appears in Apple's App Store, it is checked by Apple's review process against a long list of rules, called the App Store Review Guidelines. Apps can be rejected if they crash, collect data in sneaky ways, contain harmful content, copy other apps, or try to trick people. Google also checks apps for Google Play, using a mix of automatic scanning and human review.","Supporters say these rules protect users. Because Apple controls what goes in, iPhone owners can download apps without worrying as much about viruses or scams, and parents can trust the store a bit more. Critics say the store owners have too much power: they make the rules, they compete with some of the apps in their own stores, and they take a cut of the money. Developers have complained that rejections can be confusing, and that they were not allowed to tell customers about cheaper ways to pay outside the app.","That argument exploded on August 13, 2020. Epic Games, maker of the hugely popular game Fortnite, secretly switched on its own payment system inside the Fortnite app, offering players the game's V-Bucks currency at a 20 percent discount if they paid Epic directly instead of going through Apple or Google. This broke both stores' rules, and within hours both Apple and Google removed Fortnite. Epic was ready: the same day, it filed lawsuits against both companies and released a video that made fun of Apple's own famous 1984 advertisement.","The court case against Apple was decided by Judge Yvonne Gonzalez Rogers in California. In September 2021, she ruled that Apple was not an illegal monopoly under US federal law, which was mostly a win for Apple. But she also ruled that Apple must allow apps to tell users about other ways to pay and to link to them, a win for developers. Apple's attempts to follow the order while still charging fees led to more arguments, and in 2025 the judge found that Apple had not properly obeyed her order and told it to stop charging fees on those outside payments. Apple appealed, and in 2026 the US Supreme Court agreed to hear its appeal of that ruling. In the separate case against Google, a jury in December 2023 found that Google had illegally protected a monopoly over its Android app store and payments; an appeals court upheld the verdict in 2025, and Epic and Google later reached a settlement. Fortnite eventually returned to the iPhone in the United States in 2025.","Governments got involved too. The European Union's Digital Markets Act, which started applying in 2024, requires the biggest technology companies to open up more, and Apple began allowing alternative app stores on iPhones in the EU. Other countries, including Japan and South Korea, passed their own app store rules. The fight is not over, and people still disagree about the right balance between safety and freedom. It is a good example of how a new invention can raise questions that inventors never imagined, questions that end up in courts and parliaments."]},{"heading":"What Is an App, Really?","paragraphs":["So what actually is an app? At heart, it is a list of instructions called code, written by programmers in a programming language. On iPhones, many apps are written in a language called Swift, which Apple introduced in 2014; on Android, many are written in Kotlin or Java. The programmer's code is turned into the simple instructions the phone's chip understands (Part 11), packed together with pictures, sounds and other files, and uploaded to the store. When you tap Install, your phone downloads that package and stores it.","Apps do not have to build everything themselves. The phone's operating system offers ready-made building blocks, a bit like a toolbox, called APIs (application programming interfaces). An app that wants to know your location does not need to understand satellite clocks; it simply asks the operating system, which asks the GPS chip and hands back the answer. The same goes for the camera, the accelerometer, the speaker and the internet connection. This is why a small team can make an amazing app: they stand on the shoulders of everything the phone already knows how to do.","But you would not want any app to grab your photos, listen through your microphone or track where you go without asking. So modern phones keep each app in its own sandbox, a fenced-off area where it can only touch its own files. To reach beyond the fence, an app must ask permission, and you see a pop-up message such as 'Allow this app to use your location?' You can say yes, no, or only while using the app, and you can change your mind later in the settings. A good habit is to ask: does this app really need that? A flashlight app has no good reason to read your contacts.","Apps also keep changing after you install them. Developers fix bugs, close security holes and add new features, then send out updates through the store. Many phones install these automatically overnight. Some apps also fetch fresh information from the internet every time you open them, from computers called servers, which is why a weather app or a chat app shows new things each day even if the app itself has not changed. In a way, an app on your phone is often just the front door, and much of the work happens in giant data centers far away.","Put it all together and you can see why apps changed the smartphone so much. The hardware we explored in Parts 10 to 15 is like a powerful, beautifully made instrument. Apps are the music. Millions of different people, from huge companies to teenagers in their bedrooms, can write new music for the same instrument. A single phone can become a game console on the bus, a bank in a Kenyan village, a camera studio, a map of the whole world, or a way to say goodnight to a grandparent on another continent.","And that is the bigger story. Each app on its own might seem small: one game, one chat service, one map. But billions of phones running millions of apps added up to something far larger than any single invention. It changed how people shop, work, travel, learn, make friends and even protest. In Part 17, we zoom out from single apps to the whole planet, and ask how billions of smartphones changed the way humanity lives."]}],"deepDive":"Economists describe app stores as 'two-sided platforms': they bring together users on one side and developers on the other, and each side becomes more valuable as the other grows. More users attract more developers, more apps attract more users, and this feedback loop, called a network effect, helps explain why the market settled on just two big ecosystems, Apple's iOS and Google's Android, while rivals such as BlackBerry World and Microsoft's Windows Phone Store struggled to attract enough apps. The commission debate centres on whether the store's cut (traditionally 30 percent, now often 15 percent for small developers and long-running subscriptions) reflects fair payment for services such as security review, payment processing and distribution, or is a 'tax' that only a gatekeeper could charge. In Epic Games v. Apple, Judge Yvonne Gonzalez Rogers defined the relevant market as mobile gaming transactions and found that Apple was not an illegal monopolist under federal law, but she ordered an end to 'anti-steering' rules under California law; in 2025 she found Apple in contempt of that order, and in 2026 the US Supreme Court agreed to hear Apple's appeal of the contempt ruling. A parallel jury found against Google in December 2023, a verdict upheld on appeal in 2025. Regulators have moved too: the EU's Digital Markets Act (applying from 2024) forces 'gatekeepers' to allow alternative app stores and payment options, and Japan and South Korea have passed their own laws. Security experts warn that opening up phones can make scams and malware easier, while competition advocates argue the benefits outweigh the risks; there is no simple consensus. M-Pesa is studied for a different reason. It showed that a mobile network's existing agent shops and SMS menus could act as a cheap substitute for bank branches. Tavneet Suri and William Jack's 2016 study in Science estimated that access to M-Pesa lifted about 194,000 Kenyan households (about 2 percent) out of extreme poverty, with especially strong effects for households headed by women. A 2019 critique by Milford Bateman and colleagues argued the study's methods overstated the effect, and the debate continues, a reminder that measuring the impact of technology on poverty is genuinely hard.","funFact":"Instagram began as a check-in app called Burbn, and it reached 1 million users within two months of launching as a photo app in October 2010.","check":{"q":"What did M-Pesa, launched in Kenya in 2007, let people do with simple mobile phones?","a":"Send and receive money using text messages","wrong":["Watch live television","Download games from the App Store","Find their location using GPS"]},"sources":[{"title":"App Store (Apple)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/App_Store_(Apple)"},{"title":"Google Play","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Google_Play"},{"title":"M-Pesa","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/M-Pesa"},{"title":"Epic Games v. Apple","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Epic_Games_v._Apple"},{"title":"Angry Birds (video game)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Angry_Birds_(video_game)"},{"title":"WhatsApp","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/WhatsApp"},{"title":"Instagram","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Instagram"},{"title":"Pokémon Go","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Go"}],"photos":[{"src":"img/deep/smartphone/16-1.jpg","alt":"A small shop in Kenya with a bright green wall painted with M-Pesa and Safaricom signs.","file":"M-Pesa Kenyan Kiosk.JPG","url":"https://commons.wikimedia.org/wiki/File:M-Pesa_Kenyan_Kiosk.JPG","author":"Realt0n12","license":"CC BY-SA 3.0"},{"src":"img/deep/smartphone/16-2.jpg","alt":"People in a Stockholm street staring at their phones during the Pokémon Go craze of summer 2016.","file":"Pokemon GO Fever in Stockholm 2016.jpg","url":"https://commons.wikimedia.org/wiki/File:Pokemon_GO_Fever_in_Stockholm_2016.jpg","author":"Frankie Fouganthin","license":"CC BY 4.0"},{"src":"img/deep/smartphone/16-3.jpg","alt":"A cyclist's phone shows a folder of cycling apps: there really is an app for almost everything.","file":"Cycling apps on mobile phone.jpg","url":"https://commons.wikimedia.org/wiki/File:Cycling_apps_on_mobile_phone.jpg","author":"Alextredz","license":"CC BY-SA 4.0"}],"words":3832},{"n":17,"title":"A World in Your Pocket: How Smartphones Changed Society","when":"2007 – today","summary":"Today billions of people carry a smartphone, and it has changed almost everything: how we find our way, send money, learn, work and talk to our families. In some countries people skipped home telephones completely and jumped straight to mobile phones. Phones even gave us new words like 'selfie' and new ways to smile with emoji!","sections":[{"heading":"Billions of Pockets","paragraphs":["Try a little experiment the next time you ride a bus, wait in a doctor's office or sit in a busy café. Count the people around you, then count how many of them are holding a phone. In most places in the world today, the two numbers are surprisingly close. Only about twenty years ago that scene would have looked very strange. In 2007, when the first iPhone went on sale, most people's phones could make calls, send texts and maybe take a blurry photo. Going online meant sitting down at a computer. Today, for billions of people, the internet is simply something that lives in their pocket.","Let's look at the numbers, because they are enormous. The International Telecommunication Union, or ITU, is the United Nations agency that keeps track of the world's telephones and internet connections. It estimated that about 5.5 billion people were using the internet in 2024. That is about 68 out of every 100 people on Earth. The GSMA, an organization that represents mobile phone companies around the world, estimated that by the end of 2024 well over 4 billion people were using the internet on a mobile phone. That is well over half of humanity, and for a huge number of those people the phone is their main way online, or their only one.","Here is an even stranger fact: there are more mobile phone subscriptions in the world than there are people. By 2024 the number of subscriptions had passed 9 billion, while the world's population was a little over 8 billion. How can that be? A subscription is tied to a SIM card, not to a person. Many people carry two SIM cards, for example one for work and one for home, or one from each of two networks so they can choose the cheaper price. Some subscriptions do not belong to people at all. They live inside machines such as card-payment terminals, burglar alarms, smart meters, cars and delivery trackers that quietly talk to the network on their own.","So the number of subscriptions is not the same as the number of phone owners. The ITU measures ownership too. It found that about four out of every five people aged 10 and over own a mobile phone. In rich countries, ownership is above 95 percent, so almost everybody has one. In the world's lowest-income countries the figure is lower, about 56 percent, and women there are less likely than men to own a phone. These gaps matter, and we will come back to them.","The networks have spread too. According to the ITU, around 96 percent of the world's people live within reach of at least a 3G mobile signal, and about 92 percent are covered by 4G. Newer 5G networks covered about half of the world's people in 2024, mostly in cities and richer countries. In low-income countries only about half of people had 4G coverage and just 4 percent had 5G. Even so, the mobile phone has spread faster than almost any technology in history. The telephone took most of the 20th century to reach most homes in rich countries. The mobile phone reached most of the planet in about twenty-five years.","Still, it is important to remember the other side of the picture. About 2.6 billion people, roughly one person in three, were still offline in 2024. In Africa, about two-thirds of people own a mobile phone but only about 38 percent use the internet. Sometimes the reason is that there is no signal. More often, it is that phones and data plans cost too much, or that people have not had the chance to learn how to use them. Connecting the last third of humanity is one of the biggest challenges of the 21st century."]},{"heading":"Leapfrogging: Skipping Straight to Mobile","paragraphs":["Think about what it took to give a house a landline telephone in the 20th century. Workers had to dig trenches or put up poles, string copper wires along every street, connect each wire to a building called a telephone exchange, and then keep everything repaired when storms, floods or thieves damaged it. In big, crowded cities that was worth the cost. In a small farming village far from any town, it often was not. Across large parts of Africa, South Asia and Latin America, many villages never got landlines at all.","Mobile phones changed the math. Instead of running a wire to every single home, a company could put up one tower that covered a whole area, with a radio signal reaching many kilometers in open country. Phones themselves got cheaper every year, and prepaid plans meant you did not need a bank account or a monthly bill. You could buy a little bit of calling credit, often called airtime, from a shop or street stall whenever you had some money.","Experts call this leapfrogging. In the game of leapfrog, you jump right over another player. In technology, leapfrogging means jumping over an older stage of development entirely. Millions of people in Africa and Asia never owned a landline telephone or a desktop computer. Their first phone was a mobile phone, and later their first computer was a smartphone. India is a good example: a very large number of Indians first went online not with a laptop but with an inexpensive Android phone and a cheap data plan.","Before mobile phones, important news in some rural areas traveled on foot or by bus. In Mali, for example, people sometimes traveled from village to village just to tell relatives about a wedding, a birth or a death. With a phone, the same news can travel in seconds. Farmers can call ahead to find out the price of crops at different markets before deciding where to sell. Fishermen can find out which harbor is paying more for the day's catch. Phones also created brand-new small businesses: selling airtime, charging other people's phones for a small fee, and repairing broken handsets in roadside stalls.","The most famous leapfrogging story of all is about money. In Kenya in the early 2000s, many people did not have bank accounts. Banks were far away, and their fees were too high for people earning small amounts. Yet people often needed to send money to family members. A worker in the capital, Nairobi, might want to send part of his wages to his parents in a village hundreds of kilometers away. Usually that meant handing an envelope of cash to a bus driver or a friend and hoping it arrived safely.","The mobile network company Safaricom, working with the British company Vodafone, tested an idea in 2005 and launched it fully in March 2007. It was called M-Pesa. M stands for mobile, and pesa is the Swahili word for money. Here is how it works. You take cash to an M-Pesa agent, often a small shop that also sells airtime. The agent adds that amount to an electronic balance linked to your phone number. Then you can send money to anyone else with a phone by typing a short text-style message protected by a secret PIN. The person you sent it to goes to their own nearby agent and turns the balance back into cash. Best of all, it worked on simple, cheap phones, not just smartphones.","M-Pesa spread with astonishing speed. Within about five years, Kenya had around 17 million registered accounts, and the service later expanded to countries including Tanzania, Mozambique, the Democratic Republic of the Congo, Lesotho, Ghana, Egypt and Ethiopia. Today it serves tens of millions of people. People use it to pay school fees, electricity bills and shopkeepers, to save money and even to borrow small amounts.","Did it actually make life better? Economists Tavneet Suri and William Jack studied Kenyan households and published a famous paper in the journal Science in 2016. They estimated that access to M-Pesa had helped lift about 194,000 households, roughly 2 percent of Kenyan households, out of poverty, with especially large benefits for households led by women. Not every researcher agrees. A 2019 paper by other scholars argued the study had serious flaws. This is a good reminder that even exciting success stories need careful checking, and that scientists can disagree about how big an effect really is."]},{"heading":"A Day in a Pocket-Powered Life","paragraphs":["Imagine a single ordinary day for a family in almost any city in the world today, and count how many times a smartphone quietly does a job that used to need a completely different object.","The day starts with an alarm clock, which is the phone. Someone checks the weather forecast, which used to mean waiting for the radio or the newspaper. On the way to school or work, a bus app shows exactly when the next bus will arrive, using the bus's own GPS position. Older readers can remember when a family road trip meant unfolding a giant paper map across the car, arguing over which road to take, and stopping at gas stations to ask for directions. Now a navigation app speaks the directions out loud, warns about traffic jams ahead and recalculates the route when you miss a turn. Paper maps have not disappeared, but for most daily trips they have been replaced.","At lunchtime a grandmother in Canada makes a video call to her grandson in the Philippines. In the 1970s an international phone call was so expensive that many families made one only on special occasions, and they talked fast to save money. A video call across the world, with moving faces and voices, would have looked like science fiction. Today it costs almost nothing beyond the price of the data. For families separated by migration, work or study, this is one of the most precious changes smartphones have brought.","In the afternoon, a teenager listens to music. A generation ago, she would have bought cassette tapes or CDs, one album at a time. Today streaming apps send songs from distant computer servers, a little piece at a time, straight to her headphones. The same is true for films, television shows and podcasts. A huge share of the world's internet traffic is now video, and much of it is watched on phone screens.","The phone is also a classroom. A student can look up a word, watch a video explaining fractions, practice a new language with a learning app or read a free online encyclopedia. During the COVID-19 pandemic, which began in 2020, schools in many countries closed their buildings for weeks or months. Many students kept learning through laptops, tablets and phones. For families with no computer at home, a shared smartphone was sometimes the only link to the teacher. That period also showed the digital divide clearly: children without a device or a good connection fell further behind.","Then there is banking and shopping. Paying a bill once meant writing a check, buying a stamp and mailing an envelope, or standing in line at a bank. Now many people check their balance, send money to a friend and pay for groceries by tapping their phone on a card reader. Phones store train tickets, boarding passes and concert tickets. They are a flashlight, a calculator, a voice recorder, a dictionary, a translator that can read a restaurant menu written in another language, and a camera that has made billions of people into photographers."]},{"heading":"Work in the Age of Apps","paragraphs":["Smartphones did not just change how people relax. They changed how millions of people earn a living, and they invented jobs that did not exist before.","The most obvious new job is making apps. After Apple opened its App Store in 2008 and Google opened its Android store the same year, anyone with a computer and the right skills could build a program and sell it to the whole world. Some app makers became famous, but most work in ordinary teams at companies, designing screens, writing code, testing for bugs and answering customers' questions. There are also app-related jobs most people never think about: people who draw the icons and buttons, write the words that appear on the screen, translate apps into other languages, and check that apps are easy to use for people with poor eyesight or hearing.","A second group of new jobs is sometimes called the gig economy. A gig was originally a musician's word for a one-time performance. In the gig economy, people do short, separate jobs found through an app instead of working regular hours for one boss. When you tap a button to order a ride, an app finds a nearby driver, shows both of you a map, sets the price and handles the payment. Food delivery, grocery shopping, dog walking, cleaning and small home repairs all work in a similar way. None of this would be possible without phones that know their own location, can show maps and can take payments.","For many workers, gig apps offer something valuable: flexibility. A student can drive in the evenings, a parent can deliver meals while children are at school, and someone between jobs can earn money quickly. In India alone, a government study estimated about 7.7 million gig workers in 2020 and 2021, and predicted the number could reach about 23.5 million by 2030.","But the gig economy has also caused big arguments. Most app companies treat their drivers and couriers as independent contractors, which means they are like tiny one-person businesses rather than employees. That usually means no guaranteed minimum wage for all their working time, no paid sick days and no company pension. Workers in many countries have gone to court to argue that they deserve more protection. In February 2021, the Supreme Court of the United Kingdom ruled that a group of Uber drivers should be treated as workers entitled to rights such as the minimum wage and holiday pay. In California, by contrast, voters approved a measure called Proposition 22 in 2020, backed by the app companies, which kept drivers as contractors but promised them some extra benefits, such as earnings of at least 120 percent of the local minimum wage for time spent on trips. Governments are still arguing about the best rules.","Smartphones have changed office work too. Before mobile email, most people left their work behind when they left the building. With BlackBerrys in the 2000s and smartphones after them, messages from the boss could arrive at dinner, on weekends or on holiday. Many people like being able to work from anywhere. Others feel they can never fully switch off. Some countries have responded with rules. France, for example, introduced a so-called right to disconnect in 2017, which requires larger companies to negotiate with their staff about limits on after-hours emails and messages."]},{"heading":"Everyone Can Be a Reporter","paragraphs":["For most of history, if something important happened, ordinary people learned about it from professional reporters, often hours or days later. Newspapers, radio and television decided which stories to tell. Smartphones changed that, because they put a camera, a video recorder and a way to publish instantly into billions of hands. When ordinary people record and share news themselves, it is called citizen journalism.","Some early examples came even before smartphones. On September 11, 2001, many of the images and eyewitness accounts from near the World Trade Center in New York came from ordinary people. When the huge Indian Ocean tsunami struck in December 2004, video filmed by tourists and local residents on cameras was shown on television around the world, and bloggers shared news in real time while professional reporters were still trying to reach the area.","Smartphones made this far faster. On January 15, 2009, a passenger jet, US Airways Flight 1549, lost power in both engines after hitting a flock of birds and landed on the Hudson River in New York. All 155 people on board survived. A passenger on one of the ferries that rushed to help, Janis Krums, snapped a photo with his iPhone of people standing on the floating plane's wings and posted it on Twitter. His picture spread across the internet before most television crews had arrived. Many people point to that moment as a sign that news had changed forever.","Phones became especially important in places where governments tried to control the news. After a disputed election in Iran in 2009, foreign journalists were largely blocked from reporting, and people used social media to share what they saw. During the Arab Spring protests that spread across North Africa and the Middle East starting in late 2010, protesters filmed events on phones and uploaded them to sites like YouTube, where the whole world could watch. In the United States in 2020, a teenager named Darnella Frazier used her phone to record the arrest in Minneapolis during which a police officer killed George Floyd. Her video led to protests around the world and to a trial, and in 2021 she received a special citation from the Pulitzer Prize board, one of journalism's highest honors.","Phones help in disasters and emergencies too. After Kenya's disputed election in late 2007 led to violence, a group of Kenyan technologists including Ory Okolloh, Erik Hersman, Juliana Rotich and David Kobia built a website in just a few days that collected eyewitness reports sent by text message and email and plotted them on a map. They called it Ushahidi, which means testimony or witness in Swahili. After the devastating earthquake in Haiti in January 2010, a team using Ushahidi's tools collected nearly 40,000 reports and mapped about 4,000 separate events, helping rescuers see where help was needed.","Governments also use phones to warn people. In the United States, a system called Wireless Emergency Alerts went live in 2012. It uses a trick called cell broadcast: instead of sending a separate text to each phone, a tower sends one message to every compatible phone in its area at the same moment. That is why a tornado warning or a missing-child alert can make every phone in a room buzz at once, even when the ringer is switched off. Many other countries have similar systems, such as EU-Alert in Europe and J-Alert in Japan.","But there is a catch. When anyone can publish anything, false information can spread just as fast as the truth. Photos can be old, taken somewhere else, or edited. Rumors can race through group chats in minutes. Being a smart news reader in the smartphone age means asking good questions: Who made this? Where and when was it taken? Do trustworthy news organizations confirm it?"]},{"heading":"Smiley Faces, Selfies and Group Chats","paragraphs":["Smartphones did not only change what news we share. They changed the way humans talk to each other, and even added new words to the dictionary.","Start with emoji. As you read in Part 6, the Japanese phone company J-Phone offered a small set of picture characters in 1997, and in 1999 designer Shigetaka Kurita created a famous set of 176 emoji for NTT Docomo's i-mode service. For years, these little pictures were mostly a Japanese thing, and they often did not work between different phone companies. The breakthrough came in October 2010, when Unicode, the international standard that tells computers how to store letters and symbols, included a standard set of 722 emoji. Because of Unicode, a heart sent from one brand of phone would show up as a heart on another. Apple added an emoji keyboard for iPhone users in Japan in 2008 and made it available worldwide in 2011. After that, emoji exploded. In 2015, Oxford Dictionaries chose an emoji, the Face with Tears of Joy, as its Word of the Year. The following year, the Museum of Modern Art in New York added Kurita's original 1999 emoji to its collection. By the mid-2020s Unicode included close to 4,000 emoji, from flags and foods to people with many different skin tones.","Why did emoji become so popular? When we talk face to face, our expressions and tone of voice tell listeners whether we are joking, happy or annoyed. Short text messages lose all of that. A tiny smiling face or a thumbs-up puts some of the missing emotion back.","Next come selfies. People have made self-portraits for centuries, from painters at their easels to the American photography pioneer Robert Cornelius, who in 1839 made one of the earliest photographs of a person by pointing his camera at himself. Because cameras then were so slow, he had to uncover the lens, run into position and keep still for a minute or more. Taking a self-portrait with a normal camera remained awkward for a long time, because you could not see yourself while you aimed.","The phone fixed that with the front-facing camera. In 1999, the Kyocera VP-210 in Japan became the first camera phone with a camera facing the user, mainly for video calls. The Sony Ericsson Z1010 brought a front camera to Western shoppers in late 2003, and the iPhone 4 in 2010 helped make the selfie a worldwide habit. The word itself first appeared in writing in 2002, on an Australian internet science forum. In November 2013, Oxford Dictionaries named selfie its Word of the Year. A few months later, at the Academy Awards in March 2014, the television host Ellen DeGeneres squeezed into a selfie with a crowd of famous film stars. When she posted it on Twitter, it broke the record for the most retweets, passing 2.8 million within a day.","Group chats are another smartphone invention that changed daily life. Messaging apps made it free to send messages, photos and voice notes to whole groups of people at once: a family spread across three countries, a football team, a class project or a group of friends planning a weekend. For many people, the group chat has become a sort of digital living room, where news, jokes and plans are shared all day long.","Then there is social media: apps where people post photos, videos and updates for friends or for the whole world to see. Smartphones turned social media from something you checked on a computer once a day into something people carry everywhere. That made it possible for a teenager with a phone to start a popular cooking channel, for a scientist to explain discoveries to millions, and for people with rare illnesses to find others like them. But it also brought pressures, such as comparing yourself with others' carefully chosen photos, which Part 18 will look at honestly."]},{"heading":"The Most Powerful Tool Ever Shared","paragraphs":["Step back and look at the whole picture. In less than twenty years, the smartphone has become the most widely shared powerful tool in human history. A farmer in Kenya, a nurse in Brazil, a student in India and a retired engineer in Sweden may all carry versions of the same invention. It connects families across oceans, lets people without bank accounts send money safely, gives eyewitnesses a way to show the world what is happening, warns people about storms and puts much of the world's knowledge a few taps away.","It also reshaped the economy. Whole industries, such as app making, ride-hailing and mobile payments, grew up around it, while older businesses, from paper map makers to camera film companies and music shops, had to change or shrink. The way we talk changed too, with new words like selfie and new ways of showing feelings like emoji.","But here is a fair warning. Something this powerful does not only bring good things. The same phone that connects you to your grandmother can keep you up past midnight. The same camera that records important news can be used to embarrass someone. The same apps that make life easier collect huge amounts of information about where we go and what we do. And the materials inside every phone come from mines and factories, and old phones end up as waste. In Part 18, we will look at these problems honestly, and at what scientists, governments and ordinary people are doing about them."]}],"deepDive":"Measuring how many people use phones is trickier than it sounds. The simplest number, mobile subscriptions, passed 9 billion in 2024, more than the world's population. But subscriptions count SIM cards, not humans: one person may carry two SIMs, and millions of SIMs sit inside payment terminals, alarms and cars. That is why organizations such as the ITU also run household surveys asking who actually owns a phone and who has used the internet recently. By those measures about four in five people aged 10 and over own a mobile phone, and about 5.5 billion people (around 68 percent) used the internet in 2024. Researchers then split the remaining gap into two parts. The coverage gap is people who live where no mobile broadband signal reaches; it is now small, because about 92 percent of people are covered by 4G. The much bigger usage gap is people who live under a signal but still do not go online, usually because handsets and data are too expensive relative to income, because they lack reading or digital skills, or because they do not see content in their own language. Women in low-income countries are noticeably less likely to own a phone than men, which economists call the mobile gender gap. Studying whether phones actually improve lives is harder still. The best-known study, by Tavneet Suri and William Jack (Science, 2016), compared Kenyan households according to how close they lived to M-Pesa agents as the network spread, and estimated that mobile money lifted about 2 percent of households out of poverty, partly by helping women move from farming into business. Critics argued in 2019 that the method could not fully separate M-Pesa's effect from other changes happening in Kenya at the same time, and that it may overstate the benefits. This is a classic problem in economics: when a technology spreads everywhere at once, there is no perfect comparison group. Researchers try to solve it using natural experiments, such as the uneven roll-out of towers or agents, and by checking whether results hold up in other countries. The broad picture most economists accept is that mobile phones and mobile money bring real benefits, especially for sending money and sharing information, but the exact size of those benefits is still debated.","funFact":"When Ellen DeGeneres posted her crowded celebrity selfie from the 2014 Academy Awards, it became the most retweeted post ever at the time, passing 2.8 million retweets within about a day.","check":{"q":"What did the Kenyan service M-Pesa, launched in 2007, let people do with their mobile phones?","a":"Send and receive money using their phone, even on basic phones without a bank account","wrong":["Watch live television on their phones","Make the first video calls in Africa","Charge their phones using solar power from the network"]},"sources":[{"title":"Measuring digital development: Facts and Figures 2024 – Internet use","publisher":"International Telecommunication Union (ITU)","url":"https://www.itu.int/itu-d/reports/statistics/2024/11/10/ff24-internet-use/"},{"title":"Facts and Figures 2024 – Mobile phone ownership","publisher":"International Telecommunication Union (ITU)","url":"https://www.itu.int/itu-d/reports/statistics/2024/11/10/ff24-mobile-phone-ownership/"},{"title":"Facts and Figures 2024 – Mobile network coverage","publisher":"International Telecommunication Union (ITU)","url":"https://www.itu.int/itu-d/reports/statistics/2024/11/10/ff24-mobile-network-coverage/"},{"title":"M-Pesa","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/M-Pesa"},{"title":"Mobile phone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mobile_phone"},{"title":"Selfie","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Selfie"},{"title":"Citizen journalism","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Citizen_journalism"},{"title":"Ushahidi","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ushahidi"}],"photos":[{"src":"img/deep/smartphone/17-1.jpg","alt":"A customer at an M-Pesa mobile money and bank agent shop in Nairobi, Kenya.","file":"M-PESA mobile money and Equity agent, Nairobi, Kenya.jpg","url":"https://commons.wikimedia.org/wiki/File:M-PESA_mobile_money_and_Equity_agent,_Nairobi,_Kenya.jpg","author":"Fiona Graham","license":"CC BY-SA 2.0"},{"src":"img/deep/smartphone/17-2.jpg","alt":"Robert Cornelius's 1839 daguerreotype of himself, often called the first selfie ever taken.","file":"RobertCornelius.jpg","url":"https://commons.wikimedia.org/wiki/File:RobertCornelius.jpg","author":"Robert Cornelius","license":"Public domain"},{"src":"img/deep/smartphone/17-3.jpg","alt":"Passengers stand on the wings and rafts of US Airways Flight 1549 after it landed on the Hudson River in 2009.","file":"US Airways Flight 1549 (N106US) after crashing into the Hudson River (crop 1).jpg","url":"https://commons.wikimedia.org/wiki/File:US_Airways_Flight_1549_(N106US)_after_crashing_into_the_Hudson_River_(crop_1).jpg","author":"Greg L","license":"CC BY 2.0"}],"words":4337},{"n":18,"title":"The Dark Side: Problems and Controversies","when":"2007 – today","summary":"Smartphones are amazing, but they also cause real problems. Some apps are designed to keep us scrolling, phones can distract drivers and walkers, and scammers try to trick us. Inside every phone are metals dug from mines far away, and old phones pile up as waste. But people are working hard on fixes, from phone-free classrooms to phones you can repair yourself!","sections":[{"heading":"Built to Keep You Scrolling","paragraphs":["Have you ever picked up a phone to check one quick thing, and then looked up to discover that half an hour had vanished? If so, you are not alone, and it is not simply because you lack willpower. Many of the most popular apps are carefully designed to hold on to your attention for as long as possible.","To understand why, follow the money. Most social media apps, video sites and many games are free to download. The companies that make them still need to earn billions of dollars to pay their engineers, run their giant data centers and make a profit. A large part of that money comes from advertising. Advertisers pay to show their ads to people, so the more time people spend in an app, the more ads they see, and the more the company earns. Your attention, in other words, is the product being sold. People who study this call it the attention economy.","App designers have discovered many tricks that make it hard to stop. One is the endless feed, often called infinite scroll. On an old-fashioned website, you reached the bottom of a page and had to decide whether to click to the next one. That little pause was a natural stopping point. An endless feed removes the bottom of the page completely: new posts keep appearing as you swipe, so there is never a moment that says you are done. Video apps do something similar with autoplay, starting the next video automatically before you have decided whether you even want it.","Another trick is the unpredictable reward. Psychologists discovered decades ago, in experiments with animals, that a reward that arrives only sometimes, at random, keeps an animal pressing a lever more eagerly than a reward that comes every time. Slot machines in casinos work on the same principle. Pulling down a feed to refresh it is a bit like pulling the lever: sometimes you get an exciting new message or a funny video, sometimes nothing much. Because you never know, you keep checking.","Then there are notifications, the buzzes, banners and red dots that pull you back into apps throughout the day. Likes and hearts give a quick feeling of approval from friends. Streaks, which reward you for using an app every single day, make people worry about breaking the chain. None of these features is evil on its own, and some are genuinely useful. Together, though, they can make it very hard to put a phone down.","Sleep is one of the first things to suffer. Many young people keep phones in their bedrooms and use them late at night. Messages and games keep the brain excited when it should be winding down, and notifications can wake people up during the night. Bright screens close to the eyes may also make it a little harder to feel sleepy, although scientists think the excitement of what is on the screen probably matters more than the light itself. Sleep experts commonly recommend putting screens away an hour or so before bed and charging phones outside the bedroom.","The good news is that phones now include tools to fight back. Most have screen-time reports that show how many hours you spend in each app, timers that lock an app after a daily limit, do-not-disturb and bedtime modes that silence notifications, and settings that turn off autoplay. Some people even switch their screens to grayscale, removing the bright colors that make apps look so tempting. A little planning can make the phone work for you, instead of the other way around."]},{"heading":"What Do Scientists Really Know?","paragraphs":["Here is one of the biggest debates in science today: are smartphones and social media harming young people's mental health? It is a question that worries parents, teachers, doctors and governments, and the honest answer is that scientists do not yet fully agree.","Some facts are not in dispute. In the United States, Britain and several other countries, surveys show that rates of anxiety and depression among teenagers, especially girls, rose noticeably during the 2010s. That is the same decade in which smartphones and social media became an everyday part of teenage life. Psychologist Jean Twenge was one of the first researchers to point out this timing. In 2024, social psychologist Jonathan Haidt published a best-selling book called The Anxious Generation. He argued that a phone-based childhood, combined with less free play and independence in the real world, has caused a large rise in mental illness among young people. He pointed to four main harms: less time with friends in person, lost sleep, broken-up attention and something like addiction. He recommended phone-free schools, waiting longer before giving children smartphones and social media accounts, and giving children more independence.","Many scientists agree with parts of this, but others say the evidence is weaker than the book suggests. Psychologist Candice Odgers, writing in the science journal Nature, argued that most studies do not find a large, consistent harmful effect. Researchers such as Amy Orben and Andrew Przybylski have found that, on average, the links between screen time and well-being in big data sets are real but small. One key problem is that most studies show a correlation, which means two things happen together, rather than proving that one causes the other. If teenagers who feel lonely or depressed tend to spend more time on their phones, is the phone causing the sadness, or is the sadness causing the phone use? It could be both, or something else could be affecting both.","Scientists also point out that phones affect different people differently. For some teenagers, online friends and support groups are a lifeline, especially if they feel alone at school. For others, comparing themselves with filtered, perfect-looking photos, or getting caught up in online arguments, makes them feel much worse. What you do on a phone, and what it replaces, such as sleep, exercise or time with friends, may matter more than the total number of hours.","In 2023 the Surgeon General of the United States, the country's top public health doctor, issued an official advisory saying that there was not yet enough evidence to say social media is safe for young people, and calling for more research and stronger protections. Several countries have since begun limiting social media for younger children. So while scientists continue to argue about how big the effect is, there is wide agreement on some sensible steps: protect sleep, keep up real-world friendships and activities, and notice how different apps make you feel.","Another worry you may have heard is about phone radiation. Phones talk to towers using radio waves, a type of energy much weaker than X-rays, and very different from the kind of radiation that comes from radioactive materials. In May 2011, a group of 31 scientists from 14 countries met in Lyon, France, for the International Agency for Research on Cancer, part of the World Health Organization. They classified radio-frequency fields as possibly carcinogenic to humans, which is called Group 2B. That sounds scary, but it is important to understand what it means. Group 2B is used when the evidence is limited, meaning a link has been seen in some studies but chance, errors or other causes cannot be ruled out. The same group includes things like aloe vera extract and traditional Asian pickled vegetables. The chairman of the working group explained that the decision meant there could be some risk, so scientists needed to keep watching. Since then, large studies have not shown that phones cause cancer, and in 2024 the US National Cancer Institute said the evidence so far suggests that phone use does not cause brain or other cancers. Scientists keep studying it, but phone radiation has not been proven to cause cancer."]},{"heading":"Eyes Up! Staying Safe on the Road and Online","paragraphs":["Some smartphone dangers are much more immediate. One of the clearest is using a phone while driving. Scientists at the Virginia Tech Transportation Institute fitted cameras and sensors in real trucks and watched how drivers behaved. When drivers were texting, they took their eyes off the road for about 4.6 seconds out of every 6 around dangerous moments. At 55 miles per hour, about 90 kilometers per hour, that is like driving the full length of a football field without looking. In the study, truck drivers who were texting were more than 23 times as likely to have a crash or near-crash.","The US National Highway Traffic Safety Administration counted 3,308 people killed in crashes involving distracted drivers in 2022, and phones are one of the major distractions. Because of numbers like these, almost every US state, and many countries around the world, have made texting while driving illegal. Many phones now include a driving mode that holds messages until the car stops. If you are a passenger, you can help by offering to read or answer messages for the driver.","Walkers can get into trouble too. People staring at their screens have stepped into traffic, tripped on curbs and walked into poles, fountains and other people. Researchers at the University at Buffalo even suggested that, counting all the little accidents, texting while walking may cause more injuries than texting while driving. Some cities have painted warning signs on sidewalks and added lights at crossings to catch the eye of people looking down. The rule is simple: when you are crossing a street, look up and listen.","Phones can also bring danger to our feelings. Bullying is very old, but cyberbullying, which means bullying through phones, messages, games and social media, has some new and painful features. In the past, a child who was picked on at school could at least escape at home. Now hurtful messages can arrive at any hour. Bullies can hide behind fake accounts, and a cruel post or an embarrassing photo can be shared with hundreds of people in minutes and stay online for a long time.","If it ever happens to you or a friend, experts give clear advice. Do not reply angrily, since that can make things worse. Save the evidence with screenshots. Block the person and report them using the app's reporting tools. Most importantly, tell a trusted adult such as a parent or teacher. Many young people stay silent because they are afraid their phone will be taken away, but adults can help, and nobody deserves to be bullied.","There is one more online danger young people should know about: strangers who pretend to be someone they are not. A person who says they are another 12-year-old gamer might actually be an adult. Safety experts suggest never sharing your full name, address, school or photos with people you have only met online, never agreeing to meet them in person without a parent, and telling an adult right away if anyone makes you feel uncomfortable or asks you to keep secrets. Being careful online is not about being scared. It is about being smart, just as you look both ways before crossing a road."]},{"heading":"Who Is Watching? Privacy, Scams and Passwords","paragraphs":["Your phone knows a lot about you. It knows where you are, thanks to GPS, Wi-Fi and nearby cell towers. It knows who you talk to, what you search for, which videos you watch and how long you watch them. It may know your face, your fingerprint, your steps and your heartbeat. All of that information is called data, and data is extremely valuable.","Many apps ask for permission to use your location, camera, microphone or contacts. Sometimes that makes sense: a map app needs your location, and a video-call app needs the camera. But some apps ask for far more than they need. In the past, a simple flashlight or game app might quietly collect location data and pass it on to advertising companies. Some firms, called data brokers, buy and combine information from many sources to build detailed profiles of people, which can then be used to target ads. Investigations by journalists have shown that location data that was supposedly anonymous could sometimes be traced back to individual people, revealing where they live and work.","Governments and phone makers have started to respond. Europe's data protection law, known as the GDPR, which took effect in 2018, requires companies to explain what data they collect and gives people rights to see and delete it. In 2021, Apple began requiring apps to ask permission before tracking iPhone users across other companies' apps and websites, and Android has added its own privacy controls. A good habit is to check which apps have permission to use your location and camera, and to switch off anything that does not need it.","Phones are also a favorite target for scammers. You may have seen text messages claiming that a package could not be delivered, that your bank account has been locked or that you have won a prize. These usually contain a link to a fake website designed to steal passwords or payment details. Tricks like this are called phishing, because the scammer is fishing for information, and when they arrive by text message they are sometimes called smishing. Other scammers pretend to be a family member in trouble who urgently needs money, or a company's support team asking you to install an app that lets them control your phone.","The best defenses are simple. Do not tap links in unexpected messages; instead, open the real app or type the website's address yourself. Be suspicious of anyone who rushes you or asks you to keep a secret. Use a different, long password for every important account, which is much easier with a password manager, and turn on two-step verification, so that even if someone steals your password they also need a code from your phone. Newer technology called passkeys lets you sign in with your fingerprint or face instead of a password at all. Finally, install software updates. Updates often fix security holes that criminals have discovered, so an out-of-date phone is like a house with an unlocked window."]},{"heading":"Phones Away! The Great School Debate","paragraphs":["Picture a classroom where every student has a pocket computer that can play games, stream videos and chat with friends. Now try to teach that class long division. That is the challenge many teachers have described, and it has led to one of the biggest education debates of the smartphone age: should phones be allowed in school?","France was one of the first countries to answer with a nationwide law. In 2018 the French parliament passed a law banning students from using mobile phones in primary schools and middle schools, which in France covers children aged roughly 3 to 15. Students could still bring their phones, but had to keep them switched off and put away during the school day, with exceptions for teaching activities and for students with disabilities. France later went further, trying out a 'digital pause' from 2024 in which middle school students hand their phones in when they arrive, with plans to extend it to all middle schools.","Many others have followed. In China, the education ministry announced in 2021 that students should not bring phones into classrooms without written permission from their parents. In Australia, the state of Victoria introduced a ban on phones during the school day in its government schools in 2020, and other states followed. The Netherlands began keeping phones out of secondary school classrooms in January 2024. In the United States, Florida passed a law in 2023 banning phone use during class time, and many more states have since adopted their own rules. In 2023, UNESCO, the United Nations' education agency, published a major report warning that technology should only be used in classrooms when it clearly helps learning, and it encouraged countries to think carefully about phones in schools.","Supporters of bans say phones distract students even when they are not being used, because a buzz or the temptation to check messages pulls attention away from the lesson. Some studies, including a well-known one from the London School of Economics that looked at schools in English cities, found that test scores improved after schools banned phones, especially for students who had been struggling. Supporters also hope bans reduce cyberbullying during the school day and get children talking and playing together at break time.","Not everyone agrees. Some parents want their children to have phones in case of emergencies, or to arrange how they will get home. Some teachers use phones as learning tools for research, quizzes or photographing science experiments. And researchers point out that the evidence that bans improve mental health is still mixed, partly because schools that introduce bans often change other things at the same time. Many schools have chosen a middle path, such as phones locked in pouches or lockers during lessons but allowed before and after school. Scientists are watching carefully to see which approaches work best."]},{"heading":"The Hidden Cost: Mines and Mountains of Waste","paragraphs":["A smartphone looks clean and simple, but it contains a remarkable collection of materials dug out of the Earth from all over the world. There is copper in its wiring, gold, silver and palladium in its circuits, tin in the solder that holds parts together, tantalum in tiny electronic components, rare earth elements in its speakers and vibration motor, glass and aluminum in its body, and lithium and cobalt in its battery. Researchers at the University of Plymouth in England estimated that about 10 to 15 kilograms of rock and ore must be mined to make the materials for a single phone.","Cobalt shows how complicated this can be. Many lithium-ion batteries use cobalt in their positive electrode, and batteries are now the biggest use of the metal worldwide. According to the United States Geological Survey, about 230,000 tonnes of cobalt were mined in the world in 2023, and about 170,000 tonnes of that, roughly 74 percent, came from one country: the Democratic Republic of the Congo, often shortened to the DRC, in central Africa. Much of the rest came from Indonesia, Russia and Australia, and most of the world's cobalt is then refined in China.","Most of the DRC's cobalt comes from large industrial mines. But a significant share is dug by so-called artisanal miners: men, women and sometimes children who work with hand tools, shovels and sacks, often in dangerous, unsupported tunnels and without protective equipment. Breathing cobalt dust can damage the lungs, and tunnel collapses have killed miners. In 2016, the human rights group Amnesty International published a report describing children working at artisanal cobalt mines and accused major electronics and car companies of not doing enough to check where their cobalt came from. Since then, many companies have promised to trace their supply chains more carefully, and Apple, for example, has said it is moving toward using recycled cobalt in its batteries. Progress is real but incomplete, and human rights groups continue to report problems.","Then there is what happens at the other end of a phone's life. Electronic waste, or e-waste, means any thrown-away item with a plug or battery, from phones and laptops to toasters and televisions. According to the United Nations Global E-waste Monitor published in 2024, the world produced about 62 million tonnes of e-waste in 2022, an increase of 82 percent since 2010. Only about 22 percent of it was properly collected and recycled. The rest was thrown into landfills, stored in drawers or handled informally. If nothing changes, the report predicts about 82 million tonnes a year by 2030.","That waste is a double problem. First, some of it is dangerous. In some places, people recover metals from old electronics by burning cables in open fires or soaking circuit boards in acid, which releases toxic smoke and chemicals that harm workers, children and nearby communities. Places such as the town of Guiyu in southern China became known for this kind of informal recycling. Second, throwing electronics away wastes valuable materials. The Global E-waste Monitor estimated that the metals in 2022's uncollected e-waste were worth about 62 billion US dollars. A tonne of old phones can contain a few hundred grams of gold, far more than a tonne of typical gold ore. Yet recycling currently supplies only about 1 percent of the world's demand for rare earth elements."]},{"heading":"Fix It, Don't Toss It","paragraphs":["One of the simplest ways to make phones kinder to the planet is to keep each one working for longer. Every extra year a phone is used means one less new phone needs to be mined, manufactured and shipped. But for many years, phones were not designed to be fixed.","Older mobile phones usually had a battery you could pop out with your thumbnail and replace in seconds. As smartphones became thinner and more waterproof, batteries were sealed inside and glued down. Screens were bonded to the frame, and special screws required unusual tools. Some companies began using a practice called parts pairing, in which a phone checks the serial number of a replacement part and may show warnings or turn off features if the part was not approved by the manufacturer. In 2017, iPhone owners discovered that a software update was slowing down some older phones with worn batteries. Apple said this was to stop them from shutting down unexpectedly, apologized for not explaining it clearly and offered cheaper battery replacements.","These frustrations helped grow the right-to-repair movement, which argues that people who buy a product should be able to fix it themselves or take it to any repair shop they choose, with fair access to spare parts, tools and repair manuals. Lawmakers began to listen. New York passed a Digital Fair Repair Act in December 2022, and other US states have passed similar laws. In 2021, Apple announced a self-service repair program that sells genuine parts and tools to customers. The European Union adopted a Right to Repair Directive in 2024 that requires manufacturers to offer repairs at reasonable prices and forbids tricks designed to block repair.","Europe also set new design rules for phones. Since 20 June 2025, smartphones and tablets sold in the European Union must have spare parts available for seven years after a model stops being sold, must receive operating system updates for at least five years, and must have batteries that keep at least 80 percent of their original capacity after 800 full charge cycles. They must also survive drops and resist dust and water, and each model carries a label with a repairability score from A, the easiest to repair, to E, the hardest. A separate EU batteries law, adopted in 2023, will require most portable batteries in devices to be removable and replaceable by ordinary users from 2027, with some exceptions.","Some companies have built their whole business around these ideas. Fairphone, a social enterprise founded in Amsterdam in 2013, designs modular phones that owners can open with a simple screwdriver to replace the battery, screen or camera. It tries to use recycled and fairly mined materials, such as Fairtrade gold, and the repair website iFixit has given most of its phones a perfect 10 out of 10 repairability score.","So what can you do? Use a protective case and screen protector. Keep your phone's software updated. Get a cracked screen or tired battery replaced instead of buying a whole new phone. When a phone really has reached the end of its life, do not throw it in the trash or forget it in a drawer: take it to a proper electronics recycling point or a store take-back program, or pass it on to someone who can use it.","The problems in this part are serious, but they are not hopeless. Scientists are studying how phones affect our minds and bodies more carefully than ever. Designers are adding tools that help us control our screen time. Governments are writing rules about privacy, schools and repair, and engineers are building phones that last longer, use less cobalt and can be fixed with a screwdriver. In Part 19, we will look at what those engineers are dreaming up next."]}],"deepDive":"Two of the loudest smartphone debates, about mental health and about radiation, are really debates about evidence, so it helps to know how scientists weigh it. Most research on screens and well-being is correlational: researchers survey thousands of young people about their phone use and their mood, then look for patterns. Large analyses of such data sets, such as those by Amy Orben and Andrew Przybylski, have generally found that heavier digital technology use is linked to slightly lower well-being, but that the average link is small, and it shrinks or grows depending on which questions researchers choose to analyze. Correlation leaves the direction of cause unclear: unhappy teenagers may retreat into their phones. To get closer to cause and effect, scientists use experiments, such as asking volunteers to cut back on social media for a few weeks, and natural experiments, such as comparing places where fast internet arrived earlier or later. Some of these find modest benefits from cutting back; others find little change. Supporters of stronger action, such as Jonathan Haidt, argue that the timing of the teen mental health decline around the early 2010s, its appearance in several countries at once, and the experimental results together justify acting now rather than waiting for perfect proof. Critics such as Candice Odgers reply that the evidence is not strong enough and that focusing on phones might distract from other causes. Radiation is a different kind of debate. The International Agency for Research on Cancer classifies hazards, meaning whether something could cause cancer under some circumstances, not risks, meaning how likely harm is at everyday levels. Its 2011 Group 2B label for radio-frequency fields meant the evidence was limited: some studies of heavy users had seen associations with a brain tumor called glioma, but chance and bias could not be excluded. There is also a physics argument: radio waves do not carry enough energy per photon to break chemical bonds in DNA, unlike X-rays or ultraviolet light, and their main known biological effect is slight heating. Since 2011, brain cancer rates in many countries have not risen in the way they would be expected to if phones were a major cause, even though phone use exploded. That is why health agencies say phones have not been shown to cause cancer, while still supporting further research.","funFact":"A tonne of old mobile phones can contain a few hundred grams of gold, which is much richer than a tonne of typical gold ore dug from a mine.","check":{"q":"According to the US Geological Survey, roughly what share of the world's mined cobalt came from the Democratic Republic of the Congo in 2023?","a":"About 74 percent, nearly three-quarters","wrong":["About 5 percent","About 25 percent","All of it, 100 percent"]},"sources":[{"title":"The Global E-waste Monitor 2024","publisher":"UNITAR / ITU Global E-waste Monitor","url":"https://ewastemonitor.info/the-global-e-waste-monitor-2024/"},{"title":"Mineral Commodity Summaries 2024: Cobalt","publisher":"U.S. Geological Survey","url":"https://pubs.usgs.gov/periodicals/mcs2024/mcs2024-cobalt.pdf"},{"title":"IARC classifies radiofrequency electromagnetic fields as possibly carcinogenic to humans (Press Release No. 208)","publisher":"International Agency for Research on Cancer (WHO)","url":"https://www.iarc.who.int/wp-content/uploads/2018/07/pr208_E.pdf"},{"title":"Smartphones and tablets: energy labelling and ecodesign","publisher":"European Commission","url":"https://energy-efficient-products.ec.europa.eu/product-list/smartphones-and-tablets_en"},{"title":"Mobile phone use in schools","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mobile_phone_use_in_schools"},{"title":"The Anxious Generation","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/The_Anxious_Generation"},{"title":"Texting while driving","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Texting_while_driving"},{"title":"Right to repair","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Right_to_repair"}],"photos":[{"src":"img/deep/smartphone/18-1.jpg","alt":"Two artisanal cobalt miners carry heavy sacks of rock at an open-pit mine in the DR Congo.","file":"Artisanal cobalt miners in the Democratic Republic of Congo.jpg","url":"https://commons.wikimedia.org/wiki/File:Artisanal_cobalt_miners_in_the_Democratic_Republic_of_Congo.jpg","author":"The International Institute for Environment and Development","license":"CC BY 2.5"},{"src":"img/deep/smartphone/18-2.jpg","alt":"A bin of broken old mobile phones, cases, circuit boards and cables waiting to be recycled.","file":"Handy schrott mobile phone scrap.jpg","url":"https://commons.wikimedia.org/wiki/File:Handy_schrott_mobile_phone_scrap.jpg","author":"MikroLogika","license":"CC BY-SA 3.0"},{"src":"img/deep/smartphone/18-3.jpg","alt":"A Fairphone 3 taken apart into its swappable modules: battery, camera, display, top and bottom parts.","file":"Fairphone 3 modules on display.jpg","url":"https://commons.wikimedia.org/wiki/File:Fairphone_3_modules_on_display.jpg","author":"PKFP","license":"CC BY-SA 4.0"}],"words":4354},{"n":19,"title":"Phones of Today and Tomorrow","when":"2018 – future","summary":"Today some phones fold in half like a book, and some can send a text to a satellite when you are lost in the wilderness! Phones are also getting little brains for artificial intelligence. In this part we look at the newest phones and make some careful guesses about what might come next.","sections":[{"heading":"A Phone That Bends Like Paper","paragraphs":["For about ten years after the iPhone arrived, almost every smartphone looked the same: a flat glass rectangle with rounded corners. Phone makers made the screens a little bigger each year, shaved off a millimeter here and there, and added more cameras on the back. But there was a problem they could not get around. People wanted bigger screens for watching videos, reading and playing games, yet a phone still had to fit in a pocket. A bigger rectangle is simply a bigger rectangle. So engineers asked a strange question: what if the screen could fold?","The idea was not new. Back in 2008, Nokia showed a concept called the Morph, a dreamy bendable phone that could wrap around your wrist. It was only a vision of the future, not something you could buy. In 2013 Samsung showed off flexible screen prototypes it nicknamed 'Youm'. Other companies tried a sneakier trick: they glued two separate screens side by side with a hinge in the middle, like the Kyocera Echo in 2011 and the ZTE Axon M in 2017. Those phones folded, but there was always a thick black gap down the middle of the picture.","What made a true folding phone possible was the OLED screen, which you met in Part 10. Remember that in an OLED display each tiny pixel makes its own light. That means you do not need a stiff backlight panel behind it. If the light-making layers are printed onto thin, bendy plastic instead of glass, the whole screen can flex. Engineers had been making flexible OLED panels for curved phone edges and smartwatches for a few years. The next step was to bend one all the way over without breaking it.","The first company to actually sell a phone like this was a young Chinese company called Royole, started in 2012 by graduates of Stanford University in California. In late 2018 Royole revealed the FlexPai, a device with a screen of about 7.8 inches that could be used flat like a small tablet or folded outward so the screen wrapped around both sides like a phone. It went on sale in China around the end of 2018, which is why it is usually credited as the world's first commercially available foldable smartphone with a flexible screen.","Reviewers were amazed that it existed at all, but they were not so kind about how it worked. The FlexPai was thick when folded, the software was clumsy, and the bendy screen had a slightly wavy, plasticky look. In other words, it was a lot like the DynaTAC brick in Part 2: a proof that something could be done rather than a polished product most people would want. Royole later ran into serious money troubles, and by 2024 the company was reported to have gone bankrupt. Being first, as we keep discovering in this story, is no guarantee of success."]},{"heading":"Samsung's Rocky Unfolding","paragraphs":["Samsung, one of the biggest phone makers on Earth, had been working on bendable screens for years. On February 20, 2019, at an event in San Francisco, it unveiled the Galaxy Fold. Unlike the FlexPai, the Fold folded inward like a book, so the big screen was protected on the inside when it was closed. On the outside was a smaller screen of about 4.6 inches that you could use like a narrow ordinary phone. Open it up and you had a 7.3-inch screen, almost the size of a small tablet. It weighed about 263 grams, heavier than most phones, and it cost about $1,980 in the United States, roughly twice the price of a top normal phone.","Samsung planned to start selling it on April 26, 2019, and sent early units to technology reviewers a couple of weeks before. That is when things went wrong. Within days, several reviewers reported that their screens had broken. Some had peeled off what looked like a plastic screen protector, the kind people often remove from new phones. But on the Fold this thin layer was actually part of the screen itself, and pulling it off damaged the display. Other reviewers had not peeled anything, yet their screens developed bumps or stopped working.","When the repair experts at iFixit took a Fold apart, they found small gaps at the top and bottom of the hinge. Dust and tiny bits of grit could sneak in through those gaps and get trapped under the soft plastic screen. Every time the phone closed, the grit was pressed into the display from behind, a bit like stepping on a pebble inside a sleeping bag. On April 22, 2019, just days before the launch, Samsung delayed the Fold and called back the review units.","Samsung engineers spent the summer redesigning parts of the phone. They added little caps to close the gaps around the hinge, stretched the top protective layer out under the edges of the frame so people could not peel it off, and added extra metal layers under the screen to make it sturdier. The Fold finally went on sale in South Korea on September 6, 2019, and in the United States on September 27. It came with a warning card asking owners to be gentle, not to press hard on the screen with fingernails, and not to remove the protective layer.","Even after the fix, some people tested how many times the hinge could open and close. Samsung said it was designed for 200,000 folds, which would be about 100 folds a day for more than five years. A test by the technology website CNET used a folding machine and found the hinge in its test lasted about 120,000 folds before it had problems. That is still a lot of folding, but it showed how hard it is to make a moving part that people use dozens of times every day.","The Galaxy Fold's bumpy start became a famous lesson in technology circles. It showed that inventing a new kind of object is about much more than a clever screen. You have to think about dust, fingernails, pockets, pocket lint, cold weather, and people who peel things off without reading the instructions. Samsung kept improving the design every year, and its later Galaxy Z Fold phones became some of the best-known foldables in the world."]},{"heading":"Flip Phones Come Back From the Past","paragraphs":["Not everyone wanted a phone that turned into a tablet. Some people wanted the opposite: a normal-size phone that folded into something tiny. In Part 3 you met the Motorola StarTAC, and in Part 7 the super-thin Motorola Razr, both flip phones that snapped shut with a satisfying click. Phone makers realized that a folding screen could bring that old shape back, but with a full modern touchscreen inside.","In November 2019 Motorola announced a new Razr with a bendable screen that folded across the middle, deliberately designed to remind people of the famous Razr V3 from 2004. A few months later, on February 11, 2020, Samsung announced the Galaxy Z Flip, which folded the same way, from a tall phone into a small square that fits easily in a small pocket. The Z Flip had a 6.7-inch main screen and a tiny 1.1-inch screen on the outside that showed the time and notifications.","The Z Flip also introduced an important material. The Galaxy Fold's screen was covered with a layer of plastic, which scratches easily and can feel soft under your fingernail. The Z Flip was the first foldable phone covered with what Samsung called 'ultra-thin glass'. Glass usually shatters if you bend it, but if you make it thin enough, much thinner than a sheet of paper, it becomes flexible. It is the same reason a thick wooden plank snaps while a thin wooden ruler can bend. Engineers made the glass thin enough to bend and then strengthened it, using ideas similar to the ion-exchange trick for toughening glass that you met in Part 10.","Every foldable has to deal with the crease, the faint line across the middle where the screen bends. Early models had a very visible crease, and you could feel it under your finger. Newer designs use a clever 'waterdrop' hinge. Instead of bending the screen into a sharp fold, the hinge lets it curl into a rounded loop shaped a bit like a teardrop when the phone is closed. A gentler curve puts less strain on the screen, so the crease is smaller and the phone can close flat with no gap.","Foldables kept getting wilder. On September 10, 2024, the Chinese company Huawei announced the Mate XT, often described as the first commercially available 'tri-fold' phone. It folded twice, like a three-panel brochure, and opened into a screen of about 10.2 inches, as big as many tablets. Unfolded, its thinnest panel was only about 3.6 millimeters thick, less than the thickness of three stacked coins. It was also very expensive: about 19,999 yuan in China for the basic model, around $2,800. In December 2025 Samsung announced a tri-fold of its own, the Galaxy Z TriFold.","So are folding phones the future? Nobody knows for sure. They are still a small slice of all phones sold, because they cost more, weigh more and are more fragile than ordinary slabs. But each year they get a little thinner, tougher and cheaper. It is a bit like the early brick phones: expensive toys for some people at first, which may or may not become normal for everyone."]},{"heading":"Texting From Beyond the Last Tower","paragraphs":["In Part 12 you learned that a phone talks to cell towers, and each tower covers only a small area. That works brilliantly in cities and along busy roads. But huge parts of the planet have no towers at all: deserts, high mountains, deep forests, the open ocean and lots of countryside. If you break your leg on a hiking trail far from any town, an ordinary phone might show the dreaded words 'No Service'. For most of history, the only way to call for help from such places was a special satellite phone with a big antenna, which most people did not own.","On September 7, 2022, Apple announced the iPhone 14 with a new feature called Emergency SOS via satellite. It started working in the United States and Canada on November 15, 2022, and soon after in the UK, France, Germany and Ireland, then Australia and New Zealand in 2023. For the first time, an ordinary pocket phone sold to millions of people could send a text message for help through a satellite, with no extra gadget.","How does it work? The satellites belong to a company called Globalstar. They circle Earth in low orbit, roughly 1,400 kilometers up, which is much closer than GPS satellites (about 20,200 kilometers) but still enormously far for a tiny phone antenna that was never designed to reach space. The signal is very weak, so the phone cannot stream a video or even make a voice call. Instead, it sends very short text messages, very slowly. Apple's engineers built a special compression system that squeezes messages to about a third of their normal size, so fewer bits have to cross that huge distance.","Because the antenna is small, you have to help it. When the phone finds no cell signal, the screen shows an arrow telling you which way to point the phone toward a satellite, and asks you to step out from under trees if you can. The satellites are moving quickly across the sky, so the arrow keeps updating as they pass. Under a clear sky a message can get through in about 15 seconds, but under leaves or between cliffs it can take minutes.","To save precious bits, the phone first asks a few quick questions you answer with taps: What is the emergency? Is anyone hurt? Who needs help? It packs those answers into the first message together with your location (even your height above sea level), your battery level and, if you have set it up, your medical information. The message bounces from the satellite down to a ground station and then to emergency services, or to a relay center where trained staff can phone the rescuers for you. In the years after launch, news reports described hikers, drivers in remote areas and people caught in storms who were found after using it.","Apple was not alone. Also in 2022, Huawei's Mate 50 phones in China could send short messages through China's BeiDou navigation satellites. In 2024 Google added a Satellite SOS feature to its Pixel 9 phones. And companies including SpaceX, with its Starlink network, began launching satellites that act like 'cell towers in space', able to talk to ordinary phones that were never designed for satellites at all. Think back to Part 1: in 1946 a car phone weighed about 36 kilograms and could only reach a tower a few dozen kilometers away. Now a phone lighter than an apple can reach a satellite more than a thousand kilometers overhead."]},{"heading":"A Tiny Brain for Artificial Intelligence","paragraphs":["Artificial intelligence, or AI, means computer programs that can do jobs we used to think needed a human mind, such as recognizing faces, understanding speech or translating languages. Most modern AI works using something called a neural network, a program loosely inspired by the way brain cells connect. A neural network is trained by showing it huge numbers of examples, such as millions of photos labeled 'cat' or 'dog'. After training, it can make good guesses about new examples it has never seen. Running a trained network means doing enormous numbers of simple multiplications and additions, over and over.","In Part 11 you learned that a phone's system-on-a-chip contains several specialist parts. One of the newest is the NPU, short for neural processing unit. An ordinary processor (the CPU) is like a brilliant all-rounder who can do any job but only a few things at a time. An NPU is more like a huge team of workers who can each do only one simple sum, but all at the same moment. That makes it perfect for neural networks, and it uses far less battery than making the CPU do the same work.","Phone NPUs appeared around 2017. Huawei announced its Kirin 970 chip with a built-in NPU in September of that year, and Apple's A11 Bionic chip in the iPhone 8 and iPhone X included what Apple called the Neural Engine. Apple said it could perform up to 600 billion operations per second, and it helped power Face ID, which you met in Part 15. Only a few years later, phone NPUs were rated in the tens of trillions of operations per second. The usual measuring unit is TOPS, trillions of operations per second.","You probably use phone AI more than you realize. When your phone camera recognizes that you are photographing food or a sunset and adjusts the colors, that is AI. When the Photos app lets you search for 'dog' and finds your dog pictures without you ever labeling them, that is AI. Night mode and portrait blur from Part 14 lean heavily on it too. Voice assistants, which began with Apple's Siri in 2011 and were followed by Google Assistant and others, use AI to turn your spoken words into text and figure out what you mean. Some tools can even erase a stranger from the background of a photo and fill in the gap.","In 2024 phone makers began adding much bigger AI features. Samsung's Galaxy AI, launched with the Galaxy S24 phones in January 2024, included live translation of phone calls, so two people speaking different languages could each hear the other in their own language. In June 2024 Apple announced Apple Intelligence, with tools that could rewrite or summarize text, create small images and sum up a pile of notifications. Google built its Gemini AI into Android phones.","One big question is where the thinking happens. Some AI runs entirely on the phone's own NPU. That is faster, works without internet, and keeps your private information on your device. But the most powerful AI programs are far too big for a phone, so they run on giant computers in data centers, and the phone sends your request over the internet. Companies often mix both. Apple, for example, said simpler requests run on the iPhone while harder ones go to its own specially secured servers.","AI on phones is powerful but not perfect, and it is important to remember that. In late 2024 and early 2025, Apple's notification summaries for news apps produced some summaries that got the news badly wrong, including a false headline that was wrongly linked to the BBC. After complaints, Apple switched off summaries for news apps in a software update in early 2025 while it worked on improvements, and later brought them back with a clear label saying they were written by AI. The lesson for every phone user: AI can be a helpful assistant, but it can make confident mistakes, so important facts are always worth checking."]},{"heading":"Peeking Into the Future: Networks and Batteries","paragraphs":["Now we step from things that already exist into things that might exist. From here on, keep your detective hat on. Everything in this section is a prediction or a plan, and predictions about technology are often wrong. In the 1990s some experts thought nobody would want to type messages on a phone. Others were sure video calling on phones would take off quickly, years before networks were fast enough. So treat what follows as educated guesses, not promises.","The first guess is about networks. In Part 12 you followed the generations from 1G to 5G, with a new one arriving roughly every ten years. Engineers around the world are already researching 6G. The International Telecommunication Union, the United Nations agency that coordinates radio frequencies between countries, has set out goals for it under the name IMT-2030, and the first 6G networks are commonly predicted to arrive around 2030 or in the early 2030s. Countries including the United States, China, Japan, South Korea and India, and the European Union, all have 6G research programs.","What might 6G do? Researchers talk about even faster speeds, even lower delays, and networks that use far less energy per bit of data. Some lab tests have pushed huge amounts of data through the air. In 2022, for example, Samsung reported a test that sent about 12 gigabits per second over a distance of 30 meters, fast enough to download a full-length movie in a few seconds. Engineers have studied very high 'terahertz' frequencies, but those waves are easily blocked by walls, rain and even your hand, so more recently attention has also turned to middle frequencies. Other ideas include building satellites into the normal network so there are no dead zones, and letting the network itself use radio waves to sense movement, a bit like a gentle radar. Which of these ideas will survive into real phones is still being decided.","The second guess is about batteries, which many people say is the thing they would most like to improve. As you learned in Part 13, a lithium-ion battery moves lithium ions through a liquid called the electrolyte. That liquid can burn if the battery is badly damaged. A solid-state battery replaces the liquid with a solid material. Funnily enough, the scientist Michael Faraday discovered materials that let ions move through a solid way back in the 1830s, but making practical solid-state batteries has proved extremely difficult.","If they work, solid-state batteries might hold more energy for their weight and be less likely to catch fire. The problem is that lithium tends to grow tiny metal needles called dendrites, which can push through the solid layer and cause a short circuit. Solid-state batteries are also hard and expensive to manufacture. Car makers such as Toyota, Nissan and Honda have announced plans for the late 2020s or 2030s, but as of the mid-2020s these batteries had not yet arrived in ordinary phones. Meanwhile, some phone makers, especially in China, began using improved 'silicon-carbon' batteries, which pack in a bit more energy using a different material in one electrode. Better batteries usually arrive through many small steps rather than one miracle.","Some changes are about rules rather than inventions. The European Union passed a law in 2022 saying that new phones and many other gadgets sold there must use the same USB-C charging port by the end of 2024. Apple had used its own Lightning connector since the iPhone 5 in 2012. In September 2023 Apple released the iPhone 15 with USB-C, partly because of the EU's law. That means one cable can now charge most phones, laptops and headphones, which saves money and cuts down on piles of unused chargers."]},{"heading":"Will Something Replace the Smartphone?","paragraphs":["Here is the biggest prediction question of all. Smartphones have been the center of digital life since about 2010. But remember what happened in this story: the car phone was replaced by the brick, the brick by the flip phone, the PDA swallowed by the smartphone, and the keyboard BlackBerry pushed aside by the touchscreen. Why should today's glass slab last forever?","One possible replacement is smart glasses. Imagine directions floating in front of your eyes as you walk, a friend's name appearing when you meet them, or a translation of a menu shown right on top of the real menu. This mix of computer images layered onto the real world is called augmented reality, or AR. Google tried early smart glasses called Google Glass, offered to developers in 2013 for $1,500. They had a tiny prism in front of one eye that worked as a screen. But many people felt uneasy about a camera on someone's face that might be recording them, some places banned them, and Google stopped selling them to ordinary consumers in January 2015. Glass lived on for a few years in factories and warehouses before it was discontinued in 2023.","Other companies are trying again. Ray-Ban and Facebook (which renamed itself Meta that same year) began selling camera glasses in 2021 that can take photos, play music and answer questions, though without a real display. In 2025 Meta announced its first glasses with a small built-in display, the Meta Ray-Ban Display. Apple released the Vision Pro, a headset that blends the real world with digital images, in 2024, at a starting price of $3,499. In 2024 Meta also showed a prototype AR glasses design called Orion. These products show the dream is alive, but glasses with bright displays, all-day batteries, low prices and a normal look are still very hard to make.","Another possibility is that the phone becomes the quiet hub of a whole team of wearables: a smartwatch on your wrist, earbuds in your ears, a ring that measures your sleep, perhaps glasses later on. Many people already leave their phone in a bag and check messages on a watch. In that future you might look at your phone much less, even if it is still in your pocket doing the hard work.","And then there is the possibility nobody has thought of yet. In 1973 nobody predicted that phones would become cameras, maps and music players. Martin Cooper, whose first handheld call you read about in Part 2, has often said that a phone should belong to a person, not to a place. Perhaps the next big step continues that idea in ways we cannot guess, such as voice-only assistants that go everywhere with you, or something much stranger. Predictions are fun, but the honest answer is that the future of the phone has not been invented yet.","Before we guess any further, it is worth looking back at how far we have already come. In 1946 a 'mobile' phone was a 36-kilogram radio bolted into a car trunk, sharing a handful of channels with an entire city. Today a phone you can fold in half can find a satellite racing across the sky, translate a conversation as it happens and recognize your face in the dark. In the final part of this Deep Dive we will lay the whole journey out from start to finish, from Bell's wires and Cooper's brick to the phone that talks to space, and see what it can teach us about how inventions really happen."]}],"deepDive":"Why are foldables, satellite phones and on-device AI so hard? Each pushes against basic physics. A folding screen must survive the strain of bending. When a sheet bends, its outer surface stretches and its inner surface squeezes; the thinner the sheet, the smaller that strain. That is why ultra-thin glass works where ordinary glass shatters, and why 'waterdrop' hinges, which bend the screen around a wider loop, put less stress on it than a sharp crease. Satellite texting fights the inverse-square law: a radio signal spreads out so that, at twice the distance, it is only a quarter as strong. Low-orbit Globalstar satellites about 1,400 km up are tens of times farther away than a typical cell tower, so the signal arriving from a palm-sized antenna is extremely faint. Engineers respond by sending tiny compressed messages at very low data rates and asking the user to point the phone, which is why a short text can take from about 15 seconds to several minutes. Newer 'direct-to-cell' satellites carry very large antennas so that unmodified phones can connect, an approach still being rolled out in the mid-2020s. On-device AI is limited mainly by energy and memory. A neural network's job is dominated by multiply-and-add operations; an NPU does thousands of these in parallel, often using low-precision numbers (8-bit or even 4-bit instead of 32-bit) because neural networks still work well with rougher arithmetic and each smaller number costs less energy to move. Apple's 2017 Neural Engine was rated at 600 billion operations per second; flagship phone NPUs a few years later were rated in the tens of trillions. Even so, the largest AI models need far more memory than a phone has, which is why companies split work between phone and cloud, a choice with real trade-offs for privacy, speed and cost. For 6G, the debate is about spectrum: very high frequencies offer enormous bandwidth but travel poorly through walls and rain, so engineers expect a mix of bands. Forecasts here deserve caution; 3G and 5G both took years longer than early boosters suggested to change daily life, and some heavily hyped ideas never became mainstream at all.","funFact":"The Huawei Mate XT tri-fold phone of 2024 unfolds into a screen of about 10.2 inches, yet its thinnest panel is only about 3.6 millimeters thick.","check":{"q":"Why did Samsung delay the first Galaxy Fold in April 2019?","a":"Review units' screens broke, partly from peeling off a layer that was part of the screen and from debris getting in through gaps at the hinge.","wrong":["The battery was too small to turn the phone on","The phone could not connect to any cell towers","The European Union banned folding phones"]},"sources":[{"title":"Samsung Galaxy Fold","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Samsung_Galaxy_Fold"},{"title":"Foldable smartphone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Foldable_smartphone"},{"title":"Huawei Mate XT","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Huawei_Mate_XT"},{"title":"Emergency SOS via satellite available today on iPhone 14 lineup","publisher":"Apple Newsroom","url":"https://www.apple.com/newsroom/2022/11/emergency-sos-via-satellite-available-today-on-iphone-14-lineup/"},{"title":"Globalstar","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Globalstar"},{"title":"Apple A11","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Apple_A11"},{"title":"6G","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/6G"},{"title":"Solid-state battery","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Solid-state_battery"}],"photos":[{"src":"img/deep/smartphone/19-1.jpg","alt":"A Samsung Galaxy Fold opened up like a small tablet, showing a butterfly picture on its big screen.","file":"Galaxy Fold - 1.jpg","url":"https://commons.wikimedia.org/wiki/File:Galaxy_Fold_-_1.jpg","author":"KKPCW","license":"CC BY-SA 4.0"},{"src":"img/deep/smartphone/19-2.jpg","alt":"A Samsung Galaxy Z Flip half-folded, standing on a table like a tiny laptop.","file":"Samsung Galaxy Z Flip fold.jpg","url":"https://commons.wikimedia.org/wiki/File:Samsung_Galaxy_Z_Flip_fold.jpg","author":"Grace R. Samson","license":"CC BY 4.0"},{"src":"img/deep/smartphone/19-3.jpg","alt":"Google Glass: a thin frame with a tiny computer, camera and glass prism screen on one side.","file":"Google Glass Main.jpg","url":"https://commons.wikimedia.org/wiki/File:Google_Glass_Main.jpg","author":"Tim.Reckmann","license":"CC BY-SA 3.0"}],"words":4377},{"n":20,"title":"From Brick to Brain: Putting It All Together","when":"1876 – future","summary":"We made it to the last part! Let's zoom back through the whole story, from heavy car phones to the brick to the phone in your pocket. You will see that no single genius invented the smartphone: thousands of people each added one piece, and the next piece might be added by you.","sections":[{"heading":"The Whole Journey on One Page","paragraphs":["Imagine a long museum hallway with one glass case for every big moment in this story. Let's walk down it together, slowly, and look into each case.","The first case holds a wooden telephone with a cord leading into the wall. In March 1876 Alexander Graham Bell received his telephone patent, while others such as Elisha Gray and Antonio Meucci were working on similar ideas. Calls traveled through wires, so a phone was stuck in one place. In the next case is a radio set from the age of Guglielmo Marconi, who showed in the 1890s and 1900s that messages could fly through the air with no wires at all.","Case three is enormous. It holds a 1946 car telephone: about 36 kilograms (80 pounds) of radio equipment that filled much of a car trunk. On June 17, 1946, AT&T opened its Mobile Telephone Service in St. Louis. Every call went through a human operator, and because one big transmitter covered a whole city, only a few people could talk at once. Waiting lists stretched into the hundreds. This was mobile, but it was not cellular.","Case four holds a sheet of paper: the 1947 Bell Labs memo in which Douglas Ring and W. Rae Young described dividing a city into small cells, each with its own low-power tower, so radio channels could be reused. It took more than thirty years for electronics to catch up with that idea.","Case five holds a plastic brick. On April 3, 1973, on a New York street, Motorola's Martin Cooper made the first public call on a handheld cellular phone, and he called his rival Joel Engel at Bell Labs. Next to it is the Motorola DynaTAC 8000X, the version people could buy in 1984 for $3,995. In between, the world's first commercial cellular network opened in Tokyo in 1979, then the Nordic NMT network in 1981 and Chicago's network in October 1983.","Case six shows a small grey phone with a green screen. Digital 2G networks such as GSM arrived, with the first GSM call made in Finland on July 1, 1991. On December 3, 1992, engineer Neil Papworth sent the first text message, 'Merry Christmas', from a computer to a phone. Soon teenagers everywhere were pressing the 7 key four times to type an S, and playing Snake on Nokia phones.","Case seven holds a little army of gadgets: the Psion Organiser (1984), Apple's Newton MessagePad (1993) and the Palm Pilot (1996), electronic organizers with no phone inside. Beside them sits a chunky black device with a touchscreen and stylus: the IBM Simon, sold from August 1994. Today it is widely called the first smartphone, though nobody used that word for it at the time.","Case eight is full of Japanese phones: NTT Docomo's i-mode mobile internet (1999), the 176 emoji drawn by Shigetaka Kurita, early camera phones like the Sharp J-SH04 (2000), and the world's first commercial 3G network, FOMA, in 2001. Case nine holds a BlackBerry with its tiny thumb keyboard, the 850 of 1999 that started the 'push email' craze in offices.","Then comes the case most people crowd around: the first iPhone, announced by Steve Jobs on January 9, 2007, and sold from June 29, 2007. Beside it stands the T-Mobile G1, also called the HTC Dream, the first Android phone, which went on sale in October 2008. That same year, on July 10, Apple's App Store opened with about 500 apps, and soon there was 'an app for that' for almost everything.","The last cases glow with modern phones: big OLED screens, several cameras, fingerprint and face recognition, phones that fold, and phones that can text a satellite for help. And the very last case at the end of the hallway is empty, with a little sign: 'Coming soon.'"]},{"heading":"Nobody Invented the Smartphone","paragraphs":["If someone asks you 'Who invented the smartphone?', you now know the honest answer: nobody did, and everybody did. The smartphone is not one invention. It is a bundle of dozens of inventions, each with its own story, its own inventors and often its own arguments about who came first. Let's take a phone apart in our imagination and remember where each piece came from.","The radio inside it goes back to the work of Marconi and many others on wireless signals, and to the cellular idea from Bell Labs. The way your calls jump from tower to tower relies on handoff, which engineers such as Amos Joel Jr. worked out. Wi-Fi grew from a standard first agreed in 1997, and Bluetooth from work at Ericsson led by Jaap Haartsen.","The brain of the phone is built from transistors, the tiny on and off switches first demonstrated at Bell Labs in 1947. Integrated circuits, which put many transistors on one chip, followed in the late 1950s, and Gordon Moore's famous prediction of 1965 described how they would keep shrinking. The phone's processor almost certainly uses an ARM design, which grew from the chip that Sophie Wilson and Steve Furber designed at Acorn in Britain, first running in 1985.","The screen you tap uses capacitive touch sensing, first described by E. A. Johnson in Britain in 1965, plus decades of multi-touch research from places such as the University of Toronto and companies such as FingerWorks. The tough glass came from Corning's 1960s Chemcor research, and the glowing pixels from OLED and LCD research around the world.","The battery is lithium-ion, thanks to M. Stanley Whittingham, John Goodenough and Akira Yoshino, and to Sony, which sold the first commercial lithium-ion batteries in 1991. The camera's sensor is a CMOS active-pixel sensor, developed by Eric Fossum's team at NASA's Jet Propulsion Laboratory, following the CCD sensor invented by Willard Boyle and George Smith. The blue dot on your map depends on GPS satellites, a project led by Bradford Parkinson, with mathematical models of Earth's shape from experts such as Gladys West. And every app, message and web page depends on the internet, itself the work of thousands of researchers.","Then there are the countless smaller inventions that rarely get famous: the SIM card, the tiny microphones, the vibration motor, the speaker, the antenna design, the data compression that squeezes music and video, the software that runs it all. Every one of those has engineers behind it whose names most people never hear.","Here is one more amazing fact. Several pieces of the smartphone come from science that won Nobel Prizes, the most famous awards in science. Marconi shared the 1909 Nobel Prize in Physics for wireless telegraphy. William Shockley, John Bardeen and Walter Brattain won in 1956 for their work on the transistor. Jack Kilby shared the 2000 physics prize for his part in inventing the integrated circuit. Boyle and Smith shared the 2009 physics prize for the CCD sensor. And Whittingham, Goodenough and Yoshino shared the 2019 chemistry prize for the lithium-ion battery. When you hold a smartphone, you are holding a small pile of Nobel Prizes."]},{"heading":"Lesson One: First Is Not Always the Winner","paragraphs":["Looking back over 150 years of history, some lessons pop out again and again. The first one surprises many people: the first company to build something is often not the one that makes it a success.","Remember the IBM Simon. It had a touchscreen, a calendar, email and even a sketch pad in 1994, thirteen years before the iPhone. But it cost about $899 with a contract, weighed about half a kilogram, ran out of battery after roughly an hour of talking, and could not browse the web, because mobile networks were slow and the web itself was brand new. Roughly 50,000 were sold before it was withdrawn. Apple's Newton had a similar fate: it introduced many people to the idea of a pocket computer but was mocked for its handwriting recognition and was dropped in 1998. In Part 19 you met Royole, which sold the first foldable phone and later went bankrupt.","Why does this happen? Often the first product arrives before the world around it is ready. Simon needed fast mobile data networks, cheap color screens and long-lasting batteries, and none of those existed yet. The iPhone arrived in 2007 when touchscreens, lithium-ion batteries, ARM chips and mobile networks had all improved enough to work together. Even then, the first iPhone lacked 3G, an App Store and video recording. Good timing means waiting until many pieces of the puzzle are ready, and that is very hard to judge in advance.","This is not a story about early inventors being failures. Simon and Newton showed what was possible, and they taught engineers lessons that later products used. Jeff Hawkins, who carried a wooden block in his shirt pocket to test the size of the Palm Pilot, learned from the Newton's troubles and made his device simpler. Every pioneer's mistakes became a map for the people who came after."]},{"heading":"Lesson Two: Networks Matter, and Giants Can Fall","paragraphs":["A phone on its own is useless. It only becomes valuable because it connects to other phones, towers, satellites and services. Engineers call this a network effect: the more people who use something, the more useful it becomes for everyone. The first telephone owners had almost nobody to call. The first texters could only message a few friends. But once millions of people had phones, every new phone became more valuable, because it could reach all the others.","Network effects explain many twists in our story. Japan's i-mode took off because Docomo built the whole system at once: the network, the phones, the sites and an easy way to pay. Apple's App Store and Google Play became giants because more users attracted more app makers, and more apps attracted more users. M-Pesa in Kenya became essential once enough shops and families used it to send and receive money.","Network effects can also lock in winners for a while, which made the fall of some giants all the more shocking. Nokia was the world's largest mobile phone maker from 1998 until about 2012, and it sold more than a hundred million of a single model, the Nokia 3310 family. BlackBerry was so popular with office workers that people called it the 'CrackBerry', and even a US president fought to keep one. Both companies had brilliant engineers. Yet within a few years of the iPhone and Android arriving, both fell far behind. Nokia sold its phone business to Microsoft in 2014, and BlackBerry stopped designing its own phones in 2016.","Business historians still argue about exactly why, but some reasons come up often. Both companies were extremely good at what customers wanted yesterday, such as tough phones, long battery life, physical keyboards and data-saving email. They were slower to bet on what customers would want tomorrow: big touchscreens, full web browsers and app stores full of software from outside developers. The lesson is not that big companies are foolish. It is that being the best at today's problem does not guarantee you will win tomorrow's."]},{"heading":"Lesson Three: Tiny Steps Make Giant Leaps","paragraphs":["The third lesson is easy to miss because it happens so quietly. Most of the progress in this story did not come from one dazzling breakthrough. It came from thousands of small improvements, each one only a little better than the last, stacking up year after year until the total change was enormous.","Think about the camera. The Sharp J-SH04 of 2000 had a camera of about 0.11 megapixels, which is roughly 110,000 pixels, enough for a tiny, blurry snapshot. Each new generation of image sensor squeezed in a few more pixels, collected light a little more efficiently and wasted a little less battery. Add better lenses, image stabilization and the computational photography tricks of Part 14, and two decades later many phones had cameras of 12 to 200 megapixels that could take sharp photos at night. No single year was a miracle. The miracle was the pile of years.","Screens followed the same path. The DynaTAC had a single line of glowing red digits. Early 2000s phones had small color screens. The first iPhone in 2007 had a 3.5-inch screen with 320 by 480 pixels, which seemed amazing at the time. Many modern phones pack more than 400 pixels into every inch, so sharp that your eyes cannot pick out individual dots at a normal reading distance.","Networks grew step by step too. The first text messages in 1992 were limited to 160 characters. 3G networks from 2001 made it practical to check email and simple web pages. 4G LTE, starting in Stockholm and Oslo in December 2009, made smooth video streaming normal, and 5G from 2019 pushed speeds even higher. Each generation took about ten years and the work of thousands of engineers agreeing on shared standards so phones from different makers could all talk to each other.","Chips are the clearest example of all. Gordon Moore predicted in 1965 that the number of transistors on a chip would keep doubling roughly every couple of years. Doubling sounds modest, but repeat it again and again and the numbers explode. Apple's A11 chip of 2017 had about 4.3 billion transistors; its A17 Pro of 2023 had about 19 billion, more than four times as many in just six years. Compare that with the Apollo Guidance Computer that helped land astronauts on the Moon in 1969, which had only about 4 kilobytes of changeable memory, while a modern phone has billions of bytes.","Martin Cooper noticed the same pattern in radio. His observation, often called Cooper's Law, says that the number of conversations that can be carried over a given area of radio spectrum has doubled about every 30 months for many decades. Much of that came from making cells smaller and smarter, building on the 1947 idea from Bell Labs. Small, steady gains, kept up for a long time, beat a single big leap almost every time."]},{"heading":"Brick Versus Brain: A Side-by-Side Test","paragraphs":["Let's put two phones side by side on a table: the Motorola DynaTAC 8000X from 1983 and a typical smartphone from the mid-2020s. This is where you can really see how many small improvements add up.","Weight first. The DynaTAC weighed about 790 grams (1.75 pounds), about the same as a large bottle of water. It stood about 25 centimeters (10 inches) tall, not counting its rubbery antenna. Many modern smartphones weigh about 170 to 230 grams, roughly a quarter as much, and they are thinner than a pencil.","Battery next. The DynaTAC offered about 30 minutes of talking, and recharging it fully on its standard charger took about 10 hours. A modern smartphone usually lasts a whole day of mixed use, including calls, music, maps, photos and videos, and many can charge to half full in around half an hour. That leap came from lithium-ion batteries, far more efficient chips and smarter software that switches parts off when they are not needed.","Now abilities. The DynaTAC could make and receive calls, and its little red LED display could recall about 30 stored phone numbers. That was it. No screen for words, no texting, no camera, no maps, no music, no internet. A modern smartphone is a phone, a camera that shoots high-quality video, a map that knows where you are to within a few meters, a music player, a games console, a flashlight, a bank card, a library, a translator and a link to billions of web pages. Inside it is a chip with billions of transistors; Apple's A17 Pro chip of 2023, for example, has about 19 billion.","Finally, price. The DynaTAC cost $3,995 in 1984, more than $12,000 in today's money, so only rich people and businesses could afford one. Today a basic smartphone can cost under $100 and a top model often around $1,000, and the cheaper phones put most of the same basic abilities in the hands of billions of people.","And here is the most remarkable number of all: time. Martin Cooper's first public handheld call was in 1973. Fewer than forty years later, in the 2010s, billions of people were carrying smartphones. By 2019, about 1.5 billion new smartphones were being shipped worldwide every single year, and the International Telecommunication Union estimated that in 2024 about four out of five people aged 10 and over owned a mobile phone. Few inventions in history have spread so far, so fast."]},{"heading":"Using Your Phone Wisely","paragraphs":["After twenty parts, it is fair to ask: is the smartphone a good thing or a bad thing? The honest answer is that it is a tool, and like any powerful tool it can be used well or badly.","On the good side, phones have done wonderful things. They let a grandparent see a grandchild's face from across an ocean. They help farmers check prices and weather, let people send money safely, guide lost travelers home and call for help from a mountainside. They let ordinary people record important events and share them with the world. They put a dictionary, an encyclopedia and countless lessons in the pocket of anyone with a connection. For people with disabilities, features like screen readers, voice control and live captions can open up the world.","On the other side, as Part 18 explained, there are real problems. Many apps are designed to keep you scrolling. Phones can interrupt sleep and homework, distract drivers and walkers, and expose people to bullying, scams and privacy risks. Making phones uses rare materials, some mined in difficult conditions, and old phones add to the world's mountain of e-waste. Scientists still debate how much smartphones affect mental health, and that debate is not settled yet.","So what does using a phone wisely look like? Here are a few ideas many families find helpful, without needing to believe anything scary. Keep phones out of the bedroom at night so your sleep gets the rest it needs. Turn off notifications you do not really need, so the phone works for you instead of the other way around. Never text or look at a screen while crossing a road or riding a bike. Think before you post, because things online can last a long time. Ask a trusted adult when something online feels wrong. And when your phone gets old, recycle it properly or pass it on instead of tossing it in the bin.","A good test is to ask yourself: am I choosing to use my phone right now, or is my phone choosing for me? The engineers in this story built an incredible machine. Using it well is up to us."]},{"heading":"Your Turn to Invent","paragraphs":["Every person in this story started out as someone curious. Martin Cooper was an engineer who believed a phone should belong to a person, not a place. Neil Papworth was a young engineer testing a system when he typed 'Merry Christmas'. Jeff Hawkins carried a block of wood in his pocket to imagine a gadget that did not exist yet. Shigetaka Kurita drew tiny pictures on a 12 by 12 grid of dots. Sophie Wilson and Steve Furber designed a chip so efficient that its descendants now run in billions of phones. None of them could have known how far their ideas would travel.","So here is your final challenge. If you could reinvent one part of the smartphone, which would you choose? Maybe the battery, so it lasts a week and never wears out. Maybe the screen, so it is easier to read in bright sunshine, or kinder to tired eyes at night. Maybe the materials, so phones can be built without hard-to-mine metals and recycled completely. Maybe repair, so anyone could swap a broken part with a simple screwdriver. Maybe safety, so phones help protect kids from online strangers. Maybe accessibility, so people who cannot see, hear or move easily can use phones as easily as anyone. Or maybe something nobody has even thought of yet.","Good inventors usually start not with a gadget but with a problem. What annoys you about phones? What can they not do that you wish they could? Write it down. Sketch it. Ask how it might work. Find out who has tried before, and what went wrong. That is exactly what the people in this story did.","The smartphone went from a 36-kilogram radio in a car trunk to a supercomputer that talks to satellites in less than a single human lifetime, thanks to thousands of curious people adding one piece at a time. The next piece has not been added yet. Somewhere out there, maybe reading these very words, is the person who will add it. Maybe that person is you."]}],"deepDive":"How do historians measure a change as big as the smartphone? One way is to compare numbers at the start and end. The DynaTAC 8000X of 1983–84 weighed about 790 g, gave about 30 minutes of talk time after roughly 10 hours of charging, stored about 30 numbers on a red LED display and cost $3,995. A typical flagship of the mid-2020s weighs about 170–230 g, lasts about a day of mixed use, and contains a system-on-a-chip with tens of billions of transistors in some models. Global smartphone shipments reached about 1.5 billion in 2019, and the ITU estimated that about 80% of people aged 10 and over owned a mobile phone in 2024, although ownership was above 95% in high-income economies and only about 56% in low-income ones, a reminder that the revolution is still uneven. Historians of technology also warn against the 'lone genius' story. The smartphone is a textbook case of what scholars call combinatorial innovation: new products built by recombining existing components. Its parts trace back to Nobel Prize–winning science (radio in 1909, the transistor in 1956, the integrated circuit in 2000, the CCD in 2009 and the lithium-ion battery in 2019), to government-funded projects such as GPS and the NASA work that produced the CMOS image sensor, and to countless engineers in companies large and small. Disputes over credit are normal: Bell versus Gray and Meucci, rival walkie-talkie claims, IBM Simon versus later 'smartphones', and the patent wars between Apple and Samsung. Another debate concerns 'path dependence': choices made early, such as the GSM standard and SIM card in Europe or Japan's separate standards, shaped which companies thrived later. Economists also note that Martin Cooper's own observation, often called Cooper's Law, says the number of conversations that can be carried over a given area of radio spectrum has doubled about every 30 months for many decades, mostly thanks to smaller cells rather than new spectrum. Finally, honest history must weigh costs as well as benefits, from e-waste and mining to attention and privacy, and those debates are far from over.","funFact":"The first commercial handheld cellular phone, the DynaTAC 8000X, could store about 30 phone numbers, while a modern smartphone can hold tens of thousands of photos, songs and contacts.","check":{"q":"About how long could the 1983 DynaTAC phone be used for talking on one charge?","a":"About 30 minutes","wrong":["About a full day","About one week","About 5 hours"]},"sources":[{"title":"Motorola DynaTAC","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Motorola_DynaTAC"},{"title":"Smartphone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Smartphone"},{"title":"Mobile phone ownership (Facts and Figures 2024)","publisher":"International Telecommunication Union","url":"https://www.itu.int/itu-d/reports/statistics/2024/11/10/ff24-mobile-phone-ownership/"},{"title":"Martin Cooper (inventor)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Martin_Cooper_(inventor)"},{"title":"Lithium-ion battery","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Lithium-ion_battery"},{"title":"Nobel Prize in Physics","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nobel_Prize_in_Physics"},{"title":"Apple A11","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Apple_A11"}],"photos":[{"src":"img/deep/smartphone/20-1.jpg","alt":"A Motorola DynaTAC \"brick\" phone held next to a Samsung Galaxy Note Edge smartphone in a phone collection.","file":"Motorola DynaTAC and Samsung Galaxy Note Edge.jpg","url":"https://commons.wikimedia.org/wiki/File:Motorola_DynaTAC_and_Samsung_Galaxy_Note_Edge.jpg","author":"Umut Çolak","license":"Public domain"},{"src":"img/deep/smartphone/20-2.jpg","alt":"The IBM Simon on display at the Computer History Museum, beside a picture of its touchscreen menu.","file":"IBM Simon Personal Communicator (1993) - the first smartphone - Computer History Museum.jpg","url":"https://commons.wikimedia.org/wiki/File:IBM_Simon_Personal_Communicator_(1993)_-_the_first_smartphone_-_Computer_History_Museum.jpg","author":"Michael Hicks from Saint Paul, MN, USA","license":"CC BY 2.0"},{"src":"img/deep/smartphone/20-3.jpg","alt":"Mobile phones from 1992 to 2014 in a row: from a big Motorola brick to slim touchscreen smartphones.","file":"Mobile Phone Evolution 1992 - 2014.jpg","url":"https://commons.wikimedia.org/wiki/File:Mobile_Phone_Evolution_1992_-_2014.jpg","author":"Jojhnjoy","license":"Public domain"}],"words":3740}],"words":80129};
